--
-- Name: can_manage_conversation(uuid); Type: FUNCTION; Schema: comms; Owner: -
--

CREATE FUNCTION comms.can_manage_conversation(p_conversation_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'comms', 'public', 'pg_temp'
    AS $$
  select public.is_admin() or exists (
    select 1 from comms.conversation_participants cp
     where cp.conversation_id = p_conversation_id
       and cp.profile_id = auth.uid()
       and cp.role = 'admin'
       and cp.left_at is null
  )
$$;


--
-- Name: can_post_in_conversation(uuid); Type: FUNCTION; Schema: comms; Owner: -
--

CREATE FUNCTION comms.can_post_in_conversation(p_conversation_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'comms', 'public', 'pg_temp'
    AS $$
  select exists (
    select 1 from comms.conversation_participants cp
     join comms.conversations c on c.id = cp.conversation_id
     where cp.conversation_id = p_conversation_id
       and cp.profile_id = auth.uid()
       and cp.participant_type = 'user'
       and cp.role in ('member','admin')
       and cp.left_at is null
       and c.archived_at is null
  )
$$;


--
-- Name: can_read_connection(uuid); Type: FUNCTION; Schema: comms; Owner: -
--

CREATE FUNCTION comms.can_read_connection(p_connection_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'comms', 'public', 'pg_temp'
    AS $$
  select exists (
    select 1 from comms.connections k
     where k.id = p_connection_id
       and (
         public.is_admin()
         or k.owner_profile_id = auth.uid()
         or exists (select 1 from comms.connection_grants g
                     where g.connection_id = k.id and g.grantee_profile_id = auth.uid()
                       and g.revoked_at is null and (g.expires_at is null or g.expires_at > now()))
         or (k.visibility = 'shared' and (
               k.role_id is null and comms.is_active_profile(auth.uid())
               or exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = k.role_id and p.is_active)))
       )
  )
$$;


--
-- Name: can_read_conversation(uuid); Type: FUNCTION; Schema: comms; Owner: -
--

CREATE FUNCTION comms.can_read_conversation(p_conversation_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'comms', 'public', 'pg_temp'
    AS $$
  select exists (
    select 1 from comms.conversations c
     where c.id = p_conversation_id
       and (
         comms.is_active_participant(c.id, auth.uid())
         or (c.audience = 'internal' and c.kind = 'channel' and not c.is_private and comms.is_active_profile(auth.uid()))
         or public.is_admin()
       )
  )
$$;


--
-- Name: emit_mentions(uuid, uuid, uuid, text, text[]); Type: FUNCTION; Schema: comms; Owner: -
--

CREATE FUNCTION comms.emit_mentions(p_conversation_id uuid, p_message_id uuid, p_sender_profile uuid, p_body text, p_mentions text[] DEFAULT NULL::text[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'comms', 'spine', 'public', 'pg_temp'
    AS $_$
declare
  v_conv   record;
  v_agent  record;
  v_hit    boolean;
  v_events integer := 0;
begin
  if p_sender_profile is null then return 0; end if;  -- loop guard: only humans trigger agents
  select * into v_conv from comms.conversations where id = p_conversation_id;
  for v_agent in
    select cp.agent_identity_slug as slug, ai.chat_profile->>'display_name' as display_name
      from comms.conversation_participants cp
      join spine.agent_identities ai on ai.slug = cp.agent_identity_slug and ai.enabled
     where cp.conversation_id = p_conversation_id and cp.participant_type = 'agent' and cp.left_at is null
  loop
    if p_mentions is not null then
      v_hit := v_agent.slug = any (p_mentions);
    else
      v_hit := p_body ~* ('(^|[^[:alnum:]_])@' || v_agent.slug || '([^[:alnum:]_]|$)')
            or (v_agent.display_name is not null and position(('@' || lower(v_agent.display_name)) in lower(p_body)) > 0);
    end if;
    if v_hit then
      insert into spine.events (kind, source, payload)
      values ('chat.mention.' || v_agent.slug, 'comms.messages',
              jsonb_build_object(
                'conversation_id', p_conversation_id,
                'message_id', p_message_id,
                'agent_slug', v_agent.slug,
                'sub', p_sender_profile,
                'work_item_id', v_conv.work_item_id,
                'audience', v_conv.audience,
                'body', left(p_body, 4000)));
      v_events := v_events + 1;
    end if;
  end loop;
  if v_events > 0 then
    insert into comms.conversation_events (conversation_id, kind, actor_participant_id, payload)
    select p_conversation_id, 'handoff_to_agent', cp.id, jsonb_build_object('message_id', p_message_id, 'mentions', v_events)
      from comms.conversation_participants cp
     where cp.conversation_id = p_conversation_id and cp.profile_id = p_sender_profile and cp.left_at is null
     limit 1;
  end if;
  return v_events;
end
$_$;


--
-- Name: ingest_bridge_message(text, text, text, text, text, text, text, timestamp with time zone, jsonb, jsonb); Type: FUNCTION; Schema: comms; Owner: -
--

CREATE FUNCTION comms.ingest_bridge_message(p_provider text, p_external_ref text, p_provider_message_id text, p_provider_thread_id text, p_sender_handle text, p_sender_display text, p_body text, p_sent_at timestamp with time zone, p_attachments jsonb DEFAULT '[]'::jsonb, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'comms', 'spine', 'public', 'pg_temp'
    AS $$
declare
  v_link    record;
  v_profile uuid;
  v_pid     uuid;
  v_msg     uuid;
  v_parent  uuid;
  v_mentions integer := 0;
begin
  select * into v_link from comms.conversation_links where provider = p_provider and external_ref = p_external_ref and status = 'active';
  if v_link.id is null then
    return jsonb_build_object('status', 'unlinked', 'provider', p_provider, 'external_ref', p_external_ref);
  end if;
  if v_link.sync_mode = 'write' then
    return jsonb_build_object('status', 'skipped', 'reason', 'link is write-only');
  end if;

  select profile_id into v_profile from comms.profile_identities where provider = p_provider and handle = p_sender_handle;
  if v_profile is not null then
    insert into comms.conversation_participants (conversation_id, participant_type, profile_id, role)
    values (v_link.conversation_id, 'user', v_profile, 'member')
    on conflict (conversation_id, profile_id) where profile_id is not null do update set left_at = null
    returning id into v_pid;
  else
    insert into comms.conversation_participants (conversation_id, participant_type, external_app, role)
    values (v_link.conversation_id, 'external_app', p_provider, 'observer')
    on conflict do nothing;
    select id into v_pid from comms.conversation_participants where conversation_id = v_link.conversation_id and external_app = p_provider limit 1;
  end if;

  if p_provider_thread_id is not null then
    select id into v_parent from comms.messages where provider = p_provider and provider_message_id = p_provider_thread_id;
  end if;

  insert into comms.messages (conversation_id, sender_participant_id, connection_id, body, body_format, direction, visibility, provider,
                              provider_message_id, provider_thread_id, in_reply_to_message_id, attachments, sent_at, payload)
  values (v_link.conversation_id, v_pid, v_link.connection_id, coalesce(p_body, ''), 'markdown', 'inbound', 'all', p_provider,
          p_provider_message_id, p_provider_thread_id, v_parent, coalesce(p_attachments, '[]'::jsonb), coalesce(p_sent_at, now()),
          coalesce(p_payload, '{}'::jsonb) || jsonb_build_object('sender_handle', p_sender_handle, 'sender_display', p_sender_display, 'mapped', v_profile is not null))
  on conflict (provider, provider_message_id) where provider_message_id is not null do nothing
  returning id into v_msg;

  if v_msg is null then
    return jsonb_build_object('status', 'duplicate', 'conversation_id', v_link.conversation_id);
  end if;
  -- Only a mapped human triggers agents (loop guard: bots and unmapped senders never do).
  if v_profile is not null and not coalesce((p_payload->>'is_bot')::boolean, false) then
    v_mentions := comms.emit_mentions(v_link.conversation_id, v_msg, v_profile, coalesce(p_body, ''), null);
  end if;
  return jsonb_build_object('status', 'inserted', 'message_id', v_msg, 'conversation_id', v_link.conversation_id, 'mapped', v_profile is not null, 'mentions', v_mentions);
end
$$;


