$$;


--
-- Name: send_message_as(uuid, uuid, text, uuid, text, text[], text, text); Type: FUNCTION; Schema: comms; Owner: -
--

CREATE FUNCTION comms.send_message_as(p_profile_id uuid, p_conversation_id uuid, p_body text, p_in_reply_to uuid DEFAULT NULL::uuid, p_visibility text DEFAULT 'all'::text, p_mentions text[] DEFAULT NULL::text[], p_provider text DEFAULT 'openronin'::text, p_provider_message_id text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'comms', 'spine', 'public', 'pg_temp'
    AS $$
declare
  v_pid uuid;
  v_msg uuid;
begin
  if p_body is null or length(btrim(p_body)) = 0 then
    raise exception 'comms: empty message' using errcode = '22023';
  end if;
  if length(p_body) > 20000 then
    raise exception 'comms: message too long' using errcode = '22023';
  end if;
  select id into v_pid from comms.conversation_participants
   where conversation_id = p_conversation_id and profile_id = p_profile_id and participant_type = 'user' and left_at is null;
  if v_pid is null then
    raise exception 'comms: % is not a member of this conversation', p_profile_id using errcode = '42501';
  end if;
  if exists (select 1 from comms.conversations where id = p_conversation_id and archived_at is not null) then
    raise exception 'comms: conversation is archived' using errcode = '42501';
  end if;

  insert into comms.messages (conversation_id, sender_participant_id, body, body_format, direction, visibility, provider, provider_message_id, in_reply_to_message_id)
  values (p_conversation_id, v_pid, p_body, 'markdown',
          case when p_provider = 'openronin' then 'internal' else 'inbound' end,
          case when p_visibility = 'staff_only' then 'staff_only' else 'all' end,
          coalesce(p_provider, 'openronin'), p_provider_message_id, p_in_reply_to)
  returning id into v_msg;

  update comms.conversation_participants set last_read_at = now() where id = v_pid;
  perform comms.emit_mentions(p_conversation_id, v_msg, p_profile_id, p_body, p_mentions);
  return v_msg;
end
$$;


--
-- Name: thread_for_identity(text, uuid, uuid, uuid, integer); Type: FUNCTION; Schema: comms; Owner: -
--

CREATE FUNCTION comms.thread_for_identity(p_identity_slug text, p_sub uuid, p_conversation_id uuid, p_event_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 40) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'comms', 'spine', 'public', 'pg_temp'
    AS $$
declare
  v_conv     record;
  v_t0       timestamptz := clock_timestamp();
  v_rows     jsonb;
  v_n        integer := 0;
  v_audit_id bigint;
  v_anchor_wi uuid;
begin
  if p_sub is null or not exists (select 1 from public.profiles where id = p_sub) then
    raise exception 'comms thread: sub must be a real profile' using errcode = '23503';
  end if;
  if not exists (select 1 from spine.agent_identities where slug = p_identity_slug) then
    raise exception 'comms thread: unknown identity %', p_identity_slug using errcode = '23503';
  end if;
  if p_event_id is not null and not exists (select 1 from spine.events where id = p_event_id) then
    raise exception 'comms thread: unknown event %', p_event_id using errcode = '23503';
  end if;
  select * into v_conv from comms.conversations where id = p_conversation_id;
  if v_conv.id is null then
    raise exception 'comms thread: unknown conversation' using errcode = '23503';
  end if;
  v_anchor_wi := v_conv.work_item_id;
  if v_anchor_wi is null and p_event_id is null then
    raise exception 'comms thread: an anchor is required (conversation has no work item and no event was given)' using errcode = '22023';
  end if;

  if not exists (select 1 from spine.agent_identities where slug = p_identity_slug and enabled)
     or not exists (select 1 from comms.conversation_participants cp
                     where cp.conversation_id = p_conversation_id and cp.agent_identity_slug = p_identity_slug and cp.left_at is null) then
    v_audit_id := spine.record_agent_audit(p_sub, p_identity_slug, v_anchor_wi, 'read', 'comms.messages', 0, 0, 'denied',
                                           'identity is not a participant of this conversation (or is disabled)', p_event_id);
    return jsonb_build_object('status', 'denied', 'audit_id', v_audit_id, 'act', p_identity_slug,
                              'error', 'identity is not a participant of this conversation');
  end if;

  select coalesce(jsonb_agg(row_to_json(t)::jsonb order by t.sent_at), '[]'::jsonb), count(*)
    into v_rows, v_n
    from (
      select m.id, m.sent_at, m.body, m.body_format, m.provider, m.direction,
             cp.participant_type as sender_type,
             case cp.participant_type
               when 'user'  then coalesce(nullif(btrim(concat_ws(' ', p.first_name, p.last_name)), ''), p.email)
               when 'agent' then coalesce(ai.chat_profile->>'display_name', ai.slug)
               else coalesce(cp.external_app, 'contact') end as sender_name,
             m.in_reply_to_message_id
        from comms.messages m
        left join comms.conversation_participants cp on cp.id = m.sender_participant_id
        left join public.profiles p on p.id = cp.profile_id
        left join spine.agent_identities ai on ai.slug = cp.agent_identity_slug
       where m.conversation_id = p_conversation_id and m.deleted_at is null
       order by m.sent_at desc
       limit greatest(1, least(coalesce(p_limit, 40), 200))
    ) t;

  v_audit_id := spine.record_agent_audit(p_sub, p_identity_slug, v_anchor_wi, 'read', 'comms.messages', v_n,
                                         (extract(epoch from clock_timestamp() - v_t0) * 1000)::integer, 'ok', null, p_event_id);
  return jsonb_build_object('status', 'ok', 'audit_id', v_audit_id, 'act', p_identity_slug, 'sub', p_sub,
                            'conversation', jsonb_build_object('id', v_conv.id, 'kind', v_conv.kind, 'audience', v_conv.audience,
                                                               'title', v_conv.title, 'slug', v_conv.slug, 'client_id', v_conv.client_id,
                                                               'work_item_id', v_conv.work_item_id),
                            'rows', v_n, 'messages', v_rows);
end
$$;


--
-- Name: touch_conversation_on_message(); Type: FUNCTION; Schema: comms; Owner: -
--

CREATE FUNCTION comms.touch_conversation_on_message() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'comms', 'pg_temp'
    AS $$
begin
  update comms.conversations set last_message_at = greatest(coalesce(last_message_at, new.sent_at), new.sent_at), updated_at = now()
   where id = new.conversation_id;
  return new;
end
$$;


--
-- Name: acquisition_action_decide(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.acquisition_action_decide(p_action_id uuid, p_decision text, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'spine', 'pg_temp'
    AS $$
declare
  v_a        spine.proposed_actions%rowtype;
  v_uid      uuid := auth.uid();
  v_target   uuid;
  v_patch    jsonb;
  v_sets     text[] := '{}';
  v_key      text;
  v_note_id  uuid;
  v_new_id   uuid;
  v_event    uuid;
begin
  if v_uid is null then
    raise exception 'acquisitions: a signed-in approver is required' using errcode = '42501';
  end if;
  if not public.can_view_acquisitions() then
    raise exception 'acquisitions: the acquisitions capability is required to decide' using errcode = '42501';
  end if;
  if p_decision not in ('approved','rejected') then
    raise exception 'acquisitions: decision must be approved or rejected' using errcode = '22023';
  end if;

  select * into v_a from spine.proposed_actions where id = p_action_id for update;
  if v_a.id is null then raise exception 'acquisitions: unknown proposal' using errcode = '23503'; end if;
  if v_a.action_type not in ('acquisition_target.update','acquisition_target_note.create','acquisition_target.create') then
    raise exception 'acquisitions: not an acquisitions proposal' using errcode = '22023';
  end if;
  if v_a.status <> 'pending' then
    return jsonb_build_object('status', v_a.status, 'action_id', v_a.id);
  end if;

  -- The audit triple needs an anchor (0059: a work item, or the event that
  -- spawned the run). A proposal over MCP rarely carries a work item, so the
  -- decision itself is the event: recorded as processed so dispatch never
  -- routes it, and every audit row below anchors on it.
  if v_a.work_item_id is null then
    insert into spine.events (kind, source, payload, processed_at)
    values ('acquisitions.proposal_decided', 'spine.proposed_actions',
            jsonb_build_object('action_id', v_a.id, 'action_type', v_a.action_type, 'decision', p_decision, 'reviewer', v_uid),
            now())
    returning id into v_event;
  end if;

  if p_decision = 'rejected' then
    update spine.proposed_actions
       set status = 'rejected', reviewer_id = v_uid, decided_at = now(),
           reasoning = case when p_note is null then reasoning else coalesce(reasoning, '') || E'\n\nRejected: ' || p_note end
     where id = v_a.id;
    perform spine.record_agent_audit(v_uid, v_a.identity_slug, v_a.work_item_id, 'write', 'spine.proposed_actions', 1, null, 'denied', 'rejected by reviewer', v_event);
    return jsonb_build_object('status', 'rejected', 'action_id', v_a.id);
  end if;

  if v_a.action_type = 'acquisition_target.update' then
    v_target := (v_a.payload->>'target_id')::uuid;
    v_patch  := coalesce(v_a.payload->'patch', '{}'::jsonb);
    if v_target is null or not exists (select 1 from public.acquisition_targets where id = v_target) then
      raise exception 'acquisitions: proposal names an unknown target' using errcode = '23503';
    end if;
    for v_key in select jsonb_object_keys(v_patch) loop
      if not (v_key = any (public.acquisition_patchable_columns())) then
        raise exception 'acquisitions: column % is not patchable by proposal', v_key using errcode = '42501';
      end if;
      v_sets := v_sets || format('%I = (%L::jsonb ->> %L)::%s', v_key, v_patch, v_key,
        (select format_type(a.atttypid, a.atttypmod) from pg_attribute a
          where a.attrelid = 'public.acquisition_targets'::regclass and a.attname = v_key));
    end loop;
    if array_length(v_sets, 1) is null then
      raise exception 'acquisitions: empty patch' using errcode = '22023';
    end if;
    execute format('update public.acquisition_targets set %s where id = %L', array_to_string(v_sets, ', '), v_target);
    perform spine.record_agent_audit(v_uid, v_a.identity_slug, v_a.work_item_id, 'write', 'public.acquisition_targets', 1, null, 'ok', null, v_event);

  elsif v_a.action_type = 'acquisition_target_note.create' then
    v_target := (v_a.payload->>'target_id')::uuid;
    insert into public.acquisition_target_notes
      (target_id, kind, title, body_md, severity, risk_status, author_id, identity_slug, proposed_action_id, occurred_on)
    values
      (v_target, v_a.payload->>'kind', v_a.payload->>'title', v_a.payload->>'body_md',
       v_a.payload->>'severity', v_a.payload->>'risk_status', v_uid, v_a.identity_slug, v_a.id,
       coalesce((v_a.payload->>'occurred_on')::date, current_date))
    returning id into v_note_id;
    perform spine.record_agent_audit(v_uid, v_a.identity_slug, v_a.work_item_id, 'write', 'public.acquisition_target_notes', 1, null, 'ok', null, v_event);

  else -- acquisition_target.create
    v_patch := coalesce(v_a.payload->'row', '{}'::jsonb);
    if coalesce(v_patch->>'company_name', '') = '' then
      raise exception 'acquisitions: company_name is required' using errcode = '22023';
    end if;
    for v_key in select jsonb_object_keys(v_patch) loop
      if not (v_key = any (public.acquisition_patchable_columns())) then
        raise exception 'acquisitions: column % is not settable by proposal', v_key using errcode = '42501';
      end if;
    end loop;
    insert into public.acquisition_targets (company_name, created_by, owner_profile_id)
    values (v_patch->>'company_name', v_uid, v_uid) returning id into v_new_id;
    v_patch := v_patch - 'company_name';
    if v_patch <> '{}'::jsonb then
      v_sets := '{}';
      for v_key in select jsonb_object_keys(v_patch) loop
        v_sets := v_sets || format('%I = (%L::jsonb ->> %L)::%s', v_key, v_patch, v_key,
          (select format_type(a.atttypid, a.atttypmod) from pg_attribute a
            where a.attrelid = 'public.acquisition_targets'::regclass and a.attname = v_key));
      end loop;
      execute format('update public.acquisition_targets set %s where id = %L', array_to_string(v_sets, ', '), v_new_id);
    end if;
    v_target := v_new_id;
    perform spine.record_agent_audit(v_uid, v_a.identity_slug, v_a.work_item_id, 'write', 'public.acquisition_targets', 1, null, 'ok', null, v_event);
  end if;

  update spine.proposed_actions
     set status = 'applied', reviewer_id = v_uid, decided_at = now()
   where id = v_a.id;
  return jsonb_build_object('status', 'applied', 'action_id', v_a.id, 'target_id', v_target, 'note_id', v_note_id);
end
$$;


--
-- Name: acquisition_note_touch(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.acquisition_note_touch() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.kind in ('touch','negotiation') then
    update public.acquisition_targets
       set last_touch_on = greatest(coalesce(last_touch_on, new.occurred_on), new.occurred_on)
     where id = new.target_id;
  end if;
  return new;
end
$$;


--
-- Name: acquisition_patchable_columns(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.acquisition_patchable_columns() RETURNS text[]
    LANGUAGE sql IMMUTABLE
    AS $$
  select array[
    'company_name','website','owner_name','owner_title','email','phone','linkedin_url',
    'agency_services','employee_count','founded_year','est_revenue','city','state','country','owner_signal',
    'status','fit_score','notes',
    'vertical','notable_clients','est_ebitda','financial_confidence','retainer_mix_pct','top3_concentration_pct',
    'growth_trend','management_depth','owner_readiness','sourcing_channel','relationship_warmth',
    'last_touch_on','next_action','next_action_on','hard_gate','scorecard_total','score_drivers','recommendation',
    'batna','deal_structure','deal_stage_notes'
  ]
$$;


--
-- Name: acquisition_pending_actions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.acquisition_pending_actions() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'spine', 'pg_temp'
    AS $$
begin
  if not public.can_view_acquisitions() then
    raise exception 'acquisitions: the acquisitions capability is required' using errcode = '42501';
  end if;
  return (
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', a.id, 'action_type', a.action_type, 'identity_slug', a.identity_slug,
      'display_name', i.chat_profile->>'display_name',
      'reasoning', a.reasoning, 'payload', a.payload, 'created_at', a.created_at,
      'target_id', coalesce(a.payload->>'target_id', null),
      'target_name', (select t.company_name from public.acquisition_targets t where t.id::text = a.payload->>'target_id')
    ) order by a.created_at), '[]'::jsonb)
    from spine.proposed_actions a
    join spine.agent_identities i on i.slug = a.identity_slug
    where a.status = 'pending'
      and a.action_type in ('acquisition_target.update','acquisition_target_note.create','acquisition_target.create'));
end
$$;


--
-- Name: acquisition_target_ref_default(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.acquisition_target_ref_default() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_year text := to_char(coalesce(new.created_at, now()), 'YYYY');
  v_next int;
begin
  if new.target_ref is not null then return new; end if;
  select coalesce(max(substring(target_ref from '\d+$')::int), 0) + 1 into v_next
    from public.acquisition_targets where target_ref like 'DG-' || v_year || '-%';
  new.target_ref := 'DG-' || v_year || '-' || lpad(v_next::text, 3, '0');
  return new;
end
$_$;


--
-- Name: ai_action_preapproved(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_action_preapproved(p_agent uuid, p_action_type text, p_client uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
	select r.id from public.ai_approval_rules r
	where r.agent_id = p_agent and r.action_type = p_action_type
	  and r.revoked_at is null
	  and (r.mode = 'persistent' or r.expires_at > now())
	  and (r.client_id is null or r.client_id = p_client)
	order by (r.client_id is null), r.created_at desc
	limit 1;
$$;


--
-- Name: ai_agent_can_use(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_agent_can_use(p_agent uuid, p_user uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
	select exists (
		select 1 from public.ai_agents a
		join public.profiles p on p.id = p_user and p.is_active
		where a.id = p_agent and a.is_active
		  and (p.role in ('admin', 'exec')
		    or a.access = 'everyone'
		    or (a.access = 'roles' and p.role = any (a.access_roles))
		    or (a.access = 'users' and exists (select 1 from public.ai_agent_members m where m.agent_id = a.id and m.user_id = p_user)))
	);
$$;


--
-- Name: ai_period_start(text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_period_start(p_period text, p_at timestamp with time zone DEFAULT now()) RETURNS timestamp with time zone
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
	select (date_trunc(case p_period when 'day' then 'day' when 'week' then 'week' else 'month' end,
		p_at at time zone 'America/Chicago')) at time zone 'America/Chicago';
$$;


--
-- Name: ai_record_usage(uuid, text, numeric, integer, integer, text, uuid, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_record_usage(p_user uuid, p_model text, p_cost_usd numeric, p_input_tokens integer DEFAULT 0, p_output_tokens integer DEFAULT 0, p_agent text DEFAULT NULL::text, p_client uuid DEFAULT NULL::uuid, p_feature text DEFAULT NULL::text, p_provider text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text, p_status text DEFAULT 'ok'::text, p_meta jsonb DEFAULT '{}'::jsonb) RETURNS TABLE(log_id bigint, fired_limit uuid, fired_threshold integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
	v_id bigint;
	r record;
	t integer;
	v_start timestamptz;
	v_label text;
	v_recipients uuid[];
	v_uid uuid;
begin
	insert into public.ai_usage_log (user_id, agent_slug, model, provider, client_id, feature,
		input_tokens, output_tokens, cost_usd, status, request_id, meta)
	values (p_user, p_agent, p_model, p_provider, p_client, p_feature,
		coalesce(p_input_tokens, 0), coalesce(p_output_tokens, 0), coalesce(p_cost_usd, 0),
		coalesce(p_status, 'ok'), p_request_id, coalesce(p_meta, '{}'::jsonb))
	on conflict (provider, request_id) where request_id is not null do nothing
	returning id into v_id;

	if v_id is null then
		return; -- duplicate provider request id: already logged
	end if;
	log_id := v_id;

	for r in select c.*, s.alert_thresholds, s.alert_user_ids, s.user_id as limited_user, s.model as limited_model, s.agent_slug as limited_agent
		from public.ai_spend_check(p_user, p_model, p_agent) c
		join public.ai_spend_limits s on s.id = c.limit_id
	loop
		v_start := public.ai_period_start(r.period);
		foreach t in array r.alert_thresholds loop
			continue when r.pct < t;
			insert into public.ai_spend_alerts (limit_id, period_start, threshold, spent_usd, cap_usd)
			values (r.limit_id, v_start, t, r.spent_usd, r.cap_usd)
			on conflict (limit_id, period_start, threshold) do nothing;
			if found then
				v_label := case r.scope when 'team' then 'Team AI spend'
					when 'user' then coalesce((select nullif(trim(coalesce(first_name,'') || ' ' || coalesce(last_name,'')), '') from public.profiles where id = r.limited_user), 'A user') || '''s AI spend'
					when 'model' then 'AI spend on ' || r.limited_model
					else 'AI spend by agent ' || r.limited_agent end;
				v_recipients := array(
					select distinct x from unnest(
						array(select id from public.profiles where is_active and role in ('admin', 'exec'))
						|| r.alert_user_ids
						|| case when r.scope = 'user' then array[r.limited_user] else '{}'::uuid[] end
					) x where x is not null);
				foreach v_uid in array v_recipients loop
					insert into public.notifications (user_id, kind, title, body, href, dedupe_key)
					values (v_uid, 'ai_spend_alert',
						v_label || ' reached ' || t || '%',
						'$' || to_char(r.spent_usd, 'FM999999990.00') || ' of $' || to_char(r.cap_usd, 'FM999999990.00') || ' this ' || r.period
							|| case when r.enforce and t >= 100 then '. New calls are blocked until the period resets or the cap is raised.' else '.' end,
						'/admin/ai-spend',
						'ai_spend:' || r.limit_id || ':' || v_start::date || ':' || t)
					on conflict do nothing;
				end loop;
				fired_limit := r.limit_id;
				fired_threshold := t;
				return next;
			end if;
		end loop;
	end loop;
	if fired_limit is null then
		return next; -- always return the log id
	end if;
end;
$_$;


--
-- Name: ai_spend_check(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_spend_check(p_user uuid, p_model text, p_agent text DEFAULT NULL::text) RETURNS TABLE(limit_id uuid, scope text, period text, cap_usd numeric, spent_usd numeric, pct numeric, enforce boolean, blocked boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
	with l as (
		select * from public.ai_spend_limits s
		where s.is_active
		  and s.tenant_id = spine.default_tenant_id()
		  and (s.scope = 'team'
		    or (s.scope = 'user' and s.user_id = p_user)
		    or (s.scope = 'model' and s.model = p_model)
		    or (s.scope = 'agent' and s.agent_slug = p_agent))
	)
	select l.id, l.scope, l.period, l.cap_usd, x.spent,
		round(100 * x.spent / l.cap_usd, 2),
		l.enforce,
		(l.enforce and x.spent >= l.cap_usd)
	from l
	cross join lateral (
		select coalesce(sum(u.cost_usd), 0)::numeric as spent
		from public.ai_usage_log u
		where u.tenant_id = l.tenant_id
		  and u.occurred_at >= public.ai_period_start(l.period)
		  and u.status <> 'blocked'
		  and (l.scope = 'team'
		    or (l.scope = 'user' and u.user_id = l.user_id)
		    or (l.scope = 'model' and u.model = l.model)
		    or (l.scope = 'agent' and u.agent_slug = l.agent_slug))
	) x;
$$;


--
-- Name: approve_media_record(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_media_record(p_record uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  r           public.scraped_records%rowtype;
  v_job_kind  text;
  v_domain    text;
  v_email     text;
  v_outlet_id uuid;
  v_contact   uuid;
  v_first     text;
  v_last      text;
  v_display   text;
  v_last_seen timestamptz;
  v_created   boolean := false;
begin
  if not public.can_review_media_records() then
    raise exception 'You do not hold the review_media_records capability.'
      using errcode = 'insufficient_privilege';
  end if;

  select * into r from public.scraped_records where id = p_record for update;
  if not found then
    raise exception 'scraped record % not found', p_record using errcode = 'no_data_found';
  end if;
  select kind into v_job_kind from public.scrape_jobs where id = r.job_id;
  if v_job_kind is distinct from 'media' or r.kind not in ('media_contact', 'media_outlet') then
    raise exception 'record % is not a media row', p_record using errcode = 'check_violation';
  end if;

  -- Already decided: report, do not write.
  if r.status = 'approved' then
    return jsonb_build_object('record', r.id, 'status', 'already_approved',
      'contact_id', r.approved_contact_id, 'outlet_id', r.approved_outlet_id);
  end if;
  if r.status = 'rejected' then
    raise exception 'record % was rejected; reopen it before approving', p_record using errcode = 'check_violation';
  end if;

  v_domain := nullif(lower(trim(coalesce(r.outlet_domain, r.company_domain))), '');
  v_email  := nullif(lower(trim(r.email)), '');

  -- ---- Outlet (both kinds) ------------------------------------------------
  if v_domain is not null then
    insert into public.media_outlets (name, website, domain, categories, source, contact_email, linkedin_url, created_by)
    values (
      coalesce(nullif(trim(r.outlet_name), ''), nullif(trim(r.company_name), ''), v_domain),
      coalesce(r.company_website, 'https://' || v_domain),
      v_domain,
      coalesce(r.beats, '{}'),
      'scraper',
      case when r.kind = 'media_outlet' then v_email else null end,
      case when r.kind = 'media_outlet' then r.company_linkedin else null end,
      auth.uid()
    )
    on conflict (domain) where domain is not null do update
      set name          = case when public.media_outlets.name = public.media_outlets.domain then excluded.name else public.media_outlets.name end,
          website       = coalesce(public.media_outlets.website, excluded.website),
          categories    = (select array_agg(distinct c) from unnest(public.media_outlets.categories || excluded.categories) as c),
          contact_email = coalesce(public.media_outlets.contact_email, excluded.contact_email),
          linkedin_url  = coalesce(public.media_outlets.linkedin_url, excluded.linkedin_url)
    returning id into v_outlet_id;
  elsif r.kind = 'media_outlet' and nullif(trim(r.outlet_name), '') is not null then
    -- An outlet with no domain (rare: Google News gave a name only). Match
    -- by name, else insert without a domain.
    select id into v_outlet_id from public.media_outlets
     where lower(name) = lower(trim(r.outlet_name)) limit 1;
    if v_outlet_id is null then
      insert into public.media_outlets (name, categories, source, contact_email, created_by)
      values (trim(r.outlet_name), coalesce(r.beats, '{}'), 'scraper', v_email, auth.uid())
      returning id into v_outlet_id;
    end if;
  end if;

  if r.kind = 'media_outlet' then
    update public.scraped_records
       set status = 'approved', reviewed_by = auth.uid(), reviewed_at = now(),
           approved_outlet_id = v_outlet_id
     where id = r.id;
    return jsonb_build_object('record', r.id, 'status', 'approved', 'outlet_id', v_outlet_id, 'contact_id', null);
  end if;

  -- ---- Contact (media_contact) --------------------------------------------
  v_first   := nullif(trim(r.first_name), '');
  v_last    := nullif(trim(r.last_name), '');
  v_display := coalesce(nullif(trim(r.full_name), ''), nullif(trim(concat_ws(' ', v_first, v_last)), ''), v_email);
  if v_display is null then
    raise exception 'record % has neither a name nor an email', p_record using errcode = 'check_violation';
  end if;

  if v_email is not null then
    select id into v_contact from public.contacts where lower(email) = v_email limit 1;
  end if;
  if v_contact is null and v_email is null then
    select id into v_contact from public.contacts c
     where lower(c.display_name) = lower(v_display)
       and (r.outlet_name is null or lower(coalesce(c.organization, '')) = lower(r.outlet_name))
     limit 1;
  end if;

  if v_contact is null then
    insert into public.contacts (display_name, first_name, last_name, email, title, organization, linkedin_url)
    values (v_display, v_first, v_last, v_email, r.job_title, nullif(trim(r.outlet_name), ''), r.linkedin_url)
    returning id into v_contact;
    v_created := true;
  else
    -- Fill blanks only.
    update public.contacts c
       set first_name   = coalesce(c.first_name, v_first),
           last_name    = coalesce(c.last_name, v_last),
           email        = coalesce(c.email, v_email),
           title        = coalesce(c.title, r.job_title),
           organization = coalesce(c.organization, nullif(trim(r.outlet_name), '')),
           linkedin_url = coalesce(c.linkedin_url, r.linkedin_url)
     where c.id = v_contact;
  end if;

  insert into public.contact_roles (contact_id, role)
  values (v_contact, 'journalist')
  on conflict (contact_id, role) do nothing;

  -- Newest article date is the last-seen signal.
  select max(nullif(e ->> 'date', '')::timestamptz) into v_last_seen
    from jsonb_array_elements(coalesce(r.evidence, '[]'::jsonb)) as e
   where (e ->> 'date') ~ '^\d{4}-\d{2}-\d{2}';

  insert into public.media_contact_profiles
    (contact_id, outlet_id, beats, recent_articles, email_status, last_seen_at, source, scraped_record_id)
  values
    (v_contact, v_outlet_id, coalesce(r.beats, '{}'), coalesce(r.evidence, '[]'::jsonb),
     case when r.email_status in ('verified', 'likely', 'pattern_guess', 'not_found') then r.email_status
          when r.email_status in ('article_page', 'author_or_contact_page') then 'verified'
          when v_email is null then 'not_found'
          else null end,
     v_last_seen, 'scraper', r.id)
  on conflict (contact_id) do update
    set outlet_id       = coalesce(public.media_contact_profiles.outlet_id, excluded.outlet_id),
        beats           = (select array_agg(distinct b) from unnest(public.media_contact_profiles.beats || excluded.beats) as b),
        recent_articles = (
          select coalesce(jsonb_agg(a), '[]'::jsonb) from (
            select distinct on (a ->> 'url') a
              from jsonb_array_elements(public.media_contact_profiles.recent_articles || excluded.recent_articles) as a
             order by a ->> 'url', a ->> 'date' desc
          ) s),
        email_status    = coalesce(excluded.email_status, public.media_contact_profiles.email_status),
        last_seen_at    = greatest(public.media_contact_profiles.last_seen_at, excluded.last_seen_at),
        scraped_record_id = excluded.scraped_record_id;

  update public.scraped_records
     set status = 'approved', reviewed_by = auth.uid(), reviewed_at = now(),
         approved_contact_id = v_contact, approved_outlet_id = v_outlet_id
   where id = r.id;

  return jsonb_build_object('record', r.id, 'status', 'approved',
    'contact_id', v_contact, 'outlet_id', v_outlet_id, 'contact_created', v_created);
end;
$$;


--
-- Name: approve_media_records(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_media_records(p_records uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_id      uuid;
  v_out     jsonb := '[]'::jsonb;
  v_one     jsonb;
  v_contacts int := 0;
  v_outlets  int := 0;
begin
  if not public.can_review_media_records() then
    raise exception 'You do not hold the review_media_records capability.'
      using errcode = 'insufficient_privilege';
  end if;
  if p_records is null or array_length(p_records, 1) is null then
    return jsonb_build_object('approved', 0, 'results', v_out);
  end if;
  if array_length(p_records, 1) > 500 then
    raise exception 'approve at most 500 records per call' using errcode = 'check_violation';
  end if;
  foreach v_id in array p_records loop
    v_one := public.approve_media_record(v_id);
    v_out := v_out || v_one;
    if v_one ->> 'status' = 'approved' then
      if (v_one ->> 'contact_id') is not null then v_contacts := v_contacts + 1; end if;
      if (v_one ->> 'outlet_id')  is not null then v_outlets  := v_outlets  + 1; end if;
    end if;
  end loop;
  return jsonb_build_object(
    'approved', (select count(*) from jsonb_array_elements(v_out) e where e ->> 'status' = 'approved'),
    'contacts', v_contacts, 'outlets', v_outlets, 'results', v_out);
end;
$$;


--
-- Name: attendance_business_days(date, date, smallint[], jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.attendance_business_days(p_from date, p_to date, p_work_days smallint[] DEFAULT '{1,2,3,4,5}'::smallint[], p_holidays jsonb DEFAULT '[]'::jsonb) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select count(*)::numeric
    from generate_series(p_from, p_to, interval '1 day') g(d)
   where extract(isodow from g.d)::smallint = any(p_work_days)
     and not exists (select 1 from jsonb_array_elements(coalesce(p_holidays, '[]'::jsonb)) h where (h->>'date')::date = g.d::date)
$$;


--
-- Name: attendance_policy_for(uuid, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.attendance_policy_for(p_profile uuid, p_year smallint) RETURNS uuid
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v uuid; v_emp text; v_region text;
begin
  select policy_id into v from public.attendance_balances where profile_id = p_profile and year = p_year;
  if v is not null then return v; end if;
  select o.employment_type, o.region into v_emp, v_region from public.hire_offers o where o.hired_profile_id = p_profile order by o.decided_at desc nulls last limit 1;
  if v_emp is not null then
    select id into v from public.attendance_policies where is_active and v_emp = any(employment) and region in (v_region, 'any') order by case when region = v_region then 0 else 1 end, is_default desc limit 1;
    if v is not null then return v; end if;
  end if;
  select id into v from public.attendance_policies where is_active and is_default limit 1;
  return v;
end;
$$;


--
-- Name: attendance_summary(smallint, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.attendance_summary(p_year smallint DEFAULT (EXTRACT(year FROM CURRENT_DATE))::smallint, p_as_of date DEFAULT CURRENT_DATE) RETURNS TABLE(profile_id uuid, first_name text, last_name text, email text, department_tag_id uuid, manager_id uuid, date_started date, is_active boolean, policy_id uuid, policy_key text, policy_label text, accrual_days_per_year numeric, waiting_period_days smallint, eligible_from date, accrued_days numeric, opening_days numeric, adjustment_days numeric, used_pto_days numeric, pending_pto_days numeric, sick_days numeric, unpaid_days numeric, late_count integer, balance_days numeric, can_see_balance boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare y_start date := make_date(p_year, 1, 1); y_end date := make_date(p_year, 12, 31); v_mgr boolean; v_uid uuid := auth.uid();
begin
  v_mgr := v_uid is null or public.can_manage_attendance();
  return query
  with ppl as (
    select p.id, p.first_name, p.last_name, p.email, p.department_tag_id, p.manager_id, p.date_started, p.is_active
      from public.profiles p
     where p.is_active or exists (select 1 from public.time_off t where t.user_id = p.id and t.starts_on between y_start and y_end)
  ),
  pol as (
    select ppl.id as pid, ap.* from ppl left join public.attendance_policies ap on ap.id = public.attendance_policy_for(ppl.id, p_year)
  ),
  used as (
    -- distinct calendar days per person so overlapping rows (calendar-promoted
    -- OOO events carry an EXCLUSIVE end date and chain day to day) count once
    select d.user_id,
           count(*) filter (where d.bucket = 'pto')::numeric as pto,
           count(*) filter (where d.bucket = 'sick')::numeric as sick,
           count(*) filter (where d.bucket = 'pending')::numeric as pending
      from (
        select distinct t.user_id, g.d::date as day,
               case when t.status = 'pending' then 'pending' when t.kind = 'sick' then 'sick' else 'pto' end as bucket
          from public.time_off t
          join pol on pol.pid = t.user_id
          cross join lateral generate_series(greatest(t.starts_on, y_start)::timestamp,
                                             least(case when t.source = 'calendar_event' and t.ends_on > t.starts_on then t.ends_on - 1 else t.ends_on end, y_end)::timestamp,
                                             interval '1 day') g(d)
         where t.status in ('approved', 'pending') and t.counts_as_pto
           and t.starts_on <= y_end and t.ends_on >= y_start
           and extract(isodow from g.d)::smallint = any(coalesce(pol.work_days, '{1,2,3,4,5}'))
           and not exists (select 1 from jsonb_array_elements(coalesce(pol.holidays, '[]'::jsonb)) h where (h->>'date')::date = g.d::date)
      ) d
     group by d.user_id
  ),
  pend_req as (
    select r.requester_id as user_id,
           sum(public.attendance_business_days(greatest((r.payload->>'starts_on')::date, y_start), least(coalesce((r.payload->>'ends_on')::date, (r.payload->>'starts_on')::date), y_end), coalesce(pol.work_days, '{1,2,3,4,5}'), coalesce(pol.holidays, '[]'::jsonb))) as pending
      from public.staff_requests r join pol on pol.pid = r.requester_id
     where r.kind = 'time_off' and r.status in ('pending', 'in_review') and (r.payload->>'starts_on') is not null
       and (r.payload->>'starts_on')::date <= y_end and coalesce((r.payload->>'ends_on')::date, (r.payload->>'starts_on')::date) >= y_start
     group by r.requester_id
  ),
  ev as (
    select e.profile_id,
           sum(case when e.kind = 'sick' then coalesce(e.hours / 8, 1) else 0 end) as sick,
           sum(case when e.kind = 'unpaid' or e.kind = 'absent' then coalesce(e.hours / 8, 1) else 0 end) as unpaid,
           count(*) filter (where e.kind = 'late')::int as late
      from public.attendance_events e where e.on_date between y_start and y_end group by e.profile_id
  )
  select ppl.id, ppl.first_name, ppl.last_name, ppl.email, ppl.department_tag_id, ppl.manager_id, ppl.date_started, ppl.is_active,
         pol.id, pol.key, pol.label, pol.accrual_days_per_year, pol.waiting_period_days,
         case when ppl.date_started is not null and pol.waiting_period_days is not null then ppl.date_started + pol.waiting_period_days end as eligible_from,
         case
           when pol.accrual_method = 'none' or pol.accrual_days_per_year is null then 0
           when pol.accrual_method = 'upfront' then pol.accrual_days_per_year
           else round(pol.accrual_days_per_year * greatest(0, least(p_as_of, y_end) - greatest(coalesce(ppl.date_started, y_start), y_start) + 1) / (y_end - y_start + 1), 2)
         end as accrued_days,
         coalesce(b.opening_days, 0), coalesce(b.adjustment_days, 0),
         coalesce(used.pto, 0), coalesce(used.pending, 0) + coalesce(pend_req.pending, 0),
         coalesce(used.sick, 0) + coalesce(ev.sick, 0), coalesce(ev.unpaid, 0), coalesce(ev.late, 0),
         round(coalesce(b.opening_days, 0) + coalesce(b.adjustment_days, 0)
           + case when pol.accrual_method = 'none' or pol.accrual_days_per_year is null then 0 when pol.accrual_method = 'upfront' then pol.accrual_days_per_year
                  else pol.accrual_days_per_year * greatest(0, least(p_as_of, y_end) - greatest(coalesce(ppl.date_started, y_start), y_start) + 1) / (y_end - y_start + 1) end
           - coalesce(used.pto, 0) - case when coalesce(pol.sick_days_per_year, 0) = 0 then coalesce(used.sick, 0) else 0 end, 2) as balance_days,
         (v_mgr or ppl.id = v_uid or ppl.manager_id = v_uid) as can_see_balance
    from ppl
    left join pol on pol.pid = ppl.id
    left join public.attendance_balances b on b.profile_id = ppl.id and b.year = p_year
    left join used on used.user_id = ppl.id
    left join pend_req on pend_req.user_id = ppl.id
    left join ev on ev.profile_id = ppl.id
   order by ppl.first_name, ppl.last_name;
end;
$$;


