    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select 'a7f0f5c2-0000-4000-8000-000000000001'::uuid
$$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: automation_runs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.automation_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid DEFAULT spine.default_tenant_id() NOT NULL,
    rule_id uuid NOT NULL,
    status text DEFAULT 'queued'::text NOT NULL,
    trigger_payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    step_results jsonb DEFAULT '[]'::jsonb NOT NULL,
    current_step integer DEFAULT 0 NOT NULL,
    wake_at timestamp with time zone,
    error text,
    requested_by uuid,
    requested_via text DEFAULT 'cron'::text NOT NULL,
    approved_by uuid,
    approved_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    started_at timestamp with time zone,
    finished_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT automation_runs_current_step_check CHECK ((current_step >= 0)),
    CONSTRAINT automation_runs_payload_size CHECK ((pg_column_size(trigger_payload) <= 65536)),
    CONSTRAINT automation_runs_requested_via_check CHECK ((requested_via = ANY (ARRAY['ui'::text, 'mcp'::text, 'skill'::text, 'cron'::text, 'system'::text]))),
    CONSTRAINT automation_runs_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'running'::text, 'waiting_approval'::text, 'approved'::text, 'rejected'::text, 'done'::text, 'failed'::text, 'cancelled'::text])))
);


--
-- Name: automation_rule_run_now(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.automation_rule_run_now(p_rule_id uuid, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS public.automation_runs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_run public.automation_runs;
begin
  if not public.can_manage_automations() then
    raise exception 'automations: not allowed' using errcode = '42501';
  end if;
  insert into public.automation_runs (rule_id, trigger_payload, requested_by, requested_via)
  values (p_rule_id, jsonb_build_object('manual', true) || coalesce(p_payload, '{}'::jsonb), auth.uid(), 'ui')
  returning * into v_run;
  return v_run;
end;
$$;


--
-- Name: automation_run_cancel(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.automation_run_cancel(p_id uuid) RETURNS public.automation_runs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_run public.automation_runs;
begin
  select * into v_run from public.automation_runs where id = p_id for update;
  if not found then raise exception 'automations: run not found' using errcode = 'P0002'; end if;
  if not (public.can_manage_automations() or v_run.requested_by = auth.uid()) then
    raise exception 'automations: not allowed' using errcode = '42501';
  end if;
  update public.automation_runs set status = 'cancelled' where id = p_id returning * into v_run;
  return v_run;
end;
$$;


--
-- Name: automation_run_decide(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.automation_run_decide(p_id uuid, p_decision text, p_note text DEFAULT NULL::text) RETURNS public.automation_runs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_run public.automation_runs; v_group text;
begin
  if p_decision not in ('approved', 'rejected') then
    raise exception 'automations: decision must be approved or rejected' using errcode = '22023';
  end if;
  select * into v_run from public.automation_runs where id = p_id for update;
  if not found then raise exception 'automations: run not found' using errcode = 'P0002'; end if;
  select approver_group into v_group from public.automation_rules where id = v_run.rule_id;
  if not (public.can_manage_automations() or public.is_reviewer_by_key(v_group)) then
    raise exception 'automations: not an approver for this run' using errcode = '42501';
  end if;
  update public.automation_runs
     set status = p_decision,
         step_results = case when p_note is null then step_results
                             else step_results || jsonb_build_array(jsonb_build_object('type', 'decision', 'note', p_note)) end
   where id = p_id
   returning * into v_run;
  return v_run;
end;
$$;


--
-- Name: automation_run_retry(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.automation_run_retry(p_id uuid) RETURNS public.automation_runs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_run public.automation_runs;
begin
  select * into v_run from public.automation_runs where id = p_id for update;
  if not found then raise exception 'automations: run not found' using errcode = 'P0002'; end if;
  if not public.can_manage_automations() then
    raise exception 'automations: not allowed' using errcode = '42501';
  end if;
  update public.automation_runs set status = 'queued' where id = p_id returning * into v_run;
  return v_run;
end;
$$;


--
-- Name: bot_fleet_sync(text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_fleet_sync(p_host text, p_hermes_version text, p_profiles jsonb, p_catalog jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_p        jsonb;
  v_name     text;
  v_seen     text[] := '{}';
  v_inserted int := 0;
  v_updated  int := 0;
  v_retired  int := 0;
begin
  if auth.uid() is not null then
    raise exception 'bot_fleet_sync is service-role only' using errcode = '42501';
  end if;
  if p_profiles is null or jsonb_typeof(p_profiles) <> 'array' then
    raise exception 'profiles must be a JSON array' using errcode = '22023';
  end if;

  for v_p in select * from jsonb_array_elements(p_profiles) loop
    v_name := v_p->>'name';
    if v_name is null or v_name !~ '^[a-z0-9][a-z0-9_-]{0,63}$' then
      continue;
    end if;
    v_seen := v_seen || v_name;
    if exists (select 1 from public.bot_profiles where name = v_name) then
      update public.bot_profiles
         set observed        = coalesce(v_p->'observed', '{}'::jsonb),
             observed_at     = now(),
             gateway_running = (v_p->>'gateway_running')::boolean,
             display_name    = coalesce(display_name, nullif(v_p->>'display_name', '')),
             role_description = coalesce(role_description, nullif(v_p->>'description', '')),
             -- pending stays pending (the bridge acks it); everything else reflects reality
             status          = case when status = 'pending' then 'pending' else 'applied' end
       where name = v_name;
      v_updated := v_updated + 1;
    else
      insert into public.bot_profiles (name, display_name, role_description, desired, observed, observed_at, gateway_running, status)
      values (v_name, nullif(v_p->>'display_name', ''), nullif(v_p->>'description', ''),
              coalesce(v_p->'observed', '{}'::jsonb), coalesce(v_p->'observed', '{}'::jsonb), now(),
              (v_p->>'gateway_running')::boolean, 'applied');
      v_inserted := v_inserted + 1;
    end if;
  end loop;

  update public.bot_profiles
     set status = 'retired', gateway_running = false
   where observed_at is not null
     and status in ('applied')
     and not (name = any (v_seen));
  get diagnostics v_retired = row_count;

  if p_catalog is not null and jsonb_typeof(p_catalog) = 'object' then
    insert into public.bot_fleet_state (key, value, updated_at)
    values ('catalog', p_catalog, now())
    on conflict (key) do update set value = excluded.value, updated_at = now();
  end if;
  insert into public.bot_fleet_state (key, value, updated_at)
  values ('last_sync', jsonb_build_object('host', p_host, 'hermes_version', p_hermes_version,
                                          'at', now(), 'profile_count', coalesce(jsonb_array_length(p_profiles), 0)), now())
  on conflict (key) do update set value = excluded.value, updated_at = now();

  return jsonb_build_object('inserted', v_inserted, 'updated', v_updated, 'retired', v_retired);
end
$_$;


--
-- Name: bot_profile_upsert(text, text, text, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_profile_upsert(p_name text, p_display_name text, p_role text, p_desired jsonb, p_ops jsonb, p_soul_md text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_bot     public.bot_profiles%rowtype;
  v_op      text;
  v_req     uuid;
  v_payload jsonb;
begin
  if not public.is_admin() then
    raise exception 'bot_profile_upsert: exec or admin only' using errcode = '42501';
  end if;
  if p_name is null or p_name !~ '^[a-z0-9][a-z0-9_-]{0,63}$' then
    raise exception 'bot name must be lowercase letters, numbers, - or _, up to 64 characters' using errcode = '22023';
  end if;
  if p_name in ('default','hermes','python','node','git','sh','bash','cmd') then
    raise exception 'bot name % is reserved', p_name using errcode = '22023';
  end if;
  if p_desired is null or jsonb_typeof(p_desired) <> 'object' then
    raise exception 'desired must be a JSON object' using errcode = '22023';
  end if;
  if p_ops is null or jsonb_typeof(p_ops) <> 'array' then
    raise exception 'ops must be a JSON array' using errcode = '22023';
  end if;

  select * into v_bot from public.bot_profiles where name = p_name;
  if v_bot.id is null then
    v_op := 'create';
    insert into public.bot_profiles (name, display_name, role_description, desired, desired_updated_at, desired_updated_by, status, created_by)
    values (p_name, nullif(trim(p_display_name), ''), nullif(trim(p_role), ''), p_desired, now(), auth.uid(), 'pending', auth.uid())
    returning * into v_bot;
  else
    -- A profile the bridge has seen exists on the host: an edit is an update.
    -- A draft/failed row that never landed is re-created.
    v_op := case when v_bot.observed_at is not null or v_bot.status = 'applied' then 'update' else 'create' end;
    update public.bot_profiles
       set display_name       = nullif(trim(p_display_name), ''),
           role_description   = nullif(trim(p_role), ''),
           desired            = p_desired,
           desired_updated_at = now(),
           desired_updated_by = auth.uid(),
           status             = 'pending',
           last_error         = null
     where id = v_bot.id
     returning * into v_bot;
  end if;

  v_payload := jsonb_build_object(
    'desired', p_desired,
    'ops', p_ops,
    'description', nullif(trim(p_role), ''),
    'soul_md', p_soul_md);

  update public.bot_provision_requests
     set payload = v_payload, op = v_op, requested_by = auth.uid(), requested_at = now()
   where bot_id = v_bot.id and status = 'pending'
   returning id into v_req;
  if v_req is null then
    insert into public.bot_provision_requests (bot_id, bot_name, op, payload, requested_by)
    values (v_bot.id, v_bot.name, v_op, v_payload, auth.uid())
    returning id into v_req;
  end if;

  return jsonb_build_object('bot_id', v_bot.id, 'request_id', v_req, 'op', v_op);
end
$_$;


--
-- Name: bot_request_ack(uuid, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_request_ack(p_id uuid, p_status text, p_result jsonb DEFAULT NULL::jsonb, p_error text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_req public.bot_provision_requests%rowtype;
begin
  if auth.uid() is not null then
    raise exception 'bot_request_ack is service-role only' using errcode = '42501';
  end if;
  if p_status not in ('applied','failed') then
    raise exception 'status must be applied or failed' using errcode = '22023';
  end if;
  update public.bot_provision_requests
     set status = p_status, applied_at = now(), result = p_result, error = left(p_error, 4000)
   where id = p_id and status = 'pending'
   returning * into v_req;
  if v_req.id is null then
    raise exception 'no pending request %', p_id using errcode = 'P0002';
  end if;
  update public.bot_profiles
     set status     = p_status,
         last_error = case when p_status = 'failed' then left(p_error, 4000) else null end
   where id = v_req.bot_id;
  return jsonb_build_object('id', v_req.id, 'bot_name', v_req.bot_name, 'status', v_req.status);
end
$$;


--
-- Name: bot_provision_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bot_provision_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid DEFAULT spine.default_tenant_id() NOT NULL,
    bot_id uuid NOT NULL,
    bot_name text NOT NULL,
    op text NOT NULL,
    payload jsonb NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    requested_by uuid,
    requested_at timestamp with time zone DEFAULT now() NOT NULL,
    applied_at timestamp with time zone,
    result jsonb,
    error text,
    CONSTRAINT bot_provision_requests_op_check CHECK ((op = ANY (ARRAY['create'::text, 'update'::text]))),
    CONSTRAINT bot_provision_requests_payload_check CHECK ((jsonb_typeof(payload) = 'object'::text)),
    CONSTRAINT bot_provision_requests_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'applied'::text, 'failed'::text])))
);




--
-- Name: bot_requests_pending(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_requests_pending(p_limit integer DEFAULT 20) RETURNS SETOF public.bot_provision_requests
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select * from public.bot_provision_requests
   where status = 'pending' and auth.uid() is null
   order by requested_at
   limit greatest(1, least(coalesce(p_limit, 20), 100));
$$;


--
-- Name: bot_set_consumer_scopes(text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bot_set_consumer_scopes(p_slug text, p_scopes text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_row public.mcp_consumers%rowtype;
begin
  if not public.is_admin() then
    raise exception 'bot_set_consumer_scopes: exec or admin only' using errcode = '42501';
  end if;
  if not public.mcp_scopes_ok(coalesce(p_scopes, '{}'::text[])) then
    raise exception 'scopes contains an unknown scope' using errcode = '22023';
  end if;
  update public.mcp_consumers
     set scopes = coalesce(p_scopes, '{}'::text[])
   where slug = p_slug and revoked_at is null
   returning * into v_row;
  if v_row.id is null then
    raise exception 'no live consumer with slug %', p_slug using errcode = 'P0002';
  end if;
  return jsonb_build_object('slug', v_row.slug, 'scopes', to_jsonb(v_row.scopes), 'identity_slug', v_row.identity_slug);
end
$$;


--
-- Name: calendar_events_meeting_links(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calendar_events_meeting_links() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
begin
  if new.recurring_event_id is null and new.source = 'google' and new.external_id is not null then
    new.recurring_event_id := substring(new.external_id from '^(.+)_[0-9]{8}(?:T[0-9]{6}Z)?$');
  end if;
  -- Recomputed from the emails every time they change: nothing else writes
  -- this column, so a removed invitee drops out too.
  new.attendee_user_ids := public.meeting_profile_ids_for_emails(new.attendee_external);
  return new;
end;
$_$;


--
-- Name: calibration_compute_totals(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calibration_compute_totals(p_score uuid) RETURNS TABLE(total numeric, core_total numeric, performance_total numeric, professional_total numeric, answered integer, expected integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with q as (
    select cq.id, cq.group_key, cq.weight, a.rating
      from public.calibration_scores s
      join public.calibration_cycle_questions cq on cq.cycle_id = s.cycle_id
      left join public.calibration_answers a on a.score_id = s.id and a.cycle_question_id = cq.id
     where s.id = p_score
  )
  select round(coalesce(sum(rating::numeric / 5 * weight), 0), 2),
         round(coalesce(sum(rating::numeric / 5 * weight) filter (where group_key = 'core'), 0), 2),
         round(coalesce(sum(rating::numeric / 5 * weight) filter (where group_key = 'performance'), 0), 2),
         round(coalesce(sum(rating::numeric / 5 * weight) filter (where group_key = 'professional'), 0), 2),
         count(rating)::int,
         count(*)::int
    from q
$$;


--
-- Name: calibration_cycles_snapshot_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calibration_cycles_snapshot_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  perform public.calibration_snapshot_cycle(new.id);
  return new;
end;
$$;


--
-- Name: calibration_resnapshot_cycle(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calibration_resnapshot_cycle(p_cycle uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_status text;
begin
  if auth.uid() is not null and not public.is_admin() then
    raise exception 'only an admin re-syncs cycle questions' using errcode = '42501';
  end if;
  select status into v_status from public.calibration_cycles where id = p_cycle;
  if v_status is distinct from 'open' then
    raise exception 'only an open cycle can be re-synced';
  end if;
  if exists (select 1 from public.calibration_scores s where s.cycle_id = p_cycle) then
    raise exception 'this cycle already has scores; its questions are frozen';
  end if;
  delete from public.calibration_cycle_questions where cycle_id = p_cycle;
  return public.calibration_snapshot_cycle(p_cycle);
end;
$$;


--
-- Name: calibration_snapshot_cycle(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calibration_snapshot_cycle(p_cycle uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_n int;
begin
  insert into public.calibration_cycle_questions
    (cycle_id, question_id, key, group_key, label, prompt, weight, position, rubric)
  select p_cycle, q.id, q.key, q.group_key, q.label, q.prompt, q.weight, q.position, q.rubric
    from public.calibration_questions q
   where q.is_active
  on conflict (cycle_id, key) do nothing;
  get diagnostics v_n = row_count;
  return v_n;
end;
$$;


