--
-- Name: call_analysis_attention_valid(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.call_analysis_attention_valid(attention_points jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select
    jsonb_typeof(attention_points) = 'array'
    and not exists (
      select 1 from jsonb_array_elements(attention_points) a
      where a->>'severity' not in ('info','warning','critical')
         or jsonb_typeof(a->'point') is distinct from 'string'
    )
$$;


--
-- Name: call_analysis_dimensions_valid(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.call_analysis_dimensions_valid(dimensions jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select
    jsonb_typeof(dimensions) = 'array'
    and jsonb_array_length(dimensions) > 0
    and not exists (
      select 1 from jsonb_array_elements(dimensions) d
      where jsonb_typeof(d->'dimension') is distinct from 'string'
         or jsonb_typeof(d->'note') is distinct from 'string'
         or (
           case when jsonb_typeof(d->'score') <> 'number'
                then true
                else (d->>'score')::numeric not between 0 and 10
           end
         )
    )
$$;


--
-- Name: calls_preserve_meeting_links(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calls_preserve_meeting_links() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  -- The merge rules below exist for the ingest re-sends (n8n / inbox push),
  -- which write as the service role (auth.uid() is null). A signed-in person
  -- editing a call sets every column verbatim: an admin must be able to drop
  -- a wrongly matched attendee, clear a bad series link or retype a call.
  if auth.uid() is not null then
    if new.call_type is distinct from old.call_type and new.call_type_source is not distinct from old.call_type_source then
      new.call_type_source := 'manual';
      new.call_type_reason := null;
    end if;
    return new;
  end if;
  if new.call_type = 'untyped' and old.call_type <> 'untyped' then
    -- A re-send that does not know the type must not erase one we derived.
    new.call_type        := old.call_type;
    new.call_type_source := old.call_type_source;
    new.call_type_reason := old.call_type_reason;
  elsif new.call_type is distinct from old.call_type
        and old.call_type <> 'untyped'
        and new.call_type_source is not distinct from old.call_type_source
        and old.call_type_source <> 'sender' then
    -- The sender now supplies a real type over a rule/manual one: the sender
    -- wins (it saw the meeting), and the provenance says so.
    new.call_type_source := 'sender';
    new.call_type_reason := null;
  end if;
  -- A matched person is never dropped by a re-send.
  new.attendee_user_ids := array(
    select distinct x from unnest(coalesce(old.attendee_user_ids, '{}') || coalesce(new.attendee_user_ids, '{}')) x
  );
  new.title             := coalesce(new.title, old.title);
  new.summary_md        := coalesce(new.summary_md, old.summary_md);
  new.calendar_event_id := coalesce(new.calendar_event_id, old.calendar_event_id);
  new.series_id         := coalesce(new.series_id, old.series_id);
  new.host_user_id      := coalesce(new.host_user_id, old.host_user_id);
  return new;
end;
$$;


