--
-- Name: checkin_focus_cap(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkin_focus_cap() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
	if (select count(*) from public.checkin_focus where checkin_id = new.checkin_id) >= 3 then
		raise exception 'Pick at most 3 focus items' using errcode = '23514';
	end if;
	return new;
end;
$$;


--
-- Name: checkin_is_submitted(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkin_is_submitted(checkin uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1 from public.weekly_checkins c
    where c.id = checkin and c.status = 'submitted'
  )
$$;


--
-- Name: checkin_latest_open_week_end(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkin_latest_open_week_end() RETURNS date
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case
    when now() >= public.checkin_opens_at(public.checkin_current_week_end())
      then public.checkin_current_week_end()
    else public.checkin_current_week_end() - 7
  end
$$;


--
-- Name: checkin_missing_for_week(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkin_missing_for_week(week date) RETURNS SETOF uuid
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select u
  from public.checkin_expected_users() u
  where not exists (
    select 1 from public.weekly_checkins c
    where c.user_id = u
      and c.week_end = week
      and c.status = 'submitted'
  )
$$;


--
-- Name: checkin_open_prior_weeks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkin_open_prior_weeks() RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$ select 2 $$;


--
-- Name: checkin_opens_at(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkin_opens_at(week date) RETURNS timestamp with time zone
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select (week + time '09:15') at time zone public.company_timezone()
$$;


--
-- Name: checkin_week_end(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkin_week_end(d date) RETURNS date
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select d + ((5 - extract(isodow from d)::int + 7) % 7)
$$;


--
-- Name: checkin_week_is_open(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkin_week_is_open(week date) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select week <= public.checkin_latest_open_week_end()
     and week >= public.checkin_latest_open_week_end() - 7 * public.checkin_open_prior_weeks()
$$;


--
-- Name: checkin_window(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkin_window() RETURNS TABLE(current_week_end date, latest_open_week_end date, current_opens_at timestamp with time zone, open_prior_weeks integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select
    public.checkin_current_week_end(),
    public.checkin_latest_open_week_end(),
    public.checkin_opens_at(public.checkin_current_week_end()),
    public.checkin_open_prior_weeks()
$$;


--
-- Name: client_ticket_assign(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_ticket_assign(p_id uuid, p_assignee_id uuid, p_linked_task_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := auth.uid();
begin
  if v_me is null or not public.is_admin() then
    raise exception 'client_tickets: admin only' using errcode = '42501';
  end if;
  if not exists (select 1 from public.client_tickets where id = p_id) then
    raise exception 'client_tickets: unknown ticket' using errcode = '23503';
  end if;
  if p_assignee_id is not null and not exists (select 1 from public.profiles where id = p_assignee_id and is_active) then
    raise exception 'client_tickets: unknown assignee' using errcode = '23503';
  end if;
  if p_linked_task_id is not null and not exists (select 1 from public.projects where id = p_linked_task_id) then
    raise exception 'client_tickets: unknown linked task' using errcode = '23503';
  end if;

  update public.client_tickets
    set assignee_id = p_assignee_id,
        linked_task_id = p_linked_task_id,
        updated_at = now()
    where id = p_id
    returning id;
end;
$$;


--
-- Name: client_ticket_create(uuid, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_ticket_create(p_client_id uuid, p_kind text, p_contact_id uuid DEFAULT NULL::uuid, p_priority text DEFAULT 'medium'::text, p_body_md text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := auth.uid();
  v_id uuid;
begin
  if v_me is null or not exists (select 1 from public.profiles where id = v_me and is_active) then
    raise exception 'client_tickets: not signed in' using errcode = '42501';
  end if;
  if not exists (select 1 from public.clients_v2 where id = p_client_id) then
    raise exception 'client_tickets: unknown client' using errcode = '23503';
  end if;
  if p_kind not in ('bug','question','request','billing','other') then
    raise exception 'client_tickets: bad kind' using errcode = '22023';
  end if;
  if p_priority is not null and p_priority not in ('urgent','high','medium','low') then
    raise exception 'client_tickets: bad priority' using errcode = '22023';
  end if;

  insert into public.client_tickets (client_id, contact_id, org_tag_id, kind, priority, created_by)
    values (p_client_id, p_contact_id,
            (select org_tag_id from public.clients_v2 where id = p_client_id),
            p_kind, p_priority, v_me)
    returning id into v_id;

  return v_id;
end;
$$;


--
-- Name: client_ticket_create_conversation(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_ticket_create_conversation(p_ticket_id uuid, p_title text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'comms', 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := auth.uid();
  v_ticket record;
  v_conv uuid;
begin
  if v_me is null or not exists (select 1 from public.profiles where id = v_me and is_active) then
    raise exception 'client_tickets: not signed in' using errcode = '42501';
  end if;
  select * into v_ticket from public.client_tickets where id = p_ticket_id;
  if v_ticket.id is null then
    raise exception 'client_tickets: unknown ticket' using errcode = '23503';
  end if;
  if v_ticket.linked_conversation_id is not null then
    return v_ticket.linked_conversation_id;
  end if;

  insert into comms.conversations (kind, audience, title, client_id, contact_id, created_by)
    values ('ticket_thread', 'client',
            coalesce(p_title, v_ticket.client_id::text || ' ticket'),
            v_ticket.client_id, v_ticket.contact_id, v_me)
    returning id into v_conv;

  -- creator becomes a participant so they can post the opening message.
  insert into comms.conversation_participants (conversation_id, participant_type, profile_id, role)
    values (v_conv, 'user', v_me, 'admin');

  update public.client_tickets
    set linked_conversation_id = v_conv,
        updated_at = now()
    where id = p_ticket_id;

  return v_conv;
end;
$$;


--
-- Name: client_ticket_update_status(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_ticket_update_status(p_id uuid, p_status text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := auth.uid();
begin
  if v_me is null or not exists (select 1 from public.profiles where id = v_me and is_active) then
    raise exception 'client_tickets: not signed in' using errcode = '42501';
  end if;
  if p_status not in ('open','in_progress','waiting_on_client','resolved','closed') then
    raise exception 'client_tickets: bad status' using errcode = '22023';
  end if;
  update public.client_tickets
    set status = p_status,
        updated_at = now()
    where id = p_id
    returning id;
end;
$$;


--
-- Name: comms_add_agent(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.comms_add_agent(p_conversation_id uuid, p_agent_slug text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'comms', 'spine', 'public', 'pg_temp'
    AS $$
declare
  v_id    uuid;
  v_me    uuid := auth.uid();
  v_kind  text;
  v_aud   text;
  v_kinds jsonb;
begin
  if auth.uid() is not null and not comms.can_post_in_conversation(p_conversation_id) and not comms.can_manage_conversation(p_conversation_id) then
    raise exception 'comms: not a member of this conversation' using errcode = '42501';
  end if;
  select kind, audience into v_kind, v_aud from comms.conversations where id = p_conversation_id;
  if v_kind is null then raise exception 'comms: unknown conversation' using errcode = '23503'; end if;
  select chat_profile->'conversation_kinds' into v_kinds
    from spine.agent_identities where slug = p_agent_slug and enabled and chat_profile ? 'display_name';
  if v_kinds is null then
    raise exception 'comms: % is not a chat-enabled agent', p_agent_slug using errcode = '23503';
  end if;
  if not (v_kinds ? v_kind) then
    raise exception 'comms: % may not join a % conversation', p_agent_slug, v_kind using errcode = '42501';
  end if;
  insert into comms.conversation_participants (conversation_id, participant_type, agent_identity_slug, role, added_by)
  values (p_conversation_id, 'agent', p_agent_slug, 'member', v_me)
  on conflict (conversation_id, agent_identity_slug) where agent_identity_slug is not null
  do update set left_at = null, joined_at = now(), added_by = excluded.added_by
  returning id into v_id;
  insert into comms.conversation_events (conversation_id, kind, actor_participant_id, payload)
  values (p_conversation_id, 'participant_joined', null, jsonb_build_object('agent', p_agent_slug, 'by', v_me));
  return v_id;
end
$$;


--
-- Name: comms_add_member(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.comms_add_member(p_conversation_id uuid, p_profile_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'comms', 'public', 'pg_temp'
    AS $$
declare v_id uuid; v_me uuid := auth.uid();
begin
  if not comms.can_post_in_conversation(p_conversation_id) and not comms.can_manage_conversation(p_conversation_id) then
    raise exception 'comms: not a member of this conversation' using errcode = '42501';
  end if;
  if not exists (select 1 from public.profiles where id = p_profile_id and is_active) then
    raise exception 'comms: unknown or inactive profile' using errcode = '23503';
  end if;
  insert into comms.conversation_participants (conversation_id, participant_type, profile_id, role, added_by)
  values (p_conversation_id, 'user', p_profile_id, 'member', v_me)
  on conflict (conversation_id, profile_id) where profile_id is not null
  do update set left_at = null, joined_at = now(), added_by = excluded.added_by
  returning id into v_id;
  insert into comms.conversation_events (conversation_id, kind, payload)
  values (p_conversation_id, 'participant_joined', jsonb_build_object('profile_id', p_profile_id, 'by', v_me));
  return v_id;
end
$$;


--
-- Name: comms_create_conversation(text, text, text, boolean, uuid[], text[], uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.comms_create_conversation(p_kind text, p_title text, p_slug text DEFAULT NULL::text, p_is_private boolean DEFAULT false, p_member_ids uuid[] DEFAULT '{}'::uuid[], p_agent_slugs text[] DEFAULT '{}'::text[], p_client_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'comms', 'spine', 'public', 'pg_temp'
    AS $$
declare
  v_id   uuid;
  v_me   uuid := auth.uid();
  v_slug text := nullif(lower(regexp_replace(coalesce(p_slug, p_title, ''), '[^a-zA-Z0-9_-]+', '-', 'g')), '');
  v_pid  uuid;
  v_agent text;
begin
  if v_me is null or not exists (select 1 from public.profiles where id = v_me and is_active) then
    raise exception 'comms: not signed in' using errcode = '42501';
  end if;
  if p_kind not in ('channel','dm','group') then
    raise exception 'comms: Phase 1 creates channel, dm, or group only' using errcode = '22023';
  end if;
  if p_kind = 'dm' then
    -- One DM per pair: reuse if it exists (either direction).
    if coalesce(array_length(p_member_ids, 1), 0) <> 1 or p_member_ids[1] = v_me then
      raise exception 'comms: a dm needs exactly one other person' using errcode = '22023';
    end if;
    select c.id into v_id from comms.conversations c
     where c.kind = 'dm'
       and comms.is_active_participant(c.id, v_me)
       and comms.is_active_participant(c.id, p_member_ids[1])
     limit 1;
    if v_id is not null then return v_id; end if;
    v_slug := null;
  end if;

  insert into comms.conversations (kind, audience, slug, title, is_private, client_id, created_by)
  values (p_kind, 'internal', case when p_kind = 'channel' then v_slug end, p_title,
          case when p_kind = 'dm' then true else coalesce(p_is_private, false) end, p_client_id, v_me)
  returning id into v_id;

  insert into comms.conversation_participants (conversation_id, participant_type, profile_id, role, added_by)
  values (v_id, 'user', v_me, 'admin', v_me);

  foreach v_pid in array coalesce(p_member_ids, '{}') loop
    if v_pid <> v_me and exists (select 1 from public.profiles where id = v_pid and is_active) then
      insert into comms.conversation_participants (conversation_id, participant_type, profile_id, role, added_by)
      values (v_id, 'user', v_pid, 'member', v_me) on conflict do nothing;
    end if;
  end loop;

  foreach v_agent in array coalesce(p_agent_slugs, '{}') loop
    perform public.comms_add_agent(v_id, v_agent);
  end loop;

  insert into comms.conversation_events (conversation_id, kind, payload)
  values (v_id, 'opened', jsonb_build_object('by', v_me));
  return v_id;
end
$$;


--
-- Name: comms_ingest_bridge_message(text, text, text, text, text, text, text, timestamp with time zone, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.comms_ingest_bridge_message(p_provider text, p_external_ref text, p_provider_message_id text, p_provider_thread_id text, p_sender_handle text, p_sender_display text, p_body text, p_sent_at timestamp with time zone, p_attachments jsonb DEFAULT '[]'::jsonb, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE sql
    SET search_path TO 'comms', 'spine', 'public', 'pg_temp'
    AS $$ select comms.ingest_bridge_message(p_provider, p_external_ref, p_provider_message_id, p_provider_thread_id, p_sender_handle, p_sender_display, p_body, p_sent_at, p_attachments, p_payload) $$;


--
-- Name: comms_join_conversation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.comms_join_conversation(p_conversation_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'comms', 'public', 'pg_temp'
    AS $$
declare v_id uuid; v_me uuid := auth.uid();
begin
  if v_me is null or not comms.is_active_profile(v_me) then raise exception 'comms: not signed in' using errcode = '42501'; end if;
  if not exists (select 1 from comms.conversations c where c.id = p_conversation_id
                  and c.audience = 'internal' and c.kind = 'channel' and not c.is_private and c.archived_at is null) then
    raise exception 'comms: this conversation is not joinable' using errcode = '42501';
  end if;
  insert into comms.conversation_participants (conversation_id, participant_type, profile_id, role, added_by)
  values (p_conversation_id, 'user', v_me, 'member', v_me)
  on conflict (conversation_id, profile_id) where profile_id is not null
  do update set left_at = null, joined_at = now()
  returning id into v_id;
  return v_id;
end
$$;


--
-- Name: comms_leave_conversation(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.comms_leave_conversation(p_conversation_id uuid, p_agent_slug text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'comms', 'public', 'pg_temp'
    AS $$
declare v_me uuid := auth.uid(); v_n int;
begin
  if p_agent_slug is not null then
    if not comms.can_manage_conversation(p_conversation_id) and not comms.can_post_in_conversation(p_conversation_id) then
      raise exception 'comms: not a member of this conversation' using errcode = '42501';
    end if;
    update comms.conversation_participants set left_at = now()
     where conversation_id = p_conversation_id and agent_identity_slug = p_agent_slug and left_at is null;
    get diagnostics v_n = row_count;
    if v_n > 0 then
      insert into comms.conversation_events (conversation_id, kind, payload)
      values (p_conversation_id, 'participant_left', jsonb_build_object('agent', p_agent_slug, 'by', v_me));
    end if;
    return v_n > 0;
  end if;
  update comms.conversation_participants set left_at = now()
   where conversation_id = p_conversation_id and profile_id = v_me and left_at is null;
  get diagnostics v_n = row_count;
  return v_n > 0;
end
$$;


--
-- Name: comms_links_for_provider(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.comms_links_for_provider(p_provider text) RETURNS TABLE(id uuid, conversation_id uuid, connection_id uuid, external_ref text, external_name text, sync_mode text, cursor jsonb, status text, conversation_slug text, conversation_title text, conversation_kind text, audience text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'comms', 'public', 'pg_temp'
    AS $$
  select l.id, l.conversation_id, l.connection_id, l.external_ref, l.external_name, l.sync_mode, l.cursor, l.status,
         c.slug, c.title, c.kind, c.audience
    from comms.conversation_links l join comms.conversations c on c.id = l.conversation_id
   where l.provider = p_provider and l.status <> 'broken'
$$;


--
-- Name: comms_mark_bridged(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.comms_mark_bridged(p_message_id uuid, p_provider text, p_external_message_id text, p_error text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'comms', 'public', 'pg_temp'
    AS $$
  update comms.messages
     set payload = payload || jsonb_build_object('bridged_' || p_provider,
                     jsonb_build_object('external_message_id', p_external_message_id, 'at', now(), 'error', p_error)),
         delivered_at = case when p_error is null then coalesce(delivered_at, now()) else delivered_at end
   where id = p_message_id
  returning true
$$;


--
-- Name: comms_mark_read(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.comms_mark_read(p_conversation_id uuid) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'comms', 'public', 'pg_temp'
    AS $$
  update comms.conversation_participants set last_read_at = now()
   where conversation_id = p_conversation_id and profile_id = auth.uid() and left_at is null
  returning true
$$;


--
-- Name: comms_outbound_for_provider(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.comms_outbound_for_provider(p_provider text, p_limit integer DEFAULT 50) RETURNS TABLE(message_id uuid, conversation_id uuid, link_id uuid, external_ref text, connection_id uuid, body text, body_format text, sent_at timestamp with time zone, sender_type text, sender_name text, sender_profile_id uuid, sender_agent_slug text, sender_handle text, in_reply_to_external_id text, attachments jsonb)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'comms', 'spine', 'public', 'pg_temp'
    AS $$
  select m.id, m.conversation_id, l.id, l.external_ref, l.connection_id,
         m.body, m.body_format, m.sent_at, cp.participant_type,
         case cp.participant_type
           when 'user'  then coalesce(nullif(btrim(concat_ws(' ', p.first_name, p.last_name)), ''), p.email)
           when 'agent' then coalesce(ai.chat_profile->>'display_name', ai.slug)
           else 'Open Ronin' end,
         cp.profile_id, cp.agent_identity_slug,
         (select i.handle from comms.profile_identities i where i.profile_id = cp.profile_id and i.provider = p_provider limit 1),
         (select r.provider_message_id from comms.messages r where r.id = m.in_reply_to_message_id and r.provider = p_provider),
         m.attachments
    from comms.messages m
    join comms.conversation_links l on l.conversation_id = m.conversation_id and l.provider = p_provider and l.status = 'active' and l.sync_mode in ('write','two_way')
    left join comms.conversation_participants cp on cp.id = m.sender_participant_id
    left join public.profiles p on p.id = cp.profile_id
    left join spine.agent_identities ai on ai.slug = cp.agent_identity_slug
   where m.provider = 'openronin' and m.deleted_at is null and m.visibility = 'all'
     and not (m.payload ? ('bridged_' || p_provider))
     and coalesce(cp.participant_type, 'user') <> 'external_app'
   order by m.sent_at
   limit greatest(1, least(coalesce(p_limit, 50), 200))
$$;


--
-- Name: comms_profile_id_for_email(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.comms_profile_id_for_email(p_email text) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$ select id from public.profiles where lower(email) = lower(p_email) limit 1 $$;


--
-- Name: comms_send_message(uuid, text, uuid, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.comms_send_message(p_conversation_id uuid, p_body text, p_in_reply_to uuid DEFAULT NULL::uuid, p_visibility text DEFAULT 'all'::text, p_mentions text[] DEFAULT NULL::text[]) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'comms', 'spine', 'public', 'pg_temp'
    AS $$
begin
  if not comms.can_post_in_conversation(p_conversation_id) then
    raise exception 'comms: you are not a member of this conversation' using errcode = '42501';
  end if;
  return comms.send_message_as(auth.uid(), p_conversation_id, p_body, p_in_reply_to, p_visibility, p_mentions, 'openronin', null);
end
$$;


--
-- Name: comms_send_message_as(uuid, uuid, text, uuid, text, text[], text, text); Type: FUNCTION; Schema: public; Owner: -
--

