--
-- Name: comms_upsert_connection(text, text, text, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.comms_upsert_connection(p_provider text, p_scope text, p_external_account_id text, p_display_name text, p_status text DEFAULT 'active'::text, p_health jsonb DEFAULT '{}'::jsonb, p_credentials_enc text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'comms', 'public', 'pg_temp'
    AS $$
declare v_id uuid;
begin
  insert into comms.connections (provider, scope, visibility, external_account_id, display_name, status, health, credentials_enc, last_synced_at)
  values (p_provider, p_scope, 'shared', p_external_account_id, p_display_name, p_status, coalesce(p_health, '{}'::jsonb), p_credentials_enc, now())
  on conflict (tenant_id, provider, scope, external_account_id, coalesce(owner_profile_id, '00000000-0000-0000-0000-000000000000'::uuid))
  do update set display_name = coalesce(excluded.display_name, comms.connections.display_name),
                status = excluded.status,
                health = comms.connections.health || excluded.health,
                credentials_enc = coalesce(excluded.credentials_enc, comms.connections.credentials_enc),
                last_synced_at = now(), updated_at = now()
  returning id into v_id;
  return v_id;
end
$$;


--
-- Name: comms_upsert_link(text, text, uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.comms_upsert_link(p_provider text, p_external_ref text, p_conversation_id uuid, p_external_name text DEFAULT NULL::text, p_sync_mode text DEFAULT 'two_way'::text, p_connection_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'comms', 'public', 'pg_temp'
    AS $$
declare v_id uuid;
begin
  insert into comms.conversation_links (provider, external_ref, conversation_id, external_name, sync_mode, connection_id)
  values (p_provider, p_external_ref, p_conversation_id, p_external_name, p_sync_mode, p_connection_id)
  on conflict (provider, external_ref) do update
     set conversation_id = excluded.conversation_id, external_name = coalesce(excluded.external_name, comms.conversation_links.external_name),
         sync_mode = excluded.sync_mode, connection_id = coalesce(excluded.connection_id, comms.conversation_links.connection_id),
         status = 'active', updated_at = now()
  returning id into v_id;
  insert into comms.conversation_events (conversation_id, kind, payload)
  values (p_conversation_id, 'linked', jsonb_build_object('provider', p_provider, 'external_ref', p_external_ref));
  return v_id;
end
$$;


