-- Name: comms_upsert_profile_identity(text, text, uuid, text, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.comms_upsert_profile_identity(p_provider text, p_handle text, p_profile_id uuid, p_display text DEFAULT NULL::text, p_source text DEFAULT 'email_match'::text, p_confidence numeric DEFAULT 1.0) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'comms', 'public', 'pg_temp'
    AS $$
declare v_id uuid;
begin
  insert into comms.profile_identities (provider, handle, profile_id, display, source, confidence)
  values (p_provider, p_handle, p_profile_id, p_display, p_source, p_confidence)
  on conflict (provider, handle) do update
     set profile_id = excluded.profile_id, display = coalesce(excluded.display, comms.profile_identities.display),
         source = excluded.source, confidence = excluded.confidence
  returning id into v_id;
  return v_id;
end
$$;


