--
-- Name: compute_health_scores(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_health_scores(p_period date DEFAULT (date_trunc('month'::text, now()))::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_period       date := (date_trunc('month', p_period))::date;
  v_anchor       date;
  v_weights      jsonb;
  v_contract     record;
  v_eng          record;
  v_eng_value    numeric;
  v_sat_value    numeric;
  v_pay_on_time  int;
  v_pay_late     int;
  v_pay_value    numeric;
  v_goal         int;
  v_goal_src     text;
  v_opps         record;
  v_opp_value    numeric;
  v_opp_note     text;
  v_factors      jsonb;
  v_measured_w   numeric;
  v_weighted_sum numeric;
  v_measured_n   int;
  v_total        numeric;
  v_signals      int;
  v_scored       int := 0;
  v_escalated    int := 0;
begin
  v_anchor := least(now()::date, (v_period + interval '1 month - 1 day')::date);

  select jsonb_object_agg(key, default_weight_pct)
    into v_weights
    from health_factors where is_active;

  for v_contract in
    select c.airtable_contract_id, c.package, v2.display_name
      from contracts c
      join clients_v2 v2 on v2.id = c.client_id
     where c.status in ('active', 'hold', '60-day')
       and c.airtable_contract_id is not null
  loop
    -- ---- engagement -------------------------------------------------------
    v_eng_value := null;
    select * into v_eng
      from client_engagement
     where airtable_contract_id = v_contract.airtable_contract_id
       and period_month = v_period;
    if found then
      select avg(r) * 100 into v_eng_value
        from (values
          (case when coalesce(v_eng.calls_scheduled, 0) > 0
                then least(v_eng.calls_attended::numeric / v_eng.calls_scheduled, 1) end),
          (case when coalesce(v_eng.emails_received, 0) > 0
                then least(v_eng.emails_responded_to::numeric / v_eng.emails_received, 1) end)
        ) t(r)
       where r is not null;
    end if;

    -- ---- satisfaction -----------------------------------------------------
    select avg(nps) * 10 into v_sat_value
      from client_satisfaction
     where airtable_contract_id = v_contract.airtable_contract_id
       and nps is not null
       and captured_at >= v_period
       and captured_at < v_period + interval '1 month';

    -- ---- payment timeliness (due + 10, the org's own rule) --------------------
    select
      count(*) filter (where paid_on is not null and paid_on <= due_on + 10),
      count(*) filter (where (paid_on is not null and paid_on > due_on + 10)
                          or (paid_on is null and v_anchor > due_on + 10))
      into v_pay_on_time, v_pay_late
      from payments
     where airtable_contract_id = v_contract.airtable_contract_id
       and due_on <= v_anchor
       and due_on > v_anchor - interval '6 months'
       and coalesce(status, '') <> 'Hold';
    v_pay_value := case when v_pay_on_time + v_pay_late >= 2
                        then round(v_pay_on_time::numeric / (v_pay_on_time + v_pay_late) * 100, 1)
                        end;

    -- ---- opps vs goal (R1 goal of record · R3 counting) -------------------
    select media_opps_goal into v_goal
      from client_goals
     where airtable_contract_id = v_contract.airtable_contract_id
       and month = v_period and media_opps_goal is not null
     order by updated_at desc limit 1;
    if v_goal is not null then
      v_goal_src := 'goal row';
    else
      v_goal := public.package_opps_goal(v_contract.package);
      v_goal_src := case when v_goal is not null then 'tier default (' || v_contract.package || ')' end;
    end if;
    select * into v_opps
      from client_opp_months
     where airtable_contract_id = v_contract.airtable_contract_id and month = v_period;
    v_opp_value := null; v_opp_note := null;
    if v_goal is null or v_goal = 0 then
      v_opp_note := 'no opps quota for this package (R1) or no goal of record';
    elsif not found then
      v_opp_note := 'opp counts not synced for period';
    else
      -- In-progress month: judge month-to-date progress against the goal
      -- prorated by elapsed days, or a client on pace reads as failing on
      -- the 1st and an escalation fires on noise. Closed months (anchor =
      -- month end) use the full quota.
      declare
        v_goal_eff numeric := greatest(
          v_goal * extract(day from v_anchor)
            / extract(day from (v_period + interval '1 month - 1 day')), 1);
      begin
        v_opp_value := round(least(v_opps.secured_count::numeric / v_goal_eff, 1) * 100, 1);
        v_opp_note := 'secured ' || v_opps.secured_count || ' of ' || v_goal
          || case when v_goal_eff < v_goal
                  then ' (' || round(v_goal_eff, 1) || ' prorated to day ' || extract(day from v_anchor) || ')'
                  else '' end
          || ' — ' || v_goal_src;
      end;
    end if;

    -- ---- assemble breakdown ----------------------------------------------
    v_factors := jsonb_build_object(
      'engagement', jsonb_build_object(
        'measured', v_eng_value is not null,
        'value', round(v_eng_value, 1),
        'weight_pct', (v_weights->>'engagement')::numeric,
        'note', case when v_eng_value is null then 'no engagement data for period' end),
      'opps_vs_goal', jsonb_build_object(
        'measured', v_opp_value is not null,
        'value', v_opp_value,
        'weight_pct', (v_weights->>'opps_vs_goal')::numeric,
        'note', v_opp_note),
      'payment_timeliness', jsonb_build_object(
        'measured', v_pay_value is not null,
        'value', v_pay_value,
        'weight_pct', (v_weights->>'payment_timeliness')::numeric,
        'note', case when v_pay_value is null
                     then 'fewer than 2 eligible payment rows in trailing 6 months' end),
      'package_adherence', jsonb_build_object(
        'measured', false, 'value', null,
        'weight_pct', (v_weights->>'package_adherence')::numeric,
        'note', 'client_meta/deliverables empty'),
      'satisfaction', jsonb_build_object(
        'measured', v_sat_value is not null,
        'value', round(v_sat_value, 1),
        'weight_pct', (v_weights->>'satisfaction')::numeric,
        'note', case when v_sat_value is null then 'no rated calls in period' end),
      'quality_of_opp', jsonb_build_object(
        'measured', false, 'value', null,
        'weight_pct', (v_weights->>'quality_of_opp')::numeric,
        'note', 'ai:future')
    );

    -- ---- weight around what is measured ----------------------------------
    select
      coalesce(sum((f.value->>'weight_pct')::numeric) filter (where (f.value->>'measured')::boolean), 0),
      coalesce(sum((f.value->>'weight_pct')::numeric * (f.value->>'value')::numeric)
        filter (where (f.value->>'measured')::boolean), 0),
      count(*) filter (where (f.value->>'measured')::boolean)
      into v_measured_w, v_weighted_sum, v_measured_n
      from jsonb_each(v_factors) f;

    v_total := case when v_measured_w > 0 then round(v_weighted_sum / v_measured_w) else null end;

    insert into health_scores (airtable_contract_id, period_month, total_score, factor_breakdown, computed_at)
    values (
      v_contract.airtable_contract_id,
      v_period,
      v_total,
      jsonb_build_object(
        'factors', v_factors,
        'coverage', jsonb_build_object(
          'measured_count', v_measured_n,
          'total_count', 6,
          'weight_measured_pct', v_measured_w)),
      now())
    on conflict (airtable_contract_id, period_month)
    do update set total_score = excluded.total_score,
                  factor_breakdown = excluded.factor_breakdown,
                  computed_at = excluded.computed_at;
    v_scored := v_scored + 1;

    -- ---- escalation: two at-risk signals in a month -----------------------
    v_signals := 0;
    if v_eng_value is not null and v_eng_value < 50 then v_signals := v_signals + 1; end if;
    if v_sat_value is not null and v_sat_value < 60 then v_signals := v_signals + 1; end if;
    if v_pay_value is not null and v_pay_value < 50 then v_signals := v_signals + 1; end if;
    if v_opp_value is not null and v_opp_value < 50 then v_signals := v_signals + 1; end if;
    if v_eng.is_flagged is true then v_signals := v_signals + 1; end if;

    if v_signals >= 2 then
      insert into notifications (user_id, kind, title, body, href, dedupe_key)
      select p.id,
             'health_escalation',
             v_contract.display_name || ' is at risk',
             v_signals || ' at-risk health signals in ' || to_char(v_period, 'Mon YYYY')
               || ' — SOP: two signals in a month = escalate.',
             '/clients/' || v_contract.airtable_contract_id || '/health',
             'health-escalation:' || v_contract.airtable_contract_id || ':' || v_period
        from profiles p
       where p.role in ('exec', 'admin') and p.is_active
      on conflict (user_id, dedupe_key) do nothing;
      v_escalated := v_escalated + 1;
    end if;
  end loop;

  return jsonb_build_object(
    'period', v_period,
    'contracts_scored', v_scored,
    'escalations', v_escalated);
end;
$$;


--
-- Name: compute_the_work_metrics(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_the_work_metrics(p_period date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
        period_start date := date_trunc('month', coalesce(p_period, (now() at time zone public.company_timezone())::date))::date;
        period_end   date := (period_start + interval '1 month')::date;
        written int;
        unattributed int;
begin
        with attributed as (
                select
                        coalesce(p.owner_id, p.team_lead_id, p.project_lead_id) as subject,
                        p.kind,
                        p.completed_at,
                        p.ends_at
                from public.projects p
                where not p.archived
                        and coalesce(p.owner_id, p.team_lead_id, p.project_lead_id) is not null
                        and (
                                (p.completed_at >= period_start and p.completed_at < period_end)
                                or (p.ends_at >= period_start and p.ends_at < period_end)
                        )
        ),
        -- One row per (person, metric). Only people who had ANY item in the window
        -- appear, so a genuine zero shows and an empty month stays empty.
        counted as (
                select subject, 'v2_tasks_completed' as metric_key,
                        count(*) filter (where kind = 'task' and completed_at >= period_start and completed_at < period_end) as value
                from attributed group by subject
                union all
                select subject, 'v2_tasks_scheduled',
                        count(*) filter (where kind = 'task' and ends_at >= period_start and ends_at < period_end)
                from attributed group by subject
                union all
                select subject, 'projects_completed',
                        count(*) filter (where kind = 'project' and completed_at >= period_start and completed_at < period_end)
                from attributed group by subject
        ),
        upserted as (
                -- subject_type/subject_id MUST match what the profile UI queries
                -- ('user' + subject_id, see app/team/metrics/actions.ts). subject_key is
                -- NOT in the column list: it is GENERATED ALWAYS from subject_id (0025),
                -- so Postgres computes it â€” and still resolves the ON CONFLICT arbiter,
                -- exactly as api/ingest/metrics already relies on.
                insert into public.metrics
                        (subject_type, subject_id, metric_key, period, value, source, computed_at)
                select 'user', c.subject, c.metric_key, period_start, c.value, 'the_work', now()
                from counted c
                on conflict (subject_type, subject_key, metric_key, period, source)
                        do update set value = excluded.value, computed_at = excluded.computed_at
                returning 1
        )
        select count(*) into written from upserted;

        -- Reported so the operator can see the coverage gap instead of guessing.
        select count(*) into unattributed
        from public.projects p
        where not p.archived
                and coalesce(p.owner_id, p.team_lead_id, p.project_lead_id) is null
                and (
                        (p.completed_at >= period_start and p.completed_at < period_end)
                        or (p.ends_at >= period_start and p.ends_at < period_end)
                );

        return jsonb_build_object(
                'period', period_start,
                'rows_written', written,
                'items_unattributed', unattributed
        );
end;
$$;


--
-- Name: content_cap_for(text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.content_cap_for(p_via text, p_user uuid, p_slug text) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case
    when p_via = 'mcp' then coalesce(
      (select daily_usd from public.content_caps where scope = 'consumer' and key = p_slug),
      (select daily_usd from public.content_caps where scope = 'consumer' and key = '*'),
      0)
    else coalesce(
      (select c.daily_usd from public.content_caps c
         join public.profiles p on p.role = c.key
        where c.scope = 'role' and p.id = p_user),
      (select daily_usd from public.content_caps where scope = 'role' and key = 'contributor'),
      0)
  end
$$;


--
-- Name: content_caps_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.content_caps_audit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  new.updated_at := now();
  new.updated_by := auth.uid();
  insert into public.audit_log (actor_id, entity_kind, entity_ref, action, diff)
  values (
    auth.uid(),
    'supabase',
    'content_caps/' || new.scope || ':' || new.key,
    case when tg_op = 'INSERT' then 'create' else 'update' end,
    jsonb_build_object('old', case when tg_op = 'UPDATE' then old.daily_usd end, 'new', new.daily_usd)
  );
  return new;
end;
$$;


--
-- Name: content_daily_spend(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.content_daily_spend(p_user uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(sum(cost_usd), 0)
  from public.content_jobs
  where requested_by = p_user
    and requested_via <> 'mcp'
    and status <> 'cancelled'
    and (created_at at time zone 'America/Chicago')::date = (now() at time zone 'America/Chicago')::date
$$;


--
-- Name: content_daily_spend_consumer(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.content_daily_spend_consumer(p_slug text) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(sum(cost_usd), 0)
  from public.content_jobs
  where consumer_slug = p_slug
    and requested_via = 'mcp'
    and status <> 'cancelled'
    and (created_at at time zone 'America/Chicago')::date = (now() at time zone 'America/Chicago')::date
$$;


--
-- Name: content_jobs_enforce_cap(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.content_jobs_enforce_cap() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_cap   numeric;
  v_spent numeric;
  v_who   text;
begin
  if new.requested_via = 'mcp' then
    v_spent := public.content_daily_spend_consumer(new.consumer_slug);
    v_who := 'consumer ' || new.consumer_slug;
  else
    if new.requested_by is null then
      raise exception 'A content job needs a requester' using errcode = '23514';
    end if;
    v_spent := public.content_daily_spend(new.requested_by);
    v_who := 'this person';
  end if;
  v_cap := public.content_cap_for(new.requested_via, new.requested_by, new.consumer_slug);
  if v_spent + coalesce(new.cost_usd, 0) > v_cap then
    raise exception 'Daily content budget reached for %: $% spent today, $% estimated for this job, cap $%. Ask an admin to raise the cap on /admin/providers.',
      v_who, round(v_spent, 2), round(coalesce(new.cost_usd, 0), 2), round(v_cap, 2)
      using errcode = 'P0001';
  end if;
  return new;
end;
$_$;


--
-- Name: content_request_action_decide(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.content_request_action_decide(p_action_id uuid, p_decision text, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'spine', 'pg_temp'
    AS $$
declare
  v_a      spine.proposed_actions%rowtype;
  v_uid    uuid := auth.uid();
  v_p      jsonb;
  v_client uuid;
  v_id     uuid;
  v_event  uuid;
  v_due    date;
begin
  if v_uid is null then
    raise exception 'CONTENT_REQUEST: a signed-in approver is required' using errcode = '42501';
  end if;
  if not public.can_manage_content_requests() then
    raise exception 'CONTENT_REQUEST: the content queue decides proposals' using errcode = '42501';
  end if;
  if p_decision not in ('approved', 'rejected') then
    raise exception 'CONTENT_REQUEST: decision must be approved or rejected' using errcode = '22023';
  end if;

  select * into v_a from spine.proposed_actions where id = p_action_id for update;
  if v_a.id is null then raise exception 'CONTENT_REQUEST: unknown proposal' using errcode = '23503'; end if;
  if v_a.action_type <> 'content_request.create' then
    raise exception 'CONTENT_REQUEST: not a content request proposal' using errcode = '22023';
  end if;
  if v_a.status <> 'pending' then
    return jsonb_build_object('status', v_a.status, 'action_id', v_a.id);
  end if;

  if v_a.work_item_id is null then
    insert into spine.events (kind, source, payload, processed_at)
    values ('content_request.proposal_decided', 'spine.proposed_actions',
            jsonb_build_object('action_id', v_a.id, 'decision', p_decision, 'reviewer', v_uid), now())
    returning id into v_event;
  end if;

  if p_decision = 'rejected' then
    update spine.proposed_actions
       set status = 'rejected', reviewer_id = v_uid, decided_at = now(),
           reasoning = case when p_note is null then reasoning else coalesce(reasoning, '') || E'\n\nRejected: ' || p_note end
     where id = v_a.id;
    perform spine.record_agent_audit(v_uid, v_a.identity_slug, v_a.work_item_id, 'write', 'spine.proposed_actions', 1, null, 'denied', 'rejected by reviewer', v_event);
    return jsonb_build_object('status', 'rejected', 'action_id', v_a.id);
  end if;

  v_p := coalesce(v_a.payload, '{}'::jsonb);
  if coalesce(v_p->>'title', '') = '' then
    raise exception 'CONTENT_REQUEST: proposal has no title' using errcode = '22023';
  end if;
  if v_p->>'client_id' is not null then
    select id into v_client from public.clients_v2 where id = (v_p->>'client_id')::uuid;
    if v_client is null then
      raise exception 'CONTENT_REQUEST: proposal names an unknown client' using errcode = '23503';
    end if;
  end if;
  v_due := (v_p->>'due_on')::date;
  if v_due is not null and v_due < (now() at time zone 'America/Chicago')::date then
    v_due := null; -- a stale proposal is filed undated rather than refused; the queue sets the date
  end if;

  -- the approver is the requester of record (a human filed it); the
  -- proposing identity rides along as provenance.
  insert into public.content_requests
    (requester_id, client_id, asset_type, title, brief, due_on, priority, identity_slug, proposed_action_id)
  values
    (v_uid, v_client, coalesce(v_p->>'asset_type', 'other'), left(v_p->>'title', 200), v_p->>'brief',
     v_due, coalesce(v_p->>'priority', 'normal'), v_a.identity_slug, v_a.id)
  returning id into v_id;
  perform spine.record_agent_audit(v_uid, v_a.identity_slug, v_a.work_item_id, 'write', 'public.content_requests', 1, null, 'ok', null, v_event);

  update spine.proposed_actions
     set status = 'applied', reviewer_id = v_uid, decided_at = now()
   where id = v_a.id;
  return jsonb_build_object('status', 'applied', 'action_id', v_a.id, 'request_id', v_id);
end
$$;




--
-- Name: content_request_pending_actions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.content_request_pending_actions() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'spine', 'pg_temp'
    AS $$
begin
  if not public.can_manage_content_requests() then
    raise exception 'CONTENT_REQUEST: the content queue reads proposals' using errcode = '42501';
  end if;
  return (
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', a.id, 'identity_slug', a.identity_slug,
      'display_name', i.chat_profile->>'display_name',
      'reasoning', a.reasoning, 'payload', a.payload, 'created_at', a.created_at,
      'client_name', (select c.display_name from public.clients_v2 c where c.id::text = a.payload->>'client_id')
    ) order by a.created_at), '[]'::jsonb)
    from spine.proposed_actions a
    join spine.agent_identities i on i.slug = a.identity_slug
    where a.status = 'pending' and a.action_type = 'content_request.create');
end
$$;


--
-- Name: content_requests_sync_work_runs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.content_requests_sync_work_runs() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  r public.content_requests%rowtype;
  v_status text; v_finished timestamptz; v_client uuid;
begin
  if tg_op = 'DELETE' then
    delete from public.work_runs where source_table = 'content_requests' and source_id = old.id::text;
    return old;
  end if;
  r := new;
  v_status := case r.status
    when 'requested' then 'waiting_approval'
    when 'accepted'  then 'approved'
    when 'in_studio' then 'running'
    when 'delivered' then 'done'
    when 'declined'  then 'rejected'
    else 'waiting_approval' end;
  v_finished := case when r.status in ('delivered', 'declined') then coalesce(r.delivered_at, r.updated_at) end;
  select id into v_client from public.clients_v2 where id = r.client_id;

  perform set_config('work_engine.sync', 'on', true);
  insert into public.work_runs as w (
    domain, kind, title, status, payload, result, error,
    requested_by, requested_via, approver_group, approved_by, approved_at,
    client_id, work_item_id, parent_run_id, cost_usd,
    source_table, source_id, created_at, started_at, finished_at
  ) values (
    'content', 'request:' || r.asset_type, left(r.title, 300), v_status,
    jsonb_build_object('asset_type', r.asset_type, 'priority', r.priority, 'due_on', r.due_on,
                       'studio_job_id', r.studio_job_id, 'identity_slug', r.identity_slug, 'sla_accept_by', r.sla_accept_by),
    case when r.decision_note is null then null else jsonb_build_object('decision_note', r.decision_note) end,
    null,
    r.requester_id, case when r.identity_slug is null then 'ui' else 'mcp' end,
    'content_reviewers', r.accepted_by, r.accepted_at,
    v_client, null, null, null,
    'content_requests', r.id::text, r.created_at, r.accepted_at, v_finished
  )
  on conflict (source_table, source_id) where source_table is not null do update set
    kind = excluded.kind, title = excluded.title, status = excluded.status,
    payload = excluded.payload, result = excluded.result,
    approved_by = excluded.approved_by, approved_at = excluded.approved_at,
    client_id = excluded.client_id, started_at = excluded.started_at, finished_at = excluded.finished_at;
  perform set_config('work_engine.sync', 'off', true);
  return new;
exception when others then
  perform set_config('work_engine.sync', 'off', true);
  raise warning 'content_requests_sync_work_runs(%) skipped: %', coalesce(new.id, old.id), sqlerrm;
  return coalesce(new, old);
end;
$$;


--
-- Name: content_spend_today(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.content_spend_today() RETURNS TABLE(scope text, key text, label text, usd numeric, jobs bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select 'person'::text, j.requested_by::text,
         coalesce(nullif(trim(p.first_name || ' ' || coalesce(p.last_name, '')), ''), p.email),
         coalesce(sum(j.cost_usd), 0), count(*)
  from public.content_jobs j
  join public.profiles p on p.id = j.requested_by
  where public.is_admin()
    and j.requested_via <> 'mcp'
    and j.status <> 'cancelled'
    and (j.created_at at time zone 'America/Chicago')::date = (now() at time zone 'America/Chicago')::date
  group by j.requested_by, p.first_name, p.last_name, p.email
  union all
  select 'consumer', j.consumer_slug, j.consumer_slug, coalesce(sum(j.cost_usd), 0), count(*)
  from public.content_jobs j
  where public.is_admin()
    and j.requested_via = 'mcp'
    and j.status <> 'cancelled'
    and (j.created_at at time zone 'America/Chicago')::date = (now() at time zone 'America/Chicago')::date
  group by j.consumer_slug
$$;


--
-- Name: emit_automation_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.emit_automation_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_op text := lower(tg_op);
  v_row jsonb;
begin
  if not exists (
    select 1 from public.automation_rules r
     where r.enabled and r.trigger_kind = 'table_event'
       and r.trigger_config->>'table' = tg_table_name
       and coalesce(r.trigger_config->>'op', 'any') in ('any', v_op)
  ) then
    return null;
  end if;
  v_row := case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end;
  insert into public.automation_events (table_name, op, row_id, row_data)
  values (tg_table_name, v_op, coalesce(v_row->>'id', ''), v_row);
  return null;
exception when others then
  raise warning 'emit_automation_event(%) skipped: %', tg_table_name, sqlerrm;
  return null;
end;
$$;


--
-- Name: enforce_email_domain(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_email_domain() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  user_domain text;
  allowed text[] := public.org_email_domains();
begin
  if coalesce(new.raw_app_meta_data->>'portal', '') = 'true' then
    return new;   -- client portal login (0144): any domain, no profile, restricted by is_portal_user()
  end if;
  user_domain := split_part(new.email, '@', 2);
  if not (user_domain = any(allowed)) then
    raise exception 'Email domain % is not allowed. Allowed: %',
      user_domain, array_to_string(allowed, ', ');
  end if;
  return new;
end;
$$;


--
-- Name: enforce_work_item_children_on_kind_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_work_item_children_on_kind_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
	if new.kind is distinct from old.kind
	   and exists (select 1 from public.projects c where c.parent_id = new.id) then
		raise exception 'Move or detach the children of this % before changing its kind', old.kind
			using errcode = '23514';
	end if;
	return new;
end;
$$;


--
-- Name: enforce_work_item_parent(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_work_item_parent() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
	v_parent_kind text;
	v_allowed text;
begin
	if new.parent_id is null then
		return new;
	end if;
	if new.parent_id = new.id then
		raise exception 'A work item cannot be its own parent' using errcode = '23514';
	end if;

	v_allowed := case new.kind
		when 'priority' then 'goal'
		when 'project' then 'priority'
		when 'task' then 'project'
		when 'twelve_week_plan' then 'strategy'
		when 'campaign' then 'twelve_week_plan'
		when 'assignment' then 'campaign'
		else null
	end;

	select kind into v_parent_kind from public.projects where id = new.parent_id;

	if v_allowed is null then
		raise exception 'A % cannot have a parent', new.kind using errcode = '23514';
	end if;
	if v_parent_kind is distinct from v_allowed then
		raise exception 'A % can only sit under a % (got %)', new.kind, v_allowed, coalesce(v_parent_kind, 'nothing')
			using errcode = '23514';
	end if;
	return new;
end;
$$;


--
-- Name: external_job_heartbeat(text, text, text, text, text, text, integer, text, timestamp with time zone, timestamp with time zone, integer, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.external_job_heartbeat(p_source text, p_job_key text, p_name text, p_status text, p_owner text DEFAULT NULL::text, p_schedule_text text DEFAULT NULL::text, p_expected_interval_minutes integer DEFAULT NULL::integer, p_href text DEFAULT NULL::text, p_started_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_finished_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_duration_ms integer DEFAULT NULL::integer, p_error text DEFAULT NULL::text, p_summary jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_started  timestamptz;
  v_finished timestamptz;
  v_row      public.external_jobs%rowtype;
begin
  if auth.uid() is not null then
    raise exception 'external_job_heartbeat is service-role only' using errcode = '42501';
  end if;
  if p_status not in ('ok','error','running') then
    raise exception 'status must be ok, error or running' using errcode = '22023';
  end if;
  v_finished := case when p_status = 'running' then null else coalesce(p_finished_at, now()) end;
  v_started  := coalesce(p_started_at,
                  case when p_status = 'running' then now()
                       when p_duration_ms is not null then v_finished - make_interval(secs => p_duration_ms / 1000.0)
                       else v_finished end);

  insert into public.external_jobs
    (source, job_key, name, owner, schedule_text, expected_interval_minutes, href,
     last_started_at, last_finished_at, last_status, last_error, last_duration_ms, last_summary,
     run_count, error_count)
  values
    (p_source, p_job_key, p_name, p_owner, p_schedule_text, p_expected_interval_minutes, p_href,
     v_started, v_finished, p_status, left(p_error, 4000), p_duration_ms, p_summary,
     case when p_status = 'running' then 0 else 1 end,
     case when p_status = 'error' then 1 else 0 end)
  on conflict (source, job_key) do update
    set name                      = excluded.name,
        owner                     = coalesce(excluded.owner, public.external_jobs.owner),
        schedule_text             = coalesce(excluded.schedule_text, public.external_jobs.schedule_text),
        expected_interval_minutes = coalesce(excluded.expected_interval_minutes, public.external_jobs.expected_interval_minutes),
        href                      = coalesce(excluded.href, public.external_jobs.href),
        last_started_at           = excluded.last_started_at,
        last_finished_at          = excluded.last_finished_at,
        last_status               = excluded.last_status,
        last_error                = excluded.last_error,
        last_duration_ms          = excluded.last_duration_ms,
        last_summary              = excluded.last_summary,
        run_count                 = public.external_jobs.run_count + excluded.run_count,
        error_count               = public.external_jobs.error_count + excluded.error_count,
        enabled                   = true
  returning * into v_row;

  return jsonb_build_object('id', v_row.id, 'source', v_row.source, 'job_key', v_row.job_key,
                            'run_count', v_row.run_count, 'error_count', v_row.error_count,
                            'last_status', v_row.last_status);
end
$$;


--
-- Name: fw_agent_for(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_agent_for(p_program uuid, p_kind text, p_channel text DEFAULT NULL::text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(
    (select v.key from public.fw_agents v join public.fw_program_agents pa on pa.program_id = p_program and pa.agent_key = v.parent_key and pa.enabled
      where v.is_active and v.output_kind = p_kind and v.channel_key = p_channel and v.parent_key is not null limit 1),
    (select a.key from public.fw_agents a join public.fw_program_agents pa on pa.program_id = p_program and pa.agent_key = a.key and pa.enabled
      where a.is_active and a.output_kind = p_kind and a.parent_key is null order by case when a.key = 'copywriter' then 0 else 1 end limit 1)
  )
$$;


--
-- Name: fw_agents_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_agents_version() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.system_md is distinct from old.system_md then
    new.version := old.version + 1;
    new.history := coalesce(old.history, '[]'::jsonb) || jsonb_build_object('version', old.version, 'system_md', old.system_md, 'by', auth.uid(), 'at', now());
    if new.history is not null and jsonb_array_length(new.history) > 20 then new.history := (select jsonb_agg(x) from (select x from jsonb_array_elements(new.history) x order by (x->>'version')::int desc limit 20) s); end if;
  end if;
  return new;
end;
$$;


--
-- Name: fw_apply_draft(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_apply_draft(p_draft uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare d record; v_now timestamptz := now(); v_target text; v_text text;
begin
  if not (public.can_view_flywheel() or auth.uid() is null) then raise exception 'flywheel: not allowed' using errcode = '42501'; end if;
  select * into d from public.fw_drafts where id = p_draft;
  if d.id is null then raise exception 'flywheel: draft not found'; end if;
  if d.status <> 'approved' then raise exception 'flywheel: apply an approved draft (current: %)', d.status; end if;
  v_text := coalesce(nullif(d.humanized_md, ''), d.content_md);
  if d.kind = 'plan' and d.target_kind = 'cluster' then
    update public.fw_clusters set plan_md = v_text, plan_status = case when plan_status in ('draft', 'changes_requested') then 'verification' else plan_status end where id = d.target_id;
    v_target := 'cluster plan';
  elsif d.kind in ('keyword_research', 'site_keywords') and d.target_kind = 'cluster' then
    declare i int := 0; k jsonb; begin
      update public.fw_clusters set anchor_keyword = coalesce(anchor_keyword, d.structured->>'anchor_keyword') where id = d.target_id;
      for k in select value from jsonb_array_elements(coalesce(d.structured->'primary', '[]'::jsonb)) loop
        i := i + 1;
        update public.fw_pages set keyword = k->>'keyword', kind = 'pillar' where cluster_id = d.target_id and number = i and status = 'planned';
      end loop;
      for k in select value from jsonb_array_elements(coalesce(d.structured->'questions', '[]'::jsonb)) loop
        i := i + 1;
        update public.fw_pages set keyword = k->>'keyword', kind = 'question' where cluster_id = d.target_id and number = i and status = 'planned';
      end loop;
    end;
    v_target := 'cluster keywords';
  elsif d.kind = 'site_keywords' and d.target_kind = 'program' then
    update public.fw_programs set keyword_hypotheses = coalesce(keyword_hypotheses, '[]'::jsonb) || coalesce(d.structured->'hypotheses', '[]'::jsonb) where id = d.target_id;
    v_target := 'keyword hypotheses';
  elsif d.kind = 'visibility_report' then
    v_target := 'visibility report';
  elsif d.kind = 'page' and d.target_kind = 'page' then
    update public.fw_pages set
      body_md = case when d.humanized_md is not null and d.humanized_md <> '' then d.humanized_md else coalesce(d.structured->>'body_md', d.content_md) end,
      quick_answer_md = coalesce(d.structured->>'quick_answer_md', quick_answer_md),
      title = coalesce(d.structured->>'title', title), meta_title = coalesce(d.structured->>'meta_title', meta_title),
      faq_schema = coalesce(d.structured->'faq', faq_schema),
      status = case when status in ('planned', 'drafting', 'changes_requested') then 'verification' else status end
    where id = d.target_id;
    v_target := 'page';
  elsif d.kind = 'citation' and d.target_kind = 'citation' then
    update public.fw_citations set draft_md = case when d.humanized_md is not null and d.humanized_md <> '' then d.humanized_md else coalesce(d.structured->>'body_md', d.content_md) end, title = coalesce(d.structured->>'title', title), rules_check = d.rules_check,
      status = case when status in ('planned', 'drafting', 'in_review', 'verification') then 'approved' else status end
    where id = d.target_id;
    v_target := 'citation';
  elsif d.kind = 'script' and d.target_kind = 'video' then
    update public.fw_videos set script_md = v_text, script_status = 'approved', status = case when status = 'planned' then 'script_ready' else status end where id = d.target_id;
    v_target := 'script';
  elsif d.kind = 'shorts' and d.target_kind = 'video' then
    update public.fw_videos set shorts_cut_list = coalesce(d.structured->'clips', '[]'::jsonb) where id = d.target_id;
    v_target := 'shorts cut list';
  elsif d.kind in ('recap', 'report') then
    v_target := d.kind;   -- F6 ships these through fw_reports
  else
    raise exception 'flywheel: no apply rule for % on %', d.kind, d.target_kind;
  end if;
  update public.fw_drafts set status = 'applied', applied_at = v_now where id = p_draft;
  perform public.fw_log(d.program_id, 'note', 'Draft applied: ' || coalesce(d.title, d.kind) || ' → ' || v_target || case when d.humanized_md is not null then ' (humanized)' else '' end, jsonb_build_object('draft_id', d.id, 'kind', d.kind), false);
  return jsonb_build_object('applied', v_target, 'humanized', d.humanized_md is not null);
end;
$$;


--
-- Name: fw_apply_intake(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_apply_intake(p_program uuid, p_data jsonb, p_source text DEFAULT 'manual'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_prog record; v_fact text; v_added int := 0; v_kw text[]; v_comp text[]; v_access jsonb; v_cluster uuid; v_hyp jsonb;
  f text;
begin
  if not (public.can_view_flywheel() or auth.uid() is null) then raise exception 'flywheel: not allowed' using errcode = '42501'; end if;
  select * into v_prog from public.fw_programs where id = p_program;
  if v_prog.id is null then raise exception 'flywheel: program not found'; end if;
  v_kw := v_prog.keywords; v_comp := v_prog.competitors; v_access := v_prog.access;
  if jsonb_typeof(p_data->'keywords') = 'array' then
    select array_agg(distinct x) into v_kw from (select unnest(v_kw) x union select trim(value::text, '"') from jsonb_array_elements(p_data->'keywords') where trim(value::text, '"') <> '') s;
  end if;
  if jsonb_typeof(p_data->'competitors') = 'array' then
    select array_agg(distinct x) into v_comp from (select unnest(v_comp) x union select trim(value::text, '"') from jsonb_array_elements(p_data->'competitors') where trim(value::text, '"') <> '') s;
  end if;
  if jsonb_typeof(p_data->'access') = 'array' then
    for f in select trim(value::text, '"') from jsonb_array_elements(p_data->'access') loop v_access := v_access || jsonb_build_object(f, true); end loop;
  elsif jsonb_typeof(p_data->'access') = 'object' then
    v_access := v_access || (p_data->'access');
  end if;
  if jsonb_typeof(p_data->'keyword_hypotheses') = 'array' then v_hyp := coalesce(v_prog.keyword_hypotheses, '[]'::jsonb) || (p_data->'keyword_hypotheses'); else v_hyp := v_prog.keyword_hypotheses; end if;
  update public.fw_programs set
    brand_name  = coalesce(nullif(v_prog.brand_name, ''), nullif(p_data->>'brand_name', '')),
    primary_url = coalesce(nullif(v_prog.primary_url, ''), nullif(p_data->>'primary_url', '')),
    icp_md      = coalesce(nullif(v_prog.icp_md, ''), nullif(p_data->>'icp_md', '')),
    sme_name    = coalesce(nullif(v_prog.sme_name, ''), nullif(p_data->>'sme_name', '')),
    sme_email   = coalesce(nullif(v_prog.sme_email, ''), nullif(p_data->>'sme_email', '')),
    sme_phone   = coalesce(nullif(v_prog.sme_phone, ''), nullif(p_data->>'sme_phone', '')),
    dev_contact = coalesce(nullif(v_prog.dev_contact, ''), nullif(p_data->>'dev_contact', '')),
    angles_md   = case when nullif(p_data->>'angles_md', '') is null then v_prog.angles_md else coalesce(v_prog.angles_md || E'\n\n', '') || (p_data->>'angles_md') end,
    keywords = coalesce(v_kw, '{}'), competitors = coalesce(v_comp, '{}'), access = coalesce(v_access, '{}'::jsonb), keyword_hypotheses = coalesce(v_hyp, '[]'::jsonb),
    intake_completed_at = coalesce(v_prog.intake_completed_at, case when p_source in ('session', 'extract') then now() end)
  where id = p_program;
  if jsonb_typeof(p_data->'facts') = 'array' then
    for v_fact in select trim(coalesce(value->>'fact', trim(value::text, '"'))) from jsonb_array_elements(p_data->'facts') loop
      if v_fact <> '' and not exists (select 1 from public.fw_facts where program_id = p_program and lower(fact) = lower(v_fact)) then
        insert into public.fw_facts (program_id, fact, status, created_by) values (p_program, left(v_fact, 600), 'proposed', auth.uid());
        v_added := v_added + 1;
      end if;
    end loop;
  end if;
  if nullif(p_data->>'anchor_keyword', '') is not null then
    select id into v_cluster from public.fw_clusters where program_id = p_program and number = 1;
    if v_cluster is not null then
      update public.fw_clusters set anchor_keyword = coalesce(anchor_keyword, p_data->>'anchor_keyword') where id = v_cluster;
    end if;
  end if;
  perform public.fw_log(p_program, 'note', 'Intake applied (' || p_source || '): ' || v_added || ' new facts', jsonb_build_object('source', p_source, 'facts_added', v_added), false);
  return jsonb_build_object('facts_added', v_added, 'keywords', coalesce(array_length(v_kw, 1), 0), 'competitors', coalesce(array_length(v_comp, 1), 0));
end;
$$;


--
-- Name: fw_approvals_zz_decide(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_approvals_zz_decide() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.status is distinct from old.status and new.status in ('approved', 'auto_approved', 'changes_requested') then
    new.decided_at := coalesce(new.decided_at, now());
    if new.kind = 'plan' then
      update public.fw_clusters set plan_status = case when new.status = 'changes_requested' then 'changes_requested' else 'approved' end, plan_approved_by = case when new.status = 'changes_requested' then plan_approved_by else coalesce(new.decided_by_label, 'client') end, plan_approved_at = case when new.status = 'changes_requested' then plan_approved_at else coalesce(plan_approved_at, now()) end where id = new.target_id;
    elsif new.kind = 'page' then
      update public.fw_pages set status = case when new.status = 'changes_requested' then 'changes_requested' else 'approved' end, approved_by = case when new.status = 'changes_requested' then approved_by else coalesce(new.decided_by_label, 'client') end, approved_at = case when new.status = 'changes_requested' then approved_at else coalesce(approved_at, now()) end where id = new.target_id;
    end if;
    perform public.fw_log(new.program_id, 'approval', new.title || ' — ' || replace(new.status, '_', ' ') || coalesce(' by ' || new.decided_by_label, '') || coalesce(': ' || left(new.client_comment, 200), ''), jsonb_build_object('approval_id', new.id, 'status', new.status), true, new.decided_by_label);
  end if;
  return new;
end;
$$;


--
-- Name: fw_audit_answers_zz_spend(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_audit_answers_zz_spend() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.status = 'done' and old.status <> 'done' and new.cost_usd > 0 then
    update public.fw_ai_connections set spend_month_usd = case when spend_month = date_trunc('month', now())::date then spend_month_usd + new.cost_usd else new.cost_usd end, spend_month = date_trunc('month', now())::date, last_ok_at = now() where provider = 'nous';
  end if;
  return new;
end;
$$;


--
-- Name: fw_audit_estimate(text[], integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_audit_estimate(p_model_ids text[], p_prompts integer, p_max_tokens integer DEFAULT 600) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select round(coalesce(sum((coalesce(prompt_usd_per_m, 0) * 120 + coalesce(completion_usd_per_m, 0) * p_max_tokens) / 1000000.0), 0) * p_prompts, 4)
    from public.fw_ai_models where id = any(p_model_ids);
$$;


--
-- Name: fw_audit_prompts_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_audit_prompts_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'UPDATE' and old.is_locked and new.prompt is distinct from old.prompt then
    raise exception 'flywheel: a locked prompt cannot be edited; retire it and add a new one' using errcode = '42501';
  end if;
  if new.is_locked and new.locked_at is null then new.locked_at := now(); end if;
  return new;
end;
$$;


--
-- Name: fw_audit_queue(uuid, text, text[], uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_audit_queue(p_program uuid, p_kind text DEFAULT 'monthly'::text, p_model_ids text[] DEFAULT NULL::text[], p_cluster uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare v_conn record; v_models text[]; v_prompts uuid[]; v_est numeric; v_id uuid; v_prog record; v_cfg jsonb; v_month date := date_trunc('month', now())::date;
begin
  if not (public.can_view_flywheel() or auth.uid() is null) then raise exception 'flywheel: not allowed' using errcode = '42501'; end if;
  select * into v_conn from public.fw_ai_connections where provider = 'nous';
  if v_conn.id is null or not v_conn.is_enabled or v_conn.encrypted_api_key is null then
    raise exception 'FW_AUDIT_OFF: the AI visibility panel is off until the Nous key is entered in Admin → Integrations';
  end if;
  select * into v_prog from public.fw_programs where id = p_program;
  if v_prog.id is null then raise exception 'flywheel: program not found'; end if;
  select value into v_cfg from public.fw_settings where key = 'audit';
  select coalesce(array_agg(id order by is_core desc, sort, id), '{}') into v_models from public.fw_ai_models where is_active and in_panel and (p_model_ids is null or id = any(p_model_ids));
  if coalesce(array_length(v_models, 1), 0) = 0 then raise exception 'FW_AUDIT_PANEL: no models in the panel; sync the model list first'; end if;
  select coalesce(array_agg(id order by position), '{}') into v_prompts from public.fw_audit_prompts where program_id = p_program and is_locked and retired_at is null;
  if coalesce(array_length(v_prompts, 1), 0) = 0 then raise exception 'FW_AUDIT_PROMPTS: lock the buyer prompts first'; end if;
  v_est := public.fw_audit_estimate(v_models, array_length(v_prompts, 1), v_conn.max_tokens);
  if v_conn.spend_month < v_month then update public.fw_ai_connections set spend_month = v_month, spend_month_usd = 0 where id = v_conn.id; v_conn.spend_month_usd := 0; end if;
  if v_conn.spend_month_usd + v_est > v_conn.monthly_cap_usd then
    raise exception 'FW_AUDIT_CAP: estimate $% would exceed the monthly cap ($% of $% used)', v_est, v_conn.spend_month_usd, v_conn.monthly_cap_usd;
  end if;
  insert into public.fw_audit_runs (program_id, cluster_id, kind, model_ids, prompt_ids, competitors, estimate_usd, answers_total, requested_by)
  values (p_program, p_cluster, p_kind, v_models, v_prompts, v_prog.competitors, v_est, array_length(v_models, 1) * array_length(v_prompts, 1), auth.uid())
  returning id into v_id;
  insert into public.fw_audit_answers (run_id, program_id, prompt_id, model_id)
  select v_id, p_program, p, m from unnest(v_prompts) p cross join unnest(v_models) m;
  perform public.fw_log(p_program, 'audit', 'AI visibility ' || p_kind || ' queued: ' || array_length(v_models, 1) || ' models × ' || array_length(v_prompts, 1) || ' prompts, est $' || v_est, jsonb_build_object('run_id', v_id), false);
  return v_id;
end;
$_$;


--
-- Name: fw_audit_rollup(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_audit_rollup(p_run uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_run record; v_core text[]; v_total int; v_present int; v_core_total int; v_core_present int; v_pos numeric; v_sent numeric; v_acc numeric; v_sov numeric; v_mis int; v_pc jsonb;
begin
  select * into v_run from public.fw_audit_runs where id = p_run;
  if v_run.id is null then return null; end if;
  select coalesce(array_agg(id), '{}') into v_core from public.fw_ai_models where is_core;
  -- per prompt
  delete from public.fw_audit_scores where run_id = p_run;
  insert into public.fw_audit_scores (run_id, prompt_id, models, present, core_models, core_present, avg_position, sentiment_score, accuracy_rate, sov, misinfo_count)
  select p_run, a.prompt_id,
         count(*) filter (where a.status = 'done'),
         count(*) filter (where a.status = 'done' and a.presence),
         count(*) filter (where a.status = 'done' and a.model_id = any(v_core)),
         count(*) filter (where a.status = 'done' and a.model_id = any(v_core) and a.presence),
         round(avg(a.position) filter (where a.presence), 2),
         round(avg(case a.sentiment when 'positive' then 100 when 'mixed' then 50 when 'neutral' then 50 when 'negative' then 0 end) filter (where a.presence), 2),
         round(100.0 * count(*) filter (where a.presence and a.accuracy = 'accurate') / nullif(count(*) filter (where a.presence and a.accuracy in ('accurate', 'inaccurate', 'partial')), 0), 2),
         round(100.0 * count(*) filter (where a.presence) / nullif(count(*) filter (where a.presence) + (select coalesce(sum(cardinality(x.competitors_named)), 0) from public.fw_audit_answers x where x.run_id = p_run and x.prompt_id = a.prompt_id and x.status = 'done'), 0), 2),
         coalesce(sum(cardinality(a.misinformation)), 0)
    from public.fw_audit_answers a where a.run_id = p_run group by a.prompt_id;
  -- run totals
  select count(*) filter (where status = 'done'), count(*) filter (where status = 'done' and presence),
         count(*) filter (where status = 'done' and model_id = any(v_core)), count(*) filter (where status = 'done' and model_id = any(v_core) and presence),
         round(avg(position) filter (where presence), 2),
         round(avg(case sentiment when 'positive' then 100 when 'mixed' then 50 when 'neutral' then 50 when 'negative' then 0 end) filter (where presence), 2),
         round(100.0 * count(*) filter (where presence and accuracy = 'accurate') / nullif(count(*) filter (where presence and accuracy in ('accurate', 'inaccurate', 'partial')), 0), 2),
         coalesce(sum(cardinality(misinformation)), 0)
    into v_total, v_present, v_core_total, v_core_present, v_pos, v_sent, v_acc, v_mis
    from public.fw_audit_answers where run_id = p_run;
  select coalesce(jsonb_object_agg(c, n), '{}'::jsonb) into v_pc from (select unnest(competitors_named) c, count(*) n from public.fw_audit_answers where run_id = p_run and status = 'done' group by 1) s;
  select round(100.0 * v_present / nullif(v_present + coalesce((select sum(cardinality(competitors_named)) from public.fw_audit_answers where run_id = p_run and status = 'done'), 0), 0), 2) into v_sov;
  update public.fw_audit_runs set
    answers_done = v_total, answers_failed = (select count(*) from public.fw_audit_answers where run_id = p_run and status = 'failed'),
    actual_usd = (select coalesce(sum(cost_usd), 0) from public.fw_audit_answers where run_id = p_run),
    presence_rate = round(100.0 * v_present / nullif(v_total, 0), 2), core_presence_rate = round(100.0 * v_core_present / nullif(v_core_total, 0), 2),
    avg_position = v_pos, sentiment_score = v_sent, accuracy_rate = v_acc, sov = v_sov, misinfo_count = v_mis, per_competitor = v_pc
  where id = p_run;
  return jsonb_build_object('answers', v_total, 'present', v_present, 'presence_rate', round(100.0 * v_present / nullif(v_total, 0), 2), 'core_presence_rate', round(100.0 * v_core_present / nullif(v_core_total, 0), 2), 'sov', v_sov, 'misinfo', v_mis);
end;
$$;


--
-- Name: fw_audit_runs_zz_done(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_audit_runs_zz_done() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
begin
  if new.status = 'done' and old.status <> 'done' then
    if new.cluster_id is not null and new.kind in ('baseline', 'reaudit') then update public.fw_clusters set audit_run_id = new.id where id = new.cluster_id; end if;
    perform public.fw_log(new.program_id, 'audit', 'AI visibility ' || new.kind || ' done: presence ' || coalesce(new.presence_rate::text, '—') || '% (core ' || coalesce(new.core_presence_rate::text, '—') || '%), SOV ' || coalesce(new.sov::text, '—') || '%, misinformation ' || new.misinfo_count || ', $' || new.actual_usd, jsonb_build_object('run_id', new.id), true);
    insert into public.client_deliverables (client_id, program_id, package_key, kind, title, status, period_month, delivered_at, ref_table, ref_id, href)
    select p.client_id, new.program_id, 'flywheel', 'audit', 'AI visibility ' || new.kind || ' · ' || to_char(new.period_month, 'Mon YYYY'), 'delivered', new.period_month, new.finished_at, 'fw_audit_runs', new.id, '/flywheel/' || new.program_id || '?tab=visibility'
      from public.fw_programs p where p.id = new.program_id
    on conflict (ref_table, ref_id) where ref_id is not null do update set status = 'delivered', delivered_at = excluded.delivered_at;
  end if;
  return new;
end;
$_$;


--
-- Name: fw_audit_score_answer(text, text, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_audit_score_answer(p_answer text, p_brand text, p_url text, p_competitors text[]) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare v_low text; v_brand_pos int; v_dom text; v_dom_pos int; v_named text[] := '{}'; c text; v_pos int; v_rank int := 1; v_present boolean; v_how text; v_offsets int[] := '{}';
begin
  if p_answer is null then return jsonb_build_object('presence', null); end if;
  v_low := lower(p_answer);
  v_brand_pos := case when p_brand is not null and p_brand <> '' then nullif(position(lower(p_brand) in v_low), 0) end;
  v_dom := case when p_url is not null then regexp_replace(lower(p_url), '^https?://(www\.)?([^/]+).*$', '\2') end;
  v_dom_pos := case when v_dom is not null and v_dom <> '' then nullif(position(v_dom in v_low), 0) end;
  v_present := v_brand_pos is not null or v_dom_pos is not null;
  v_how := case when v_brand_pos is not null and v_dom_pos is not null then 'both' when v_brand_pos is not null then 'name' when v_dom_pos is not null then 'domain' end;
  foreach c in array coalesce(p_competitors, '{}') loop
    if c is null or c = '' then continue; end if;
    v_pos := nullif(position(lower(c) in v_low), 0);
    if v_pos is not null then
      v_named := v_named || c;
      if v_present and v_pos < least(coalesce(v_brand_pos, v_dom_pos), coalesce(v_dom_pos, v_brand_pos)) then v_rank := v_rank + 1; end if;
    end if;
  end loop;
  return jsonb_build_object('presence', v_present, 'presence_how', v_how, 'position', case when v_present then v_rank end, 'competitors_named', to_jsonb(v_named));
end;
$_$;


--
-- Name: fw_audit_trend(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_audit_trend(p_program uuid) RETURNS TABLE(run_id uuid, kind text, period_month date, finished_at timestamp with time zone, presence_rate numeric, core_presence_rate numeric, avg_position numeric, sentiment_score numeric, accuracy_rate numeric, sov numeric, misinfo_count integer, models integer, answers integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select id, kind, period_month, finished_at, presence_rate, core_presence_rate, avg_position, sentiment_score, accuracy_rate, sov, misinfo_count, cardinality(model_ids), answers_done
    from public.fw_audit_runs where program_id = p_program and status = 'done' and public.can_view_flywheel()
   order by finished_at;
$$;


--
-- Name: fw_auto_approve_due(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_auto_approve_due() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare n int;
begin
  with due as (select id from public.fw_approvals where status = 'pending' and due_at is not null and due_at < now())
  update public.fw_approvals a set status = 'auto_approved', decided_by_label = 'auto', client_comment = coalesce(client_comment, 'Approved automatically after the agreed window (client auto-approve is on).')
    from due where a.id = due.id;
  get diagnostics n = row_count;
  return n;
end;
$$;


--
-- Name: fw_check_rules(text, text, text, text, text[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_check_rules(p_text text, p_brand text, p_url text, p_keyword text, p_facts text[], p_channel text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare v_low text; v_dom text; v_checks jsonb := '{}'::jsonb; v_failed text[] := '{}'; f text; v_fact_hit boolean := false; v_promo int;
begin
  if p_text is null or p_text = '' then return jsonb_build_object('ok', false, 'failed', jsonb_build_array('empty'), 'checks', '{}'::jsonb); end if;
  v_low := lower(p_text);
  -- verbatim keyword in the first 200 chars (title / lead)
  v_checks := v_checks || jsonb_build_object('verbatim_keyword', p_keyword is not null and position(lower(p_keyword) in left(v_low, 300)) > 0);
  v_dom := case when p_url is not null then regexp_replace(lower(p_url), '^https?://(www\.)?([^/]+).*$', '\2') end;
  v_checks := v_checks || jsonb_build_object('brand_url', v_dom is not null and position(v_dom in v_low) > 0);
  v_checks := v_checks || jsonb_build_object('full_brand_name', p_brand is not null and position(lower(p_brand) in v_low) > 0);
  foreach f in array coalesce(p_facts, '{}') loop
    -- a fact "hits" when at least 60% of its significant words (len > 3) appear
    if f is not null and f <> '' then
      declare words text[]; w text; n int := 0; hit int := 0; begin
        words := regexp_split_to_array(lower(f), '[^a-z0-9]+');
        foreach w in array words loop
          if length(w) > 3 then n := n + 1; if position(w in v_low) > 0 then hit := hit + 1; end if; end if;
        end loop;
        if n > 0 and hit::numeric / n >= 0.6 then v_fact_hit := true; end if;
      end;
    end if;
  end loop;
  v_checks := v_checks || jsonb_build_object('one_fact', v_fact_hit);
  if p_channel in ('reddit', 'quora_answer', 'quora_space') then
    v_promo := (select count(*) from regexp_matches(v_low, '(buy now|limited time|discount|sign up today|best in the world|#1 |number one|order now|promo code|click here)', 'g'));
    v_checks := v_checks || jsonb_build_object('non_promotional', v_promo = 0);
  end if;
  select coalesce(array_agg(key), '{}') into v_failed from jsonb_each(v_checks) where value = 'false'::jsonb;
  return jsonb_build_object('ok', cardinality(v_failed) = 0, 'failed', to_jsonb(v_failed), 'checks', v_checks, 'checked_at', now());
end;
$_$;


--
-- Name: fw_citations_zz_queue(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_citations_zz_queue() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_due timestamptz;
begin
  if new.status in ('approved', 'queued') and (tg_op = 'INSERT' or old.status not in ('approved', 'queued')) then
    select citation_wave_due_at into v_due from public.fw_pages where id = new.page_id;
    insert into public.fw_posting_queue (program_id, citation_id, channel_key, poster_kind, assignee_id, due_at)
    values (new.program_id, new.id, new.channel_key, new.poster_kind, new.poster_id, v_due)
    on conflict (citation_id) do update set status = case when public.fw_posting_queue.status = 'dropped' then 'queued' else public.fw_posting_queue.status end, due_at = coalesce(excluded.due_at, public.fw_posting_queue.due_at);
    if new.status = 'approved' then update public.fw_citations set status = 'queued' where id = new.id; end if;
  end if;
  return new;
end;
$$;


--
-- Name: fw_citations_zz_rollup(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_citations_zz_rollup() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_live int; v_target int;
begin
  if new.status in ('posted', 'live') and (tg_op = 'INSERT' or old.status not in ('posted', 'live')) then
    if new.posted_on is null then update public.fw_citations set posted_on = current_date where id = new.id; end if;
    if new.fact_id is not null then update public.fw_facts set use_count = use_count + 1 where id = new.fact_id; end if;
  end if;
  if new.page_id is not null then
    select count(*) filter (where c.status in ('posted', 'live')), coalesce(max(p.target_citations), 20)
      into v_live, v_target
      from public.fw_citations c join public.fw_pages p on p.id = c.page_id
     where c.page_id = new.page_id;
    if v_live >= v_target then
      update public.fw_pages set citation_wave_done_at = coalesce(citation_wave_done_at, now()) where id = new.page_id;
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: fw_clusters_dates(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_clusters_dates() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.starts_on is not null then
    if new.ends_on is null or (tg_op = 'UPDATE' and new.starts_on is distinct from old.starts_on and new.ends_on = old.ends_on) then new.ends_on := new.starts_on + 90; end if;
    if new.reaudit_due_on is null or (tg_op = 'UPDATE' and new.starts_on is distinct from old.starts_on and new.reaudit_due_on = old.reaudit_due_on) then new.reaudit_due_on := new.starts_on + 90; end if;
  end if;
  if new.plan_status = 'approved' and new.plan_approved_at is null then new.plan_approved_at := now(); end if;
  return new;
end;
$$;


--
-- Name: fw_deliverable_status(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_deliverable_status(p_status text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case p_status
    when 'planned' then 'planned'
    when 'draft' then 'in_progress'
    when 'drafting' then 'in_progress'
    when 'script_ready' then 'in_progress'
    when 'scheduled' then 'in_progress'
    when 'recorded' then 'in_progress'
    when 'edited' then 'in_progress'
    when 'in_production' then 'in_progress'
    when 'in_review' then 'in_review'
    when 'verification' then 'in_review'
    when 'awaiting_client' then 'awaiting_client'
    when 'changes_requested' then 'in_progress'
    when 'approved' then 'approved'
    when 'handed_off' then 'approved'
    when 'live' then 'delivered'
    when 'published' then 'delivered'
    when 'closed' then 'delivered'
    else 'in_progress' end
$$;


--
-- Name: fw_drafts_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_drafts_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_has_verifier boolean;
begin
  if tg_op = 'UPDATE' and new.status is distinct from old.status then
    if new.status = 'in_review' and old.status not in ('draft', 'in_review', 'verification', 'approved') then raise exception 'flywheel: only a draft goes to review'; end if;
    if new.status = 'verification' then
      if old.status <> 'in_review' then raise exception 'flywheel: lane review comes before verification'; end if;
      new.reviewed_by := coalesce(new.reviewed_by, auth.uid()); new.reviewed_at := coalesce(new.reviewed_at, now());
    end if;
    if new.status = 'approved' then
      select exists (select 1 from public.fw_program_members where program_id = new.program_id and role = 'verifier') into v_has_verifier;
      if old.status = 'verification' then
        new.verified_by := coalesce(new.verified_by, auth.uid()); new.verified_at := coalesce(new.verified_at, now());
      elsif old.status = 'in_review' and not v_has_verifier then
        new.reviewed_by := coalesce(new.reviewed_by, auth.uid()); new.reviewed_at := coalesce(new.reviewed_at, now());
      else
        raise exception 'flywheel: approval needs lane review then verification (the program has a verifier)' using errcode = '42501';
      end if;
    end if;
    if new.status = 'applied' and old.status <> 'approved' then raise exception 'flywheel: apply an approved draft'; end if;
    if new.status = 'applied' then new.applied_at := coalesce(new.applied_at, now()); end if;
    if new.status = 'rejected' then new.reviewed_by := coalesce(new.reviewed_by, auth.uid()); new.reviewed_at := coalesce(new.reviewed_at, now()); end if;
  end if;
  return new;
end;
$$;


--
-- Name: fw_health_check(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_health_check(p_program uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare p record; v_scope jsonb; v_month date := date_trunc('month', now())::date; v_day int; v_pages_live int; v_cits int; v_pages_goal numeric; v_cits_goal numeric; v_flags int := 0; v_resolved int := 0; v_bells int := 0;
  v_now_kinds text[]; r record; v_owner uuid; v_target uuid; v_last_run record; v_base record; v_report boolean; v_call boolean; v_delivery numeric; v_resp numeric; v_decided int; v_ontime int;
begin
  select id into v_owner from public.profiles where lower(email) = public.org_owner_email();
  for p in select pr.*, t.scope from public.fw_programs pr join public.fw_package_templates t on t.key = pr.package_key where pr.status = 'active' and (p_program is null or pr.id = p_program) loop
    v_now_kinds := '{}';
    v_scope := p.scope;
    v_day := extract(day from now())::int;
    -- 1. approvals overdue (past due_at, or > 5 business days with no window)
    for r in select a.* from public.fw_approvals a where a.program_id = p.id and a.status = 'pending' and coalesce(a.due_at, a.requested_at + interval '7 days') < now() loop
      insert into public.fw_health_flags (program_id, client_id, kind, severity, summary, detail, ref_id) values (p.id, p.client_id, 'approval_overdue', 'warning', 'Client approval overdue: ' || r.title, jsonb_build_object('due_at', r.due_at, 'requested_at', r.requested_at), r.id)
      on conflict (program_id, kind, coalesce(ref_id, '00000000-0000-0000-0000-000000000000'::uuid)) where status = 'open' do update set last_seen_at = now();
      v_now_kinds := v_now_kinds || ('approval_overdue:' || r.id);
    end loop;
    -- 2. citation waves > 72 h
    for r in select pg.* from public.fw_pages pg where pg.program_id = p.id and pg.live_at is not null and pg.citation_wave_done_at is null and pg.citation_wave_due_at < now() loop
      insert into public.fw_health_flags (program_id, client_id, kind, severity, summary, detail, ref_id) values (p.id, p.client_id, 'wave_overdue', 'critical', 'Citation wave past 72 h: page ' || r.number || ' (' || r.keyword || ')', jsonb_build_object('live_at', r.live_at, 'due_at', r.citation_wave_due_at), r.id)
      on conflict (program_id, kind, coalesce(ref_id, '00000000-0000-0000-0000-000000000000'::uuid)) where status = 'open' do update set last_seen_at = now();
      v_now_kinds := v_now_kinds || ('wave_overdue:' || r.id);
    end loop;
    -- 3. monthly pace (after day 10; prorated goal)
    select count(*) into v_pages_live from public.fw_pages where program_id = p.id and live_at >= v_month;
    select count(*) into v_cits from public.fw_citations where program_id = p.id and status in ('posted', 'live') and posted_on >= v_month;
    v_pages_goal := coalesce((v_scope->'per_month'->>'pages_min')::numeric, 3) * least(v_day, 30) / 30.0;
    v_cits_goal := coalesce((v_scope->'per_month'->>'citations_min')::numeric, 60) * least(v_day, 30) / 30.0;
    if v_day > 10 and p.first_set_live_on is not null and v_pages_live < floor(v_pages_goal * 0.6) then
      insert into public.fw_health_flags (program_id, client_id, kind, severity, summary, detail) values (p.id, p.client_id, 'pages_behind', 'warning', 'Pages behind monthly pace: ' || v_pages_live || ' live by day ' || v_day || ' (pace ' || round(v_pages_goal, 1) || ')', jsonb_build_object('live', v_pages_live, 'pace', v_pages_goal))
      on conflict (program_id, kind, coalesce(ref_id, '00000000-0000-0000-0000-000000000000'::uuid)) where status = 'open' do update set last_seen_at = now(), summary = excluded.summary, detail = excluded.detail;
      v_now_kinds := v_now_kinds || 'pages_behind:';
    end if;
    if v_day > 10 and p.first_set_live_on is not null and v_cits < floor(v_cits_goal * 0.6) then
      insert into public.fw_health_flags (program_id, client_id, kind, severity, summary, detail) values (p.id, p.client_id, 'citations_behind', 'warning', 'Citations behind monthly pace: ' || v_cits || ' shipped by day ' || v_day || ' (pace ' || round(v_cits_goal) || ')', jsonb_build_object('shipped', v_cits, 'pace', v_cits_goal))
      on conflict (program_id, kind, coalesce(ref_id, '00000000-0000-0000-0000-000000000000'::uuid)) where status = 'open' do update set last_seen_at = now(), summary = excluded.summary, detail = excluded.detail;
      v_now_kinds := v_now_kinds || 'citations_behind:';
    end if;
    -- 4. missed report (no monthly report sent for the previous month by the 10th) / missed call (no client call last month)
    if v_day > 10 and p.first_set_live_on is not null and p.first_set_live_on < v_month - interval '1 month' then
      select exists (select 1 from public.fw_reports where program_id = p.id and kind = 'monthly_report' and status in ('sent', 'delivered', 'opened') and period_to >= (v_month - interval '1 month')::date) into v_report;
      if not v_report then
        insert into public.fw_health_flags (program_id, client_id, kind, severity, summary) values (p.id, p.client_id, 'report_missed', 'warning', 'Monthly report for ' || to_char(v_month - interval '1 month', 'Mon YYYY') || ' not sent')
        on conflict (program_id, kind, coalesce(ref_id, '00000000-0000-0000-0000-000000000000'::uuid)) where status = 'open' do update set last_seen_at = now();
        v_now_kinds := v_now_kinds || 'report_missed:';
      end if;
      select exists (select 1 from public.calls where client_id = p.client_id and occurred_at >= v_month - interval '1 month' and occurred_at < v_month) into v_call;
      if not v_call then
        insert into public.fw_health_flags (program_id, client_id, kind, severity, summary) values (p.id, p.client_id, 'call_missed', 'info', 'No client call recorded in ' || to_char(v_month - interval '1 month', 'Mon YYYY'))
        on conflict (program_id, kind, coalesce(ref_id, '00000000-0000-0000-0000-000000000000'::uuid)) where status = 'open' do update set last_seen_at = now();
        v_now_kinds := v_now_kinds || 'call_missed:';
      end if;
    end if;
    -- 5. no visibility movement at 90 days (latest done run vs the earliest, both exist, >= 90 days apart, presence not up)
    select * into v_last_run from public.fw_audit_runs where program_id = p.id and status = 'done' order by finished_at desc limit 1;
    select * into v_base from public.fw_audit_runs where program_id = p.id and status = 'done' order by finished_at asc limit 1;
    if v_last_run.id is not null and v_base.id is not null and v_last_run.id <> v_base.id and v_last_run.finished_at >= v_base.finished_at + interval '85 days' and coalesce(v_last_run.presence_rate, 0) <= coalesce(v_base.presence_rate, 0) then
      insert into public.fw_health_flags (program_id, client_id, kind, severity, summary, detail) values (p.id, p.client_id, 'visibility_flat', 'critical', 'No AI visibility movement at 90 days: ' || coalesce(v_base.presence_rate::text, '—') || '% → ' || coalesce(v_last_run.presence_rate::text, '—') || '%', jsonb_build_object('baseline', v_base.presence_rate, 'latest', v_last_run.presence_rate))
      on conflict (program_id, kind, coalesce(ref_id, '00000000-0000-0000-0000-000000000000'::uuid)) where status = 'open' do update set last_seen_at = now(), summary = excluded.summary;
      v_now_kinds := v_now_kinds || 'visibility_flat:';
    end if;
    -- 6. monthly recording missed (after day 20, no fw_videos row for this month past 'planned')
    if v_day > 20 and p.first_set_live_on is not null and not exists (select 1 from public.fw_videos where program_id = p.id and month = v_month and status not in ('planned')) then
      insert into public.fw_health_flags (program_id, client_id, kind, severity, summary) values (p.id, p.client_id, 'recording_missed', 'warning', 'Monthly seed-video recording not scheduled / recorded for ' || to_char(v_month, 'Mon YYYY'))
      on conflict (program_id, kind, coalesce(ref_id, '00000000-0000-0000-0000-000000000000'::uuid)) where status = 'open' do update set last_seen_at = now();
      v_now_kinds := v_now_kinds || 'recording_missed:';
    end if;
    -- resolve open flags no longer observed
    update public.fw_health_flags f set status = 'resolved', resolved_at = now()
     where f.program_id = p.id and f.status = 'open' and not ((f.kind || ':' || coalesce(f.ref_id::text, '')) = any(v_now_kinds));
    get diagnostics v_resolved = row_count;
    -- bells: once per flag per day to the Strategist + Verifier + Alex
    for r in select * from public.fw_health_flags where program_id = p.id and status = 'open' and (bell_day is null or bell_day < current_date) and (muted_until is null or muted_until < now()) loop
      for v_target in select user_id from public.fw_program_members where program_id = p.id and role in ('strategist', 'verifier') union select v_owner where v_owner is not null loop
        perform public.rev_bell(v_target, 'flywheel_health', (select display_name from public.clients_v2 where id = p.client_id) || ': ' || r.summary, 'Flywheel health flag (' || r.severity || ').', '/flywheel/' || p.id, 'fw:health:' || r.id || ':' || current_date);
        v_bells := v_bells + 1;
      end loop;
      update public.fw_health_flags set bell_day = current_date where id = r.id;
      v_flags := v_flags + 1;
    end loop;
    -- metrics for the health engine / dashboards (client-scoped, this month)
    v_delivery := case when v_pages_goal + v_cits_goal > 0 then round(100 * least(1, (v_pages_live + v_cits) / (coalesce((v_scope->'per_month'->>'pages_min')::numeric, 3) + coalesce((v_scope->'per_month'->>'citations_min')::numeric, 60)))) end;
    select count(*), count(*) filter (where decided_at <= coalesce(due_at, requested_at + interval '3 days')) into v_decided, v_ontime from public.fw_approvals where program_id = p.id and status in ('approved', 'changes_requested') and decided_at >= v_month;
    v_resp := case when v_decided > 0 then round(100.0 * v_ontime / v_decided) end;
    insert into public.metrics (subject_type, subject_ref, metric_key, period, value, source, computed_at)
    values ('client', p.client_id::text, 'fw_pages_live', v_month, v_pages_live, 'flywheel', now()),
           ('client', p.client_id::text, 'fw_citations_shipped', v_month, v_cits, 'flywheel', now()),
           ('client', p.client_id::text, 'fw_delivery_pct', v_month, coalesce(v_delivery, 0), 'flywheel', now()),
           ('client', p.client_id::text, 'fw_ai_presence', v_month, coalesce(v_last_run.presence_rate, 0), 'flywheel', now())
    on conflict (subject_type, subject_key, metric_key, period, source) do update set value = excluded.value, computed_at = excluded.computed_at;
  end loop;
  return jsonb_build_object('flags_open', v_flags, 'resolved', v_resolved, 'bells', v_bells);
end;
$$;


--
-- Name: fw_intake_resolve(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_intake_resolve(p_token_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare s record; p record;
begin
  select * into s from public.fw_intake_sessions where token_hash = p_token_hash and expires_at > now() and status in ('open', 'submitted');
  if s.id is null then return null; end if;
  select p1.brand_name, c.display_name into p from public.fw_programs p1 join public.clients_v2 c on c.id = p1.client_id where p1.id = s.program_id;
  return jsonb_build_object('session_id', s.id, 'program_id', s.program_id, 'kind', s.kind, 'status', s.status, 'step', s.step, 'answers', s.answers, 'client_name', p.display_name, 'brand_name', p.brand_name);
end;
$$;


--
-- Name: fw_is_member(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_is_member(p_program uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists (select 1 from public.fw_program_members m where m.program_id = p_program and m.user_id = auth.uid())
$$;


--
-- Name: fw_log(uuid, text, text, jsonb, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_log(p_program uuid, p_kind text, p_summary text, p_payload jsonb DEFAULT '{}'::jsonb, p_client_visible boolean DEFAULT false, p_actor_label text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  -- A portal login never writes the timeline directly (the app logs on its
  -- behalf through the service role); a staff user outside the module may
  -- not call this RPC by hand, but the triggers that log for them still run.
  if public.is_portal_user() then raise exception 'flywheel: not allowed' using errcode = '42501'; end if;
  if pg_trigger_depth() = 0 and auth.uid() is not null and not public.can_view_flywheel() then raise exception 'flywheel: not allowed' using errcode = '42501'; end if;
  insert into public.fw_events (program_id, kind, summary, payload, actor_id, actor_label, client_visible)
  values (p_program, p_kind, p_summary, coalesce(p_payload, '{}'::jsonb), auth.uid(), p_actor_label, p_client_visible);
end;
$$;


--
-- Name: fw_mirror_deliverable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_mirror_deliverable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_client uuid; v_kind text; v_title text; v_status text; v_href text; v_period date; v_delivered timestamptz; v_due date; v_prog uuid;
begin
  v_prog := new.program_id;
  select client_id into v_client from public.fw_programs where id = v_prog;
  if v_client is null then return new; end if;
  if tg_table_name = 'fw_pages' then
    v_kind := 'page'; v_title := 'Page ' || new.number || ': ' || coalesce(new.title, new.keyword);
    v_status := public.fw_deliverable_status(new.status); v_delivered := new.live_at;
    v_href := '/flywheel/' || v_prog || '/pages/' || new.id;
    select date_trunc('month', coalesce(new.live_at, now()))::date into v_period;
  elsif tg_table_name = 'fw_videos' then
    v_kind := 'seed_video'; v_title := 'Seed video · ' || to_char(new.month, 'Mon YYYY') || coalesce(': ' || new.title, '');
    v_status := public.fw_deliverable_status(new.status); v_delivered := new.published_at; v_period := new.month;
    v_href := '/flywheel/' || v_prog || '/videos/' || new.id; v_due := (new.shoot_at)::date;
  elsif tg_table_name = 'fw_clusters' then
    v_kind := 'plan'; v_title := 'Cluster ' || new.number || ' plan' || coalesce(': ' || new.anchor_keyword, '');
    v_status := public.fw_deliverable_status(new.plan_status); v_delivered := new.plan_approved_at; v_period := date_trunc('month', coalesce(new.starts_on, current_date))::date;
    v_href := '/flywheel/' || v_prog || '/clusters/' || new.id;
  else
    return new;
  end if;
  insert into public.client_deliverables (client_id, program_id, package_key, kind, title, status, period_month, delivered_at, ref_table, ref_id, href, due_on)
  values (v_client, v_prog, 'flywheel', v_kind, v_title, v_status, v_period, v_delivered, tg_table_name, new.id, v_href, v_due)
  on conflict (ref_table, ref_id) where ref_id is not null do update
    set title = excluded.title, status = excluded.status, period_month = excluded.period_month, delivered_at = excluded.delivered_at, href = excluded.href, due_on = coalesce(excluded.due_on, public.client_deliverables.due_on);
  return new;
end;
$$;


--
-- Name: fw_onboarding_progress(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_onboarding_progress(p_program uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_out jsonb;
begin
  if not (public.can_view_flywheel() or auth.uid() is null) then raise exception 'flywheel: not allowed' using errcode = '42501'; end if;
  with t as (
    select t.*, (select x from unnest(t.tags) x where x like 'phase:%' limit 1) as phase
      from public.tasks t join public.fw_programs p on p.onboarding_project_id = t.project_id
     where p.id = p_program
  )
  select jsonb_build_object(
    'total', count(*), 'done', count(*) filter (where status = 'done'),
    'overdue', count(*) filter (where status not in ('done', 'cancelled') and due_at < now()),
    'phases', (select jsonb_agg(jsonb_build_object('phase', replace(phase, 'phase:', ''), 'total', n, 'done', d, 'overdue', o) order by mn)
                 from (select phase, count(*) n, count(*) filter (where status = 'done') d, count(*) filter (where status not in ('done','cancelled') and due_at < now()) o, min(position) mn from t group by phase) s))
    into v_out
  from t;
  return v_out;
end;
$$;


--
-- Name: fw_pages_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_pages_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_scope jsonb; v_hours int;
begin
  if new.word_target_min is null or new.word_target_max is null then
    select t.scope into v_scope from public.fw_programs p join public.fw_package_templates t on t.key = p.package_key where p.id = new.program_id;
    if new.kind = 'pillar' then
      new.word_target_min := coalesce(new.word_target_min, (v_scope->'pillar_words'->>'min')::int, 1800);
      new.word_target_max := coalesce(new.word_target_max, (v_scope->'pillar_words'->>'max')::int, 2500);
    else
      new.word_target_min := coalesce(new.word_target_min, (v_scope->'question_words'->>'min')::int, 1200);
      new.word_target_max := coalesce(new.word_target_max, (v_scope->'question_words'->>'max')::int, 1800);
    end if;
    if new.target_citations is null then new.target_citations := coalesce((v_scope->'per_cluster'->>'citations_per_page_min')::int, 20); end if;
  end if;
  if new.status = 'live' and new.live_at is null then new.live_at := now(); end if;
  if new.live_at is not null and new.citation_wave_due_at is null then
    select coalesce((value->>'citation_wave_hours')::int, 72) into v_hours from public.fw_settings where key = 'sla';
    new.citation_wave_due_at := new.live_at + make_interval(hours => coalesce(v_hours, 72));
  end if;
  if new.status = 'handed_off' and new.handed_off_at is null then new.handed_off_at := now(); end if;
  if new.status = 'approved' and new.approved_at is null then new.approved_at := now(); end if;
  return new;
end;
$$;


--
-- Name: fw_plan_citations(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_plan_citations(p_page uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_page record; v_ch record; v_n int := 0; i int; v_have int;
begin
  if not (public.can_view_flywheel() or auth.uid() is null) then raise exception 'flywheel: not allowed' using errcode = '42501'; end if;
  select * into v_page from public.fw_pages where id = p_page;
  if v_page.id is null then raise exception 'flywheel: page not found'; end if;
  for v_ch in select * from public.fw_channels where is_active and per_page_min > 0 order by sort loop
    select count(*) into v_have from public.fw_citations where page_id = p_page and channel_key = v_ch.key;
    for i in (v_have + 1)..v_ch.per_page_min loop
      insert into public.fw_citations (program_id, cluster_id, page_id, channel_key, keyword, poster_kind, created_by)
      values (v_page.program_id, v_page.cluster_id, p_page, v_ch.key, v_page.keyword, v_ch.poster_default, auth.uid());
      v_n := v_n + 1;
    end loop;
  end loop;
  return v_n;
end;
$$;


--
-- Name: fw_portal_files_zz_video(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_portal_files_zz_video() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.kind = 'recording' and new.video_id is not null then
    update public.fw_videos set recording_path = new.path, status = case when status in ('planned', 'script_ready', 'scheduled') then 'recorded' else status end where id = new.video_id;
    if new.program_id is not null then perform public.fw_log(new.program_id, 'video', 'Recording uploaded: ' || new.original_name, jsonb_build_object('file_id', new.id, 'video_id', new.video_id), true, new.uploaded_by_label); end if;
  end if;
  return new;
end;
$$;


--
-- Name: fw_portal_overview(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_portal_overview(p_client uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'client', (select jsonb_build_object('id', id, 'name', display_name) from public.clients_v2 where id = p_client),
    'programs', (select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'package_key', p.package_key, 'label', p.label, 'status', p.status, 'kickoff_on', p.kickoff_on, 'first_set_live_on', p.first_set_live_on, 'auto_approve', p.auto_approve, 'brand_name', p.brand_name, 'primary_url', p.primary_url) order by p.created_at), '[]'::jsonb) from public.fw_programs p where p.client_id = p_client and p.status <> 'closed'),
    'pending_approvals', (select count(*) from public.fw_approvals where client_id = p_client and status = 'pending'),
    'open_notes', (select count(*) from public.fw_portal_notes where client_id = p_client and status in ('open', 'acknowledged', 'in_progress')),
    'deliverables', (select coalesce(jsonb_agg(jsonb_build_object('id', d.id, 'package_key', d.package_key, 'kind', d.kind, 'title', d.title, 'status', d.status, 'due_on', d.due_on, 'period_month', d.period_month, 'delivered_at', d.delivered_at, 'client_href', d.client_href) order by d.period_month desc nulls last, d.created_at), '[]'::jsonb) from public.client_deliverables d where d.client_id = p_client and d.visible_to_client)
  )
$$;


--
-- Name: fw_portal_trackers(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_portal_trackers(p_program uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'clusters', (select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'number', c.number, 'anchor_keyword', c.anchor_keyword, 'status', c.status, 'plan_status', c.plan_status, 'plan_md', case when c.plan_status in ('awaiting_client', 'approved') then c.plan_md end, 'plan_loom_url', c.plan_loom_url, 'starts_on', c.starts_on, 'ends_on', c.ends_on, 'reaudit_due_on', c.reaudit_due_on) order by c.number), '[]'::jsonb) from public.fw_clusters c where c.program_id = p_program),
    'pages', (select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'cluster_id', p.cluster_id, 'number', p.number, 'kind', p.kind, 'keyword', p.keyword, 'title', p.title, 'status', p.status, 'quick_answer_md', case when p.status in ('awaiting_client', 'approved', 'handed_off', 'live') then p.quick_answer_md end, 'body_md', case when p.status in ('awaiting_client', 'approved', 'handed_off', 'live') then p.body_md end, 'live_url', p.live_url, 'live_at', p.live_at, 'target_citations', p.target_citations, 'citations_shipped', (select count(*) from public.fw_citations x where x.page_id = p.id and x.status in ('posted', 'live'))) order by p.cluster_id, p.number), '[]'::jsonb) from public.fw_pages p where p.program_id = p_program),
    'citations', (select coalesce(jsonb_agg(jsonb_build_object('id', ci.id, 'page_id', ci.page_id, 'channel_key', ci.channel_key, 'channel', ch.label, 'status', ci.status, 'title', ci.title, 'url', ci.url, 'posted_on', ci.posted_on, 'keyword', ci.keyword, 'models_surfacing', ci.models_surfacing) order by ci.posted_on desc nulls last), '[]'::jsonb) from public.fw_citations ci join public.fw_channels ch on ch.key = ci.channel_key where ci.program_id = p_program and ci.status in ('posted', 'live', 'queued', 'approved')),
    'videos', (select coalesce(jsonb_agg(jsonb_build_object('id', v.id, 'month', v.month, 'title', v.title, 'status', v.status, 'shoot_at', v.shoot_at, 'youtube_url', v.youtube_url, 'checklist', v.checklist, 'chapters', v.chapters, 'script_md', case when v.script_status = 'approved' then v.script_md end, 'recording_path', v.recording_path) order by v.month desc), '[]'::jsonb) from public.fw_videos v where v.program_id = p_program),
    'facts', (select coalesce(jsonb_agg(jsonb_build_object('id', f.id, 'fact', f.fact, 'status', f.status) order by f.sort), '[]'::jsonb) from public.fw_facts f where f.program_id = p_program and f.status <> 'retired')
  )
$$;


--
-- Name: fw_posting_queue_zz_posted(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_posting_queue_zz_posted() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.status = 'claimed' and old.status <> 'claimed' then new.claimed_at := coalesce(new.claimed_at, now()); new.assignee_id := coalesce(new.assignee_id, auth.uid()); end if;
  if new.status = 'posted' and old.status <> 'posted' then
    new.posted_at := coalesce(new.posted_at, now());
    update public.fw_citations set status = 'posted', url = coalesce(new.posted_url, url), posted_on = coalesce(posted_on, current_date), poster_id = coalesce(poster_id, new.assignee_id), poster_handle = coalesce(poster_handle, new.network_property) where id = new.citation_id;
  end if;
  if new.status = 'verified' and old.status <> 'verified' then
    new.verified_at := coalesce(new.verified_at, now());
    update public.fw_citations set status = 'live', verified_by = coalesce(verified_by, auth.uid()), verified_at = coalesce(verified_at, now()) where id = new.citation_id;
  end if;
  return new;
end;
$$;


--
-- Name: fw_programs_sync_contract(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_programs_sync_contract() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.contract_id is not null and (tg_op = 'INSERT' or new.first_set_live_on is distinct from old.first_set_live_on or new.setup_fee_cents is distinct from old.setup_fee_cents or new.contract_id is distinct from old.contract_id) then
    update public.contracts
       set billing_starts_on = coalesce(new.first_set_live_on, billing_starts_on),
           setup_fee_cents   = coalesce(new.setup_fee_cents, setup_fee_cents)
     where id = new.contract_id;
  end if;
  return new;
end;
$$;


--
-- Name: fw_programs_zz_default_agents(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_programs_zz_default_agents() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  insert into public.fw_program_agents (program_id, agent_key, enabled, assigned_by)
  select new.id, a.key, true, new.created_by from public.fw_agents a where a.is_active and a.parent_key is null
  on conflict do nothing;
  return new;
end;
$$;


--
-- Name: fw_reminders_tick(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_reminders_tick() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare r record; v_cfg jsonb; v_queued int := 0; v_bells int := 0; v_window interval; v_half timestamptz; v_due timestamptz; v_bd int; v_label text; v_strat uuid; v_ver uuid; v_owner uuid; v_email text; v_name text;
begin
  select value into v_cfg from public.fw_settings where key = 'reminders';
  select id into v_owner from public.profiles where lower(email) = public.org_owner_email();
  for r in select a.*, c.display_name as client_name from public.fw_approvals a join public.clients_v2 c on c.id = a.client_id where a.status = 'pending' loop
    select u.email, coalesce(u.display_name, u.email) into v_email, v_name from public.fw_portal_users u where u.client_id = r.client_id and u.is_active order by u.is_primary desc, u.invited_at limit 1;
    v_due := coalesce(r.due_at, r.requested_at + interval '3 days');
    v_half := r.requested_at + (v_due - r.requested_at) * (coalesce((v_cfg->>'reminder_1_pct')::numeric, 50) / 100.0);
    -- reminder 1
    if now() >= v_half and r.reminder_1_at is null then
      insert into public.fw_reminders (program_id, client_id, approval_id, step, to_email, subject, body_md) values (r.program_id, r.client_id, r.id, 'reminder_1', v_email, replace(coalesce(v_cfg->>'client_subject', '{{title}}'), '{{title}}', r.title), coalesce(v_cfg->>'client_body', '')) on conflict do nothing;
      update public.fw_approvals set reminder_1_at = now() where id = r.id;
      v_queued := v_queued + 1;
    end if;
    -- reminder 2 at due (only when there is a real window)
    if r.due_at is not null and now() >= r.due_at and r.reminder_2_at is null and coalesce((v_cfg->>'reminder_2_at_due')::boolean, true) then
      insert into public.fw_reminders (program_id, client_id, approval_id, step, to_email, subject, body_md) values (r.program_id, r.client_id, r.id, 'reminder_2', v_email, 'Today: ' || r.title, coalesce(v_cfg->>'client_body', '')) on conflict do nothing;
      update public.fw_approvals set reminder_2_at = now() where id = r.id;
      v_queued := v_queued + 1;
    end if;
    -- escalation ladder (business days past due)
    select count(*) into v_bd from generate_series(v_due::date + 1, current_date, '1 day') d where extract(isodow from d) < 6;
    if v_bd >= coalesce((v_cfg->>'escalate_after_business_days')::int, 1) and r.escalated_at is null then
      for v_strat in select user_id from public.fw_program_members where program_id = r.program_id and role = 'strategist' loop
        perform public.rev_bell(v_strat, 'flywheel', r.client_name || ': approval overdue', r.title || ' has waited ' || v_bd || ' business days past the window.', '/flywheel/' || r.program_id || '?tab=portal', 'fw:esc1:' || r.id);
        v_bells := v_bells + 1;
      end loop;
      insert into public.fw_reminders (program_id, client_id, approval_id, step, channel, status, sent_at) values (r.program_id, r.client_id, r.id, 'escalate_strategist', 'bell', 'sent', now()) on conflict do nothing;
      update public.fw_approvals set escalated_at = now() where id = r.id;
    end if;
    if v_bd >= coalesce((v_cfg->>'escalate_verifier_after_business_days')::int, 3) then
      for v_ver in select user_id from public.fw_program_members where program_id = r.program_id and role = 'verifier' loop
        perform public.rev_bell(v_ver, 'flywheel', r.client_name || ': approval overdue (' || v_bd || ' d)', r.title || ' — the Strategist was alerted; please follow up.', '/flywheel/' || r.program_id || '?tab=portal', 'fw:esc2:' || r.id);
        v_bells := v_bells + 1;
      end loop;
      insert into public.fw_reminders (program_id, client_id, approval_id, step, channel, status, sent_at) values (r.program_id, r.client_id, r.id, 'escalate_verifier', 'bell', 'sent', now()) on conflict do nothing;
    end if;
    if v_bd >= coalesce((v_cfg->>'escalate_owner_after_business_days')::int, 5) and v_owner is not null then
      perform public.rev_bell(v_owner, 'flywheel', r.client_name || ': approval stuck ' || v_bd || ' business days', r.title, '/flywheel/' || r.program_id || '?tab=portal', 'fw:esc3:' || r.id);
      insert into public.fw_reminders (program_id, client_id, approval_id, step, channel, status, sent_at) values (r.program_id, r.client_id, r.id, 'escalate_owner', 'bell', 'sent', now()) on conflict do nothing;
      v_bells := v_bells + 1;
    end if;
  end loop;
  return jsonb_build_object('queued', v_queued, 'bells', v_bells);
end;
$$;


--
-- Name: fw_report_opened(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_report_opened(p_token text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_id uuid;
begin
  update public.fw_reports set open_count = open_count + 1, opened_at = coalesce(opened_at, now()), status = case when status in ('sent', 'delivered') then 'opened' else status end
   where open_token = p_token and status in ('sent', 'delivered', 'opened') returning id into v_id;
  return v_id is not null;
end;
$$;


--
-- Name: fw_reports_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_reports_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'INSERT' then
    if auth.uid() is not null and new.status in ('sent', 'delivered', 'opened') then new.status := 'awaiting_review'; end if;
  elsif new.status is distinct from old.status then
    if new.status = 'awaiting_review' then new.reviewed_by := coalesce(auth.uid(), new.reviewed_by); new.reviewed_at := coalesce(new.reviewed_at, now()); end if;
    if new.status = 'approved' then new.approved_by := coalesce(auth.uid(), new.approved_by); new.approved_at := now(); end if;
    if new.status in ('sent', 'delivered', 'opened') and auth.uid() is not null then
      raise exception 'flywheel: reports are sent by the app after approval, not marked sent by hand' using errcode = '42501';
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: fw_reports_zz_log(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_reports_zz_log() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.status = 'sent' and old.status <> 'sent' and new.program_id is not null then
    perform public.fw_log(new.program_id, 'report', coalesce(new.subject, new.kind) || ' sent', jsonb_build_object('report_id', new.id), true);
    insert into public.client_deliverables (client_id, program_id, package_key, kind, title, status, period_month, delivered_at, ref_table, ref_id, client_href)
    values (new.client_id, new.program_id, 'flywheel', 'report', coalesce(new.subject, new.kind), 'delivered', date_trunc('month', new.period_to)::date, new.sent_at, 'fw_reports', new.id, '/portal?tab=reports')
    on conflict (ref_table, ref_id) where ref_id is not null do update set status = 'delivered', delivered_at = excluded.delivered_at;
  end if;
  if new.status = 'opened' and old.status <> 'opened' and new.program_id is not null then
    perform public.fw_log(new.program_id, 'report', coalesce(new.subject, new.kind) || ' opened by the client', jsonb_build_object('report_id', new.id), false);
  end if;
  return new;
end;
$$;


--
-- Name: fw_review_inbox(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_review_inbox(p_user uuid DEFAULT auth.uid()) RETURNS TABLE(draft_id uuid, program_id uuid, client_name text, kind text, title text, status text, lane text, created_at timestamp with time zone, my_role text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select d.id, d.program_id, c.display_name, d.kind, d.title, d.status, d.lane, d.created_at,
         case when d.status = 'in_review' then d.lane when d.status = 'verification' then 'verifier' end
    from public.fw_drafts d
    join public.fw_programs p on p.id = d.program_id
    join public.clients_v2 c on c.id = p.client_id
   where public.can_view_flywheel()
     and d.status in ('in_review', 'verification')
     and (
       (d.status = 'in_review' and exists (select 1 from public.fw_program_members m where m.program_id = d.program_id and m.user_id = p_user and m.role = d.lane))
       or (d.status = 'verification' and exists (select 1 from public.fw_program_members m where m.program_id = d.program_id and m.user_id = p_user and m.role = 'verifier'))
       or public.can_manage_flywheel()
     )
   order by d.created_at;
$$;


--
-- Name: fw_scaffold_cluster(uuid, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_scaffold_cluster(p_program uuid, p_anchor text DEFAULT NULL::text, p_starts_on date DEFAULT NULL::date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_id uuid; v_n int; v_scope jsonb; v_pages int; v_pillar int; i int;
begin
  if not (public.can_view_flywheel() or auth.uid() is null) then raise exception 'flywheel: not allowed' using errcode = '42501'; end if;
  select coalesce(max(number), 0) + 1 into v_n from public.fw_clusters where program_id = p_program;
  select t.scope into v_scope from public.fw_programs p join public.fw_package_templates t on t.key = p.package_key where p.id = p_program;
  v_pages := coalesce((v_scope->'per_cluster'->>'pages')::int, 10);
  v_pillar := coalesce((v_scope->'per_cluster'->>'pillar_pages_max')::int, 4);
  insert into public.fw_clusters (program_id, number, anchor_keyword, starts_on, created_by)
  values (p_program, v_n, p_anchor, p_starts_on, auth.uid()) returning id into v_id;
  for i in 1..v_pages loop
    insert into public.fw_pages (program_id, cluster_id, number, kind, keyword, chapter_index, created_by)
    values (p_program, v_id, i, case when i <= v_pillar then 'pillar' else 'question' end, case when i = 1 and p_anchor is not null then p_anchor else '(keyword ' || i || ')' end, i, auth.uid());
  end loop;
  return v_id;
end;
$$;


--
-- Name: fw_start_onboarding(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_start_onboarding(p_program uuid, p_kickoff date DEFAULT NULL::date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_prog record; v_t uuid; v_proj uuid; v_kick date; r record; v_assignee uuid; v_client text;
begin
  if not (public.can_view_flywheel() or auth.uid() is null) then raise exception 'flywheel: not allowed' using errcode = '42501'; end if;
  select * into v_prog from public.fw_programs where id = p_program;
  if v_prog.id is null then raise exception 'flywheel: program not found'; end if;
  if v_prog.onboarding_project_id is not null then return v_prog.onboarding_project_id; end if;
  v_kick := coalesce(p_kickoff, v_prog.kickoff_on, current_date);
  select id into v_t from public.project_templates where slug = 'flywheel-onboarding';
  select display_name into v_client from public.clients_v2 where id = v_prog.client_id;
  insert into public.projects (name, kind, client_id, status, starts_at, ends_at, owner_id, description_md, source_kind, source_id, created_by)
  values ('Flywheel onboarding · ' || coalesce(v_client, 'client'), 'client_work', v_prog.client_id, 'active', v_kick, v_kick + 30,
          (select user_id from public.fw_program_members where program_id = p_program and role = 'strategist' limit 1),
          'Day 0 → 30 onboarding for the Flywheel program. Tasks carry phase:* and intake:* tags; ticking an intake task mirrors onto the program.',
          'fw_programs', p_program::text, auth.uid())
  returning id into v_proj;
  for r in select * from public.project_template_tasks where template_id = v_t order by position loop
    select user_id into v_assignee from public.fw_program_members where program_id = p_program and role = r.default_assignee_role limit 1;
    insert into public.tasks (project_id, title, status, priority, assignee_id, starts_at, due_at, is_lead_indicator, position, tags, checklist, created_by)
    values (v_proj, r.title, 'todo', case when r.is_milestone then 'high' else 'medium' end, v_assignee,
            (v_kick + r.offset_start_days)::timestamptz, (v_kick + r.offset_start_days + greatest(r.duration_days - 1, 0))::timestamptz + interval '23 hours 59 minutes',
            r.is_milestone, r.position, r.tags, coalesce(r.checklist, '[]'::jsonb), auth.uid());
  end loop;
  update public.fw_programs set onboarding_project_id = v_proj, kickoff_on = coalesce(kickoff_on, v_kick) where id = p_program;
  perform public.fw_log(p_program, 'status', 'Onboarding started: 65-task checklist from ' || v_kick, jsonb_build_object('project_id', v_proj), true);
  return v_proj;
end;
$$;


--
-- Name: fw_studio_items(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_studio_items(p_program uuid DEFAULT NULL::uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date) RETURNS TABLE(item_kind text, item_id uuid, program_id uuid, client_name text, cluster_number integer, page_number integer, title text, keyword text, channel_key text, status text, scheduled_for timestamp with time zone, due_at timestamp with time zone, published_at timestamp with time zone, live_url text, assignee_id uuid, draft_status text, humanized boolean, updated_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with d as (
    select distinct on (target_kind, target_id) target_kind, target_id, status, humanized_md is not null as humanized
      from public.fw_drafts where status not in ('rejected', 'failed') order by target_kind, target_id, created_at desc
  )
  select 'page', p.id, p.program_id, c.display_name, cl.number, p.number,
         coalesce(p.title, p.keyword), p.keyword, null::text, p.status, p.scheduled_for, p.citation_wave_due_at, p.live_at, p.live_url, p.assignee_id, d.status, coalesce(d.humanized, false), p.updated_at
    from public.fw_pages p join public.fw_programs pr on pr.id = p.program_id join public.clients_v2 c on c.id = pr.client_id join public.fw_clusters cl on cl.id = p.cluster_id
    left join d on d.target_kind = 'page' and d.target_id = p.id
   where (public.can_view_flywheel() or auth.uid() is null) and (p_program is null or p.program_id = p_program)
     and (p_from is null or coalesce(p.scheduled_for, p.live_at, p.updated_at)::date >= p_from) and (p_to is null or coalesce(p.scheduled_for, p.live_at, p.updated_at)::date <= p_to)
  union all
  select 'citation', ci.id, ci.program_id, c.display_name, cl.number, p.number,
         coalesce(ci.title, ch.label || ' · ' || coalesce(ci.keyword, p.keyword, '')), coalesce(ci.keyword, p.keyword), ci.channel_key, ci.status, ci.scheduled_for, p.citation_wave_due_at, coalesce(ci.published_at, ci.posted_on::timestamptz), ci.url, coalesce(ci.assignee_id, ci.poster_id), d.status, coalesce(d.humanized, false), ci.updated_at
    from public.fw_citations ci join public.fw_programs pr on pr.id = ci.program_id join public.clients_v2 c on c.id = pr.client_id
    left join public.fw_pages p on p.id = ci.page_id left join public.fw_clusters cl on cl.id = ci.cluster_id left join public.fw_channels ch on ch.key = ci.channel_key
    left join d on d.target_kind = 'citation' and d.target_id = ci.id
   where (public.can_view_flywheel() or auth.uid() is null) and (p_program is null or ci.program_id = p_program) and ci.status not in ('removed', 'rejected')
     and (p_from is null or coalesce(ci.scheduled_for, ci.published_at, ci.updated_at)::date >= p_from) and (p_to is null or coalesce(ci.scheduled_for, ci.published_at, ci.updated_at)::date <= p_to)
  union all
  select 'video', v.id, v.program_id, c.display_name, cl.number, null,
         coalesce(v.title, 'Seed video ' || to_char(v.month, 'Mon YYYY')), null, 'youtube', v.status, coalesce(v.scheduled_for, v.shoot_at), null, v.published_at, v.youtube_url, null, d.status, coalesce(d.humanized, false), v.updated_at
    from public.fw_videos v join public.fw_programs pr on pr.id = v.program_id join public.clients_v2 c on c.id = pr.client_id left join public.fw_clusters cl on cl.id = v.cluster_id
    left join d on d.target_kind = 'video' and d.target_id = v.id
   where (public.can_view_flywheel() or auth.uid() is null) and (p_program is null or v.program_id = p_program)
     and (p_from is null or coalesce(v.scheduled_for, v.shoot_at, v.updated_at)::date >= p_from) and (p_to is null or coalesce(v.scheduled_for, v.shoot_at, v.updated_at)::date <= p_to)
$$;


--
-- Name: fw_tasks_zz_intake(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_tasks_zz_intake() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_prog uuid; v_key text;
begin
  if new.status = 'done' and (old.status is distinct from 'done') then
    select p.id into v_prog from public.fw_programs p where p.onboarding_project_id = new.project_id;
    if v_prog is null then return new; end if;
    select replace(x, 'intake:', '') into v_key from unnest(new.tags) x where x like 'intake:%' limit 1;
    if v_key = 'setup_paid' then update public.fw_programs set setup_paid_on = coalesce(setup_paid_on, current_date) where id = v_prog;
    elsif v_key = 'first_set' then update public.fw_programs set first_set_live_on = coalesce(first_set_live_on, current_date), status = case when status = 'onboarding' then 'active' else status end where id = v_prog;
    elsif v_key = 'access' then update public.fw_programs set access = access || jsonb_build_object('gbp', true, 'search_console', true, 'analytics', true, 'site_backend', true) where id = v_prog;
    end if;
    perform public.fw_log(v_prog, 'note', 'Onboarding: ' || new.title, jsonb_build_object('task_id', new.id, 'intake', v_key), coalesce(new.is_lead_indicator, false));
  end if;
  return new;
end;
$$;


--
-- Name: fw_zz_log_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_zz_log_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_table_name = 'fw_programs' then
    if tg_op = 'INSERT' then perform public.fw_log(new.id, 'status', 'Program created (' || new.package_key || ', ' || new.status || ')', '{}'::jsonb, false);
    elsif new.status is distinct from old.status then perform public.fw_log(new.id, 'status', 'Program ' || old.status || ' → ' || new.status, jsonb_build_object('from', old.status, 'to', new.status), true);
    end if;
    if tg_op = 'UPDATE' and new.first_set_live_on is distinct from old.first_set_live_on and new.first_set_live_on is not null then perform public.fw_log(new.id, 'status', 'First set live ' || new.first_set_live_on || ' — monthly billing starts', jsonb_build_object('first_set_live_on', new.first_set_live_on), true);
    end if;
  elsif tg_table_name = 'fw_clusters' then
    if tg_op = 'INSERT' then perform public.fw_log(new.program_id, 'plan', 'Cluster ' || new.number || ' created' || coalesce(' · ' || new.anchor_keyword, ''), jsonb_build_object('cluster_id', new.id), false);
    elsif new.plan_status is distinct from old.plan_status then perform public.fw_log(new.program_id, 'plan', 'Cluster ' || new.number || ' plan ' || old.plan_status || ' → ' || new.plan_status, jsonb_build_object('cluster_id', new.id, 'from', old.plan_status, 'to', new.plan_status), new.plan_status in ('awaiting_client', 'approved'));
    elsif new.status is distinct from old.status then perform public.fw_log(new.program_id, 'plan', 'Cluster ' || new.number || ' ' || old.status || ' → ' || new.status, jsonb_build_object('cluster_id', new.id), true);
    end if;
  elsif tg_table_name = 'fw_pages' then
    if tg_op = 'UPDATE' and new.status is distinct from old.status then perform public.fw_log(new.program_id, 'page', 'Page ' || new.number || ' (' || new.keyword || ') ' || old.status || ' → ' || new.status, jsonb_build_object('page_id', new.id, 'from', old.status, 'to', new.status, 'live_url', new.live_url), new.status in ('awaiting_client', 'approved', 'live'));
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: fw_zz_open_approval(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fw_zz_open_approval() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_prog record; v_due timestamptz; v_days int; v_on boolean; v_title text; v_summary text; v_kind text; v_fixed timestamptz;
begin
  if tg_table_name = 'fw_clusters' then
    if not (new.plan_status = 'awaiting_client' and (tg_op = 'INSERT' or old.plan_status is distinct from 'awaiting_client')) then return new; end if;
    v_kind := 'plan'; v_title := 'Cluster ' || new.number || ' plan' || coalesce(' · ' || new.anchor_keyword, ''); v_summary := left(new.plan_md, 4000); v_fixed := new.plan_auto_approve_at;
  elsif tg_table_name = 'fw_pages' then
    if not (new.status = 'awaiting_client' and (tg_op = 'INSERT' or old.status is distinct from 'awaiting_client')) then return new; end if;
    v_kind := 'page'; v_title := 'Page ' || new.number || ': ' || coalesce(new.title, new.keyword); v_summary := coalesce(new.quick_answer_md, left(new.body_md, 1500)); v_fixed := new.auto_approve_at;
  else
    return new;
  end if;
  select p.*, c.id as cid into v_prog from public.fw_programs p join public.clients_v2 c on c.id = p.client_id where p.id = new.program_id;
  if v_kind = 'plan' then v_on := coalesce((v_prog.auto_approve->'plans'->>'enabled')::boolean, false); v_days := coalesce((v_prog.auto_approve->'plans'->>'business_days')::int, 3);
  else v_on := coalesce((v_prog.auto_approve->'content'->>'enabled')::boolean, false); v_days := coalesce((v_prog.auto_approve->'content'->>'business_days')::int, 2); end if;
  -- business days: add v_days weekdays
  v_due := now();
  while v_days > 0 loop
    v_due := v_due + interval '1 day';
    if extract(isodow from v_due) < 6 then v_days := v_days - 1; end if;
  end loop;
  if v_fixed is not null then v_due := v_fixed; end if;
  insert into public.fw_approvals (program_id, client_id, kind, target_id, title, summary_md, requested_by, due_at)
  values (new.program_id, v_prog.client_id, v_kind, new.id, v_title, v_summary, auth.uid(), case when v_on then v_due else null end)
  on conflict (kind, target_id) where status = 'pending' do update set title = excluded.title, summary_md = excluded.summary_md, due_at = excluded.due_at;
  perform public.fw_log(new.program_id, 'approval', 'Sent for client approval: ' || v_title || case when v_on then ' (silent approval ' || to_char(v_due, 'Mon DD') || ')' else '' end, jsonb_build_object('kind', v_kind, 'target_id', new.id), true);
  return new;
end;
$$;


--
-- Name: guard_automation_rule(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_automation_rule() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  s jsonb;
  v_type text;
  v_target text;
begin
  if jsonb_typeof(new.steps) <> 'array' then
    raise exception 'automation_rules: steps must be a JSON array';
  end if;
  if jsonb_array_length(new.steps) > 20 then
    raise exception 'automation_rules: at most 20 steps';
  end if;
  for s in select * from jsonb_array_elements(new.steps) loop
    v_type := s->>'type';
    if v_type is null or v_type not in (
      'filter', 'map', 'run_skill', 'generate_content', 'notify', 'write_row', 'call_n8n_webhook', 'wait',
      'move_stage', 'rescore', 'push_ghl', 'create_task_revenue'
    ) then
      raise exception 'automation_rules: unknown step type %', coalesce(v_type, '(none)');
    end if;
    if s->'config' is not null and jsonb_typeof(s->'config') <> 'object' then
      raise exception 'automation_rules: step config must be an object';
    end if;
    if v_type = 'write_row' then
      v_target := s->'config'->>'table';
      if v_target is null or not exists (select 1 from public.automation_write_targets t where t.table_name = v_target) then
        raise exception 'automation_rules: write_row target % is not allowlisted', coalesce(v_target, '(none)');
      end if;
    end if;
    if v_type = 'move_stage' and coalesce(s->'config'->>'stage', '') !~ '^[a-z0-9-]{1,60}$' then
      raise exception 'automation_rules: move_stage needs a stage slug';
    end if;
    if v_type = 'create_task_revenue' and coalesce(s->'config'->>'title', '') = '' then
      raise exception 'automation_rules: create_task_revenue needs a title';
    end if;
  end loop;

  if new.trigger_kind = 'schedule' and coalesce(new.trigger_config->>'cron', '') !~ '^\S+\s+\S+\s+\S+\s+\S+\s+\S+$' then
    raise exception 'automation_rules: schedule needs a five-field cron expression';
  end if;
  if new.trigger_kind = 'table_event' and not exists (
    select 1 from public.automation_event_sources e where e.table_name = new.trigger_config->>'table'
  ) then
    raise exception 'automation_rules: table_event source % is not allowlisted', coalesce(new.trigger_config->>'table', '(none)');
  end if;
  if new.trigger_kind = 'ingest_event' and coalesce(new.trigger_config->>'endpoint', '') !~ '^[a-z0-9-]{1,60}$' then
    raise exception 'automation_rules: ingest_event needs an endpoint slug';
  end if;

  if tg_op = 'INSERT' and auth.uid() is not null then
    new.created_by := coalesce(new.created_by, auth.uid());
  end if;
  if new.enabled and new.trigger_kind = 'schedule' and new.next_run_at is null then
    new.next_run_at := now();
  end if;
  return new;
end;
$_$;


--
-- Name: guard_automation_run_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_automation_run_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_rule public.automation_rules;
  v_today int;
begin
  select * into v_rule from public.automation_rules where id = new.rule_id;
  if not found then raise exception 'automation_runs: rule not found'; end if;
  if new.status not in ('queued', 'waiting_approval') then
    raise exception 'automation_runs: a new run starts queued or waiting_approval';
  end if;
  select count(*) into v_today
    from public.automation_runs
   where rule_id = new.rule_id
     and created_at >= date_trunc('day', now() at time zone 'America/Chicago') at time zone 'America/Chicago';
  if v_today >= v_rule.daily_run_cap then
    raise exception 'AUTOMATION_RUN_CAP: rule % reached its daily cap of %', v_rule.slug, v_rule.daily_run_cap;
  end if;
  if v_rule.requires_approval then
    new.status := 'waiting_approval';
  end if;
  if auth.uid() is not null then
    new.requested_by := coalesce(new.requested_by, auth.uid());
  end if;
  return new;
end;
$$;


--
-- Name: guard_automation_run_transition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_automation_run_transition() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_group text;
begin
  if new.rule_id <> old.rule_id then
    raise exception 'automation_runs: rule_id is immutable';
  end if;
  if not public.work_run_transition_allowed(old.status, new.status) then
    raise exception 'automation_runs: illegal transition % -> %', old.status, new.status;
  end if;
  if new.status = old.status then
    new.approved_by := old.approved_by;
    new.approved_at := old.approved_at;
    return new;
  end if;
  if new.status in ('approved', 'rejected') then
    select approver_group into v_group from public.automation_rules where id = old.rule_id;
    if auth.uid() is not null
       and not (public.can_manage_automations() or public.is_reviewer_by_key(v_group)) then
      raise exception 'automation_runs: only a member of % decides this run', coalesce(v_group, 'the approver group');
    end if;
    new.approved_by := coalesce(auth.uid(), new.approved_by);
    new.approved_at := now();
  end if;
  if new.status = 'running' and new.started_at is null then
    new.started_at := now();
  end if;
  if new.status in ('done', 'failed', 'cancelled', 'rejected') then
    new.finished_at := coalesce(new.finished_at, now());
    update public.automation_rules
       set last_run_at = now(), last_run_status = new.status,
           last_error = case when new.status = 'failed' then new.error else null end
     where id = new.rule_id;
  elsif new.status = 'queued' then
    new.started_at := null; new.finished_at := null; new.error := null;
    new.current_step := 0; new.step_results := '[]'::jsonb; new.wake_at := null;
  end if;
  return new;
end;
$$;


--
-- Name: guard_calibration_answer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_calibration_answer() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_score   record;
  v_q_cycle uuid;
begin
  select s.cycle_id, s.scorer_id, s.submitted_at, c.status as cycle_status
    into v_score
    from public.calibration_scores s
    join public.calibration_cycles c on c.id = s.cycle_id
   where s.id = new.score_id;
  if v_score is null then
    raise exception 'unknown score row';
  end if;
  if tg_op = 'UPDATE' and (new.score_id <> old.score_id or new.cycle_question_id <> old.cycle_question_id) then
    raise exception 'score and question are immutable on an answer';
  end if;
  select cycle_id into v_q_cycle from public.calibration_cycle_questions where id = new.cycle_question_id;
  if v_q_cycle is distinct from v_score.cycle_id then
    raise exception 'that question does not belong to this cycle';
  end if;
  if auth.uid() is not null then
    if v_score.cycle_status <> 'open' then
      raise exception 'this calibration cycle is closed';
    end if;
    if v_score.submitted_at is not null then
      raise exception 'this round is submitted; its answers are frozen';
    end if;
    if v_score.scorer_id <> auth.uid() then
      raise exception 'an answer is written by the round''s scorer';
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: guard_calibration_score(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_calibration_score() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_cycle_status text;
  v_manager      uuid;

  v_self_done    boolean;
  v_leader_done  boolean;
  v_t            record;
begin
  select status into v_cycle_status from public.calibration_cycles where id = new.cycle_id;
  if v_cycle_status is null then
    raise exception 'unknown calibration cycle';
  end if;
  if auth.uid() is not null and v_cycle_status <> 'open' then
    raise exception 'this calibration cycle is closed';
  end if;

  if not public.calibration_subject_ok(new.subject_id) then
    raise exception 'this person is excluded from calibration';
  end if;

  -- identity never changes; a submitted round is immutable (service role exempt)
  if tg_op = 'UPDATE' then
    if new.cycle_id <> old.cycle_id or new.subject_id <> old.subject_id or new.round <> old.round then
      raise exception 'cycle, subject and round are immutable';
    end if;
    if auth.uid() is not null and old.submitted_at is not null then
      raise exception 'a submitted % score cannot be changed', old.round;
    end if;
    new.scorer_id := old.scorer_id;
    new.model := old.model;
  end if;

  -- imported history (model = 'import', written by the service role only):
  -- the old form had no rounds, so the sequence gates and the role checks
  -- below do not apply; the payload CHECK is the only requirement.
  if new.model = 'import' then
    if auth.uid() is not null then
      raise exception 'imported history is written by the import job, not from the app';
    end if;
    return new;
  end if;

  -- who may write which round
  if auth.uid() is not null then
    if new.round = 'self' and new.scorer_id <> new.subject_id then
      raise exception 'the self round is scored by the person themselves';
    end if;
    if new.round = 'leader' then
      select manager_id into v_manager from public.profiles where id = new.subject_id;
      if not (new.scorer_id = v_manager or public.is_admin()) then
        raise exception 'the leader round is scored by the person''s manager';
      end if;
    end if;
    if new.round = 'exec' and not public.is_exec_reconciler() then
      raise exception 'the exec round is reconciled by the exec reconcilers';
    end if;
    if new.scorer_id <> auth.uid() then
      raise exception 'a score is written by its scorer';
    end if;
  end if;

  -- the gate: leader needs self submitted; exec needs self AND leader submitted
  if new.round in ('leader', 'exec') then
    select exists (
      select 1 from public.calibration_scores s
       where s.cycle_id = new.cycle_id and s.subject_id = new.subject_id
         and s.round = 'self' and s.submitted_at is not null
    ) into v_self_done;
    if not v_self_done then
      raise exception 'self-scoring must be submitted before the % round opens', new.round;
    end if;
  end if;
  if new.round = 'exec' then
    select exists (
      select 1 from public.calibration_scores s
       where s.cycle_id = new.cycle_id and s.subject_id = new.subject_id
         and s.round = 'leader' and s.submitted_at is not null
    ) into v_leader_done;
    if not v_leader_done then
      raise exception 'the leader score must be submitted before exec reconcile opens';
    end if;
  end if;

  -- the outcome is the exec round's call
  if new.outcome is not null and new.round <> 'exec' then
    raise exception 'the outcome is set on the exec round';
  end if;

  -- submitting: the nine-box pair, or every scorecard question answered
  if new.submitted_at is not null then
    if new.model = 'ninebox' then
      if new.performance is null or new.potential is null then
        raise exception 'both performance and potential are required to submit';
      end if;
    elsif new.model = 'scorecard' then
      if tg_op = 'INSERT' then
        raise exception 'save a draft before submitting a scorecard round';
      end if;
      select * into v_t from public.calibration_compute_totals(new.id);
      if v_t.expected = 0 then
        raise exception 'this cycle has no questions; an admin must sync them first';
      end if;
      if v_t.answered < v_t.expected then
        raise exception 'every category must be rated before submitting (% of % done)', v_t.answered, v_t.expected;
      end if;
      new.total := v_t.total;
      new.core_total := v_t.core_total;
      new.performance_total := v_t.performance_total;
      new.professional_total := v_t.professional_total;
    end if;
    -- 'import' rows arrive with their totals already set (CHECK covers it)
  else
    -- drafts never carry a total: it is computed at submit
    if new.model = 'scorecard' then
      new.total := null;
      new.core_total := null;
      new.performance_total := null;
      new.professional_total := null;
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: guard_checkin_response_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_checkin_response_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  parent_week date;
  parent_id uuid := coalesce(new.checkin_id, old.checkin_id);
begin
  if auth.uid() is null then
    return coalesce(new, old);
  end if;
  select week_end into parent_week from public.weekly_checkins where id = parent_id;
  if parent_week is not null and not public.checkin_week_is_open(parent_week) then
    raise exception 'The check-in this answer belongs to (week ending %) is closed and can no longer be edited', parent_week
      using errcode = '42501';
  end if;
  return coalesce(new, old);
end;
$$;


--
-- Name: guard_checkin_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_checkin_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if auth.uid() is null then
    return new;
  end if;

  if not public.checkin_week_is_open(new.week_end) then
    if new.week_end > public.checkin_latest_open_week_end() then
      raise exception 'The check-in for the week ending % opens on Friday at 9:15 AM (%)',
        new.week_end, public.company_timezone()
        using errcode = '42501';
    end if;
    raise exception 'The check-in for the week ending % is closed and can no longer be edited', new.week_end
      using errcode = '42501';
  end if;

  if tg_op = 'UPDATE' and old.status = 'submitted' then
    if new.status <> 'submitted' then
      raise exception 'A submitted check-in stays submitted — edit it, do not un-submit it'
        using errcode = '42501';
    end if;
    if new.user_id <> old.user_id or new.week_end <> old.week_end then
      raise exception 'A submitted check-in cannot be moved to another person or week'
        using errcode = '42501';
    end if;
    -- The first submission is the fact of record; updated_at tells the edit.
    new.submitted_at := old.submitted_at;
  end if;

  return new;
end;
$$;


--
-- Name: guard_content_request_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_content_request_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  new.status := 'requested';
  new.accepted_at := null; new.accepted_by := null;
  new.delivered_at := null; new.closed_by := null;
  new.studio_job_id := null;
  new.sla_accept_by := coalesce(new.created_at, now()) + interval '24 hours';
  if auth.uid() is not null and new.requester_id <> auth.uid() then
    raise exception 'CONTENT_REQUEST: a request is filed by its requester';
  end if;
  if new.due_on is not null and new.due_on < (now() at time zone 'America/Chicago')::date then
    raise exception 'CONTENT_REQUEST: due date is in the past';
  end if;
  return new;
end;
$$;


--
-- Name: guard_content_request_transition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_content_request_transition() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_uid     uuid := auth.uid();
  v_manager boolean := public.can_manage_content_requests();
  v_ok      boolean;
begin
  if new.requester_id <> old.requester_id or new.asset_type <> old.asset_type
     or new.identity_slug is distinct from old.identity_slug
     or new.proposed_action_id is distinct from old.proposed_action_id
     or new.created_at <> old.created_at then
    raise exception 'CONTENT_REQUEST: requester, asset type, provenance and created_at are immutable';
  end if;

  if old.status in ('delivered', 'declined') and v_uid is not null then
    raise exception 'CONTENT_REQUEST: a % request is closed', old.status;
  end if;

  if new.status = old.status then
    -- field edits. Managers edit anything open; the requester edits their
    -- brief/due/priority/client/title only while it is still requested.
    if v_uid is not null and not v_manager then
      if old.requester_id <> v_uid or old.status <> 'requested' then
        raise exception 'CONTENT_REQUEST: only the queue may edit an accepted request';
      end if;
      if new.assignee_id is distinct from old.assignee_id or new.studio_job_id is distinct from old.studio_job_id
         or new.decision_note is distinct from old.decision_note then
        raise exception 'CONTENT_REQUEST: assignee, studio job and decision note are set by the queue';
      end if;
    end if;
    return new;
  end if;

  v_ok := case old.status
    when 'requested' then new.status in ('accepted', 'declined')
    when 'accepted'  then new.status in ('in_studio', 'delivered', 'declined')
    when 'in_studio' then new.status in ('delivered', 'declined')
    else false end;
  if not v_ok then
    raise exception 'CONTENT_REQUEST: cannot move a request from % to %', old.status, new.status;
  end if;

  if v_uid is not null and not v_manager then
    -- the requester's one move: withdraw while nobody has picked it up.
    if not (old.requester_id = v_uid and old.status = 'requested' and new.status = 'declined') then
      raise exception 'CONTENT_REQUEST: the content queue decides this request';
    end if;
  end if;

  if new.status = 'in_studio' and new.studio_job_id is null then
    raise exception 'CONTENT_REQUEST: in_studio needs a studio job';
  end if;

  if new.status = 'accepted' then
    new.accepted_at := coalesce(new.accepted_at, now());
    new.accepted_by := coalesce(new.accepted_by, v_uid);
    new.assignee_id := coalesce(new.assignee_id, v_uid);
  elsif new.status = 'delivered' then
    new.delivered_at := coalesce(new.delivered_at, now());
    new.closed_by := coalesce(new.closed_by, v_uid);
  elsif new.status = 'declined' then
    new.closed_by := coalesce(new.closed_by, v_uid);
  end if;
  return new;
end;
$$;


--
-- Name: guard_form_submission(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_form_submission() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_form public.forms%rowtype;
begin
  select * into v_form from public.forms where id = new.form_id;
  if v_form.id is null then raise exception 'unknown form'; end if;
  if auth.uid() is not null and v_form.status <> 'open' then
    raise exception 'this form is %', v_form.status;
  end if;
  if not (v_form.anonymous_ok or v_form.is_public) and new.submitted_by is null then
    raise exception 'this form requires a signed-in submitter';
  end if;
  if not v_form.allow_multiple and new.submitted_by is not null and exists (
    select 1 from public.form_submissions s where s.form_id = new.form_id and s.submitted_by = new.submitted_by
  ) then
    raise exception 'you already submitted this form';
  end if;
  if new.request_type is null then new.request_type := v_form.request_type; end if;
  -- the form's standing tags under the submission's own (a later MQL pass filters on these)
  new.tags := coalesce(v_form.submission_tags, '{}'::jsonb) || coalesce(new.tags, '{}'::jsonb);
  return new;
end;
$$;


--
-- Name: guard_locked_metric(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_locked_metric() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  -- once exported to a payroll run, a metric row is history: corrections go
  -- through the revision path, not an UPDATE (service ctx exempt for the
  -- future revision RPC, which runs server-side).
  if old.payroll_run_id is not null and auth.uid() is not null then
    raise exception 'metric row is locked to a payroll run; file a correction instead';
  end if;
  return new;
end;
$$;


--
-- Name: guard_podcast_release(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_podcast_release() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.release_signed and new.release_signed_at is null then
    new.release_signed_at := now();
  end if;
  if not new.release_signed then
    new.release_signed_at := null;
  end if;
  if new.status in ('recorded', 'editing', 'published')
     and not new.release_signed
     and public.podcast_two_party_consent_state(new.guest_state) then
    raise exception 'PODCAST_RELEASE_GATE: episode "%" cannot be % — guest state % requires a signed release first',
      new.title, new.status, coalesce(upper(new.guest_state), 'unknown')
      using errcode = 'check_violation';
  end if;
  return new;
end;
$$;


--
-- Name: guard_position_request_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_position_request_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_pos uuid;
begin
  if new.kind <> 'position_request' then return new; end if;
  if auth.uid() is not null and not (public.is_admin() or public.is_people_manager(auth.uid())) then
    raise exception 'hiring: only people managers file a position request' using errcode = '42501';
  end if;
  if coalesce(btrim(new.payload->>'role_title'), '') = '' then
    raise exception 'position_request payload needs role_title';
  end if;
  if coalesce(new.payload->>'employment_type', 'full_time') not in ('full_time', 'part_time', 'contractor', 'intern') then
    raise exception 'position_request employment_type must be full_time | part_time | contractor | intern';
  end if;
  if new.payload ? 'position_id' and nullif(new.payload->>'position_id', '') is not null then
    v_pos := (new.payload->>'position_id')::uuid;
    if not exists (select 1 from public.hire_positions p where p.id = v_pos and p.status in ('draft', 'pending_approval')) then
      raise exception 'position_request: position % is not a draft', v_pos;
    end if;
    new.subject_table := 'hire_positions';
    new.subject_id := v_pos::text;
  end if;
  return new;
end;
$$;


--
-- Name: guard_staff_request_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_staff_request_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  new.status := 'pending';
  new.decided_by := null;
  new.decided_at := null;
  if auth.uid() is not null and new.requester_id <> auth.uid() then
    raise exception 'a staff request is filed by its requester';
  end if;
  if new.kind = 'time_off' then
    if new.payload->>'starts_on' is null or new.payload->>'ends_on' is null
       or (new.payload->>'ends_on')::date < (new.payload->>'starts_on')::date then
      raise exception 'time_off request payload needs starts_on <= ends_on';
    end if;
    if coalesce(new.payload->>'time_off_kind', 'vacation')
       not in ('vacation', 'sick', 'personal', 'holiday') then
      raise exception 'time_off_kind must be vacation | sick | personal | holiday';
    end if;
  end if;
  if new.kind = 'software_change' then
    if coalesce(new.payload->>'request_type', '')
       not in ('new_tool', 'access_change', 'feature_request') then
      raise exception 'software_change request_type must be new_tool | access_change | feature_request';
    end if;
    if coalesce(new.payload->>'urgency', 'normal')
       not in ('low', 'normal', 'high', 'blocking') then
      raise exception 'software_change urgency must be low | normal | high | blocking';
    end if;
    new.payload := jsonb_set(new.payload, '{urgency}', to_jsonb(coalesce(new.payload->>'urgency', 'normal')));
  end if;
  if new.kind = 'innovation' then
    if coalesce(new.payload->>'innovation_type', '')
       not in ('platform_change', 'process_insight', 'policy_request', 'new_project', 'other') then
      raise exception 'innovation innovation_type must be platform_change | process_insight | policy_request | new_project | other';
    end if;
  end if;
  if new.kind = 'headcount_request' then
    if length(trim(coalesce(new.payload->>'role_title', ''))) = 0 then
      raise exception 'headcount_request payload needs role_title';
    end if;
    if coalesce(new.payload->>'employment_type', 'full_time')
       not in ('full_time', 'part_time', 'contractor', 'intern') then
      raise exception 'headcount_request employment_type must be full_time | part_time | contractor | intern';
    end if;
    if coalesce((new.payload->>'headcount')::int, 1) < 1 then
      raise exception 'headcount_request headcount must be >= 1';
    end if;
    if new.payload ? 'target_start_on' and new.payload->>'target_start_on' is not null then
      perform (new.payload->>'target_start_on')::date;
    end if;
    new.payload := new.payload
      || jsonb_build_object('employment_type', coalesce(new.payload->>'employment_type', 'full_time'),
                            'headcount', coalesce((new.payload->>'headcount')::int, 1));
  end if;
  return new;
end;
$$;


--
-- Name: guard_staff_request_transition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_staff_request_transition() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_time_off_id text;
  v_two_step boolean;
begin
  if new.requester_id <> old.requester_id or new.kind <> old.kind then
    raise exception 'requester and kind are immutable';
  end if;
  v_two_step := old.kind in ('software_change', 'innovation');
  if auth.uid() is not null
     and (old.status in ('denied', 'withdrawn', 'completed')
          or (old.status = 'approved' and not v_two_step)) then
    raise exception 'a % request is closed', old.status;
  end if;

  if new.status = old.status then
    if auth.uid() is not null then
      if new.reviewer_group_id <> old.reviewer_group_id and not public.is_admin() then
        raise exception 'only an admin reassigns the reviewer group';
      end if;
      if not (auth.uid() = old.requester_id or public.is_admin()) then
        raise exception 'only the requester edits a pending request';
      end if;
    end if;
    new.decided_by := old.decided_by;
    new.decided_at := old.decided_at;
    return new;
  end if;

  if new.status = 'withdrawn' then
    if old.status <> 'pending' then
      raise exception 'only a pending request may be withdrawn';
    end if;
    if auth.uid() is not null and auth.uid() <> old.requester_id and not public.is_admin() then
      raise exception 'only the requester withdraws a request';
    end if;
  elsif new.status = 'in_review' then
    if not v_two_step or old.status <> 'pending' then
      raise exception 'illegal transition % -> % for kind %', old.status, new.status, old.kind;
    end if;
    if auth.uid() is not null and not public.is_reviewer(old.reviewer_group_id) then
      raise exception 'only a member of the reviewer group starts a review';
    end if;
  elsif new.status in ('approved', 'denied') then
    if old.status not in ('pending', 'in_review') then
      raise exception 'illegal transition % -> %', old.status, new.status;
    end if;
    if auth.uid() is not null and not public.is_reviewer(old.reviewer_group_id) then
      raise exception 'only a member of the reviewer group decides a request';
    end if;
    new.decided_by := coalesce(auth.uid(), new.decided_by);
    new.decided_at := now();
    if new.status = 'approved' and new.kind = 'time_off' then
      insert into public.time_off (user_id, starts_on, ends_on, kind, status, approved_by, notes, source, source_id)
      values (
        new.requester_id,
        (new.payload->>'starts_on')::date,
        (new.payload->>'ends_on')::date,
        coalesce(new.payload->>'time_off_kind', 'vacation'),
        'approved',
        new.decided_by,
        new.title,
        'staff_request',
        new.id::text)
      on conflict (source, source_id) do nothing;
      select id::text into v_time_off_id
        from public.time_off
       where source = 'staff_request' and source_id = new.id::text;
      new.subject_table := 'time_off';
      new.subject_id := v_time_off_id;
    end if;
  elsif new.status = 'completed' then
    if not v_two_step or old.status <> 'approved' then
      raise exception 'illegal transition % -> % for kind %', old.status, new.status, old.kind;
    end if;
    if auth.uid() is not null and not public.is_reviewer(old.reviewer_group_id) then
      raise exception 'only a member of the reviewer group marks a request completed';
    end if;
  else
    raise exception 'illegal transition % -> %', old.status, new.status;
  end if;
  return new;
end;
$$;


--
-- Name: guard_tag_hierarchy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_tag_hierarchy() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_parent_category text;
begin
  if new.parent_tag_id is null then
    return new;
  end if;
  select category into v_parent_category from public.tags where id = new.parent_tag_id;
  if new.category = 'org' then
    raise exception 'an org has no parent';
  elsif new.category = 'department' and v_parent_category is distinct from 'org' then
    raise exception 'a department''s parent must be an org';
  elsif new.category = 'sub_team' and v_parent_category is distinct from 'department' then
    raise exception 'a sub-team''s parent must be a department';
  end if;
  return new;
end;
$$;


--
-- Name: guard_time_study_entry(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_time_study_entry() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_study public.time_studies%rowtype;
begin
  select * into v_study from public.time_studies where id = new.study_id;
  if v_study.id is null then
    raise exception 'unknown time study';
  end if;
  if new.day < v_study.starts_on or new.day > v_study.ends_on then
    raise exception 'day % is outside the study window (% to %)', new.day, v_study.starts_on, v_study.ends_on;
  end if;
  if auth.uid() is not null then
    if v_study.status <> 'open' then
      raise exception 'this time study is %, entries are locked', v_study.status;
    end if;
    if exists (select 1 from public.time_study_submissions s where s.study_id = new.study_id and s.user_id = new.user_id) then
      raise exception 'you already submitted this time study; ask a leader to reopen it';
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: guard_time_study_submission(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_time_study_submission() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_status text;
begin
  select status into v_status from public.time_studies where id = new.study_id;
  if tg_op = 'INSERT' then
    if v_status not in ('open', 'review') then
      raise exception 'this time study is %, it cannot be submitted', v_status;
    end if;
    new.reviewed_by := null;
    new.reviewed_at := null;
  else
    if auth.uid() is not null and not (public.is_admin() or public.is_people_manager(auth.uid())) then
      raise exception 'only a people-manager, exec or admin reviews a submission';
    end if;
    if new.reviewed_at is not null and old.reviewed_at is null then
      new.reviewed_by := coalesce(auth.uid(), new.reviewed_by);
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: guard_work_run_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_work_run_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if coalesce(current_setting('work_engine.sync', true), '') = 'on' then
    return new;
  end if;
  if new.source_table is not null then
    raise exception 'work_runs: mirrored rows are written by sync_to_work_runs() only';
  end if;
  if new.status not in ('queued', 'waiting_approval') then
    raise exception 'work_runs: a new run starts queued or waiting_approval, not %', new.status;
  end if;
  if new.status = 'waiting_approval' and new.approver_group is null then
    raise exception 'work_runs: waiting_approval needs an approver_group';
  end if;
  if auth.uid() is not null then
    new.requested_by := coalesce(new.requested_by, auth.uid());
  end if;
  return new;
end;
$$;


--
-- Name: guard_work_run_transition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_work_run_transition() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  -- Mirrored rows: the source table's guard already ruled. Only the sync
  -- function sets this GUC, transaction-locally, around its own upsert.
  if coalesce(current_setting('work_engine.sync', true), '') = 'on' then
    return new;
  end if;

  if new.domain <> old.domain or new.kind <> old.kind
     or new.requested_by is distinct from old.requested_by
     or new.source_table is distinct from old.source_table
     or new.source_id is distinct from old.source_id then
    raise exception 'work_runs: domain, kind, requester and source are immutable';
  end if;

  if old.source_table is not null and auth.uid() is not null then
    raise exception 'WORK_ENGINE_LEGACY: act on this run through its % record', old.source_table;
  end if;

  if not public.work_run_transition_allowed(old.status, new.status) then
    raise exception 'work_runs: illegal transition % -> %', old.status, new.status;
  end if;

  if new.status = old.status then
    new.approved_by := old.approved_by;
    new.approved_at := old.approved_at;
    return new;
  end if;

  if new.status in ('approved', 'rejected') then
    if auth.uid() is not null
       and not (public.can_manage_work_engine() or public.is_reviewer_by_key(old.approver_group)) then
      raise exception 'work_runs: only a member of % decides this run', coalesce(old.approver_group, 'the approver group');
    end if;
    new.approved_by := coalesce(auth.uid(), new.approved_by);
    new.approved_at := now();
  end if;

  if new.status = 'running' and new.started_at is null then
    new.started_at := now();
  end if;
  if new.status in ('done', 'failed', 'cancelled', 'rejected') then
    new.finished_at := coalesce(new.finished_at, now());
  elsif new.status = 'queued' then
    -- retry: clear the previous attempt's timestamps and error
    new.started_at := null;
    new.finished_at := null;
    new.error := null;
  end if;

  return new;
end;
$$;


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  meta jsonb := new.raw_user_meta_data;
  fn text;
  ln text;
  full_n text;
  space_pos int;
begin
  if coalesce(new.raw_app_meta_data->>'portal', '') = 'true' then
    return new;   -- client portal login (0144): no profiles row, so no staff gate ever passes
  end if;
  fn := coalesce(nullif(meta->>'first_name', ''), nullif(meta->>'given_name', ''));
  ln := coalesce(nullif(meta->>'last_name', ''), nullif(meta->>'family_name', ''));

  if fn is null or ln is null then
    full_n := coalesce(meta->>'name', meta->>'full_name', '');
    space_pos := position(' ' in full_n);
    if space_pos > 0 then
      fn := coalesce(fn, substring(full_n from 1 for space_pos - 1));
      ln := coalesce(ln, substring(full_n from space_pos + 1));
    elsif full_n <> '' then
      fn := coalesce(fn, full_n);
    end if;
  end if;

  if fn is null or fn = '' then
    fn := split_part(new.email, '@', 1);
  end if;

  insert into public.profiles (id, email, first_name, last_name)
  values (new.id, new.email, fn, coalesce(ln, ''))
  on conflict (id) do nothing;
  return new;
end;
$$;


--
-- Name: handle_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;


--
-- Name: has_capability(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_capability(p_capability text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.user_capabilities uc
    join public.profiles p on p.id = uc.user_id
    where uc.user_id = auth.uid()
      and uc.capability = p_capability
      and p.is_active
  );
$$;


--
-- Name: has_module_access(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_module_access(p_module text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1 from public.profiles p
    where p.id = auth.uid()
      and p.is_active
      and (
        -- Anti-lockout floor: admin/exec always pass, matrix cannot demote them.
        p.role in ('admin', 'exec')
        or exists (
          select 1 from public.role_permissions rp
          where rp.role = p.role
            and rp.module_key = p_module
            and rp.allowed
        )
      )
  );
$$;


--
-- Name: hire_application_config_check(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hire_application_config_check(p jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare s jsonb; q jsonb; v_keys text[] := '{}'; v_key text;
begin
  if p is null or jsonb_typeof(p) <> 'object' then return 'config must be an object'; end if;
  if jsonb_typeof(p->'sections') <> 'array' then return 'config.sections must be an array'; end if;
  for s in select * from jsonb_array_elements(p->'sections') loop
    if coalesce(s->>'key', '') !~ '^[a-z][a-z0-9_]{0,40}$' then return 'section key invalid: ' || coalesce(s->>'key', '(null)'); end if;
    if coalesce(s->>'kind', '') not in ('consent', 'contact', 'screening', 'skills', 'challenge', 'video', 'resume', 'links', 'questionnaire', 'custom') then return 'section kind invalid: ' || coalesce(s->>'kind', '(null)'); end if;
    if jsonb_typeof(s->'questions') <> 'array' then return 'section ' || (s->>'key') || ' needs questions[]'; end if;
    for q in select * from jsonb_array_elements(s->'questions') loop
      v_key := q->>'key';
      if coalesce(v_key, '') !~ '^[a-z][a-z0-9_]{0,60}$' then return 'question key invalid: ' || coalesce(v_key, '(null)'); end if;
      if v_key = any(v_keys) then return 'duplicate question key: ' || v_key; end if;
      v_keys := array_append(v_keys, v_key);
      if coalesce(q->>'type', '') not in ('short_text', 'long_text', 'number', 'select', 'multi', 'boolean', 'rating_1_5', 'url', 'email', 'phone', 'date', 'file', 'video', 'timed_text', 'statement') then return 'question type invalid: ' || v_key; end if;
      if coalesce(q->>'paste', 'track') not in ('allow', 'track', 'block') then return 'question paste mode invalid: ' || v_key; end if;
      if q->>'type' = 'timed_text' and coalesce((q->>'time_limit_s')::int, 0) < 30 then return 'timed question needs time_limit_s >= 30: ' || v_key; end if;
    end loop;
  end loop;
  return null;
end;
$_$;


--
-- Name: hire_applications_zz_log(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hire_applications_zz_log() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.status is distinct from old.status or new.stage_key is distinct from old.stage_key then
    insert into public.hire_application_events (application_id, kind, summary, payload, actor_id)
    values (new.id, 'stage', coalesce(old.stage_key, old.status) || ' → ' || coalesce(new.stage_key, new.status), jsonb_build_object('from_status', old.status, 'to_status', new.status, 'from_stage', old.stage_key, 'to_stage', new.stage_key), auth.uid());
  end if;
  return new;
end;
$$;


--
-- Name: hire_approve_four_r_draft(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hire_approve_four_r_draft(p_draft_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare d record; v_written boolean := false;
begin
  if not (public.is_admin() or public.is_people_manager(auth.uid())) then
    raise exception 'hiring: approving a 4R draft needs people-manager or admin' using errcode = '42501';
  end if;
  select * into d from public.hire_four_r_drafts where id = p_draft_id for update;
  if d.id is null then raise exception 'draft not found'; end if;
  if d.status <> 'pending' then raise exception 'draft already %', d.status; end if;
  if not exists (select 1 from public.profile_four_r where user_id = d.user_id) then
    insert into public.profile_four_r (user_id, position_label, department, reports_to, role_md, responsibilities_md, results_md, requirements_md, template_slug, source, created_by, updated_by, pending_note)
    values (d.user_id,
            coalesce(d.draft->>'position_label', ''), d.draft->>'department', d.draft->>'reports_to',
            coalesce(d.draft->>'role_md', ''), coalesce(d.draft->>'responsibilities_md', ''), coalesce(d.draft->>'results_md', ''), coalesce(d.draft->>'requirements_md', ''),
            d.template_slug, case when d.source = 'ai' then 'ai' when d.source = 'drive' then 'drive' else 'template' end,
            auth.uid(), auth.uid(), 'Approved from a ' || d.source || ' draft (hiring backfill)');
    v_written := true;
  end if;
  update public.hire_four_r_drafts set status = 'approved', decided_by = auth.uid(), decided_at = now() where id = p_draft_id;
  return jsonb_build_object('written', v_written, 'user_id', d.user_id);
end;
$$;


--
-- Name: hire_convert_to_hire(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hire_convert_to_hire(p_offer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare o record; c record; pos record; v_profile uuid; v_hired int; v_items int := 0; t record; v_mgr_dept uuid; v_tag uuid; v_plan uuid;
begin
  if auth.uid() is not null and not public.can_view_hiring() then raise exception 'hiring: not allowed' using errcode = '42501'; end if;
  select * into o from public.hire_offers where id = p_offer_id;
  if o.id is null then raise exception 'offer not found'; end if;
  if o.status <> 'accepted' then raise exception 'hiring: the offer must be accepted (all documents signed) before conversion'; end if;
  select * into c from public.hire_candidates where id = o.candidate_id;
  select * into pos from public.hire_positions where id = o.position_id;

  select id into v_profile from public.profiles where lower(email) = c.email_key;
  if v_profile is not null then
    select department_tag_id into v_mgr_dept from public.profiles where id = o.manager_id;
    v_tag := coalesce(pos.department_tag_id, v_mgr_dept);
    update public.profiles
       set manager_id = coalesce(o.manager_id, pos.hiring_manager_id, manager_id),
           job_role = coalesce(nullif(job_role, ''), pos.title),
           pap_position = coalesce(pap_position, pos.pap_position),
           position_track = coalesce(position_track, pos.position_track),
           position_level = coalesce(position_level, 3),
           department_tag_id = coalesce(department_tag_id, v_tag),
           date_started = coalesce(date_started, o.start_on),
           employment_status = coalesce(employment_status, 'Active'),
           is_active = true
     where id = v_profile;
    insert into public.profile_sensitive (user_id, comp_base_cents, comp_currency, pay_structure, pap_status, pap_started_on, pap_owner_id, notes_md)
    values (v_profile, (o.monthly_base_cents)::int, o.currency, case when o.employment_type = 'contractor' then 'contract' else 'salary' end, 'not_on_pap', null, o.manager_id,
            'Hired via Open Ronin hiring ' || to_char(now(), 'YYYY-MM-DD') || ': ' || pos.title || ' · ' || coalesce(o.pay_level, '') || ' × ' || coalesce(o.pay_multiplier::text, '') || ' step ' || o.step || ' · target ' || coalesce((o.monthly_target_cents / 100)::text, '') || '/mo')
    on conflict (user_id) do update set comp_base_cents = coalesce(public.profile_sensitive.comp_base_cents, excluded.comp_base_cents), pay_structure = coalesce(public.profile_sensitive.pay_structure, excluded.pay_structure), pap_owner_id = coalesce(public.profile_sensitive.pap_owner_id, excluded.pap_owner_id);
    if c.disc is not null and (select disc from public.profiles where id = v_profile) is null then
      update public.profiles set disc = c.disc->>'style' where id = v_profile and (c.disc->>'style') is not null;
    end if;
    if not exists (select 1 from public.profile_four_r where user_id = v_profile) and btrim(pos.role_md) <> '' then
      insert into public.profile_four_r (user_id, position_label, department, reports_to, role_md, responsibilities_md, results_md, requirements_md, template_slug, source, created_by, updated_by, pending_note)
      values (v_profile, pos.title, pos.department_label, pos.reports_to_label, pos.role_md, pos.responsibilities_md, pos.results_md, pos.requirements_md, pos.four_r_template_slug, 'template', coalesce(auth.uid(), o.created_by), coalesce(auth.uid(), o.created_by), 'From the hiring position ' || pos.slug);
    end if;
    update public.hire_offers set hired_profile_id = v_profile where id = p_offer_id;
    update public.hire_provisioning set profile_id = v_profile where offer_id = p_offer_id and profile_id is null;
    -- H7: the onboarding plan (60-Day Plan + progressive framework), calibration held until day 60
    v_plan := public.hire_onboarding_create(v_profile, o.start_on, coalesce(o.manager_id, pos.hiring_manager_id), p_offer_id, o.employment_type, null);
  end if;

  update public.hire_applications set status = 'hired', stage_key = 'hired', decided_by = coalesce(auth.uid(), decided_by), decided_at = coalesce(decided_at, now()), last_activity_at = now() where id = o.application_id and status <> 'hired';
  select count(*) into v_hired from public.hire_applications where position_id = pos.id and status = 'hired';
  if v_hired >= pos.headcount and pos.status in ('open', 'paused', 'approved') then
    update public.hire_positions set status = 'filled', updated_by = coalesce(auth.uid(), o.created_by) where id = pos.id;
  end if;

  if not exists (select 1 from public.hire_provisioning where offer_id = p_offer_id) then
    for t in select * from public.hire_provisioning_templates where is_active and o.employment_type = any(employment) and o.region = any(regions) order by sort loop
      insert into public.hire_provisioning (offer_id, candidate_id, profile_id, template_key, label, owner_role, owner_id, automation_key, due_on)
      values (p_offer_id, o.candidate_id, v_profile, t.key, t.label, t.owner_role,
              case t.owner_role when 'manager' then coalesce(o.manager_id, pos.hiring_manager_id) when 'owner' then (select id from public.profiles where lower(email) = public.org_owner_email()) else null end,
              t.automation_key, case when o.start_on is not null then o.start_on + t.due_offset_days else null end);
      v_items := v_items + 1;
    end loop;
    if v_profile is not null then
      update public.hire_provisioning set status = 'done', done_at = now(), note = 'profile linked' where offer_id = p_offer_id and automation_key = 'platform_invite';
    end if;
  end if;

  insert into public.hire_application_events (application_id, kind, summary, payload, actor_id)
  values (o.application_id, 'status', 'Hired' || case when v_profile is null then ' (profile pending: invite not accepted yet)' else '' end, jsonb_build_object('offer_id', p_offer_id, 'profile_id', v_profile, 'provisioning_items', v_items, 'onboarding_plan_id', v_plan), auth.uid());

  return jsonb_build_object('profile_id', v_profile, 'position_filled', v_hired >= pos.headcount, 'provisioning_items', v_items, 'hired_count', v_hired, 'onboarding_plan_id', v_plan);
end;
$$;


--
-- Name: hire_disc_responses_zz_carry(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hire_disc_responses_zz_carry() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.profile_id is not null then
    update public.profiles set disc = new.style where id = new.profile_id and disc is distinct from new.style;
    update public.hire_onboarding_items i set status = 'done', note_md = coalesce(i.note_md, 'DISC ' || new.style || ' (' || new.source || ')')
      from public.hire_onboarding_plans p where p.id = i.plan_id and p.profile_id = new.profile_id and i.template_key = 'disc' and i.status in ('todo', 'in_progress');
  end if;
  if new.candidate_id is not null then
    update public.hire_candidates set disc = jsonb_build_object('style', new.style, 'scores', new.scores, 'source', new.source, 'completed_at', new.completed_at, 'response_id', new.id) where id = new.candidate_id;
  end if;
  return new;
end;
$$;


--
-- Name: hire_disc_score(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hire_disc_score(p_answers jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare a jsonb; m int; d int := 0; i int := 0; s int := 0; c int := 0; n int := 0; pct jsonb; ordered text[]; vals numeric[]; v_style text; v_total numeric;
begin
  for a in select * from jsonb_array_elements(coalesce(p_answers, '[]'::jsonb)) loop
    n := n + 1;
    case a->>'most' when 'D' then d := d + 1; when 'I' then i := i + 1; when 'S' then s := s + 1; when 'C' then c := c + 1; else null; end case;
    case a->>'least' when 'D' then d := d - 1; when 'I' then i := i - 1; when 'S' then s := s - 1; when 'C' then c := c - 1; else null; end case;
  end loop;
  if n = 0 then return jsonb_build_object('D', 25, 'I', 25, 'S', 25, 'C', 25, 'style', '', 'n', 0); end if;
  v_total := 4 * n;  -- sum of (most - least + n) over four traits
  pct := jsonb_build_object(
    'D', round((d + n) * 100.0 / v_total, 1),
    'I', round((i + n) * 100.0 / v_total, 1),
    'S', round((s + n) * 100.0 / v_total, 1),
    'C', round((c + n) * 100.0 / v_total, 1));
  select array_agg(k order by v desc, k), array_agg(v order by v desc, k) into ordered, vals
    from (values ('D', (d + n) * 100.0 / v_total), ('I', (i + n) * 100.0 / v_total), ('S', (s + n) * 100.0 / v_total), ('C', (c + n) * 100.0 / v_total)) t(k, v);
  v_style := ordered[1];
  if vals[2] >= 25 then v_style := v_style || case when vals[1] - vals[2] <= 5 then ordered[2] else lower(ordered[2]) end; end if;
  if vals[3] >= 25 then v_style := v_style || lower(ordered[3]); end if;
  return pct || jsonb_build_object('style', v_style, 'n', n);
end;
$$;


--
-- Name: hire_disc_submit_candidate(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hire_disc_submit_candidate(p_token_hash text, p_answers jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare t record; sc jsonb; v_id uuid;
begin
  select * into t from public.hire_portal_tokens where token_hash = p_token_hash and expires_at > now();
  if t.id is null then raise exception 'portal link expired'; end if;
  if jsonb_array_length(coalesce(p_answers, '[]'::jsonb)) < 20 then raise exception 'answer every group before submitting'; end if;
  sc := public.hire_disc_score(p_answers);
  insert into public.hire_disc_responses (candidate_id, source, answers, scores, style)
  values (t.candidate_id, 'in_app', p_answers, sc - 'style' - 'n', sc->>'style') returning id into v_id;
  insert into public.hire_application_events (application_id, kind, summary, payload)
  select id, 'note', 'DISC completed: ' || (sc->>'style'), jsonb_build_object('scores', sc) from public.hire_applications where candidate_id = t.candidate_id and status not in ('rejected', 'withdrawn');
  return jsonb_build_object('id', v_id, 'style', sc->>'style', 'scores', sc - 'style' - 'n');
end;
$$;


--
-- Name: hire_documents_zz_accept(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hire_documents_zz_accept() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_offer record; v_unsigned int;
begin
  if new.status <> 'signed' or new.offer_id is null then return new; end if;
  select * into v_offer from public.hire_offers where id = new.offer_id;
  if v_offer.id is null or v_offer.status in ('accepted', 'declined', 'withdrawn') then return new; end if;
  select count(*) into v_unsigned from public.hire_documents where offer_id = new.offer_id and status not in ('signed', 'void');
  if v_unsigned = 0 then
    update public.hire_offers set status = 'accepted', decided_at = now() where id = new.offer_id;
    update public.hire_applications set status = 'offer', stage_key = 'offer', last_activity_at = now() where id = v_offer.application_id and status not in ('hired');
    insert into public.hire_application_events (application_id, kind, summary, payload)
    values (v_offer.application_id, 'status', 'Offer accepted: all documents signed', jsonb_build_object('offer_id', new.offer_id));
  end if;
  return new;
end;
$$;


--
-- Name: hire_enqueue_enrichment(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hire_enqueue_enrichment(p_application_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare a record; c record; v_n int := 0; u text;
begin
  if public.is_portal_user() then raise exception 'hiring: not allowed from the client portal' using errcode = '42501'; end if;
  select * into a from public.hire_applications where id = p_application_id;
  if a.id is null then return 0; end if;
  select * into c from public.hire_candidates where id = a.candidate_id;
  if c.resume_path is not null then
    insert into public.hire_enrichment_jobs (application_id, candidate_id, kind, target) values (a.id, c.id, 'resume', c.resume_path) on conflict do nothing; v_n := v_n + 1;
  end if;
  if c.video_path is not null then
    insert into public.hire_enrichment_jobs (application_id, candidate_id, kind, target) values (a.id, c.id, 'video', c.video_path) on conflict do nothing; v_n := v_n + 1;
  elsif c.video_url is not null then
    insert into public.hire_enrichment_jobs (application_id, candidate_id, kind, target) values (a.id, c.id, 'video', c.video_url) on conflict do nothing; v_n := v_n + 1;
  end if;
  if c.linkedin_url is not null then
    insert into public.hire_enrichment_jobs (application_id, candidate_id, kind, target) values (a.id, c.id, 'linkedin', c.linkedin_url) on conflict do nothing; v_n := v_n + 1;
  end if;
  foreach u in array coalesce(c.portfolio_urls, '{}') loop
    if u ~* '^https?://' and u !~* 'linkedin\.com' then
      insert into public.hire_enrichment_jobs (application_id, candidate_id, kind, target) values (a.id, c.id, 'link', left(u, 500)) on conflict do nothing; v_n := v_n + 1;
    end if;
  end loop;
  return v_n;
end;
$$;


--
-- Name: hire_honeypot_followup(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hire_honeypot_followup(p_session_token text, p_text text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_app uuid;
begin
  select application_id into v_app from public.hire_application_sessions where token = p_session_token and submitted_at is not null;
  if v_app is null then return false; end if;
  update public.hire_applications set honeypot_followup = left(p_text, 4000) where id = v_app and honeypot_followup is null;
  return true;
end;
$$;


--
-- Name: hire_interviews_zz_log(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hire_interviews_zz_log() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'INSERT' then
    insert into public.hire_application_events (application_id, kind, summary, payload, actor_id)
    values (new.application_id, 'interview', new.kind || ' interview ' || new.status, jsonb_build_object('interview_id', new.id, 'scheduled_at', new.scheduled_at), coalesce(auth.uid(), new.created_by));
  elsif new.status is distinct from old.status or new.scheduled_at is distinct from old.scheduled_at then
    insert into public.hire_application_events (application_id, kind, summary, payload, actor_id)
    values (new.application_id, 'interview', new.kind || ' interview ' || new.status || case when new.scheduled_at is not null then ' · ' || to_char(new.scheduled_at at time zone 'UTC', 'Mon DD HH24:MI') || ' UTC' else '' end, jsonb_build_object('interview_id', new.id, 'scheduled_at', new.scheduled_at, 'from', old.status), auth.uid());
  end if;
  return new;
end;
$$;


--
-- Name: hire_link_hit(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hire_link_hit(p_code text, p_ip_hash text, p_user_agent text, p_referer text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare l record; v_slug text; v_status text;
begin
  select * into l from public.hire_links where code = p_code and is_active;
  if l.code is null then return null; end if;
  insert into public.hire_link_hits (code, ip_hash, user_agent, referer) values (p_code, p_ip_hash, left(p_user_agent, 300), left(p_referer, 500));
  update public.hire_links set hits = hits + 1, last_hit_at = now() where code = p_code;
  select slug, status into v_slug, v_status from public.hire_positions where id = l.position_id;
  return jsonb_build_object('slug', v_slug, 'status', v_status, 'source', l.source, 'position_id', l.position_id, 'referrer_user_id', l.referrer_user_id);
end;
$$;


--
-- Name: hire_message_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hire_message_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.drafted_by is null then new.drafted_by := auth.uid(); end if;
    if auth.uid() is not null and new.status in ('sent', 'received') then new.status := 'draft'; end if;
  elsif new.status is distinct from old.status then
    if new.status = 'approved' then
      new.approved_by := coalesce(auth.uid(), new.approved_by);
      new.approved_at := now();
    elsif new.status = 'sent' and auth.uid() is not null then
      raise exception 'hiring: messages are sent by the app after approval, not marked sent by hand' using errcode = '42501';
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: hire_offer_compute(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hire_offer_compute() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare r record;
begin
  if tg_op = 'INSERT' and new.created_by is null then new.created_by := auth.uid(); end if;
  if new.pay_multiplier is not null and new.pay_level is not null then
    select * into r from public.hire_pay_target(new.pay_multiplier, new.pay_level, new.step);
    new.monthly_target_cents := r.monthly_target_cents;
    new.monthly_base_cents := r.monthly_base_cents;
    new.annual_target_cents := r.annual_target_cents;
    new.annual_base_cents := r.monthly_base_cents * 12;
  end if;
  if new.status is distinct from coalesce(old.status, '') then
    if new.status = 'approved' then
      if auth.uid() is not null and not public.is_reviewer_by_key('people_reviewers') then
        raise exception 'hiring: only the people reviewers (Alex) approve an offer' using errcode = '42501';
      end if;
      new.approved_by := coalesce(auth.uid(), new.approved_by); new.approved_at := now();
    elsif new.status = 'sent' then
      if old.status not in ('approved') and auth.uid() is not null then raise exception 'hiring: approve the offer before sending'; end if;
      new.sent_at := coalesce(new.sent_at, now());
    elsif new.status in ('accepted', 'declined', 'withdrawn') then
      new.decided_at := coalesce(new.decided_at, now());
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: hire_onboarding_create(uuid, date, uuid, uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hire_onboarding_create(p_profile_id uuid, p_start_on date DEFAULT NULL::date, p_manager_id uuid DEFAULT NULL::uuid, p_offer_id uuid DEFAULT NULL::uuid, p_employment text DEFAULT NULL::text, p_hold_calibration boolean DEFAULT NULL::boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare p record; v_plan uuid; v_start date; v_mgr uuid; v_emp text; t record; v_hold boolean; v_owner uuid;
begin
  if auth.uid() is not null and not (public.is_admin() or public.is_people_manager(auth.uid()) or public.has_capability('manage_hiring') or exists (select 1 from public.profiles where id = p_profile_id and manager_id = auth.uid())) then
    raise exception 'onboarding: not allowed' using errcode = '42501';
  end if;
  select * into p from public.profiles where id = p_profile_id;
  if p.id is null then raise exception 'profile not found'; end if;
  v_start := coalesce(p_start_on, p.date_started, current_date);
  v_mgr := coalesce(p_manager_id, p.manager_id);
  v_emp := coalesce(p_employment, 'full_time');
  -- hold out of calibration only while the person is inside the 60-day window
  v_hold := coalesce(p_hold_calibration, v_start + 60 > current_date);
  select id into v_owner from public.profiles where lower(email) = public.org_owner_email();

  insert into public.hire_onboarding_plans (profile_id, offer_id, manager_id, start_on, employment_type, calibration_hold, created_by)
  values (p_profile_id, p_offer_id, v_mgr, v_start, v_emp, v_hold, auth.uid())
  on conflict (profile_id) do update set offer_id = coalesce(public.hire_onboarding_plans.offer_id, excluded.offer_id), manager_id = coalesce(public.hire_onboarding_plans.manager_id, excluded.manager_id)
  returning id into v_plan;

  for t in select * from public.hire_onboarding_templates where is_active and v_emp = any(employment) order by phase, sort loop
    if not exists (select 1 from public.hire_onboarding_items where plan_id = v_plan and template_key = t.key) then
      insert into public.hire_onboarding_items (plan_id, template_key, label, description, phase, kind, owner_role, owner_id, due_on, window_from, sort)
      values (v_plan, t.key, t.label, t.description, t.phase, t.kind, t.owner_role,
              case t.owner_role when 'manager' then v_mgr when 'hire' then p_profile_id when 'owner' then v_owner else null end,
              v_start + t.due_day, case when t.window_from_day is not null then v_start + t.window_from_day else null end, t.sort);
    end if;
  end loop;
  -- DISC already on file (carried from the candidate or entered before) closes the DISC module
  if p.disc is not null and btrim(p.disc) <> '' then
    update public.hire_onboarding_items set status = 'done', note_md = coalesce(note_md, 'DISC already on the profile: ' || p.disc) where plan_id = v_plan and template_key = 'disc' and status = 'todo';
  end if;
  -- the calibration hold: new hires are not assessed before day 60 (decision 8).
  -- protect_profile_privileges() lets only admins (or no JWT: service role,
  -- the cron, the convert RPC) flip the flag; a people manager starting a
  -- plan by hand keeps the plan's hold and the tick lifts it at day 60.
  if v_hold and not p.calibration_excluded and (auth.uid() is null or public.is_admin()) then
    update public.profiles set calibration_excluded = true where id = p_profile_id;
    update public.hire_onboarding_plans set hold_flag_set = true where id = v_plan;
  end if;
  return v_plan;
end;
$$;


--
-- Name: hire_onboarding_items_stamp(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hire_onboarding_items_stamp() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.status = 'done' and (tg_op = 'INSERT' or old.status <> 'done') then
    new.done_at := coalesce(new.done_at, now());
    new.done_by := coalesce(new.done_by, auth.uid());
  elsif new.status <> 'done' then
    new.done_at := null; new.done_by := null;
  end if;
  return new;
end;
$$;


--
-- Name: hire_onboarding_tick(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hire_onboarding_tick() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare it record; pl record; v_cycle uuid; v_cycle_q text; v_overdue int := 0; v_enrolled int := 0; v_completed int := 0; v_phases int := 0; v_owner uuid; v_name text;
begin
  select id into v_owner from public.profiles where lower(email) = public.org_owner_email();
  -- 1. overdue items -> bell the owner (and the manager when the owner is the hire), once per item
  for it in select i.*, p.profile_id, p.manager_id as plan_manager from public.hire_onboarding_items i join public.hire_onboarding_plans p on p.id = i.plan_id
            where p.status = 'active' and i.status in ('todo', 'in_progress') and i.due_on < current_date and i.overdue_notified_at is null loop
    select coalesce(nullif(btrim(first_name || ' ' || coalesce(last_name, '')), ''), email) into v_name from public.profiles where id = it.profile_id;
    insert into public.notifications (user_id, kind, title, body, href, dedupe_key)
    select u, 'hiring', 'Onboarding item overdue: ' || it.label, v_name || ' · due ' || to_char(it.due_on, 'Mon DD') || ' · phase ' || it.phase, '/team/onboarding/' || it.profile_id, 'onb:overdue:' || it.id
      from unnest(array_remove(array[it.owner_id, case when it.owner_role = 'hire' then it.plan_manager end], null)) u
    on conflict (user_id, dedupe_key) do nothing;
    update public.hire_onboarding_items set overdue_notified_at = now() where id = it.id;
    v_overdue := v_overdue + 1;
  end loop;
  -- 2. phase stamps + completion
  for pl in select * from public.hire_onboarding_plans where status = 'active' loop
    if pl.phase1_done_at is null and not exists (select 1 from public.hire_onboarding_items where plan_id = pl.id and phase = 1 and status not in ('done', 'skipped')) then
      update public.hire_onboarding_plans set phase1_done_at = now() where id = pl.id; v_phases := v_phases + 1;
    end if;
    if pl.phase2_done_at is null and not exists (select 1 from public.hire_onboarding_items where plan_id = pl.id and phase = 2 and status not in ('done', 'skipped')) then
      update public.hire_onboarding_plans set phase2_done_at = now() where id = pl.id; v_phases := v_phases + 1;
    end if;
    if pl.phase3_done_at is null and not exists (select 1 from public.hire_onboarding_items where plan_id = pl.id and phase = 3 and status not in ('done', 'skipped')) then
      update public.hire_onboarding_plans set phase3_done_at = now(), completed_at = now(), status = 'complete' where id = pl.id; v_phases := v_phases + 1; v_completed := v_completed + 1;
    end if;
  end loop;
  -- 3. calibration enrolment: day 60 passed, still on hold, an open cycle exists -> lift the hold, record the cycle, bell
  select c.id, q.name into v_cycle, v_cycle_q from public.calibration_cycles c join public.quarters q on q.id = c.quarter_id where c.status = 'open' order by q.starts_on desc limit 1;
  if v_cycle is not null then
    for pl in select p.*, pr.first_name, pr.last_name, pr.email from public.hire_onboarding_plans p join public.profiles pr on pr.id = p.profile_id
              where p.status in ('active', 'complete') and p.calibration_hold and p.calibration_enrolled_at is null and p.start_on + 60 <= current_date loop
      update public.profiles set calibration_excluded = false where id = pl.profile_id and calibration_excluded and pl.hold_flag_set;
      update public.hire_onboarding_plans set calibration_hold = false, calibration_enrolled_cycle_id = v_cycle, calibration_enrolled_at = now() where id = pl.id;
      v_name := coalesce(nullif(btrim(pl.first_name || ' ' || coalesce(pl.last_name, '')), ''), pl.email);
      insert into public.notifications (user_id, kind, title, body, href, dedupe_key)
      select u, 'calibration', 'Calibration: ' || v_name || ' joins cycle ' || v_cycle_q, 'Day 60 of onboarding passed; the self → leader → exec rounds are open for them in this cycle.', '/team/calibration', 'onb:calib:' || pl.id
        from unnest(array_remove(array[pl.profile_id, pl.manager_id, v_owner], null)) u
      on conflict (user_id, dedupe_key) do nothing;
      v_enrolled := v_enrolled + 1;
    end loop;
  end if;
  return jsonb_build_object('overdue_notified', v_overdue, 'phase_stamps', v_phases, 'completed', v_completed, 'calibration_enrolled', v_enrolled, 'open_cycle', v_cycle);
end;
$$;


--
-- Name: hire_pay_target(numeric, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hire_pay_target(p_multiplier numeric, p_level text, p_step integer DEFAULT 1) RETURNS TABLE(monthly_target_cents bigint, monthly_base_cents bigint, monthly_performance_cents bigint, annual_target_cents bigint, global_step integer)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_cfg jsonb;
  v_start numeric; v_first numeric; v_step numeric;
  v_sort int; v_steps int; v_base_pct numeric;
  v_idx int; v_monthly numeric;
begin
  select value into v_cfg from public.hire_settings where key = 'pay_progression';
  v_start := p_multiplier * coalesce((v_cfg->>'start_per_multiplier')::numeric, 100);
  v_first := coalesce((v_cfg->>'first_step_factor')::numeric, 1.05);
  v_step  := coalesce((v_cfg->>'step_factor')::numeric, 1.04);
  select l.sort, l.steps, l.base_pct into v_sort, v_steps, v_base_pct from public.hire_pay_levels l where l.slug = p_level;
  if v_sort is null then raise exception 'hire_pay_target: unknown level %', p_level; end if;
  if p_step < 1 or p_step > v_steps then raise exception 'hire_pay_target: step % out of range 1..%', p_step, v_steps; end if;
  select coalesce(sum(l.steps), 0) into v_idx from public.hire_pay_levels l where l.sort < v_sort and l.is_active;
  v_idx := v_idx + (p_step - 1);
  v_monthly := round(v_start * v_first * power(v_step, v_idx));
  monthly_target_cents := (v_monthly * 100)::bigint;
  monthly_base_cents := (round(v_monthly * v_base_pct / 100) * 100)::bigint;
  monthly_performance_cents := monthly_target_cents - monthly_base_cents;
  annual_target_cents := monthly_target_cents * 12;
  global_step := v_idx;
  return next;
end;
$$;


--
-- Name: hire_pool_closed_role(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hire_pool_closed_role(p_position_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare pos record; a record; v_n int := 0;
begin
  if auth.uid() is not null and not public.can_view_hiring() then raise exception 'hiring: not allowed' using errcode = '42501'; end if;
  select * into pos from public.hire_positions where id = p_position_id;
  if pos.id is null then raise exception 'position not found'; end if;
  for a in select id, candidate_id from public.hire_applications where position_id = p_position_id and status not in ('hired', 'rejected', 'withdrawn', 'pool') loop
    update public.hire_applications set status = 'pool', stage_key = null, decided_by = auth.uid(), decided_at = now(), last_activity_at = now() where id = a.id;
    update public.hire_candidates set talent_pool = true,
           pool_tags = (select coalesce(array_agg(distinct x), '{}') from unnest(pool_tags || array_remove(array[pos.department_label, pos.title, pos.pap_position], null)) x)
     where id = a.candidate_id;
    v_n := v_n + 1;
  end loop;
  return v_n;
end;
$$;


--
-- Name: hire_portal_resolve(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hire_portal_resolve(p_token_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare t record; c record;
begin
  select * into t from public.hire_portal_tokens where token_hash = p_token_hash and expires_at > now();
  if t.id is null then return null; end if;
  update public.hire_portal_tokens set last_seen_at = now(), used_at = coalesce(used_at, now()) where id = t.id;
  select id, full_name, email, phone from public.hire_candidates where id = t.candidate_id into c;
  return jsonb_build_object('candidate_id', c.id, 'full_name', c.full_name, 'email', c.email, 'purpose', t.purpose, 'expires_at', t.expires_at);
end;
$$;


--
-- Name: hire_position_comp_compute(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hire_position_comp_compute() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare r record;
begin
  if new.pay_multiplier is not null and new.pay_level is not null then
    select * into r from public.hire_pay_target(new.pay_multiplier, new.pay_level, new.step);
    new.monthly_target_cents := r.monthly_target_cents;
    new.monthly_base_cents := r.monthly_base_cents;
    new.monthly_performance_cents := r.monthly_performance_cents;
    new.annual_target_cents := r.annual_target_cents;
  end if;
  if new.updated_by is null then new.updated_by := auth.uid(); end if;
  return new;
end;
$$;


--
-- Name: hire_position_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hire_position_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.created_by is null then new.created_by := auth.uid(); end if;
    if new.status not in ('draft', 'approved') then new.status := 'draft'; end if;
    if new.status = 'approved' and auth.uid() is not null and not public.is_reviewer_by_key('people_reviewers') then
      new.status := 'draft';
    end if;
    return new;
  end if;
  if new.updated_by is null or new.updated_by is not distinct from old.updated_by then new.updated_by := coalesce(auth.uid(), new.updated_by); end if;
  if new.status is distinct from old.status then
    if new.status = 'approved' and auth.uid() is not null and not public.is_reviewer_by_key('people_reviewers') then
      raise exception 'hiring: only the people reviewers (Alex) approve a position' using errcode = '42501';
    end if;
    if new.status = 'open' then
      if new.approved_at is null then
        raise exception 'hiring: a position opens only after approval (file a position request)';
      end if;
      if btrim(new.role_md) = '' or btrim(new.responsibilities_md) = '' or btrim(new.results_md) = '' or btrim(new.requirements_md) = '' then
        raise exception 'hiring: finish the 4R (role, responsibilities, results, requirements) before opening';
      end if;
      if new.opened_at is null then new.opened_at := now(); end if;
    end if;
    if new.status in ('closed', 'filled') and new.closed_at is null then new.closed_at := now(); end if;
    if new.status = 'approved' and new.approved_at is null then new.approved_at := now(); new.approved_by := coalesce(new.approved_by, auth.uid()); end if;
  end if;
  return new;
end;
$$;


--
-- Name: hire_position_log(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hire_position_log() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'INSERT' then
    insert into public.hire_position_events (position_id, actor_id, kind, to_status)
    values (new.id, coalesce(auth.uid(), new.created_by), 'created', new.status);
  elsif new.status is distinct from old.status then
    insert into public.hire_position_events (position_id, actor_id, kind, from_status, to_status)
    values (new.id, coalesce(auth.uid(), new.updated_by), 'status', old.status, new.status);
  end if;
  return new;
end;
$$;


--
-- Name: hire_position_zz_close_postings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hire_position_zz_close_postings() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.status is distinct from old.status and new.status in ('paused', 'closed', 'filled') then
    update public.hire_postings set status = 'closed', updated_by = new.updated_by
     where position_id = new.id and status in ('planned', 'posted', 'live');
  end if;
  return new;
end;
$$;


--
-- Name: hire_posting_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hire_posting_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_days int;
begin
  if tg_op = 'INSERT' and new.created_by is null then new.created_by := auth.uid(); end if;
  if new.updated_by is null or (tg_op = 'UPDATE' and new.updated_by is not distinct from old.updated_by) then new.updated_by := coalesce(auth.uid(), new.updated_by); end if;
  if new.status in ('posted', 'live') then
    if new.posted_at is null then new.posted_at := now(); end if;
    if new.expires_at is null then
      select default_days into v_days from public.hire_boards where key = new.board_key;
      new.expires_at := new.posted_at + make_interval(days => coalesce(v_days, 30));
    end if;
  end if;
  if new.status in ('closed', 'expired') and new.closed_at is null then new.closed_at := now(); end if;
  return new;
end;
$$;


--
-- Name: hire_quality_funnel(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hire_quality_funnel() RETURNS TABLE(position_id uuid, title text, status text, brand text, department_label text, hiring_manager_id uuid, recruiter_id uuid, opened_at timestamp with time zone, closed_at timestamp with time zone, headcount integer, applications integer, by_status jsonb, stage_entries jsonb, interviews integer, no_shows integer, offers integer, offers_declined integer, hired integer, median_time_to_hire_days numeric, avg_time_to_hire_days numeric, posting_cost_cents bigint, cost_per_hire_cents bigint, avg_overall_score numeric, avg_overall_hired numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
#variable_conflict use_column
begin
  if auth.uid() is not null and not public.can_view_hiring() then raise exception 'hiring: not allowed' using errcode = '42501'; end if;
  return query
  with apps as (select a.* from public.hire_applications a where not a.hidden),
  st as (select x.position_id, jsonb_object_agg(x.status, x.n) as by_status from (select a1.position_id, a1.status, count(*)::int as n from apps a1 group by 1, 2) x group by x.position_id),
  ev as (
    select a2.position_id, jsonb_object_agg(a2.to_s, a2.n) as entries
      from (select a0.position_id, coalesce(e.payload->>'to_status', '?') as to_s, count(distinct e.application_id)::int as n
              from public.hire_application_events e join apps a0 on a0.id = e.application_id where e.kind = 'stage' group by 1, 2) a2
     group by a2.position_id
  ),
  iv as (select i.position_id, count(*)::int as n, count(*) filter (where i.status = 'no_show')::int as ns from public.hire_interviews i group by i.position_id),
  offs as (select o.position_id, count(*)::int as n, count(*) filter (where o.status = 'declined')::int as declined from public.hire_offers o group by o.position_id),
  hires as (
    select a3.position_id, count(*)::int as n,
           percentile_cont(0.5) within group (order by (a3.decided_at::date - a3.submitted_at::date)) as med,
           round(avg(a3.decided_at::date - a3.submitted_at::date), 1) as avg_days,
           round(avg(a3.overall_score), 1) as avg_hired
      from apps a3 where a3.status = 'hired' and a3.decided_at is not null group by a3.position_id
  ),
  cost as (select pst.position_id, sum(coalesce(pst.cost_cents, 0))::bigint as cents from public.hire_postings pst group by pst.position_id),
  sc as (select a4.position_id, round(avg(a4.overall_score), 1) as avg_all from apps a4 group by a4.position_id)
  select p.id, p.title, p.status, p.brand, p.department_label, p.hiring_manager_id, p.recruiter_id, p.opened_at, p.closed_at, p.headcount::int,
         coalesce((select count(*)::int from apps a5 where a5.position_id = p.id), 0),
         coalesce(st.by_status, '{}'::jsonb), coalesce(ev.entries, '{}'::jsonb),
         coalesce(iv.n, 0), coalesce(iv.ns, 0), coalesce(offs.n, 0), coalesce(offs.declined, 0), coalesce(hires.n, 0),
         hires.med::numeric, hires.avg_days, coalesce(cost.cents, 0), case when coalesce(hires.n, 0) > 0 then (coalesce(cost.cents, 0) / hires.n)::bigint end,
         sc.avg_all, hires.avg_hired
    from public.hire_positions p
    left join st on st.position_id = p.id
    left join ev on ev.position_id = p.id
    left join iv on iv.position_id = p.id
    left join offs on offs.position_id = p.id
    left join hires on hires.position_id = p.id
    left join cost on cost.position_id = p.id
    left join sc on sc.position_id = p.id
   where p.status not in ('draft')
   order by p.opened_at desc nulls last, p.created_at desc;
end;
$$;


--
-- Name: hire_quality_hires(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hire_quality_hires(p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date) RETURNS TABLE(profile_id uuid, full_name text, email text, job_role text, department_tag_id uuid, manager_id uuid, date_started date, is_active boolean, employment_status text, exited_on date, days_employed integer, retained_30 boolean, retained_60 boolean, retained_90 boolean, retained_180 boolean, advancements integer, level_now smallint, calibration_latest numeric, calibration_avg numeric, calibration_outcome text, calibration_cycles integer, contributions integer, contributions_open integer, offer_id uuid, application_id uuid, position_id uuid, position_title text, source text, link_code text, board_key text, referrer_user_id uuid, recruiter_id uuid, hiring_manager_id uuid, submitted_at timestamp with time zone, hired_at timestamp with time zone, time_to_hire_days integer, interviewer_ids uuid[], scorecard_avg numeric, overall_score numeric, onboarding_status text, onboarding_done integer, onboarding_total integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
#variable_conflict use_column
begin
  if auth.uid() is not null and not public.can_view_hiring() then raise exception 'hiring: not allowed' using errcode = '42501'; end if;
  return query
  with staff as (
    select p.id, coalesce(nullif(btrim(coalesce(p.first_name, '') || ' ' || coalesce(p.last_name, '')), ''), p.email) as full_name, p.email, p.job_role, p.department_tag_id, p.manager_id, p.date_started, p.is_active, p.employment_status, p.position_level,
           case when p.is_active then null else coalesce((select min(h.changed_at)::date from public.hire_level_history h where h.profile_id = p.id and h.field = 'is_active' and h.to_value = 'false'), p.updated_at::date) end as exited_on
      from public.profiles p
     where p.date_started is not null
       and lower(split_part(p.email, '@', 2)) = any (public.org_email_domains())
       and p.role in ('exec', 'admin', 'manager', 'contributor')
       and (p_from is null or p.date_started >= p_from) and (p_to is null or p.date_started <= p_to)
  ),
  off as (
    select distinct on (o.hired_profile_id) o.id as offer_id, o.application_id, o.position_id, o.hired_profile_id, o.decided_at
      from public.hire_offers o where o.hired_profile_id is not null and o.status = 'accepted'
     order by o.hired_profile_id, o.decided_at desc nulls last
  ),
  adv as (select h.profile_id, count(*)::int as n from public.hire_level_history h join staff s on s.id = h.profile_id where h.is_advancement and h.changed_at::date > s.date_started group by h.profile_id),
  cal as (
    select cs.subject_id,
           (array_agg(cs.total order by q.starts_on desc))[1] as latest,
           round(avg(cs.total), 1) as avg_total,
           (array_agg(cs.outcome order by q.starts_on desc) filter (where cs.outcome is not null))[1] as outcome,
           count(distinct cs.cycle_id)::int as cycles
      from public.calibration_scores cs
      join public.calibration_cycles c on c.id = cs.cycle_id
      join public.quarters q on q.id = c.quarter_id
     where cs.submitted_at is not null and cs.round in ('exec', 'leader') and cs.total is not null
     group by cs.subject_id
  ),
  contrib as (
    select s.id as profile_id,
           count(distinct pr.id) filter (where pr.completed_at is not null)::int as done,
           count(distinct pr.id) filter (where pr.completed_at is null and not pr.archived)::int as open
      from staff s
      join public.projects pr on (pr.owner_id = s.id or pr.project_lead_id = s.id or pr.team_lead_id = s.id or exists (select 1 from public.work_item_owners w where w.work_item_id = pr.id and w.user_id = s.id))
     where coalesce(pr.completed_at, pr.created_at) >= s.date_started
     group by s.id
  ),
  ivs as (
    select i.application_id, array_agg(distinct u) as interviewers
      from public.hire_interviews i cross join lateral unnest(i.interviewer_ids || coalesce(array[i.owner_id], '{}')) u
     where u is not null group by i.application_id
  ),
  cards as (select sc.application_id, round(avg(sc.avg_score), 2) as avg_score from public.hire_scorecards sc where sc.submitted_at is not null and not sc.is_ai group by sc.application_id),
  onb as (
    select pl.profile_id, pl.status, (select count(*)::int from public.hire_onboarding_items i where i.plan_id = pl.id and i.status in ('done', 'skipped')) as done, (select count(*)::int from public.hire_onboarding_items i where i.plan_id = pl.id) as total
      from public.hire_onboarding_plans pl
  )
  select s.id, s.full_name, s.email, s.job_role, s.department_tag_id, s.manager_id, s.date_started, s.is_active, s.employment_status,
         s.exited_on,
         (coalesce(s.exited_on, current_date) - s.date_started)::int as days_employed,
         case when s.date_started + 30 > current_date and s.is_active then null else (coalesce(s.exited_on, current_date) - s.date_started) >= 30 end,
         case when s.date_started + 60 > current_date and s.is_active then null else (coalesce(s.exited_on, current_date) - s.date_started) >= 60 end,
         case when s.date_started + 90 > current_date and s.is_active then null else (coalesce(s.exited_on, current_date) - s.date_started) >= 90 end,
         case when s.date_started + 180 > current_date and s.is_active then null else (coalesce(s.exited_on, current_date) - s.date_started) >= 180 end,
         coalesce(adv.n, 0), s.position_level,
         cal.latest, cal.avg_total, cal.outcome, coalesce(cal.cycles, 0),
         coalesce(contrib.done, 0), coalesce(contrib.open, 0),
         off.offer_id, off.application_id, off.position_id, pos.title, coalesce(a.source, case when off.offer_id is null then 'legacy' end), a.link_code, l.board_key, a.referrer_user_id, pos.recruiter_id, pos.hiring_manager_id,
         a.submitted_at, coalesce(a.decided_at, off.decided_at), case when a.submitted_at is not null then (coalesce(a.decided_at, off.decided_at)::date - a.submitted_at::date) end,
         ivs.interviewers, cards.avg_score, a.overall_score::numeric, onb.status, onb.done, onb.total
    from staff s
    left join off on off.hired_profile_id = s.id
    left join public.hire_applications a on a.id = off.application_id
    left join public.hire_positions pos on pos.id = off.position_id
    left join public.hire_links l on l.code = a.link_code
    left join adv on adv.profile_id = s.id
    left join cal on cal.subject_id = s.id
    left join contrib on contrib.profile_id = s.id
    left join ivs on ivs.application_id = off.application_id
    left join cards on cards.application_id = off.application_id
    left join onb on onb.profile_id = s.id
   order by s.date_started desc, s.full_name;
end;
$$;


--
-- Name: hire_quality_interviewers(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hire_quality_interviewers() RETURNS TABLE(scorer_id uuid, cards integer, interviews integer, avg_score numeric, strong_hire integer, advance integer, conditional integer, no_hire integer, decided integer, agreed integer, accuracy_pct numeric, hired_after_yes integer, hired_after_no integer, rejected_after_yes integer, avg_score_hired numeric, avg_score_rejected numeric, retained_90_after_yes integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
#variable_conflict use_column
begin
  if auth.uid() is not null and not public.can_view_hiring() then raise exception 'hiring: not allowed' using errcode = '42501'; end if;
  return query
  with sc as (
    select s.scorer_id, s.interview_id, s.application_id, s.avg_score, s.recommendation,
           a.status as app_status,
           (s.recommendation in ('strong_hire', 'advance')) as said_yes,
           (s.recommendation = 'no_hire') as said_no
      from public.hire_scorecards s join public.hire_applications a on a.id = s.application_id
     where s.submitted_at is not null and not s.is_ai and s.scorer_id is not null
  ),
  ret as (
    select o.application_id from public.hire_offers o join public.profiles p on p.id = o.hired_profile_id
     where o.status = 'accepted' and p.is_active and p.date_started is not null and p.date_started + 90 <= current_date
  )
  select sc.scorer_id, count(*)::int, count(distinct sc.interview_id)::int, round(avg(sc.avg_score), 2),
         count(*) filter (where sc.recommendation = 'strong_hire')::int, count(*) filter (where sc.recommendation = 'advance')::int,
         count(*) filter (where sc.recommendation = 'conditional')::int, count(*) filter (where sc.recommendation = 'no_hire')::int,
         count(*) filter (where sc.app_status in ('hired', 'rejected') and (sc.said_yes or sc.said_no))::int,
         count(*) filter (where (sc.app_status = 'hired' and sc.said_yes) or (sc.app_status = 'rejected' and sc.said_no))::int,
         case when count(*) filter (where sc.app_status in ('hired', 'rejected') and (sc.said_yes or sc.said_no)) > 0
              then round(100.0 * count(*) filter (where (sc.app_status = 'hired' and sc.said_yes) or (sc.app_status = 'rejected' and sc.said_no)) / count(*) filter (where sc.app_status in ('hired', 'rejected') and (sc.said_yes or sc.said_no)), 0) end,
         count(*) filter (where sc.app_status = 'hired' and sc.said_yes)::int,
         count(*) filter (where sc.app_status = 'hired' and sc.said_no)::int,
         count(*) filter (where sc.app_status = 'rejected' and sc.said_yes)::int,
         round(avg(sc.avg_score) filter (where sc.app_status = 'hired'), 2),
         round(avg(sc.avg_score) filter (where sc.app_status = 'rejected'), 2),
         count(*) filter (where sc.said_yes and exists (select 1 from ret r where r.application_id = sc.application_id))::int
    from sc
   group by sc.scorer_id
   order by count(*) desc;
end;
$$;


--
-- Name: hire_quality_sources(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hire_quality_sources() RETURNS TABLE(position_id uuid, source text, board_key text, applications integer, past_screening integer, interviewed integer, offered integer, hired integer, retained_90 integer, avg_overall numeric, avg_integrity numeric, flagged integer, posting_cost_cents bigint, cost_per_hire_cents bigint, link_hits integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
#variable_conflict use_column
begin
  if auth.uid() is not null and not public.can_view_hiring() then raise exception 'hiring: not allowed' using errcode = '42501'; end if;
  return query
  with apps as (
    select a.*, coalesce(l.board_key, a.source, 'direct') as src, l.board_key as bk
      from public.hire_applications a left join public.hire_links l on l.code = a.link_code where not a.hidden
  ),
  ret as (
    select o.application_id, (p.is_active and p.date_started is not null and p.date_started + 90 <= current_date) as r90
      from public.hire_offers o join public.profiles p on p.id = o.hired_profile_id where o.status = 'accepted'
  ),
  cost as (select pst.position_id, pst.board_key, sum(coalesce(pst.cost_cents, 0))::bigint as cents from public.hire_postings pst group by 1, 2),
  hits as (select l.position_id, coalesce(l.board_key, l.source) as src, sum(l.hits)::int as hits from public.hire_links l group by 1, 2)
  select a.position_id, a.src, a.bk,
         count(*)::int,
         count(*) filter (where a.status not in ('new', 'screening', 'rejected', 'withdrawn', 'pool') or (a.status = 'rejected' and a.stage_key not in ('new', 'screening')))::int,
         count(*) filter (where exists (select 1 from public.hire_interviews i where i.application_id = a.id and i.status in ('scheduled', 'completed', 'no_show', 'rescheduled')))::int,
         count(*) filter (where exists (select 1 from public.hire_offers o where o.application_id = a.id))::int,
         count(*) filter (where a.status = 'hired')::int,
         count(*) filter (where exists (select 1 from ret r where r.application_id = a.id and r.r90))::int,
         round(avg(a.overall_score), 1), round(avg(a.integrity_score), 1),
         count(*) filter (where a.honeypot_hits > 0 or a.blocked_paste_attempts > 0 or a.ai_text_flags > 0)::int,
         coalesce(max(cost.cents), 0),
         case when count(*) filter (where a.status = 'hired') > 0 then (coalesce(max(cost.cents), 0) / count(*) filter (where a.status = 'hired'))::bigint end,
         coalesce(max(hits.hits), 0)
    from apps a
    left join cost on cost.position_id = a.position_id and cost.board_key = a.bk
    left join hits on hits.position_id = a.position_id and hits.src = a.src
   group by a.position_id, a.src, a.bk
   order by count(*) desc;
end;
$$;


--
-- Name: hire_referral_link(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hire_referral_link(p_position_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_code text; v_slug text; v_first text;
begin
  if auth.uid() is null or not public.is_internal_staff() then
    raise exception 'hiring: sign in as staff to get a referral link' using errcode = '42501';
  end if;
  select code into v_code from public.hire_links where position_id = p_position_id and referrer_user_id = auth.uid();
  if v_code is not null then return v_code; end if;
  select slug into v_slug from public.hire_positions where id = p_position_id;
  if v_slug is null then raise exception 'position not found'; end if;
  select lower(regexp_replace(coalesce(first_name, 'ref'), '[^a-zA-Z0-9]', '', 'g')) into v_first from public.profiles where id = auth.uid();
  v_code := left(v_slug, 24) || '-' || left(coalesce(nullif(v_first, ''), 'ref'), 10) || '-' || left(replace(gen_random_uuid()::text, '-', ''), 4);
  insert into public.hire_links (code, position_id, source, referrer_user_id, label, created_by)
  values (v_code, p_position_id, 'referral', auth.uid(), 'Referral link', auth.uid());
  return v_code;
end;
$$;


--
-- Name: hire_scorecard_compute(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hire_scorecard_compute() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v jsonb; n int := 0; sum numeric := 0; mn int := null; ones int := 0; twos int := 0; fours int := 0; sc int;
begin
  if auth.uid() is not null and not new.is_ai then
    if new.scorer_id is null then new.scorer_id := auth.uid(); end if;
    if new.scorer_id <> auth.uid() and not public.can_manage_hiring() then
      raise exception 'hiring: a scorecard is filled by its scorer' using errcode = '42501';
    end if;
  end if;
  for v in select value from jsonb_each(coalesce(new.answers, '{}'::jsonb)) loop
    sc := nullif(v->>'score', '')::int;
    if sc is null then continue; end if;
    if sc < 1 or sc > 4 then raise exception 'hiring: scores are 1-4'; end if;
    n := n + 1; sum := sum + sc;
    mn := least(coalesce(mn, sc), sc);
    if sc = 1 then ones := ones + 1; elsif sc = 2 then twos := twos + 1; elsif sc = 4 then fours := fours + 1; end if;
  end loop;
  new.avg_score := case when n > 0 then round(sum / n, 2) end;
  new.min_score := mn; new.ones := ones; new.twos := twos; new.fours := fours;
  return new;
end;
$$;


--
-- Name: hire_scorecards_zz_log(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hire_scorecards_zz_log() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.submitted_at is not null and (tg_op = 'INSERT' or old.submitted_at is null) then
    insert into public.hire_application_events (application_id, kind, summary, payload, actor_id)
    values (new.application_id, 'scorecard', (case when new.is_ai then 'AI prefill ' else 'Scorecard ' end) || new.kind || ' · avg ' || coalesce(new.avg_score::text, '—') || coalesce(' · ' || new.recommendation, ''), jsonb_build_object('scorecard_id', new.id, 'avg', new.avg_score, 'ones', new.ones, 'twos', new.twos, 'fours', new.fours), new.scorer_id);
  end if;
  return new;
end;
$$;


--
-- Name: hire_shortlist(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hire_shortlist(p_position_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_n int;
begin
  if auth.uid() is not null and not public.can_view_hiring() then
    raise exception 'hiring: not allowed' using errcode = '42501';
  end if;
  update public.hire_applications set shortlist_rank = null where position_id = p_position_id and shortlist_rank is not null;
  with ranked as (
    select id, row_number() over (order by overall_score desc, integrity_score desc nulls last, submitted_at asc) as rn
      from public.hire_applications
     where position_id = p_position_id and overall_score is not null and not hidden
       and status not in ('rejected', 'withdrawn', 'pool')
  )
  update public.hire_applications a set shortlist_rank = r.rn from ranked r where r.id = a.id;
  get diagnostics v_n = row_count;
  return v_n;
end;
$$;


--
-- Name: hire_submit_application(text, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hire_submit_application(p_session_token text, p_contact jsonb, p_answers jsonb, p_meta jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  s record; pos record; cand uuid; app uuid; existing uuid;
  v_email text; v_phone text; v_linkedin text; v_name text;
  v_restarts int; v_sessions int; v_paste int := 0; v_pasted int := 0; v_typed int := 0; v_blocked int := 0; v_honey int := 0; v_total int := 0;
  a jsonb; qk text; q jsonb; sect jsonb; v_q_type text; v_label text; v_sect_key text; v_is_honey boolean;
  v_link record; v_link_code text; v_referrer uuid; v_source text;
begin
  select * into s from public.hire_application_sessions where token = p_session_token for update;
  if s.id is null then raise exception 'session not found'; end if;
  if s.submitted_at is not null then
    return jsonb_build_object('application_id', s.application_id, 'already', true);
  end if;
  select * into pos from public.hire_positions where id = s.position_id;
  if pos.id is null or pos.status <> 'open' then raise exception 'this role is not accepting applications'; end if;

  v_email := btrim(p_contact->>'email');
  if v_email is null or v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'a valid email is required'; end if;
  v_name := left(btrim(coalesce(p_contact->>'full_name', '')), 160);
  if v_name = '' then raise exception 'full name is required'; end if;
  v_phone := nullif(btrim(coalesce(p_contact->>'phone_e164', '')), '');
  v_linkedin := nullif(btrim(coalesce(p_contact->>'linkedin_url', '')), '');

  -- dedupe: email, then phone, then LinkedIn
  select id into cand from public.hire_candidates where email_key = lower(v_email);
  if cand is null and v_phone is not null then select id into cand from public.hire_candidates where phone_e164 = v_phone; end if;
  if cand is null and v_linkedin is not null then
    select id into cand from public.hire_candidates where linkedin_key = nullif(lower(regexp_replace(v_linkedin, '^https?://(www\.)?linkedin\.com/in/|/+$|\?.*$', '', 'g')), '');
  end if;
  if cand is null then
    insert into public.hire_candidates (full_name, email, phone, phone_e164, linkedin_url, location_text, country, timezone, current_title, portfolio_urls, consent_version, consented_at)
    values (v_name, v_email, nullif(p_contact->>'phone', ''), v_phone, v_linkedin, nullif(p_contact->>'location_text', ''), nullif(p_contact->>'country', ''), nullif(p_contact->>'timezone', ''), nullif(p_contact->>'current_role', ''),
            coalesce((select array_agg(x) from jsonb_array_elements_text(coalesce(p_contact->'portfolio_urls', '[]'::jsonb)) x), '{}'),
            coalesce(s.consent_version, 1), coalesce(s.consented_at, now()))
    returning id into cand;
  else
    update public.hire_candidates
       set full_name = v_name,
           phone = coalesce(nullif(p_contact->>'phone', ''), phone),
           phone_e164 = coalesce(v_phone, phone_e164),
           linkedin_url = coalesce(v_linkedin, linkedin_url),
           location_text = coalesce(nullif(p_contact->>'location_text', ''), location_text),
           country = coalesce(nullif(p_contact->>'country', ''), country),
           timezone = coalesce(nullif(p_contact->>'timezone', ''), timezone),
           current_title = coalesce(nullif(p_contact->>'current_role', ''), current_title),
           portfolio_urls = (select coalesce(array_agg(distinct x), '{}') from unnest(portfolio_urls || coalesce((select array_agg(y) from jsonb_array_elements_text(coalesce(p_contact->'portfolio_urls', '[]'::jsonb)) y), '{}')) x),
           consent_version = greatest(coalesce(consent_version, 0), coalesce(s.consent_version, 1)),
           consented_at = coalesce(consented_at, s.consented_at, now())
     where id = cand;
  end if;

  select id into existing from public.hire_applications where position_id = pos.id and candidate_id = cand;
  if existing is not null then
    update public.hire_application_sessions set submitted_at = now(), application_id = existing where id = s.id;
    return jsonb_build_object('application_id', existing, 'already', true);
  end if;

  -- restarts: other sessions for this role by the same email or fingerprint
  select count(*) into v_sessions from public.hire_application_sessions x
   where x.position_id = pos.id and x.id <> s.id and x.submitted_at is null
     and ((x.email_key is not null and x.email_key = lower(v_email)) or (x.fingerprint is not null and x.fingerprint = s.fingerprint));
  v_restarts := v_sessions;

  -- source attribution
  v_source := 'direct';
  if s.link_code is not null then
    select * into v_link from public.hire_links where code = s.link_code;
    if v_link.code is not null then v_source := v_link.source; v_referrer := v_link.referrer_user_id; v_link_code := v_link.code; end if;
  end if;

  insert into public.hire_applications (position_id, candidate_id, source, link_code, referrer_user_id, utm, config_snapshot, consent_version, restarts, sessions_count, ip_hash, user_agent, total_time_s)
  values (pos.id, cand, v_source, v_link_code, v_referrer, coalesce(p_meta->'utm', '{}'::jsonb), pos.application_config, coalesce(s.consent_version, 1), v_restarts, v_sessions + 1, s.ip_hash, s.user_agent,
          greatest(0, extract(epoch from (now() - s.started_at)))::int)
  returning id into app;

  -- answers: p_answers = { question_key: { value, typed_chars, pasted_chars, paste_events, blocked, time_used_s, started_at, finished_at } }
  for sect in select * from jsonb_array_elements(pos.application_config->'sections') loop
    v_sect_key := sect->>'key';
    for q in select * from jsonb_array_elements(sect->'questions') loop
      qk := q->>'key';
      a := p_answers->qk;
      if a is null then continue; end if;
      v_q_type := q->>'type';
      v_label := q->>'label';
      v_is_honey := coalesce((q->>'honeypot')::boolean, false);
      v_paste := v_paste + coalesce((a->>'paste_events')::int, 0);
      v_pasted := v_pasted + coalesce((a->>'pasted_chars')::int, 0);
      v_typed := v_typed + coalesce((a->>'typed_chars')::int, 0);
      v_blocked := v_blocked + coalesce((a->>'blocked')::int, 0);
      if v_is_honey and v_q_type = 'rating_1_5' and coalesce((a->>'value')::int, 0) >= coalesce((q->>'honeypot_threshold')::int, 3) then v_honey := v_honey + 1; end if;
      insert into public.hire_application_answers (application_id, section_key, question_key, question_type, label, value, typed_chars, pasted_chars, paste_events, blocked_paste_attempts, time_used_s, started_at, finished_at, is_honeypot)
      values (app, v_sect_key, qk, v_q_type, v_label, a->'value',
              coalesce((a->>'typed_chars')::int, 0), coalesce((a->>'pasted_chars')::int, 0), coalesce((a->>'paste_events')::int, 0), coalesce((a->>'blocked')::int, 0),
              nullif(a->>'time_used_s', '')::int, nullif(a->>'started_at', '')::timestamptz, nullif(a->>'finished_at', '')::timestamptz, v_is_honey)
      on conflict (application_id, question_key) do nothing;
    end loop;
  end loop;

  update public.hire_applications
     set paste_events = v_paste, pasted_chars = v_pasted, typed_chars = v_typed, blocked_paste_attempts = v_blocked, honeypot_hits = v_honey,
         integrity_notes = (
           select coalesce(jsonb_agg(n), '[]'::jsonb) from (
             select 'restarted ' || v_restarts || ' time(s)' as n where v_restarts > 0
             union all select 'pasted ' || v_pasted || ' chars across ' || v_paste || ' paste(s)' where v_pasted > 0
             union all select v_blocked || ' blocked paste attempt(s) on no-paste questions' where v_blocked > 0
             union all select 'rated ' || v_honey || ' honeypot skill(s) >= threshold' where v_honey > 0
           ) t)
   where id = app;

  -- files recorded during the session move onto the application
  update public.hire_application_files set application_id = app, candidate_id = cand where application_id is null and path like 'sessions/' || s.token || '/%';
  update public.hire_candidates c
     set resume_path = coalesce((select f.path from public.hire_application_files f where f.application_id = app and f.kind = 'resume' order by f.created_at desc limit 1), c.resume_path),
         video_path = coalesce((select f.path from public.hire_application_files f where f.application_id = app and f.kind = 'video' order by f.created_at desc limit 1), c.video_path),
         video_url = coalesce(nullif(p_contact->>'video_url', ''), c.video_url)
   where c.id = cand;

  update public.hire_application_sessions set submitted_at = now(), application_id = app, email_key = lower(v_email) where id = s.id;

  -- H4: queue enrichment now that resume / video paths are on the candidate
  perform public.hire_enqueue_enrichment(app);

  -- bell the hiring manager + recruiter
  insert into public.notifications (user_id, kind, title, body, href, dedupe_key)
  select u, 'hiring', 'New application: ' || pos.title, v_name || ' · ' || v_source || case when v_honey > 0 or v_restarts > 0 then ' · integrity flags' else '' end, '/hiring/positions/' || pos.id || '/applications/' || app, 'hire:app:' || app
  from unnest(array_remove(array[pos.hiring_manager_id, pos.recruiter_id], null)) u
  on conflict (user_id, dedupe_key) do nothing;

  return jsonb_build_object('application_id', app, 'candidate_id', cand, 'already', false, 'honeypot_hits', v_honey, 'restarts', v_restarts);
end;
$_$;


--
-- Name: hire_subscribe_alert(text, text, text[], uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hire_subscribe_alert(p_email text, p_name text, p_tags text[], p_position_id uuid, p_source text, p_consent integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare v_id uuid; v_token text;
begin
  if p_email is null or p_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'invalid email'; end if;
  select id, token into v_id, v_token from public.hire_job_alerts where email_key = lower(btrim(p_email)) and unsubscribed_at is null;
  if v_id is null then
    insert into public.hire_job_alerts (email, name, tags, position_id, source, consent_version)
    values (btrim(p_email), left(p_name, 120), coalesce(p_tags, '{}'), p_position_id, p_source, coalesce(p_consent, 1))
    returning id, token into v_id, v_token;
    return jsonb_build_object('id', v_id, 'token', v_token, 'created', true);
  end if;
  update public.hire_job_alerts
     set tags = (select array_agg(distinct t) from unnest(tags || coalesce(p_tags, '{}')) t),
         name = coalesce(nullif(left(p_name, 120), ''), name),
         position_id = coalesce(p_position_id, position_id)
   where id = v_id;
  return jsonb_build_object('id', v_id, 'token', v_token, 'created', false);
end;
$_$;


--
-- Name: is_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_admin() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1 from public.profiles
    where id = auth.uid()
      and role in ('admin', 'exec')
      and is_active = true
  );
$$;


--
-- Name: is_comp_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_comp_admin() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select auth.uid() is not null and auth.uid() = (
    select id from public.profiles where lower(email) = public.org_owner_email()
  );
$$;


--
-- Name: is_exec_reconciler(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_exec_reconciler() RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select public.is_admin() or exists (
    select 1
      from public.reviewer_group_members m
      join public.reviewer_groups g on g.id = m.group_id
     where g.key = 'exec_reconcilers' and m.user_id = auth.uid()
  )
$$;


--
-- Name: is_in_leadership_chain(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_in_leadership_chain(viewer uuid, subject uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with recursive up as (
    select p.manager_id, 1 as depth
    from public.profiles p
    where p.id = subject
    union all
    select p.manager_id, up.depth + 1
    from up
    join public.profiles p on p.id = up.manager_id
    where up.manager_id is not null and up.depth < 12
  )
  select viewer is not null
     and exists (select 1 from up where up.manager_id = viewer);
$$;


--
-- Name: is_internal_staff(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_internal_staff(p_uid uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1 from public.profiles p
     where p.id = p_uid
       and p.is_active
       and p.role in ('exec', 'admin', 'manager', 'contributor')
       and lower(split_part(p.email, '@', 2)) = any (public.org_email_domains())
  )
$$;


