--

CREATE FUNCTION public.log_checkin_comment_edit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.body is distinct from old.body then
    insert into public.comment_edit_history (comment_id, previous_body, edited_by)
    values (old.id, old.body, auth.uid());
    new.edited_at := now();
  end if;
