--
-- Name: log_metric_revision(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_metric_revision() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if old.value is distinct from new.value or old.goal is distinct from new.goal then
    insert into public.metric_revisions
      (metric_id, old_value, old_goal, old_source, old_meta, old_computed_at,
       new_value, new_goal, changed_by, reason_code)
    values
      (old.id, old.value, old.goal, old.source, old.meta, old.computed_at,
       new.value, new.goal, auth.uid(), 'upsert_overwrite');
  end if;
  return new;
end;
$$;


--
-- Name: log_profile_four_r_revision(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_profile_four_r_revision() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_changed text[] := '{}';
  v_note    text := new.pending_note;
begin
  if tg_op = 'UPDATE' then
    if new.position_label      is distinct from old.position_label      then v_changed := array_append(v_changed, 'position_label'); end if;
    if new.department          is distinct from old.department          then v_changed := array_append(v_changed, 'department'); end if;
    if new.reports_to          is distinct from old.reports_to          then v_changed := array_append(v_changed, 'reports_to'); end if;
    if new.role_md             is distinct from old.role_md             then v_changed := array_append(v_changed, 'role'); end if;
    if new.responsibilities_md is distinct from old.responsibilities_md then v_changed := array_append(v_changed, 'responsibilities'); end if;
    if new.results_md          is distinct from old.results_md          then v_changed := array_append(v_changed, 'results'); end if;
    if new.requirements_md     is distinct from old.requirements_md     then v_changed := array_append(v_changed, 'requirements'); end if;
    -- A save that changed nothing is not a revision.
    if coalesce(array_length(v_changed, 1), 0) = 0 then
      new.pending_note := null;
      new.revision := old.revision;
      return new;
    end if;
    new.revision := old.revision + 1;
  else
    v_changed := array['position_label','department','reports_to','role','responsibilities','results','requirements'];
    new.revision := 1;
  end if;

  new.pending_note := null;
  -- Attribution: the app sets updated_by explicitly; an edit from the SQL
  -- editor or MCP does not, and would otherwise inherit the previous
  -- editor. When the row's updated_by was not changed by this statement,
  -- the current session user is the editor.
  if tg_op = 'UPDATE' and auth.uid() is not null
     and new.updated_by is not distinct from old.updated_by then
    new.updated_by := auth.uid();
  end if;
  if new.updated_by is null then new.updated_by := auth.uid(); end if;
  if tg_op = 'INSERT' and new.created_by is null then new.created_by := auth.uid(); end if;

  insert into public.profile_four_r_revisions
    (user_id, revision, snapshot, changed_fields, change_note, changed_by)
  values (
    new.user_id,
    new.revision,
    jsonb_build_object(
      'position_label',      new.position_label,
      'department',          new.department,
      'reports_to',          new.reports_to,
      'role_md',             new.role_md,
      'responsibilities_md', new.responsibilities_md,
      'results_md',          new.results_md,
      'requirements_md',     new.requirements_md,
      'template_slug',       new.template_slug,
      'source',              new.source
    ),
    v_changed,
    nullif(btrim(coalesce(v_note, '')), ''),
    coalesce(new.updated_by, auth.uid())
  );
  return new;
end;
$$;


--
-- Name: log_project_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_project_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'DELETE' then
    insert into public.work_item_events
      (entity_kind, entity_id, entity_label, event_type, from_value, actor_id)
    values
      ('project', old.id, old.name, 'deleted', old.status, auth.uid());
    return old;
  elsif tg_op = 'INSERT' then
    insert into public.work_item_events
      (project_id, entity_kind, entity_id, entity_label, event_type, to_value, actor_id)
    values
      (new.id, 'project', new.id, new.name, 'created', new.status, auth.uid());
  elsif tg_op = 'UPDATE' then
    if new.status is distinct from old.status then
      insert into public.work_item_events
        (project_id, entity_kind, entity_id, entity_label, event_type, from_value, to_value, actor_id)
      values
        (new.id, 'project', new.id, new.name, 'status_change', old.status, new.status, auth.uid());
    end if;
    if new.owner_id is distinct from old.owner_id then
      insert into public.work_item_events
        (project_id, entity_kind, entity_id, entity_label, event_type, from_value, to_value, actor_id)
      values
        (new.id, 'project', new.id, new.name, 'assignee_change', old.owner_id::text, new.owner_id::text, auth.uid());
    end if;
    if new.kind is distinct from old.kind then
      insert into public.work_item_events
        (project_id, entity_kind, entity_id, entity_label, event_type, from_value, to_value, actor_id)
      values
        (new.id, 'project', new.id, new.name, 'kind_change', old.kind, new.kind, auth.uid());
    end if;
    if new.parent_id is distinct from old.parent_id then
      insert into public.work_item_events
        (project_id, entity_kind, entity_id, entity_label, event_type, from_value, to_value, actor_id)
      values
        (new.id, 'project', new.id, new.name, 'parent_change', old.parent_id::text, new.parent_id::text, auth.uid());
    end if;
    if new.archived is distinct from old.archived then
      insert into public.work_item_events
        (project_id, entity_kind, entity_id, entity_label, event_type, from_value, to_value, actor_id)
      values
        (new.id, 'project', new.id, new.name, case when new.archived then 'archived' else 'restored' end, null, null, auth.uid());
    end if;
  end if;
  return new;
end;
$$;


