--
-- Name: mcp_bind_consumer_identity(text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_bind_consumer_identity(p_slug text, p_identity_slug text, p_owner_profile_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'spine', 'pg_temp'
    AS $$
declare v_n int;
begin
  if auth.uid() is not null and not public.is_admin() then
    raise exception 'Only an admin or exec can bind an MCP consumer to an identity' using errcode = '42501';
  end if;
  update public.mcp_consumers
     set identity_slug = p_identity_slug, owner_profile_id = p_owner_profile_id
   where slug = p_slug and revoked_at is null;
  get diagnostics v_n = row_count;
  return v_n > 0;
end
$$;


--
-- Name: mcp_describe_table(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_describe_table(p_schema text, p_table text, OUT col_name text, OUT col_type text, OUT col_nullable text) RETURNS SETOF record
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select c.column_name::text, c.data_type::text, c.is_nullable::text
  from information_schema.columns c
  where c.table_schema = p_schema
    and c.table_name  = p_table
    and (p_schema || '.' || p_table) <> all (array[
      'public.ghl_connections', 'public.google_calendar_connections',
      'public.ghl_oauth_states', 'public.integrations', 'public.mcp_consumers',
      'public.profile_sensitive', 'public.payroll_runs',
      'public.comp_reconciliation', 'public.metric_revisions',
      'public.project_rate_overrides', 'comms.connections'
    ])
  order by c.ordinal_position
$$;


--
-- Name: mcp_identity_registry(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_identity_registry() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'spine', 'pg_temp'
    AS $$
  select coalesce(jsonb_agg(row_json order by i.slug), '[]'::jsonb)
  from spine.agent_identities i
  cross join lateral (
    select jsonb_build_object(
      'slug', i.slug,
      'tier', i.tier,
      'pg_role', i.pg_role,
      'workflow', i.workflow,
      'justification', i.justification,
      'enabled', i.enabled,
      'created_at', i.created_at,
      'disabled_at', i.disabled_at,
      'allowed_scopes', to_jsonb(i.allowed_scopes),
      'owner', (select jsonb_build_object('id', p.id, 'email', p.email,
                       'name', nullif(trim(concat_ws(' ', p.first_name, p.last_name)), ''))
                  from public.profiles p where p.id = i.owner_user_id),
      'display_name', i.chat_profile->>'display_name',
      'consumers', (
        select coalesce(jsonb_agg(jsonb_build_object(
                 'slug', c.slug, 'name', c.name, 'scopes', to_jsonb(c.scopes),
                 'created_at', c.created_at, 'last_used_at', c.last_used_at, 'revoked_at', c.revoked_at)
                 order by c.revoked_at nulls first, c.created_at desc), '[]'::jsonb)
          from public.mcp_consumers c where c.identity_slug = i.slug),
      'table_grants', (
        select coalesce(jsonb_agg(distinct g.table_schema || '.' || g.table_name), '[]'::jsonb)
          from information_schema.role_table_grants g where g.grantee = i.pg_role),
      'last_audit_at', (select max(a.occurred_at) from spine.agent_audit a where a.act = i.slug),
      'audit_rows_30d', (select count(*) from spine.agent_audit a where a.act = i.slug and a.occurred_at > now() - interval '30 days')
    ) as row_json
  ) j
$$;


--
-- Name: mcp_identity_registry_guarded(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_identity_registry_guarded() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'spine', 'pg_temp'
    AS $$
begin
  if auth.uid() is not null and not public.is_admin() then
    raise exception 'Only an admin or exec can read the identity registry' using errcode = '42501';
  end if;
  return public.mcp_identity_registry();
end
$$;


--
-- Name: mcp_mint_consumer(text, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_mint_consumer(p_slug text, p_name text, p_scopes text[]) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_token text;
  v_hash  text;
begin
  if auth.uid() is not null and not public.is_admin() then
    raise exception 'Only an admin or exec can mint an MCP consumer' using errcode = '42501';
  end if;
  -- 32 random bytes, base64url (no padding): 43 chars, safe in a header.
  v_token := translate(rtrim(encode(gen_random_bytes(32), 'base64'), '='), '+/', '-_');
  v_hash  := encode(digest(v_token, 'sha256'), 'hex');
  insert into public.mcp_consumers (slug, name, token_hash, scopes, created_by)
  values (p_slug, p_name, v_hash, p_scopes, auth.uid());
  return v_token;
end
$$;


--
-- Name: mcp_provision_consumer(text, text, text, text[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_provision_consumer(p_identity_slug text, p_consumer_slug text, p_name text, p_scopes text[], p_replace boolean DEFAULT false) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'spine', 'extensions', 'pg_temp'
    AS $$
declare
  v_id      spine.agent_identities%rowtype;
  v_over    text[];
  v_token   text;
  v_bound   boolean;
  v_replaced boolean := false;
begin
  if auth.uid() is not null and not public.is_admin() then
    raise exception 'Only an admin or exec can provision an MCP consumer' using errcode = '42501';
  end if;
  select * into v_id from spine.agent_identities where slug = p_identity_slug;
  if v_id.slug is null then
    raise exception 'spine: unknown identity %', p_identity_slug using errcode = '23503';
  end if;
  if not v_id.enabled then
    raise exception 'spine: identity % is disabled; provision_identity re-enables it', p_identity_slug using errcode = '42501';
  end if;
  if v_id.owner_user_id is null then
    raise exception 'spine: identity % has no owner (sub); set one before minting', p_identity_slug using errcode = '23503';
  end if;
  select coalesce(array_agg(s), '{}') into v_over
    from unnest(p_scopes) s where not (s = any (v_id.allowed_scopes));
  if coalesce(array_length(v_over, 1), 0) > 0 then
    raise exception 'SPINE_SCOPE_CEILING: % exceeds identity % ceiling %', v_over, p_identity_slug, v_id.allowed_scopes using errcode = '42501';
  end if;

  if exists (select 1 from public.mcp_consumers where slug = p_consumer_slug and revoked_at is null) then
    if not p_replace then
      raise exception 'mcp: consumer % is live; pass p_replace => true to rotate it', p_consumer_slug using errcode = '23505';
    end if;
    perform public.mcp_revoke_consumer(p_consumer_slug);
    v_replaced := true;
  end if;
  -- The unique constraint on slug means a rotated consumer needs a new slug
  -- or the old row renamed. Rename the revoked row: history keeps the audit
  -- rows' entity_ref (they name the slug) readable and the live slug stable.
  update public.mcp_consumers
     set slug = p_consumer_slug || '-revoked-' || to_char(revoked_at, 'YYYYMMDDHH24MISS')
   where slug = p_consumer_slug and revoked_at is not null;

  v_token := public.mcp_mint_consumer(p_consumer_slug, p_name, p_scopes);
  v_bound := public.mcp_bind_consumer_identity(p_consumer_slug, p_identity_slug, v_id.owner_user_id);
  if not v_bound then
    raise exception 'mcp: bind failed for %', p_consumer_slug;
  end if;

  insert into public.audit_log (actor_id, entity_kind, entity_ref, action, diff, status)
  values (auth.uid(), 'mcp', 'mcp_consumers/' || p_consumer_slug,
          case when v_replaced then 'mcp.consumer.rotated' else 'mcp.consumer.provisioned' end,
          jsonb_build_object('identity', p_identity_slug, 'scopes', p_scopes), 'ok');
  return v_token;
end
$$;


--
-- Name: mcp_read_table(text, text, integer, integer, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_read_table(p_schema text, p_table text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0, p_order text DEFAULT NULL::text, p_desc boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_allowed constant text[] := array[
    'comms.conversations', 'comms.conversation_participants',
    'comms.conversation_links', 'comms.conversation_events',
    'comms.messages', 'comms.profile_identities', 'comms.connection_grants',
    'spine.agent_identities', 'spine.agent_audit', 'spine.action_types',
    'spine.event_routes', 'spine.events', 'spine.proposed_actions',
    'spine.tenants'
  ];
  v_ref   text := p_schema || '.' || p_table;
  v_order text := '';
  v_rows  jsonb;
begin
  if not (v_ref = any (v_allowed)) then
    raise exception 'Table % is not readable through mcp_read_table', v_ref
      using errcode = '42501';
  end if;

  -- Ordering column must exist on that table, or we fall back to unordered.
  -- %I on an unchecked string would otherwise be an injection point.
  if p_order is not null and exists (
    select 1 from information_schema.columns
    where table_schema = p_schema and table_name = p_table and column_name = p_order
  ) then
    v_order := format(' order by %I %s', p_order, case when p_desc then 'desc' else 'asc' end);
  end if;

  execute format(
    'select coalesce(jsonb_agg(to_jsonb(t)), ''[]''::jsonb) from (select * from %I.%I%s limit %s offset %s) t',
    p_schema, p_table, v_order, greatest(1, least(p_limit, 200)), greatest(0, p_offset)
  ) into v_rows;

  return v_rows;
end
$$;


--
-- Name: mcp_revoke_consumer(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_revoke_consumer(p_slug text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_n int;
begin
  if auth.uid() is not null and not public.is_admin() then
    raise exception 'Only an admin or exec can revoke an MCP consumer' using errcode = '42501';
  end if;
  update public.mcp_consumers set revoked_at = now()
   where slug = p_slug and revoked_at is null;
  get diagnostics v_n = row_count;
  return v_n > 0;
end
$$;


--
-- Name: mcp_scopes_ok(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_scopes_ok(s text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  select coalesce(array_length(s, 1), 0) <= 16
     and not exists (
       select 1 from unnest(s) e
       where e is null
          or e not in (
            'clients:read', 'sessions:read', 'team:read', 'work:read',
            'spine:transcripts:read',
            'calendar:read',
            'content:run',
            'content:propose',
            'data:read',
            'spine:identities:read',
            'acquisitions:read', 'acquisitions:propose',
            'finance:read',
            'contracts:read'
          )
     )
$$;


--
-- Name: mcp_unbound_consumers(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_unbound_consumers() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if auth.uid() is not null and not public.is_admin() then
    raise exception 'Only an admin or exec can read MCP consumers' using errcode = '42501';
  end if;
  return (
    select coalesce(jsonb_agg(jsonb_build_object(
             'slug', c.slug, 'name', c.name, 'scopes', to_jsonb(c.scopes),
             'created_at', c.created_at, 'last_used_at', c.last_used_at) order by c.created_at desc), '[]'::jsonb)
      from public.mcp_consumers c where c.identity_slug is null and c.revoked_at is null);
end
$$;


--
-- Name: meeting_classify(text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.meeting_classify(p_title text, p_summary text, p_has_external boolean) RETURNS TABLE(call_type text, reason text)
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  t text := coalesce(public.meeting_norm(p_title), '');
  s text := lower(coalesce(p_summary, ''));
begin
  -- A summary that says it was a sales/discovery call (and never calls it
  -- internal or a client call) wins over the title: the summary describes what
  -- happened, a calendar title can be stale or a mis-link.
  if s ~ '(sales (consult|consultation|call|discovery|meeting)|discovery (call|meeting|session)|sales and discovery|(introductory|initial) consultation|consultation call|prospective client|with (a|the) prospect\M)'
     and s !~ '(internal|rather than a sales|not a sales|team meeting|existing client|account review|check-in|kick-off|kickoff|bi-weekly|onboarding)' then
    return query select 'sales_consult', 'summary: sales / discovery call'; return;
  end if;

  if t <> '' then
    -- Internal sales practice and booking blocks first: they carry sales words
    -- but nobody outside Open Ronin is on them.
    if t ~ '(slots open|call block|role ?play|sales training|sales op|sales daily|review sales)' then
      return query select 'internal_project', 'title: internal sales practice / block'; return;
    end if;
    if p_has_external and t ~ '\m(discovery|consultation|consult|strategy session|intro call|sales call|initial call|demo)\M' then
      return query select 'sales_consult', 'title: discovery/consult with an external attendee'; return;
    end if;
    if t ~ '\m(interview|interviews|hiring|candidate)\M' and t !~ '\mpodcast\M' then
      return query select 'hiring', 'title: hiring'; return;
    end if;
    if t ~ '\m(onboarding|kick ?off)\M' then
      return query select 'onboarding', 'title: onboarding / kick-off'; return;
    end if;
    if t ~ '\mmedia training\M' then
      return query select 'media_training', 'title: media training'; return;
    end if;
    if t ~ '\m(standup|stand up|huddle|daily)\M' then
      return query select 'internal_standup', 'title: daily / standup'; return;
    end if;
    if t ~ 'personal meeting room' then
      return query select 'personal_room', 'title: personal meeting room'; return;
    end if;
    if not coalesce(p_has_external, false) then
      return query select 'internal_project', 'title + internal attendees only'; return;
    end if;
    if t ~ '\m(check ?in|bi ?weekly|weekly|monthly|monthlies|sync|recap|pr call|status)\M' then
      return query select 'client_recurring', 'title: recurring check-in with an external attendee'; return;
    end if;
  end if;

  if s <> '' then
    if s ~ '(transcript (is|was|appears) (essentially |extremely |very )?(empty|incomplete|too short)|no (meaningful|substantive|actual) (conversation|dialogue|discussion|meeting)|summary unavailable|consists only of)' then
      return query select 'untyped', 'summary: no usable content'; return;
    end if;
    if s ~ '(huddle|daily standup|standup meeting|stand-up)' then
      return query select 'internal_standup', 'summary: standup / huddle'; return;
    end if;
    if s ~ '(kick-off|kickoff|onboarding call)' then
      return query select 'onboarding', 'summary: kick-off / onboarding'; return;
    end if;
    if s ~ '(job interview|candidate|hiring interview)' then
      return query select 'hiring', 'summary: hiring'; return;
    end if;
    if s ~ '(internal|team (meeting|sync|standup|check-in)|coaching session|training session|book club|alignment)' then
      return query select 'internal_project', 'summary: internal meeting'; return;
    end if;
    if s ~ '(bi-weekly|biweekly|monthly|weekly|recurring)' and s ~ 'client' then
      return query select 'client_recurring', 'summary: recurring client call'; return;
    end if;
    if s ~ '(client|check-in|account review)' then
      return query select 'client_followup', 'summary: client call'; return;
    end if;
  end if;

  return query select 'untyped', 'no rule matched';
end;
$$;




--
-- Name: meeting_extract_transcript_to_talk(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.meeting_extract_transcript_to_talk(p_call_id uuid, p_speaker uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_name   text;
  v_series uuid;
  v_n      int := 0;
begin
  select coalesce(first_name, '') || ' ' || coalesce(last_name, '') into v_name from public.profiles where id = p_speaker;
  if v_name is null or btrim(v_name) = '' then
    return 0;
  end if;
  select series_id into v_series from public.calls where id = p_call_id;

  with lines as (
    select row_number() over () as pos, btrim(m[1]) as line
    from public.call_transcripts t,
         regexp_matches(t.content, '(?:^|\n)' || regexp_replace(btrim(v_name), '([.^$*+?()\[\]{}|\\])', '\\\1', 'g') || ':\s*([^\r\n]+)', 'g') as m
    where t.call_id = p_call_id
  ), hits as (
    select pos, left(line, 500) as line from lines
    where line ~* '(next time|(on|in|for|at) (the|our) next (call|meeting|sync|session|one|1:1)|remind me (to|about)|i (want|need|wanna) to (talk|discuss|cover|raise|bring up|go over)|let''s (talk|discuss|cover|revisit|circle back)|we (need|should|have) to (talk|discuss) about|(put|add) (it|that|this) (on|to) the agenda|circle back (on|to)|bring (this|that|it) up (with|on|at|next|again))'
      and length(line) >= 25
  ), ins as (
    insert into public.meeting_items (call_id, series_id, kind, body, owner_user_id, owner_name, owner_source, source, position)
    select p_call_id, v_series, 'to_talk', line, p_speaker, btrim(v_name), 'speaker', 'transcript', pos::int from hits
    on conflict (call_id, kind, body_hash) do nothing
    returning 1
  )
  select count(*) into v_n from ins;
  return v_n;
end;
$_$;




--
-- Name: meeting_ingest_altercall(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.meeting_ingest_altercall(p_email_id uuid, p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_email        public.meeting_source_emails%rowtype;
  v_mailbox_user uuid;
  v_host         uuid;
  v_title        text := nullif(btrim(p->>'title'), '');
  v_recorded     timestamptz := (p->>'recordedAt')::timestamptz;
  v_ref          text;
  v_names        text[];
  v_people       uuid[] := '{}';
  v_unmatched    text[] := '{}';
  v_event        public.calendar_events%rowtype;
  v_call_id      uuid;
  v_existing     uuid;
  v_link         jsonb;
  v_items        int := 0;
  v_name         text;
  v_pid          uuid;
  it             jsonb;
  v_pos          int := 0;
  v_owner        uuid;
  v_owner_src    text;
  v_series       uuid;
begin
  select * into v_email from public.meeting_source_emails where id = p_email_id;
  if not found then
    raise exception 'meeting_ingest_altercall: email % not found', p_email_id;
  end if;
  if v_title is null then
    raise exception 'meeting_ingest_altercall: no title';
  end if;

  select id into v_mailbox_user from public.profiles where lower(email) = lower(v_email.mailbox);
  v_host := coalesce(public.meeting_profile_id_for_name(p->>'hostName'), v_mailbox_user);

  -- People on the call: host, the mailbox owner (AlterCall only mails people
  -- who were on the session), every participant name we can match.
  v_names := array(select jsonb_array_elements_text(coalesce(p->'participantKeys', '[]'::jsonb)));
  foreach v_name in array v_names loop
    v_pid := public.meeting_profile_id_for_name(v_name);
    if v_pid is null then
      v_unmatched := v_unmatched || replace(v_name, '_', ' ');
    else
      v_people := v_people || v_pid;
    end if;
  end loop;
  v_people := array(select distinct u from unnest(v_people || v_host || v_mailbox_user) u where u is not null);

  -- The calendar event: the host's (else the mailbox owner's) event with this
  -- title that was running when AlterCall finished the session.
  if v_recorded is not null then
    select e.* into v_event
    from public.calendar_events e
    where e.user_id in (v_host, v_mailbox_user)
      and e.source = 'google'
      and e.status is distinct from 'cancelled'
      and not e.all_day
      and e.starts_at between v_recorded - interval '4 hours' and v_recorded + interval '10 minutes'
      and coalesce(e.ends_at, e.starts_at + interval '1 hour') >= v_recorded - interval '3 hours'
      and public.meeting_title_similarity(v_title, e.title) >= 0.5
    order by public.meeting_title_similarity(v_title, e.title) desc,
             (e.user_id = v_mailbox_user) desc,
             abs(extract(epoch from (coalesce(e.ends_at, e.starts_at) - v_recorded))),
             (e.recurring_event_id is not null) desc,
             e.id
    limit 1;
  end if;

  v_ref := case when nullif(p->>'zoomUuid', '') is not null then 'zoom:' || (p->>'zoomUuid')
                else 'altercall:' || coalesce(nullif(p->>'sessionKey', ''), v_email.message_id) end;

  select id into v_existing from public.calls where external_call_id = v_ref;
  if v_existing is null then
    insert into public.calls (external_call_id, call_type, occurred_at, duration_minutes, attendee_user_ids, attendee_external,
                              title, source, external_ref, host_user_id, calendar_event_id)
    values (
      v_ref, 'untyped',
      coalesce(v_event.starts_at, v_recorded, v_email.received_at),
      case when v_event.id is not null and v_recorded is not null
           then greatest(1, least(600, round(extract(epoch from (v_recorded - v_event.starts_at)) / 60)))::int end,
      array(select distinct u from unnest(v_people || coalesce(v_event.attendee_user_ids, '{}')) u),
      array(select distinct e from unnest(coalesce(v_event.attendee_external, '{}')) e
            where not public.is_org_email(e)),
      v_title, 'altercall', p->>'sessionKey', v_host, v_event.id
    )
    returning id into v_call_id;
  else
    -- Zoom already sent this meeting through n8n: enrich, never replace.
    update public.calls
    set title = coalesce(title, v_title),
        external_ref = coalesce(external_ref, p->>'sessionKey'),
        host_user_id = coalesce(host_user_id, v_host),
        calendar_event_id = coalesce(calendar_event_id, v_event.id),
        attendee_user_ids = array(select distinct u from unnest(attendee_user_ids || v_people || coalesce(v_event.attendee_user_ids, '{}')) u)
    where id = v_existing;
    v_call_id := v_existing;
  end if;

  v_link := public.meeting_link_call(v_call_id);
  v_series := nullif(v_link->>'series_id', '')::uuid;

  for it in select * from jsonb_array_elements(coalesce(p->'items', '[]'::jsonb)) loop
    v_pos := v_pos + 1;
    v_owner := null;
    v_owner_src := 'none';
    if nullif(it->>'ownerName', '') is not null then
      v_owner := public.meeting_profile_id_for_name(it->>'ownerName');
      if v_owner is null then
        -- "Alex to …": a first name; resolve among the people on this call.
        select u into v_owner from unnest(v_people) u
        join public.profiles pr on pr.id = u
        where public.meeting_norm(pr.first_name) = public.meeting_norm(it->>'ownerName')
        limit 1;
      end if;
      v_owner_src := 'explicit';
    elsif (p->>'role') = 'host' then
      -- AlterCall files a host session's actions on the host's own list.
      v_owner := v_host;
      v_owner_src := 'host_default';
    end if;
    insert into public.meeting_items (call_id, series_id, kind, body, owner_user_id, owner_name, owner_source, source, source_email_id, position)
    values (v_call_id, v_series, public.meeting_item_kind(it->>'text'), left(btrim(it->>'text'), 2000), v_owner,
            nullif(it->>'ownerName', ''), v_owner_src, 'altercall', p_email_id, v_pos)
    on conflict (call_id, kind, body_hash) do nothing;
    if found then
      v_items := v_items + 1;
    end if;
  end loop;

  update public.meeting_source_emails
  set call_id = v_call_id, parse_status = 'parsed', parse_error = null, kind = 'session',
      parsed = p || jsonb_build_object('unmatchedParticipants', to_jsonb(v_unmatched))
  where id = p_email_id;

  return v_link || jsonb_build_object('items_written', v_items, 'unmatched_participants', to_jsonb(v_unmatched),
                                      'created', v_existing is null);
end;
$_$;




--
-- Name: meeting_item_kind(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.meeting_item_kind(p_text text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  select case
    when p_text ~* '^\s*(discuss|bring up|raise|revisit|talk (to|with|about|through)|ask|check (in )?with|follow up (with|on)|circle back|sync with|align with|confirm with|touch base|get (an )?update|update [a-z ]{1,30} on|mention|remind)\M'
      or p_text ~* '\m(next (meeting|call|session|sync|1:1|one-on-one|time)|at the next|on the next|in the next (meeting|call))\M'
      then 'to_talk'
    when p_text ~ '\?\s*$' then 'question'
    else 'action'
  end
$_$;




--
-- Name: meeting_link_call(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.meeting_link_call(p_call_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  c            public.calls%rowtype;
  v_speakers   uuid[] := '{}';
  v_event      public.calendar_events%rowtype;
  v_has_ext    boolean;
  v_summary    text;
  v_type       text;
  v_reason     text;
  v_series     uuid;
  v_owner      uuid;
  v_owner     uuid;
  v_to_talk    int := 0;
begin
  select * into c from public.calls where id = p_call_id;
  if not found then
    return jsonb_build_object('error', 'call not found');
  end if;

  -- (a) attendees from transcript speaker labels ("Jamie Rivera: …").
  -- STRICT matching only (first + last name): attendee_user_ids feeds
  -- can_view_call(), so a bare first name ("Chloe" the client) must never
  -- resolve to the one staff Chloe and hand her the transcript. The bare
  -- first-name rule stays available for the email parser's owner phrases.
  select coalesce(array_agg(distinct pid) filter (where pid is not null), '{}') into v_speakers
  from (
    select public.meeting_profile_id_for_name(sp, true) as pid
    from (
      select distinct btrim(m[1]) as sp
      from public.call_transcripts t,
           regexp_matches(t.content, '(?:^|\n)([^\r\n:]{2,60}):\s', 'g') as m
      where t.call_id = c.id
    ) s
    where sp !~ '^\d' and sp !~* '-->'
  ) x;
  if cardinality(v_speakers) > 0 then
    update public.calls set attendee_user_ids = array(
      select distinct u from unnest(attendee_user_ids || v_speakers) u)
    where id = c.id
    returning * into c;
  end if;

  -- (b) the calendar event: an event that brackets the start, with the most
  -- attendees in common (and the call host's own copy first).
  if c.calendar_event_id is null and cardinality(c.attendee_user_ids) > 0 then
    select e.* into v_event
    from public.calendar_events e
    where e.source = 'google'
      and e.status is distinct from 'cancelled'
      and not e.all_day
      and coalesce(e.location, '') !~* '^\s*no meeting'
      -- A Zoom recording starts within minutes of the scheduled start; a call
      -- with a title (AlterCall) is matched on that title over a wider window.
      and e.starts_at between c.occurred_at - case when c.title is null then interval '30 minutes' else interval '3 hours' end
                          and c.occurred_at + interval '20 minutes'
      and coalesce(e.ends_at, e.starts_at + interval '1 hour') >= c.occurred_at - interval '10 minutes'
      and (e.user_id = any (c.attendee_user_ids) or e.attendee_user_ids && c.attendee_user_ids)
      and (c.title is null or public.meeting_title_similarity(c.title, e.title) >= 0.5)
    order by
      (select count(*) from unnest(c.attendee_user_ids) u where u = any (e.attendee_user_ids || e.user_id)) desc,
      (c.title is not null and public.meeting_norm(c.title) = public.meeting_norm(e.title)) desc,
      (coalesce(e.location, '') ~* 'zoom' or coalesce(e.description_md, '') ~* 'zoom\.us') desc,
      abs(extract(epoch from (e.starts_at - c.occurred_at))),
      (e.user_id = c.host_user_id) desc,
      (e.recurring_event_id is not null) desc,
      e.id
    limit 1;
    -- Without a title to confirm it, two people in common is the bar: one shared
    -- person (the host) is in every meeting they have that day.
    if v_event.id is not null and c.title is null
       and (select count(*) from unnest(c.attendee_user_ids) u where u = any (v_event.attendee_user_ids || v_event.user_id)) < 2 then
      v_event := null;
    end if;
    if v_event.id is not null then
      update public.calls
      set calendar_event_id = v_event.id,
          title = coalesce(title, v_event.title),
          attendee_user_ids = array(select distinct u from unnest(attendee_user_ids || v_event.attendee_user_ids) u)
      where id = c.id
      returning * into c;
    end if;
  elsif c.calendar_event_id is not null then
    select * into v_event from public.calendar_events where id = c.calendar_event_id;
  end if;

  -- (c) series
  v_owner := coalesce(c.host_user_id, v_event.user_id);
  if c.series_id is null and (c.title is not null or v_event.recurring_event_id is not null) then
    v_series := public.meeting_series_ensure(coalesce(c.title, v_event.title), v_event.recurring_event_id, v_owner);
    update public.calls set series_id = v_series where id = c.id returning * into c;
  end if;

  -- (d) type (untyped only; a sender's type is never overridden)
  v_has_ext := exists (select 1 from unnest(c.attendee_external) e where not public.is_org_email(e))
            or exists (select 1 from unnest(coalesce(v_event.attendee_external, '{}')) e where not public.is_org_email(e));
  if c.call_type = 'untyped' then
    select a.summary_md into v_summary from public.call_analyses a where a.call_id = c.id order by a.created_at desc limit 1;
    select k.call_type, k.reason into v_type, v_reason
    from public.meeting_classify(coalesce(c.title, v_event.title), coalesce(v_summary, c.summary_md), v_has_ext) k;
    update public.calls
    set call_type = v_type,
        -- 'rule' only when a rule produced a real type, so a later sender type
        -- over a still-untyped row keeps 'sender' provenance (see the trigger).
        call_type_source = case when v_type = 'untyped' then call_type_source else 'rule' end,
        call_type_reason = v_reason
    where id = c.id and call_type = 'untyped'
    returning * into c;
  end if;

  if c.series_id is not null then
    update public.meeting_series s
    set first_call_at = least(coalesce(s.first_call_at, c.occurred_at), c.occurred_at),
        last_call_at  = greatest(coalesce(s.last_call_at, c.occurred_at), c.occurred_at),
        call_type     = coalesce(s.call_type, nullif(c.call_type, 'untyped')),
        is_sales      = s.is_sales or c.call_type = 'sales_consult'
    where s.id = c.series_id;
    update public.meeting_items set series_id = c.series_id where call_id = c.id and series_id is null;
  end if;

  -- (e) Alex's to-talk lines on the transcript
  select id into v_owner from public.profiles where lower(email) = public.org_owner_email();
  if v_owner is not null and v_owner = any (c.attendee_user_ids) then
    v_to_talk := public.meeting_extract_transcript_to_talk(c.id, v_owner);
  end if;

  return jsonb_build_object(
    'call_id', c.id, 'calendar_event_id', c.calendar_event_id, 'series_id', c.series_id,
    'call_type', c.call_type, 'call_type_source', c.call_type_source, 'attendees', cardinality(c.attendee_user_ids),
    'to_talk_from_transcript', v_to_talk
  );
end;
$_$;




--
-- Name: meeting_norm(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.meeting_norm(p text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select nullif(btrim(regexp_replace(lower(extensions.unaccent(coalesce(p, ''))), '[^a-z0-9]+', ' ', 'g')), '')
$$;




--
-- Name: meeting_prep(text, uuid, timestamp with time zone, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.meeting_prep(p_event_ref text DEFAULT NULL::text, p_series_id uuid DEFAULT NULL::uuid, p_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_user_email text DEFAULT NULL::text, p_to_talk_days integer DEFAULT 60) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_user     uuid;
  v_event    public.calendar_events%rowtype;
  v_series   public.meeting_series%rowtype;
  v_title    text;
  v_at       timestamptz;
  v_prev     public.calls%rowtype;
  v_basis    text;
  v_has_ext  boolean;
  v_type     text;
  v_summary  text;
  v_sales    boolean;
begin
  select id into v_user from public.profiles where lower(email) = lower(coalesce(p_user_email, public.org_owner_email()));

  if p_event_ref is not null then
    select e.* into v_event
    from public.calendar_events e
    where (e.id::text = p_event_ref or e.external_id = p_event_ref)
    order by (e.user_id = v_user) desc, e.updated_at desc
    limit 1;
    if v_event.id is null then
      return jsonb_build_object('error', 'event_not_found', 'event_ref', p_event_ref);
    end if;
    v_title := v_event.title;
    v_at := v_event.starts_at;
    if v_event.recurring_event_id is not null then
      select * into v_series from public.meeting_series where gcal_recurring_event_id = v_event.recurring_event_id limit 1;
    end if;
    if v_series.id is null then
      select * into v_series from public.meeting_series
      where norm_title = public.meeting_norm(v_event.title)
      order by (owner_user_id = coalesce(v_event.user_id, v_user)) desc, last_call_at desc nulls last
      limit 1;
    end if;
  elsif p_series_id is not null then
    select * into v_series from public.meeting_series where id = p_series_id;
    if v_series.id is null then
      return jsonb_build_object('error', 'series_not_found', 'series_id', p_series_id);
    end if;
    v_title := v_series.title;
    v_at := coalesce(p_at, now());
  else
    return jsonb_build_object('error', 'pass event_ref or series_id');
  end if;

  -- Previous meeting: latest call in the series before this one; else the
  -- latest call with the same title the user was on.
  if v_series.id is not null then
    select * into v_prev from public.calls
    where series_id = v_series.id and occurred_at < v_at - interval '5 minutes'
    order by occurred_at desc limit 1;
    v_basis := case when v_prev.id is not null then 'series' end;
  end if;
  if v_prev.id is null and public.meeting_norm(v_title) is not null then
    select * into v_prev from public.calls
    where public.meeting_norm(title) = public.meeting_norm(v_title)
      and occurred_at < v_at - interval '5 minutes'
      and (v_user is null or v_user = any (attendee_user_ids) or host_user_id = v_user)
    order by occurred_at desc limit 1;
    v_basis := case when v_prev.id is not null then 'title' end;
  end if;

  v_has_ext := exists (select 1 from unnest(coalesce(v_event.attendee_external, '{}')) e where not public.is_org_email(e));
  select k.call_type into v_type from public.meeting_classify(v_title, null, v_has_ext) k;
  v_sales := v_type = 'sales_consult' or coalesce(v_series.is_sales, false);

  if v_prev.id is not null then
    select a.summary_md into v_summary from public.call_analyses a where a.call_id = v_prev.id order by a.created_at desc limit 1;
  end if;

  return jsonb_build_object(
    'meeting', jsonb_build_object(
      'calendar_event_id', v_event.id,
      'google_event_id', v_event.external_id,
      'recurring_event_id', v_event.recurring_event_id,
      'title', v_title,
      'starts_at', v_at,
      'ends_at', v_event.ends_at,
      'attendees', coalesce((
        select jsonb_agg(jsonb_build_object('email', e,
          'user_id', (select pr.id from public.profiles pr where lower(pr.email) = lower(e) limit 1),
          'name', (select btrim(coalesce(pr.first_name, '') || ' ' || coalesce(pr.last_name, '')) from public.profiles pr where lower(pr.email) = lower(e) limit 1)))
        from unnest(coalesce(v_event.attendee_external, '{}')) e), '[]'::jsonb),
      'series_id', v_series.id,
      'series_title', v_series.title,
      'expected_call_type', v_type,
      'is_sales', v_sales,
      'skip_reason', case when v_sales then 'sales_call' end
    ),
    'previous', case when v_prev.id is null then null else jsonb_build_object(
      'call_id', v_prev.id,
      'title', v_prev.title,
      'occurred_at', v_prev.occurred_at,
      'source', v_prev.source,
      'call_type', v_prev.call_type,
      'link_basis', v_basis,
      'summary_md', coalesce(v_summary, v_prev.summary_md),
      'recording_url', v_prev.recording_url
    ) end,
    'action_items', coalesce((
      select jsonb_agg(x order by x->>'origin', (x->>'position')::int) from (
        select jsonb_build_object(
          'id', i.id, 'origin', 'meeting_item', 'kind', i.kind, 'text', i.body, 'status', i.status,
          'owner', case when i.owner_user_id is null and i.owner_name is null then null else jsonb_build_object(
            'user_id', i.owner_user_id,
            'name', coalesce((select btrim(coalesce(pr.first_name, '') || ' ' || coalesce(pr.last_name, '')) from public.profiles pr where pr.id = i.owner_user_id), i.owner_name),
            'email', (select pr.email from public.profiles pr where pr.id = i.owner_user_id)) end,
          'owner_source', i.owner_source, 'source', i.source, 'position', i.position) as x
        from public.meeting_items i
        where i.call_id = v_prev.id and i.kind in ('action', 'question') and i.status = 'open'
        union all
        select jsonb_build_object(
          'id', t.id, 'origin', 'suggested_task', 'kind', 'action', 'text', t.title, 'status', t.status,
          'owner', case when t.suggested_owner_email is null then null else jsonb_build_object(
            'user_id', (select pr.id from public.profiles pr where lower(pr.email) = lower(t.suggested_owner_email) limit 1),
            'name', (select btrim(coalesce(pr.first_name, '') || ' ' || coalesce(pr.last_name, '')) from public.profiles pr where lower(pr.email) = lower(t.suggested_owner_email) limit 1),
            'email', t.suggested_owner_email) end,
          'owner_source', case when t.suggested_owner_email is null then 'none' else 'explicit' end,
          'source', 'zoom_analysis', 'position', 0) as x
        from public.call_suggested_tasks t
        where t.call_id = v_prev.id and t.status in ('pending', 'accepted')
      ) q), '[]'::jsonb),
    'to_talk', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', i.id, 'text', i.body, 'source', i.source, 'status', i.status,
        'from_call_id', i.call_id, 'from_occurred_at', c.occurred_at, 'from_title', c.title)
        order by c.occurred_at desc, i.position)
      from public.meeting_items i
      join public.calls c on c.id = i.call_id
      where i.kind = 'to_talk' and i.status = 'open'
        and c.occurred_at < v_at - interval '5 minutes'
        and c.occurred_at >= v_at - make_interval(days => greatest(coalesce(p_to_talk_days, 60), 1))
        and (i.owner_user_id is null or i.owner_user_id = v_user)
        and ((v_series.id is not null and c.series_id = v_series.id) or c.id = v_prev.id)
      ), '[]'::jsonb),
    'generated_at', now()
  );
end;
$_$;




--
-- Name: meeting_prep_for_day(date, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.meeting_prep_for_day(p_date date, p_user_email text DEFAULT NULL::text, p_tz text DEFAULT 'America/Chicago'::text, p_include_sales boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user uuid;
  v_out  jsonb := '[]'::jsonb;
  v_prep jsonb;
  e      record;
begin
  select id into v_user from public.profiles where lower(email) = lower(p_user_email);
  if v_user is null then
    return jsonb_build_object('error', 'user_not_found', 'user_email', p_user_email);
  end if;
  for e in
    select distinct on (coalesce(ce.recurring_event_id, ce.external_id), ce.starts_at) ce.id
    from public.calendar_events ce
    where ce.user_id = v_user
      and ce.status is distinct from 'cancelled'
      and not ce.all_day
      and coalesce(ce.category_key, '') not in ('time_off', 'focus_block', 'travel')
      and cardinality(ce.attendee_external) >= 2
      and (ce.starts_at at time zone p_tz)::date = p_date
    order by coalesce(ce.recurring_event_id, ce.external_id), ce.starts_at, ce.updated_at desc
  loop
    v_prep := public.meeting_prep(e.id::text, null, null, p_user_email);
    if p_include_sales or not coalesce((v_prep->'meeting'->>'is_sales')::boolean, false) then
      v_out := v_out || jsonb_build_array(v_prep);
    end if;
  end loop;
  return jsonb_build_object(
    'date', p_date, 'tz', p_tz, 'user_email', p_user_email,
    'meetings', coalesce((select jsonb_agg(m order by m->'meeting'->>'starts_at') from jsonb_array_elements(v_out) m), '[]'::jsonb),
    'generated_at', now());
end;
$$;




--
-- Name: meeting_profile_id_for_name(text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.meeting_profile_id_for_name(p_name text, p_strict boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_raw    text := btrim(coalesce(p_name, ''));
  v_key    text;
  v_norm   text;
  v_tokens text[];
  v_ids    uuid[];
begin
  if v_raw = '' then
    return null;
  end if;

  -- AlterCall writes names with every non-alphanumeric character as one
  -- underscore ("Ana_Lima", "J_lia_Souza"). Compare in that alphabet first,
  -- before unaccenting throws the information away.
  v_key := lower(regexp_replace(v_raw, '[^A-Za-z0-9]', '_', 'g'));
  select array_agg(id) into v_ids
  from public.profiles
  where last_name is not null
    and lower(regexp_replace(coalesce(first_name, '') || ' ' || last_name, '[^A-Za-z0-9]', '_', 'g')) = v_key;
  if cardinality(v_ids) = 1 then
    return v_ids[1];
  end if;
  -- ...and with the underscore as LIKE's one-character wildcard, so the DB's
  -- "Julia Souza" still matches AlterCall's "J_lia_Souza" for "Júlia".
  if v_raw ~ '_' and v_raw !~ '[%\\]' then
    select array_agg(id) into v_ids
    from public.profiles
    where last_name is not null
      and lower(coalesce(first_name, '') || ' ' || last_name) like v_key;
    if cardinality(v_ids) = 1 then
      return v_ids[1];
    end if;
  end if;

  -- Display names: drop the brand / device noise Zoom adds ("Cal | Publicity
  -- For Good", "Jamie's iPhone") and compare normalised.
  v_norm := public.meeting_norm(v_raw);
  v_norm := btrim(regexp_replace(coalesce(v_norm, ''), '\m(audio shared by|s iphone|iphone|ipad|android)\M', ' ', 'g'));
  v_norm := nullif(regexp_replace(v_norm, '\s+', ' ', 'g'), '');
  if v_norm is null then
    return null;
  end if;
  v_tokens := string_to_array(v_norm, ' ');

  select array_agg(id) into v_ids
  from public.profiles
  where public.meeting_norm(coalesce(first_name, '') || ' ' || coalesce(last_name, '')) = v_norm
     or replace(public.meeting_norm(coalesce(first_name, '') || ' ' || coalesce(last_name, '')), ' ', '') = replace(v_norm, ' ', '');
  if cardinality(v_ids) = 1 then
    return v_ids[1];
  end if;

  -- Every first-name and last-name word present, any order: "Souza Julia",
  -- "Ana Maria Lima", "Pedro Alves Costa".
  select array_agg(id) into v_ids
  from public.profiles
  where public.meeting_norm(first_name) is not null
    and public.meeting_norm(last_name) is not null
    and string_to_array(public.meeting_norm(first_name), ' ') <@ v_tokens
    and string_to_array(public.meeting_norm(last_name), ' ') <@ v_tokens;
  if cardinality(v_ids) = 1 then
    return v_ids[1];
  elsif cardinality(v_ids) > 1 then
    select array_agg(id) into v_ids from public.profiles where id = any (v_ids) and is_active;
    if cardinality(v_ids) = 1 then
      return v_ids[1];
    end if;
  end if;

  -- Last name present + the first word is a short form of the first name:
  -- "Rob Lane" (Robert), "JM Lee" (John Michael).
  if cardinality(v_tokens) >= 2 then
    select array_agg(id) into v_ids
    from public.profiles
    where public.meeting_norm(last_name) is not null
      and string_to_array(public.meeting_norm(last_name), ' ') <@ v_tokens[2:]
      and public.meeting_norm(first_name) is not null
      and (
        public.meeting_norm(first_name) like v_tokens[1] || '%'
        or v_tokens[1] = (select string_agg(left(w, 1), '') from unnest(string_to_array(public.meeting_norm(first_name), ' ')) w)
      );
    if cardinality(v_ids) = 1 then
      return v_ids[1];
    end if;
  end if;

  -- A bare first name ("Julia") only when exactly one profile has it (active
  -- first; history includes people who have left). Never in strict mode: a
  -- transcript speaker label is not evidence that a staffer was on the call.
  if cardinality(v_tokens) = 1 and not p_strict then
    select array_agg(id) into v_ids
    from public.profiles
    where is_active and public.meeting_norm(first_name) = v_norm;
    if cardinality(v_ids) = 1 then
      return v_ids[1];
    end if;
    if coalesce(cardinality(v_ids), 0) = 0 then
      select array_agg(id) into v_ids
      from public.profiles
      where public.meeting_norm(first_name) = v_norm;
      if cardinality(v_ids) = 1 then
        return v_ids[1];
      end if;
    end if;
  end if;
  return null;
end;
$$;




--
-- Name: meeting_profile_ids_for_emails(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.meeting_profile_ids_for_emails(p_emails text[]) RETURNS uuid[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(array_agg(distinct p.id), '{}')
  from public.profiles p
  where lower(p.email) in (select lower(btrim(e)) from unnest(coalesce(p_emails, '{}')) e)
$$;




--
-- Name: meeting_series_ensure(text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.meeting_series_ensure(p_title text, p_recurring_event_id text, p_owner uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_norm text := public.meeting_norm(p_title);
  v_id   uuid;
begin
  if v_norm is null and p_recurring_event_id is null then
    return null;
  end if;
  if p_recurring_event_id is not null then
    select id into v_id from public.meeting_series where gcal_recurring_event_id = p_recurring_event_id limit 1;
    if v_id is not null then
      return v_id;
    end if;
  end if;
  if v_norm is not null then
    select id into v_id
    from public.meeting_series
    where norm_title = v_norm and owner_user_id is not distinct from p_owner
    order by (gcal_recurring_event_id is not null) desc, created_at
    limit 1;
    if v_id is not null then
      if p_recurring_event_id is not null then
        update public.meeting_series set gcal_recurring_event_id = p_recurring_event_id
        where id = v_id and gcal_recurring_event_id is null;
      end if;
      return v_id;
    end if;
  end if;
  insert into public.meeting_series (series_key, title, norm_title, gcal_recurring_event_id, owner_user_id)
  values (
    case when p_recurring_event_id is not null then 'gcal:' || p_recurring_event_id
         else 'title:' || coalesce(p_owner::text, '-') || ':' || v_norm end,
    coalesce(nullif(btrim(p_title), ''), v_norm, '(untitled)'),
    coalesce(v_norm, ''),
    p_recurring_event_id,
    p_owner
  )
  on conflict (tenant_id, series_key) do update set title = excluded.title
  returning id into v_id;
  return v_id;
end;
$$;


--
-- Name: meeting_title_similarity(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.meeting_title_similarity(a text, b text) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  with x as (
    select coalesce(string_to_array(public.meeting_norm(a), ' '), '{}') as ta,
           coalesce(string_to_array(public.meeting_norm(b), ' '), '{}') as tb
  )
  select case
    when public.meeting_norm(a) is null or public.meeting_norm(b) is null then 0
    when public.meeting_norm(a) = public.meeting_norm(b) then 1
    else round(
      (select count(distinct t) from unnest(ta) t where t = any (tb))::numeric
      / greatest((select count(distinct t) from unnest(ta || tb) t), 1), 3)
  end
  from x
$$;




--
-- Name: notification_channels_for(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notification_channels_for(p_user uuid, p_kind text) RETURNS TABLE(in_app boolean, email boolean, push boolean, sms boolean, digest text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
	select
		coalesce(p.in_app, k.default_in_app, true),
		coalesce(p.email, k.default_email, false),
		coalesce(p.push, k.default_push, false),
		coalesce(k.urgent, false) and coalesce(p.sms, k.default_sms, false),
		coalesce(p.digest, 'off')
	from (select 1) one
	left join public.notification_kinds k on k.kind = p_kind
	left join public.notification_preferences p on p.user_id = p_user and p.kind = p_kind;
$$;


--
-- Name: notification_settings_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notification_settings_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
	-- Only signed-in API callers are restricted; the service role, the
	-- migration runner and SECURITY DEFINER code pass through.
	if current_user in ('authenticated', 'anon') then
		if tg_op = 'INSERT' then
			new.sms_verified_at := null;
		elsif new.sms_verified_at is distinct from old.sms_verified_at then
			new.sms_verified_at := old.sms_verified_at;
		end if;
	end if;
	if tg_op = 'UPDATE' and new.sms_phone is distinct from old.sms_phone then
		new.sms_verified_at := null;
	end if;
	return new;
end;
$$;


--
-- Name: notifications_apply_preferences(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notifications_apply_preferences() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
	c record;
begin
	select * into c from public.notification_channels_for(new.user_id, new.kind);
	new.in_app := coalesce(c.in_app, true);
	return new;
end;
$$;


--
-- Name: notifications_queue_deliveries(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notifications_queue_deliveries() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
	c record;
	s record;
	v_digest_at timestamptz;
begin
	select * into c from public.notification_channels_for(new.user_id, new.kind);
	select * into s from public.notification_settings where user_id = new.user_id;

	if c.email then
		if c.digest in ('daily', 'weekly') then
			-- next digest slot in the person's time zone
			v_digest_at := (date_trunc('day', now() at time zone coalesce(s.timezone, 'America/Chicago'))
				+ make_interval(hours => coalesce(s.digest_hour, 8))) at time zone coalesce(s.timezone, 'America/Chicago');
			if v_digest_at <= now() then v_digest_at := v_digest_at + interval '1 day'; end if;
			if c.digest = 'weekly' then
				while extract(dow from v_digest_at at time zone coalesce(s.timezone, 'America/Chicago')) <> coalesce(s.digest_weekday, 1) loop
					v_digest_at := v_digest_at + interval '1 day';
				end loop;
			end if;
			insert into public.notification_deliveries (notification_id, user_id, channel, send_after)
			values (new.id, new.user_id, 'digest', v_digest_at) on conflict do nothing;
		else
			insert into public.notification_deliveries (notification_id, user_id, channel)
			values (new.id, new.user_id, 'email') on conflict do nothing;
		end if;
	end if;
	if c.push and exists (select 1 from public.push_subscriptions where user_id = new.user_id) then
		insert into public.notification_deliveries (notification_id, user_id, channel)
		values (new.id, new.user_id, 'push') on conflict do nothing;
	end if;
	if c.sms and s.sms_phone is not null and s.sms_verified_at is not null then
		insert into public.notification_deliveries (notification_id, user_id, channel)
		values (new.id, new.user_id, 'sms') on conflict do nothing;
	end if;
	return null;
end;
$$;


--
-- Name: notify_content_request_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_content_request_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_reviewer uuid;
  v_label    text := replace(initcap(replace(new.asset_type, '_', ' ')), ' ', ' ');
begin
  if tg_op = 'INSERT' then
    for v_reviewer in
      select m.user_id from public.reviewer_group_members m
        join public.reviewer_groups g on g.id = m.group_id
       where g.key = 'content_reviewers' and m.user_id <> new.requester_id
    loop
      insert into public.notifications (user_id, kind, title, body, href, dedupe_key)
      values (v_reviewer, 'content_request_submitted', v_label || ' request filed',
              new.title || coalesce(' · due ' || to_char(new.due_on, 'Mon DD'), ''),
              '/social/studio/requests',
              'content-request:' || new.id::text || ':submitted:' || v_reviewer::text)
      on conflict (user_id, dedupe_key) where dedupe_key is not null do nothing;
    end loop;
    return new;
  end if;

  if new.status <> old.status and new.requester_id is distinct from auth.uid() then
    insert into public.notifications (user_id, kind, title, body, href, dedupe_key)
    values (new.requester_id, 'content_request_status',
            v_label || ' request ' || replace(new.status, '_', ' '),
            coalesce(new.decision_note, new.title),
            '/the-work/content-requests',
            'content-request:' || new.id::text || ':' || new.status)
    on conflict (user_id, dedupe_key) where dedupe_key is not null do nothing;
  end if;
  return new;
end;
$$;


--
-- Name: notify_staff_request_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_staff_request_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_reviewer     uuid;
  v_kind_label   text;
begin
  v_kind_label := case when new.kind = 'innovation' then 'Innovation Desk'
                       else replace(initcap(replace(new.kind, '_', ' ')), ' ', ' ') end;

  if tg_op = 'INSERT' then
    for v_reviewer in
      select user_id from public.reviewer_group_members where group_id = new.reviewer_group_id
    loop
      insert into public.notifications (user_id, kind, title, body, href, dedupe_key)
      values (
        v_reviewer,
        'staff_request_submitted',
        v_kind_label || ' request submitted',
        new.title,
        '/the-work/innovation-desk',
        'staff-request:' || new.id::text || ':submitted:' || v_reviewer::text)
      on conflict (user_id, dedupe_key) where dedupe_key is not null do nothing;
    end loop;
    return new;
  end if;

  if new.status <> old.status then
    if new.status in ('in_review') then
      return new;
    end if;
    insert into public.notifications (user_id, kind, title, body, href, dedupe_key)
    values (
      new.requester_id,
      'staff_request_status',
      v_kind_label || ' request ' || new.status,
      new.decision_note_md,
      '/the-work/innovation-desk',
      'staff-request:' || new.id::text || ':' || new.status)
    on conflict (user_id, dedupe_key) where dedupe_key is not null do nothing;
  end if;
  return new;
end;
$$;


--
-- Name: nt_key_for_index(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nt_key_for_index(n integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select chr(97 + ((n / 25) / 676) % 26)
      || chr(97 + ((n / 25) / 26) % 26)
      || chr(97 + (n / 25) % 26)
      || chr(98 + n % 25);
$$;


--
-- Name: nt_like_escape(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nt_like_escape(s text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select replace(replace(replace(coalesce(s, ''), '\', '\\'), '%', '\%'), '_', '\_');
$$;


--
-- Name: nt_query_rows(uuid, jsonb, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nt_query_rows(p_table_id uuid, p_query jsonb DEFAULT '{}'::jsonb, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, created_at timestamp with time zone, order_key text, cells jsonb, total bigint)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_filters jsonb := coalesce(p_query->'filters', '[]'::jsonb);
  v_sorts jsonb := coalesce(p_query->'sorts', '[]'::jsonb);
  v_search text := nullif(trim(coalesce(p_query->>'search', '')), '');
  v_conj text := case when lower(coalesce(p_query->>'conjunction', 'and')) = 'or' then ' or ' else ' and ' end;
  v_where text[] := '{}';
  v_order text[] := '{}';
  v_sql text;
  f jsonb;
  s jsonb;
  v_col_id uuid;
  v_type text;
  v_op text;
  v_val text;
  v_arr text[];
  v_pred text;
  v_cell text := 'exists (select 1 from public.nt_cells c where c.row_id = r.id and c.column_id = %L::uuid and %s)';
  v_text_cols uuid[];
  v_limit integer := least(greatest(coalesce(p_limit, 100), 1), 1000);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
begin
  if jsonb_typeof(v_filters) <> 'array' or jsonb_typeof(v_sorts) <> 'array' then
    raise exception 'nt_query_rows: filters and sorts must be arrays';
  end if;
  if jsonb_array_length(v_filters) > 20 or jsonb_array_length(v_sorts) > 5 then
    raise exception 'nt_query_rows: at most 20 filters and 5 sorts';
  end if;

  -- ---- filters ------------------------------------------------------------
  for f in select * from jsonb_array_elements(v_filters) loop
    v_col_id := (f->>'column_id')::uuid;
    select col.type::text into v_type from public.nt_columns col where col.id = v_col_id and col.table_id = p_table_id;
    if v_type is null then raise exception 'nt_query_rows: unknown column %', v_col_id; end if;
    v_op := f->>'op';
    v_val := case when jsonb_typeof(f->'value') = 'string' then f->>'value' else null end;
    if jsonb_typeof(f->'value') = 'array' then
      select array_agg(x) into v_arr from jsonb_array_elements_text(f->'value') x;
    else
      v_arr := null;
    end if;

    -- Whitelist: (type family, op) -> predicate over c.value. Anything not
    -- listed falls through to the RAISE at the end of the CASE chain.
    v_pred := null;
    if v_type in ('text', 'long_text', 'url', 'email', 'phone', 'formula') then
      v_pred := case v_op
        when 'eq'           then format('(c.value #>> ''{}'') = %L', v_val)
        when 'neq'          then null
        when 'contains'     then format('(c.value #>> ''{}'') ilike %L', '%' || public.nt_like_escape(v_val) || '%')
        when 'not_contains' then null
        when 'starts_with'  then format('(c.value #>> ''{}'') ilike %L', public.nt_like_escape(v_val) || '%')
        when 'is_empty'     then null
        when 'is_not_empty' then 'c.value is not null and c.value <> ''null''::jsonb and c.value <> ''""''::jsonb'
        else '__bad__' end;
      if v_op = 'neq' then
        v_pred := 'not ' || format(v_cell, v_col_id, format('(c.value #>> ''{}'') = %L', v_val));
      elsif v_op = 'not_contains' then
        v_pred := 'not ' || format(v_cell, v_col_id, format('(c.value #>> ''{}'') ilike %L', '%' || public.nt_like_escape(v_val) || '%'));
      end if;
    elsif v_type in ('number', 'currency', 'percent', 'rating', 'duration') then
      if v_op not in ('is_empty', 'is_not_empty') and (v_val is null or v_val !~ '^-?[0-9]+(\.[0-9]+)?$') then
        raise exception 'nt_query_rows: numeric filter needs a numeric value';
      end if;
      v_pred := case v_op
        when 'eq'  then format('jsonb_typeof(c.value) = ''number'' and (c.value #>> ''{}'')::numeric = %L::numeric', v_val)
        when 'neq' then null
        when 'gt'  then format('jsonb_typeof(c.value) = ''number'' and (c.value #>> ''{}'')::numeric > %L::numeric', v_val)
        when 'gte' then format('jsonb_typeof(c.value) = ''number'' and (c.value #>> ''{}'')::numeric >= %L::numeric', v_val)
        when 'lt'  then format('jsonb_typeof(c.value) = ''number'' and (c.value #>> ''{}'')::numeric < %L::numeric', v_val)
        when 'lte' then format('jsonb_typeof(c.value) = ''number'' and (c.value #>> ''{}'')::numeric <= %L::numeric', v_val)
        when 'is_empty' then null
        when 'is_not_empty' then 'jsonb_typeof(c.value) = ''number'''
        else '__bad__' end;
      if v_op = 'neq' then
        v_pred := 'not ' || format(v_cell, v_col_id, format('jsonb_typeof(c.value) = ''number'' and (c.value #>> ''{}'')::numeric = %L::numeric', v_val));
      end if;
    elsif v_type = 'boolean' then
      v_pred := case v_op
        when 'is_true'  then 'c.value = ''true''::jsonb'
        when 'is_false' then null
        else '__bad__' end;
      if v_op = 'is_false' then
        v_pred := 'not ' || format(v_cell, v_col_id, 'c.value = ''true''::jsonb');
      end if;
    elsif v_type = 'datetime' then
      if v_op not in ('is_empty', 'is_not_empty') then
        begin
          perform v_val::timestamptz;
        exception when others then
          raise exception 'nt_query_rows: date filter needs a date value';
        end;
      end if;
      v_pred := case v_op
        when 'on'     then format('jsonb_typeof(c.value) = ''string'' and (c.value #>> ''{}'')::timestamptz >= %L::timestamptz and (c.value #>> ''{}'')::timestamptz < %L::timestamptz + interval ''1 day''', v_val, v_val)
        when 'before' then format('jsonb_typeof(c.value) = ''string'' and (c.value #>> ''{}'')::timestamptz < %L::timestamptz', v_val)
        when 'after'  then format('jsonb_typeof(c.value) = ''string'' and (c.value #>> ''{}'')::timestamptz > %L::timestamptz', v_val)
        when 'is_empty' then null
        when 'is_not_empty' then 'jsonb_typeof(c.value) = ''string'''
        else '__bad__' end;
    elsif v_type in ('select', 'link') then
      if v_op = 'has_any' and (v_arr is null or cardinality(v_arr) = 0) then
        raise exception 'nt_query_rows: has_any needs at least one value';
      end if;
      v_pred := case v_op
        when 'has_any' then format('jsonb_typeof(c.value) = ''array'' and c.value ?| %L::text[]', v_arr)
        when 'is_empty' then null
        when 'is_not_empty' then 'jsonb_typeof(c.value) = ''array'' and jsonb_array_length(c.value) > 0'
        else '__bad__' end;
    elsif v_type in ('user', 'brand') then
      v_pred := case v_op
        when 'eq'  then format('coalesce(c.value ->> ''id'', c.value #>> ''{}'') = %L', v_val)
        when 'neq' then null
        when 'is_empty' then null
        when 'is_not_empty' then 'c.value is not null and c.value <> ''null''::jsonb'
        else '__bad__' end;
      if v_op = 'neq' then
        v_pred := 'not ' || format(v_cell, v_col_id, format('coalesce(c.value ->> ''id'', c.value #>> ''{}'') = %L', v_val));
      end if;
    else
      raise exception 'nt_query_rows: unsupported column type %', v_type;
    end if;

    if v_pred = '__bad__' then
      raise exception 'nt_query_rows: operator % is not allowed on a % column', v_op, v_type;
    end if;

    if v_op = 'is_empty' then
      -- Absent cell, JSON null, empty string or empty array all count as empty.
      v_pred := 'not ' || format(v_cell, v_col_id, 'c.value is not null and c.value <> ''null''::jsonb and c.value <> ''""''::jsonb and c.value <> ''[]''::jsonb');
    elsif v_pred not like 'not exists%' then
      v_pred := format(v_cell, v_col_id, v_pred);
    end if;
    v_where := v_where || v_pred;
  end loop;

  -- ---- search (ILIKE across text-like columns of this table) ---------------
  if v_search is not null then
    select array_agg(col.id) into v_text_cols
    from public.nt_columns col
    where col.table_id = p_table_id
      and col.type::text in ('text', 'long_text', 'url', 'email', 'phone', 'select', 'formula');
    if v_text_cols is not null then
      v_where := v_where || format(
        '(exists (select 1 from public.nt_cells c where c.row_id = r.id and c.column_id = any(%L::uuid[]) and (c.value #>> ''{}'') ilike %L))',
        v_text_cols, '%' || public.nt_like_escape(left(v_search, 200)) || '%');
    else
      v_where := v_where || 'false';
    end if;
  end if;

  -- ---- sorts ---------------------------------------------------------------
  for s in select * from jsonb_array_elements(v_sorts) loop
    v_col_id := (s->>'column_id')::uuid;
    select col.type::text into v_type from public.nt_columns col where col.id = v_col_id and col.table_id = p_table_id;
    if v_type is null then raise exception 'nt_query_rows: unknown sort column %', v_col_id; end if;
    v_val := case when lower(coalesce(s->>'dir', 'asc')) = 'desc' then 'desc' else 'asc' end;
    if v_type in ('number', 'currency', 'percent', 'rating', 'duration') then
      v_pred := 'case when jsonb_typeof(c.value) = ''number'' then (c.value #>> ''{}'')::numeric end';
    elsif v_type = 'boolean' then
      v_pred := 'case when c.value = ''true''::jsonb then 1 else 0 end';
    elsif v_type = 'datetime' then
      v_pred := 'case when jsonb_typeof(c.value) = ''string'' then (c.value #>> ''{}'')::timestamptz end';
    elsif v_type in ('user', 'brand') then
      v_pred := 'coalesce(c.value ->> ''name'', c.value #>> ''{}'')';
    else
      v_pred := 'c.value #>> ''{}''';
    end if;
    v_order := v_order || format('(select %s from public.nt_cells c where c.row_id = r.id and c.column_id = %L::uuid) %s nulls last', v_pred, v_col_id, v_val);
  end loop;
  v_order := v_order || array['r.order_key asc', 'r.created_at asc', 'r.id asc'];

  -- ---- assemble ------------------------------------------------------------
  v_sql := format(
    'select r.id, r.created_at, r.order_key,
            coalesce((select jsonb_object_agg(c.column_id, c.value) from public.nt_cells c where c.row_id = r.id), ''{}''::jsonb) as cells,
            count(*) over () as total
       from public.nt_rows r
      where r.table_id = %L::uuid %s
      order by %s
      limit %s offset %s',
    p_table_id,
    case when cardinality(v_where) > 0 then ' and (' || array_to_string(v_where, v_conj) || ')' else '' end,
    array_to_string(v_order, ', '),
    v_limit, v_offset);

  return query execute v_sql;
end $_$;


--
-- Name: nt_renumber_rows(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nt_renumber_rows(p_table_id uuid) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_n integer;
begin
  if not public.can_manage_native_tables() then
    raise exception 'insufficient_privilege: cannot manage native tables' using errcode = '42501';
  end if;
  if (select count(*) from public.nt_rows where table_id = p_table_id) >= 439400 then
    raise exception 'nt_renumber_rows: table too large for fixed-width keys';
  end if;
  with ordered as (
    select id, (row_number() over (order by order_key, created_at, id) - 1)::integer as n
    from public.nt_rows where table_id = p_table_id
  )
  update public.nt_rows r set order_key = public.nt_key_for_index(o.n)
  from ordered o where o.id = r.id;
  get diagnostics v_n = row_count;
  return v_n;
end $$;


--
-- Name: package_family(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.package_family(p_package text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case
    when p_package is null then 'Unknown'
    when p_package ilike '%high visibility%' then 'High Visibility'
    when p_package ilike '%grow & scale%' or p_package ilike '%grow and scale%' then 'Grow & Scale'
    when p_package ilike '%brand accelerator%' then 'Brand Accelerator'
    when p_package ilike '%kickstarter%' then 'Kickstarter'
    when p_package ilike '%maintenance%' then 'Maintenance'
    when p_package ilike '%beacon%' then 'Beacon'
    else 'Other'
  end;
$$;


--
-- Name: package_opps_goal(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.package_opps_goal(p_package text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case
    when p_package is null then null
    when p_package ilike '%high visibility%' then 18
    when p_package ilike '%grow & scale%' or p_package ilike '%grow and scale%' then 12
    when p_package ilike '%brand accelerator%' then 7
    when p_package ilike '%kickstarter%' then 5
    when p_package ilike '%maintenance%' then 2
    else null   -- Beacon-only / project / custom: no opps quota (R1)
  end;
$$;


--
-- Name: podcast_two_party_consent_state(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.podcast_two_party_consent_state(p_state text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  select p_state is null
      or upper(trim(p_state)) not similar to '[A-Z]{2}'
      or upper(trim(p_state)) in ('CA','CT','DE','FL','IL','MD','MA','MI','MT','NV','NH','OR','PA','WA');
$$;




--
-- Name: position_request_after_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.position_request_after_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.kind = 'position_request' and nullif(new.payload->>'position_id', '') is not null then
    update public.hire_positions
       set status = 'pending_approval', request_id = new.id, requested_by = coalesce(requested_by, new.requester_id), updated_by = new.requester_id
     where id = (new.payload->>'position_id')::uuid and status = 'draft';
  end if;
  return new;
end;
$$;


--
-- Name: profiles_zz_level_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.profiles_zz_level_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.position_level is distinct from old.position_level then
    insert into public.hire_level_history (profile_id, field, from_value, to_value, is_advancement, actor_id)
    values (new.id, 'position_level', old.position_level::text, new.position_level::text, old.position_level is not null and new.position_level is not null and new.position_level < old.position_level, auth.uid());
  end if;
  if new.pap_position is distinct from old.pap_position then
    insert into public.hire_level_history (profile_id, field, from_value, to_value, is_advancement, actor_id)
    values (new.id, 'pap_position', old.pap_position, new.pap_position, old.pap_position is not null and new.pap_position is not null, auth.uid());
  end if;
  if new.position_track is distinct from old.position_track then
    insert into public.hire_level_history (profile_id, field, from_value, to_value, is_advancement, actor_id)
    values (new.id, 'position_track', old.position_track, new.position_track, false, auth.uid());
  end if;
  if new.job_role is distinct from old.job_role then
    insert into public.hire_level_history (profile_id, field, from_value, to_value, is_advancement, actor_id)
    values (new.id, 'job_role', old.job_role, new.job_role, old.job_role is not null and nullif(btrim(old.job_role), '') is not null and new.job_role is not null, auth.uid());
  end if;
  if new.manager_id is distinct from old.manager_id then
    insert into public.hire_level_history (profile_id, field, from_value, to_value, is_advancement, actor_id)
    values (new.id, 'manager_id', old.manager_id::text, new.manager_id::text, false, auth.uid());
  end if;
  if new.employment_status is distinct from old.employment_status then
    insert into public.hire_level_history (profile_id, field, from_value, to_value, is_advancement, actor_id)
    values (new.id, 'employment_status', old.employment_status, new.employment_status, false, auth.uid());
  end if;
  if new.is_active is distinct from old.is_active then
    insert into public.hire_level_history (profile_id, field, from_value, to_value, is_advancement, actor_id)
    values (new.id, 'is_active', old.is_active::text, new.is_active::text, false, auth.uid());
  end if;
  return new;
end;
$$;


--
-- Name: projects_guard_rev_task(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.projects_guard_rev_task() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if current_setting('app.rev_task_sync', true) = 'on' or (select auth.uid()) is null then
    return coalesce(new, old);
  end if;
  if tg_op in ('INSERT', 'UPDATE') and new.source_kind = 'rev_task'
     and (tg_op = 'INSERT' or old.source_kind is distinct from 'rev_task') then
    raise exception 'Prospect tasks are created in Prospects' using errcode = '42501';
  end if;
  if tg_op in ('UPDATE', 'DELETE') and old.source_kind = 'rev_task' then
    if not public.can_view_revenue() then
      raise exception 'Only the sales team can change a prospect task' using errcode = '42501';
    end if;
    if tg_op = 'UPDATE' and (new.source_kind, new.source_id) is distinct from (old.source_kind, old.source_id) then
      raise exception 'A prospect task keeps its link to Prospects' using errcode = '42501';
    end if;
  end if;
  return coalesce(new, old);
end;
$$;


--
-- Name: proof_industry_ok(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.proof_industry_ok(p text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  select p is null or p in (
    'legal','finance','cpg','personal_brand','professional_services','luxury',
    'healthcare_wellness','real_estate','tech_saas','nonprofit_impact',
    'hospitality_food_beverage','sports_entertainment','other'
  )
$$;


--
-- Name: proof_item_media_type(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.proof_item_media_type(p_kind text, p_id uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case p_kind
    when 'case_study'  then (select media_type from public.proof_case_studies where id = p_id)
    when 'testimonial' then (select media_type from public.proof_testimonials where id = p_id)
    when 'asset'       then (select case when type = 'video' then 'video' else 'image' end from public.proof_assets where id = p_id)
  end
$$;


--
-- Name: proof_log_event(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.proof_log_event(p_placement_id uuid, p_event text, p_ip_hash text DEFAULT NULL::text, p_session_id text DEFAULT NULL::text, p_page_url text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_recent int;
begin
  if p_event not in ('impression','click','conversion') then return 'bad_event'; end if;
  if not exists (select 1 from public.proof_placements where id = p_placement_id) then return 'unknown_placement'; end if;
  if p_ip_hash is not null then
    select count(*) into v_recent from public.proof_events
      where ip_hash = p_ip_hash and created_at > now() - interval '1 minute';
    if v_recent >= 120 then return 'rate_limited'; end if;
  end if;
  if p_event = 'impression' and p_session_id is not null and exists (
    select 1 from public.proof_events
      where placement_id = p_placement_id and event = 'impression' and session_id = p_session_id
        and created_at > now() - interval '10 minutes'
  ) then
    return 'deduped';
  end if;
  insert into public.proof_events (placement_id, event, ip_hash, session_id, page_url)
  values (p_placement_id, p_event, left(p_ip_hash, 64), left(p_session_id, 64), left(p_page_url, 500));
  update public.proof_placements set
    impressions = impressions + (p_event = 'impression')::int,
    clicks      = clicks      + (p_event = 'click')::int,
    conversions = conversions + (p_event = 'conversion')::int
  where id = p_placement_id;
  return 'ok';
end $$;


--
-- Name: proof_placements_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.proof_placements_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_slot public.proof_slots%rowtype;
  v_media text;
begin
  select * into v_slot from public.proof_slots where key = new.slot_key;
  if not found then raise exception 'PROOF_SLOT_MISSING: %', new.slot_key; end if;
  if v_slot.item_kind <> new.item_kind then
    raise exception 'PROOF_SLOT_KIND: slot % takes % items, not %', new.slot_key, v_slot.item_kind, new.item_kind;
  end if;
  v_media := public.proof_item_media_type(new.item_kind, new.item_id);
  if v_media is null then raise exception 'PROOF_ITEM_MISSING: % %', new.item_kind, new.item_id; end if;
  if v_media <> v_slot.media_type then
    raise exception 'PROOF_SLOT_MEDIA: slot % is %, item is %', new.slot_key, v_slot.media_type, v_media;
  end if;
  return new;
end $$;


