  select p is null or p <@ array['pr','social','podcast','flywheel','beacon']::text[]
$$;


--
-- Name: protect_comp_visibility(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_comp_visibility() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.can_view_comp is distinct from old.can_view_comp
     and auth.uid() is not null
     and not public.is_comp_admin() then
    raise exception 'only Alex changes comp visibility';
  end if;
  return new;
end;
$$;


--
-- Name: protect_profile_privileges(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_profile_privileges() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if (new.role is distinct from old.role)
     or (new.is_active is distinct from old.is_active)
     or (new.calibration_excluded is distinct from old.calibration_excluded) then

    -- No JWT user (service role / dashboard / migrations): allow.
    if auth.uid() is null then
      return new;
    end if;

    if not public.is_admin() then
      raise exception 'Only admins can change role, active status or calibration exclusion'
        using errcode = '42501'; -- insufficient_privilege
    end if;
  end if;

  return new;
end;
$$;


--
-- Name: protect_profile_structure(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_profile_structure() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if (new.title is distinct from old.title)
     or (new.manager_id is distinct from old.manager_id)
     or (new.department_tag_id is distinct from old.department_tag_id)
     or (new.position_track is distinct from old.position_track)
     or (new.position_level is distinct from old.position_level)
     or (new.job_role is distinct from old.job_role) then

    -- No JWT user (service role / SQL editor / migrations): allow.
    if auth.uid() is null then
      return new;
    end if;

    if not (public.is_admin() or public.is_people_manager(auth.uid())) then
      raise exception 'Only people managers, execs or admins can change position or role fields'
        using errcode = '42501'; -- insufficient_privilege
    end if;
  end if;

  return new;
end;
$$;


--
-- Name: quick_action_keys_ok(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.quick_action_keys_ok(k text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
                select coalesce(array_length(k, 1), 0) <= 20
                         and not exists (select 1 from unnest(k) e where e is null or length(e) > 64) $$;


--
-- Name: rate_limit_hit(text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rate_limit_hit(p_bucket text, p_key_hash text, p_max integer, p_window_seconds integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_window timestamptz;
  v_hits   integer;
begin
  if p_bucket is null or p_key_hash is null or p_max is null
     or p_window_seconds is null or p_window_seconds < 1 then
    raise exception 'rate_limit_hit: bucket, key, max and a positive window are required';
  end if;

  v_window := to_timestamp(floor(extract(epoch from now()) / p_window_seconds) * p_window_seconds);

  insert into public.rate_limit_counters as c (bucket, key_hash, window_start, hits)
  values (p_bucket, p_key_hash, v_window, 1)
  on conflict (bucket, key_hash, window_start)
  do update set hits = c.hits + 1
  returning c.hits into v_hits;

  -- Opportunistic cleanup, about 1 call in 100: nothing here is worth keeping
  -- past a day (the longest window in use is 15 minutes).
  if random() < 0.01 then
    delete from public.rate_limit_counters where window_start < now() - interval '1 day';
  end if;

  return v_hits > p_max;
end;
$$;


--
-- Name: request_approvers(text, uuid, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_approvers(p_type text, p_requester uuid, p_step smallint DEFAULT 1) RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
	select distinct x.uid from (
		select a.user_id as uid from public.request_type_approvers a
			where a.request_type = p_type and a.step = p_step and a.approver_kind = 'user'
		union all
		select m.user_id from public.request_type_approvers a
			join public.reviewer_group_members m on m.group_id = a.group_id
			where a.request_type = p_type and a.step = p_step and a.approver_kind = 'group'
		union all
		select r.manager_id from public.request_type_approvers a
			join public.profiles r on r.id = p_requester
			where a.request_type = p_type and a.step = p_step and a.approver_kind = 'requester_manager'
		union all
		select p.id from public.request_type_approvers a
			join public.profiles p on p.role = a.role
			where a.request_type = p_type and a.step = p_step and a.approver_kind = 'role'
		union all
		select p.id from public.request_type_approvers a
			join public.profiles p on lower(p.title) = lower(a.title)
			where a.request_type = p_type and a.step = p_step and a.approver_kind = 'title'
	) x
	join public.profiles p on p.id = x.uid and p.is_active
	where x.uid is not null and x.uid <> p_requester;
$$;


--
-- Name: rev_accept_action_item(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_accept_action_item(p_item uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare it public.rev_call_action_items%rowtype; v_task uuid; d public.rev_deals%rowtype;
begin
  if auth.uid() is not null and not public.can_view_revenue() then raise exception 'revenue: internal staff only' using errcode = '42501'; end if;
  select * into it from public.rev_call_action_items where id = p_item;
  if it.id is null then raise exception 'action item not found'; end if;
  if it.task_id is not null then return it.task_id; end if;
  select * into d from public.rev_deals where id = it.deal_id;
  insert into public.rev_tasks (deal_id, person_id, owner_id, title, body_md, due_at, created_by, created_by_kind)
  values (it.deal_id, d.primary_person_id, coalesce(it.owner_id, auth.uid()), it.title, 'From the post-call summary.', it.due_at, auth.uid(), 'ai')
  returning id into v_task;
  update public.rev_call_action_items set status = 'accepted', task_id = v_task where id = p_item;
  if it.owner_id is not null and it.owner_id <> coalesce(auth.uid(), '00000000-0000-0000-0000-000000000000'::uuid) then
    perform public.rev_bell(it.owner_id, 'revenue', 'Action item: ' || it.title, coalesce(d.title, ''), '/prospects/deals/' || it.deal_id, 'rev:action:' || p_item);
  end if;
  return v_task;
end
$$;


--
-- Name: rev_activities_bell_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_activities_bell_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare d public.rev_deals%rowtype; v_owner uuid; v_noshow boolean := false;
begin
  if new.deal_id is null then return null; end if;
  select * into d from public.rev_deals where id = new.deal_id;
  v_owner := coalesce(d.owner_setter_id, d.owner_closer_id, d.owner_lg_id);
  if v_owner is null or v_owner = new.actor_id then return null; end if;
  if new.disposition_id is not null then
    select 'no_show' = any(counts_as) into v_noshow from public.rev_dispositions where id = new.disposition_id;
  end if;
  if coalesce(new.is_positive, false) then
    perform public.rev_bell(v_owner, 'revenue', 'Positive reply: ' || d.title, left(coalesce(new.body_md, new.subject, ''), 200), '/prospects/deals/' || d.id, 'rev:positive:' || new.id);
  elsif new.direction = 'inbound' and new.kind in ('email', 'dm', 'sms') then
    perform public.rev_bell(v_owner, 'revenue', 'Reply: ' || d.title, left(coalesce(new.body_md, new.subject, ''), 200), '/prospects/deals/' || d.id, 'rev:reply:' || new.id);
  elsif coalesce(v_noshow, false) then
    perform public.rev_bell(v_owner, 'revenue', 'No-show: ' || d.title, 'Reschedule within 24 h.', '/prospects/deals/' || d.id, 'rev:noshow:' || new.id);
  end if;
  return null;
end
$$;


--
-- Name: rev_activities_ghl_eligible_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_activities_ghl_eligible_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.deal_id is not null and coalesce(new.is_positive, false) then
    perform public.rev_ghl_mark_eligible(new.deal_id, 'positive reply');
  end if;
  return null;
end
$$;


--
-- Name: rev_activity_touch(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_activity_touch() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_noshow boolean := false;
begin
  if new.deal_id is null then return new; end if;
  if new.disposition_id is not null then
    select 'no_show' = any(counts_as) into v_noshow from public.rev_dispositions where id = new.disposition_id;
  end if;
  update public.rev_deals d
     set first_touch_at = case when new.is_touch then least(coalesce(d.first_touch_at, new.occurred_at), new.occurred_at) else d.first_touch_at end,
         last_touch_at  = case when new.is_touch then greatest(coalesce(d.last_touch_at, new.occurred_at), new.occurred_at) else d.last_touch_at end,
         touches_30d    = (select count(*) from public.rev_activities a where a.deal_id = d.id and a.is_touch and a.occurred_at >= now() - interval '30 days'),
         no_show_count  = d.no_show_count + case when coalesce(v_noshow, false) then 1 else 0 end
   where d.id = new.deal_id;
  -- a system row written by rev_rescore itself must not rescore again
  if new.kind <> 'system' and pg_trigger_depth() <= 1 then
    perform public.rev_rescore(new.deal_id);
  end if;
  return new;
end
$$;


--
-- Name: rev_attach_referral(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_attach_referral(p_deal uuid, p_code text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare rc public.rev_referral_codes%rowtype; v_id uuid; d public.rev_deals%rowtype;
begin
  if public.is_portal_user() then raise exception 'revenue: not allowed from the client portal' using errcode = '42501'; end if;
  select * into rc from public.rev_referral_codes where code = p_code and is_active;
  if rc.code is null then return null; end if;
  select * into d from public.rev_deals where id = p_deal;
  if d.id is null then return null; end if;
  if exists (select 1 from public.rev_referrals where deal_id = p_deal) then return (select id from public.rev_referrals where deal_id = p_deal limit 1); end if;
  insert into public.rev_referrals (code, referrer_person_id, referrer_client_id, referrer_name, referrer_kind, deal_id, person_id)
  values (rc.code, rc.referrer_person_id, rc.referrer_client_id, rc.referrer_name, rc.kind, p_deal, d.primary_person_id) returning id into v_id;
  update public.rev_referral_codes set uses = uses + 1 where code = rc.code;
  update public.rev_deals set source = coalesce(nullif(source, ''), 'referral'), meta = meta || jsonb_build_object('referral_code', rc.code) where id = p_deal and (source is null or source = '' or source = 'other');
  insert into public.rev_activities (deal_id, person_id, kind, actor_kind, subject, is_touch, meta) values (p_deal, d.primary_person_id, 'system', 'system', 'Referred by ' || coalesce(rc.referrer_name, rc.referrer_email, rc.code), false, jsonb_build_object('referral_id', v_id, 'code', rc.code));
  return v_id;
end
$$;


--
-- Name: rev_bell(uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_bell(p_user uuid, p_kind text, p_title text, p_body text, p_href text, p_key text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if p_user is null then return; end if;
  insert into public.notifications (user_id, kind, title, body, href, dedupe_key)
  values (p_user, p_kind, p_title, p_body, p_href, p_key)
  on conflict (user_id, dedupe_key) where dedupe_key is not null do nothing;
end
$$;


--
-- Name: rev_budget_tier(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_budget_tier(p_band text) RETURNS smallint
    LANGUAGE sql IMMUTABLE
    AS $$
  select case p_band
    when 'none' then 1 when '500_3k' then 2 when '3k_7_5k' then 3 when '7_5k_20k' then 4 when '20k_plus' then 5
    else null end::smallint
$$;


--
-- Name: rev_calls_activity_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_calls_activity_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'INSERT' and new.deal_id is not null and new.activity_id is null then
    insert into public.rev_activities (deal_id, person_id, kind, channel, direction, actor_id, actor_kind, subject, occurred_at, is_touch, external_source, external_id, recording_url, meta)
    values (new.deal_id, new.person_id, 'meeting', case new.source when 'zoom' then 'zoom' when 'ghl' then 'ghl' else 'other' end, 'internal',
            coalesce(new.owner_id, new.created_by), case when new.source = 'manual' then 'human' else 'system' end,
            initcap(new.call_kind) || ' call ' || new.status, coalesce(new.occurred_at, new.scheduled_at, now()), new.status not in ('scheduled', 'cancelled'),
            'rev_calls', new.id::text, new.recording_url, jsonb_build_object('call_kind', new.call_kind))
    on conflict do nothing
    returning id into new.activity_id;
    update public.rev_calls set activity_id = new.activity_id where id = new.id;
  end if;
  return null;
end
$$;


--
-- Name: rev_calls_feedback_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_calls_feedback_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'UPDATE' and new.status in ('recorded', 'transcribed', 'analyzed') and old.status = 'scheduled' and new.deal_id is not null then
    insert into public.rev_feedback (kind, deal_id, call_id, subject_user_id, respondent_person_id, requested_at)
    select 'call', new.deal_id, new.id, new.owner_id, new.person_id, now()
    where not exists (select 1 from public.rev_feedback f where f.call_id = new.id);
  end if;
  return null;
end
$$;


--
-- Name: rev_cfg_num(text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_cfg_num(p_key text, p_default numeric DEFAULT 0) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce((select case when jsonb_typeof(value) = 'number' then (value)::text::numeric
                               when jsonb_typeof(value) = 'string' then nullif(value #>> '{}', '')::numeric end
                     from public.rev_scoring_config where key = p_key), p_default)
$$;


--
-- Name: rev_channel_metrics(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_channel_metrics(p_from date, p_to date) RETURNS TABLE(day date, channel text, source text, metric text, value numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with acts as (
    select (a.occurred_at at time zone 'America/Chicago')::date as day, coalesce(a.channel, 'other') as channel, coalesce(d.source, 'unknown') as source,
           a.kind, a.direction, a.is_positive, coalesce(dp.counts_as, '{}') as counts_as
      from public.rev_activities a
      left join public.rev_deals d on d.id = a.deal_id
      left join public.rev_dispositions dp on dp.id = a.disposition_id
     where a.occurred_at >= (p_from::timestamp at time zone 'America/Chicago')
       and a.occurred_at <  ((p_to + 1)::timestamp at time zone 'America/Chicago')
  )
  select day, channel, source, 'sent'::text, count(*)::numeric from acts where direction = 'outbound' and kind in ('email', 'dm', 'sms', 'call') group by 1,2,3
  union all select day, channel, source, 'replies', count(*) from acts where direction = 'inbound' and kind in ('email', 'dm', 'sms') group by 1,2,3
  union all select day, channel, source, 'positive_replies', count(*) from acts where coalesce(is_positive, false) group by 1,2,3
  union all select day, channel, source, 'booked', count(*) from acts where 'set' = any(counts_as) group by 1,2,3
  union all select day, channel, source, 'shown', count(*) from acts where 'show' = any(counts_as) group by 1,2,3
  union all
  select (d.created_at at time zone 'America/Chicago')::date, coalesce(d.channel, 'other'), coalesce(d.source, 'unknown'), 'new_leads', count(*)::numeric
    from public.rev_deals d
   where d.created_at >= (p_from::timestamp at time zone 'America/Chicago') and d.created_at < ((p_to + 1)::timestamp at time zone 'America/Chicago')
   group by 1,2,3
$$;


--
-- Name: rev_commission_rule(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_commission_rule(p_kind text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $_$
  select case p_kind
    when 'client' then jsonb_build_object('intro_cents', 0, 'pct', 5, 'months', 5, 'alt_pct', 10, 'alt_while_both_clients', true, 'note', 'Client (subscriber): 5% for 5 months, or 10% for as long as both remain clients')
    when 'staff'  then jsonb_build_object('intro_cents', 0, 'pct', 0, 'months', 0, 'note', 'Staff referrals carry no commission')
    else jsonb_build_object('intro_cents', 10000, 'pct', 10, 'months', 5, 'note', 'Non-client: $100 for an intro that reaches a call; 10% for 5 months if they close it')
  end
$_$;


--
-- Name: rev_compute_heat(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_compute_heat(p_deal uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  d public.rev_deals%rowtype;
  v_parts jsonb := '{}'::jsonb;
  v_total numeric := 0;
  v_w numeric;
  v_touches int;
  v_stage_slug text;
  v_pipeline_slug text;
  v_showed boolean := false;
  v_booked boolean := false;
  v_booked_after_show boolean := false;
  v_positive boolean := false;
  v_last_show timestamptz;
begin
  select * into d from public.rev_deals where id = p_deal;
  if d.id is null then return null; end if;

  select count(*) into v_touches from public.rev_activities a where a.deal_id = d.id and a.is_touch and a.occurred_at >= now() - interval '30 days';
  v_w := public.rev_cfg_num('h_touch', 1);
  if v_touches > 0 then v_total := v_total + v_touches * v_w; v_parts := v_parts || jsonb_build_object('touches', v_touches * v_w, 'touch_count', v_touches); end if;

  if coalesce(d.budget_band, d.fit_signals->>'budget_band') is not null and coalesce(d.budget_band, d.fit_signals->>'budget_band') <> 'none' then
    v_w := public.rev_cfg_num('h_budget', 5); v_total := v_total + v_w; v_parts := v_parts || jsonb_build_object('budget', v_w);
  end if;

  v_w := case coalesce(d.timing, d.fit_signals->>'timing')
           when 'immediately' then public.rev_cfg_num('h_timing_immediately', 5)
           when 'within_30'   then public.rev_cfg_num('h_timing_within_30', 3)
           when 'after_30'    then public.rev_cfg_num('h_timing_after_30', 1)
           else 0 end;
  if v_w > 0 then v_total := v_total + v_w; v_parts := v_parts || jsonb_build_object('timing', v_w); end if;

  -- call status, highest applicable wins
  select s.slug, p.slug into v_stage_slug, v_pipeline_slug
    from public.rev_stages s join public.rev_pipelines p on p.id = s.pipeline_id where s.id = d.stage_id;
  select bool_or(dp.counts_as @> array['show']), bool_or(dp.counts_as @> array['set']), bool_or(coalesce(a.is_positive, false)),
         max(a.occurred_at) filter (where dp.counts_as @> array['show'])
    into v_showed, v_booked, v_positive, v_last_show
    from public.rev_activities a left join public.rev_dispositions dp on dp.id = a.disposition_id
   where a.deal_id = d.id;
  if v_last_show is not null then
    select exists (select 1 from public.rev_activities a join public.rev_dispositions dp on dp.id = a.disposition_id
                    where a.deal_id = d.id and dp.counts_as @> array['set'] and a.occurred_at > v_last_show) into v_booked_after_show;
  end if;
  v_booked := coalesce(v_booked, false) or v_stage_slug in ('booked', 'discovery-booked', 'sales-booked', 'demo', 'discovery');
  if v_pipeline_slug = 'closer' and v_stage_slug in ('sales-booked', 'offer', 'contract-sent', 'won') or v_stage_slug in ('discovery-taken', 'trial', 'proposal', 'contract') then
    v_w := public.rev_cfg_num('h_call_next_steps', 5); v_parts := v_parts || jsonb_build_object('call', v_w, 'call_status', 'next_steps');
  elsif coalesce(v_showed, false) and v_booked_after_show then
    v_w := public.rev_cfg_num('h_call_showed_booked', 4); v_parts := v_parts || jsonb_build_object('call', v_w, 'call_status', 'showed_booked_again');
  elsif v_booked then
    v_w := public.rev_cfg_num('h_call_booked', 3); v_parts := v_parts || jsonb_build_object('call', v_w, 'call_status', 'booked');
  elsif coalesce(v_positive, false) then
    v_w := public.rev_cfg_num('h_positive_reply', 1); v_parts := v_parts || jsonb_build_object('call', v_w, 'call_status', 'positive_reply');
  else
    v_w := 0;
  end if;
  v_total := v_total + v_w;

  if d.no_show_count > 0 then
    v_w := public.rev_cfg_num('h_no_show', -5) * d.no_show_count;
    v_total := v_total + v_w; v_parts := v_parts || jsonb_build_object('no_shows', v_w, 'no_show_count', d.no_show_count);
  end if;

  return jsonb_build_object('total', v_total, 'parts', v_parts);
end
$$;


--
-- Name: rev_compute_quality(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_compute_quality(p_deal uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  d public.rev_deals%rowtype;
  f jsonb;
  v_email text;
  v_parts jsonb := '{}'::jsonb;
  v_total numeric := 0;
  v_max numeric := 0;
  v_w numeric;
  v_site numeric;
  v_industry text;
  v_fit boolean := false;
  v_item text;
begin
  select * into d from public.rev_deals where id = p_deal;
  if d.id is null then return null; end if;
  f := coalesce(d.fit_signals, '{}'::jsonb);

  -- work email: explicit signal, else infer from the primary person's email
  v_w := public.rev_cfg_num('q_work_email', 2); v_max := v_max + v_w;
  if f ? 'work_email' then
    if (f->>'work_email')::boolean then v_total := v_total + v_w; v_parts := v_parts || jsonb_build_object('work_email', v_w); end if;
  else
    select p.email into v_email from public.rev_people p where p.id = d.primary_person_id;
    if v_email is not null and position('@' in v_email) > 0
       and not exists (select 1 from jsonb_array_elements_text(coalesce((select value from public.rev_scoring_config where key = 'free_email_domains'), '[]'::jsonb)) x where x = lower(split_part(v_email, '@', 2))) then
      v_total := v_total + v_w; v_parts := v_parts || jsonb_build_object('work_email', v_w);
    end if;
  end if;

  -- website 0-3
  v_w := public.rev_cfg_num('q_website_max', 3); v_max := v_max + v_w;
  v_site := least(greatest(coalesce(nullif(f->>'website', '')::numeric, 0), 0), v_w);
  if v_site > 0 then v_total := v_total + v_site; v_parts := v_parts || jsonb_build_object('website', v_site); end if;

  -- text answers
  v_w := public.rev_cfg_num('q_why_grow', 2); v_max := v_max + v_w;
  if length(btrim(coalesce(f->>'why_grow', ''))) > 3 then v_total := v_total + v_w; v_parts := v_parts || jsonb_build_object('why_grow', v_w); end if;
  v_w := public.rev_cfg_num('q_roadblock', 2); v_max := v_max + v_w;
  if length(btrim(coalesce(f->>'roadblock', ''))) > 3 then v_total := v_total + v_w; v_parts := v_parts || jsonb_build_object('roadblock', v_w); end if;

  -- interests
  v_w := public.rev_cfg_num('q_interest_pr', 1); v_max := v_max + v_w;
  if coalesce((f->>'interest_pr')::boolean, false) then v_total := v_total + v_w; v_parts := v_parts || jsonb_build_object('interest_pr', v_w); end if;
  v_w := public.rev_cfg_num('q_interest_ads', 1); v_max := v_max + v_w;
  if coalesce((f->>'interest_ads')::boolean, false) then v_total := v_total + v_w; v_parts := v_parts || jsonb_build_object('interest_ads', v_w); end if;
  v_w := public.rev_cfg_num('q_interest_smm', 1); v_max := v_max + v_w;
  if coalesce((f->>'interest_smm')::boolean, false) then v_total := v_total + v_w; v_parts := v_parts || jsonb_build_object('interest_smm', v_w); end if;

  -- industry fit (signal text, else the brand's industry / vertical)
  v_w := public.rev_cfg_num('q_industry', 4); v_max := v_max + v_w;
  v_industry := lower(coalesce(nullif(f->>'industry', ''), (select coalesce(b.industry, b.vertical) from public.rev_brands b where b.id = d.brand_id), ''));
  if v_industry <> '' then
    for v_item in select jsonb_array_elements_text(coalesce((select value from public.rev_scoring_config where key = 'industry_fit'), '[]'::jsonb)) loop
      if position(lower(v_item) in v_industry) > 0 then v_fit := true; exit; end if;
    end loop;
  end if;
  if v_fit then v_total := v_total + v_w; v_parts := v_parts || jsonb_build_object('industry', v_w); end if;

  -- budget: full for $3k+, half for $500-3k
  v_w := public.rev_cfg_num('q_budget', 5); v_max := v_max + v_w;
  if coalesce(d.budget_band, f->>'budget_band') in ('3k_7_5k', '7_5k_20k', '20k_plus') then
    v_total := v_total + v_w; v_parts := v_parts || jsonb_build_object('budget', v_w);
  elsif coalesce(d.budget_band, f->>'budget_band') = '500_3k' then
    v_total := v_total + round(v_w / 2); v_parts := v_parts || jsonb_build_object('budget', round(v_w / 2));
  end if;

  v_w := public.rev_cfg_num('q_agency_before', 3); v_max := v_max + v_w;
  if coalesce((f->>'agency_before')::boolean, false) then v_total := v_total + v_w; v_parts := v_parts || jsonb_build_object('agency_before', v_w); end if;

  return jsonb_build_object('total', v_total, 'max', v_max, 'parts', v_parts);
end
$_$;


--
-- Name: rev_contracts_growth_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_contracts_growth_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'UPDATE' and new.status = 'signed' and old.status is distinct from 'signed' then
    insert into public.rev_reviews (client_id, deal_id, person_id, milestone, requested_by)
    select new.client_id, new.deal_id, new.signer_person_id, 'signed', new.created_by
    where not exists (select 1 from public.rev_reviews r where r.deal_id = new.deal_id and r.milestone = 'signed');
    insert into public.rev_feedback (kind, deal_id, client_id, respondent_person_id, respondent_email, requested_at)
    select 'client', new.deal_id, new.client_id, new.signer_person_id, new.signer_email, now()
    where not exists (select 1 from public.rev_feedback f where f.deal_id = new.deal_id and f.kind = 'client');
  end if;
  return null;
end
$$;


--
-- Name: rev_contracts_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_contracts_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if auth.uid() is not null and old.status = 'signed' and (new.body_md is distinct from old.body_md or new.line_items is distinct from old.line_items or new.mrr_cents is distinct from old.mrr_cents or new.status <> 'signed') then
    raise exception 'a signed contract cannot be changed; void it and create a new one' using errcode = 'P0001';
  end if;
  return new;
end
$$;


--
-- Name: rev_contracts_status_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_contracts_status_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare d public.rev_deals%rowtype; v_stage uuid; v_slug text;
begin
  if tg_op = 'UPDATE' and new.status is not distinct from old.status then return null; end if;
  select * into d from public.rev_deals where id = new.deal_id;
  if d.id is null then return null; end if;
  v_slug := case new.status when 'sent' then 'contract-sent' when 'viewed' then 'contract-sent' when 'signed' then 'won' else null end;
  if v_slug is not null then
    select s.id into v_stage from public.rev_stages s where s.pipeline_id = d.pipeline_id and s.slug in (v_slug, case v_slug when 'won' then 'subscribed' else 'contract' end) order by position limit 1;
    if v_stage is not null and v_stage <> d.stage_id then
      update public.rev_deals set stage_id = v_stage, meta = meta || jsonb_build_object('move_reason', 'contract:' || new.status) where id = d.id;
    end if;
  end if;
  insert into public.rev_activities (deal_id, person_id, brand_id, kind, direction, actor_id, actor_kind, subject, is_touch, meta)
  values (d.id, new.signer_person_id, d.brand_id, 'system', 'internal', auth.uid(), case when auth.uid() is null then 'system' else 'human' end,
          'Contract ' || new.status || ': ' || new.title, new.status in ('viewed', 'signed'), jsonb_build_object('contract_id', new.id, 'status', new.status));
  if not exists (select 1 from public.rev_documents x where x.meta->>'contract_id' = new.id::text) then
    insert into public.rev_documents (deal_id, brand_id, kind, title, bucket_path, url, status, meta, created_by)
    values (d.id, d.brand_id, 'contract', new.title, new.signed_pdf_path, new.provider_url,
            case new.status when 'signed' then 'signed' when 'sent' then 'sent' when 'viewed' then 'viewed' when 'void' then 'void' when 'declined' then 'void' else 'draft' end,
            jsonb_build_object('contract_id', new.id), new.created_by);
  end if;
  -- one document row per contract, kept current
  update public.rev_documents x set status = case new.status when 'signed' then 'signed' when 'sent' then 'sent' when 'viewed' then 'viewed' when 'void' then 'void' when 'declined' then 'void' else 'draft' end,
         bucket_path = coalesce(new.signed_pdf_path, x.bucket_path), url = coalesce(new.provider_url, x.url)
   where x.meta->>'contract_id' = new.id::text;
  if new.status = 'signed' then
    perform public.rev_convert_deal(new.deal_id, new.id);
  end if;
  return null;
end
$$;


--
-- Name: rev_convert_deal(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_convert_deal(p_deal uuid, p_contract uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  d public.rev_deals%rowtype; c public.rev_contracts%rowtype; b public.rev_brands%rowtype; co public.rev_companies%rowtype; s public.rev_people%rowtype;
  v_client uuid; v_contract uuid; v_contact uuid; v_org_tag uuid; v_name text; v_created boolean := false; v_slug text;
begin
  if auth.uid() is not null and not public.can_view_revenue() then raise exception 'revenue: internal staff only' using errcode = '42501'; end if;
  select * into d from public.rev_deals where id = p_deal;
  if d.id is null then raise exception 'deal not found'; end if;
  if p_contract is not null then select * into c from public.rev_contracts where id = p_contract; end if;
  if d.brand_id is not null then select * into b from public.rev_brands where id = d.brand_id; end if;
  if d.company_id is not null then select * into co from public.rev_companies where id = d.company_id; end if;
  v_name := coalesce(b.name, co.name, d.title);

  -- client: existing link on brand/company, else by name key, else create
  v_client := coalesce(b.client_id, co.client_id, c.client_id);
  if v_client is null then
    select id into v_client from public.clients_v2 where display_name_key = lower(btrim(v_name));
  end if;
  if v_client is null then
    select case p.brand when 'beacon' then 'org-beacon' when 'premium' then 'org-premium' else 'org-main' end into v_slug from public.rev_pipelines p where p.id = d.pipeline_id;
    v_slug := coalesce(v_slug, case d.motion when 'beacon' then 'org-beacon' when 'premium' then 'org-premium' else 'org-main' end);
    select id into v_org_tag from public.tags where category = 'org' and slug = v_slug;
    insert into public.clients_v2 (display_name, status, org_tag_id) values (v_name, 'active', v_org_tag) returning id into v_client;
    v_created := true;
  else
    update public.clients_v2 set status = 'active' where id = v_client and status in ('unknown', 'closed', 'post contract fulfillment');
  end if;
  if b.id is not null then update public.rev_brands set client_id = v_client where id = b.id and client_id is null; end if;
  if co.id is not null then update public.rev_companies set client_id = v_client where id = co.id and client_id is null; end if;

  -- contract row (0040 contracts; airtable_contract_id stays null for native deals)
  if c.id is not null then
    if c.contract_row_id is not null then
      v_contract := c.contract_row_id;
    else
      insert into public.contracts (client_id, airtable_contract_id, package, per_month_cents, starts_on, ends_on, status)
      values (v_client, null,
              coalesce((select string_agg(li->>'name', ' + ') from jsonb_array_elements(c.line_items) li where coalesce(li->>'billing', 'monthly') = 'monthly'), c.title),
              c.mrr_cents, coalesce(c.starts_on, current_date),
              case when c.term_months is not null then coalesce(c.starts_on, current_date) + make_interval(months => c.term_months) else null end,
              'active')
      returning id into v_contract;
    end if;
  end if;

  -- signer -> contacts (0002, admin-write: this function is security definer) + client_contacts needs an airtable id; native deals link through rev_people.contact_id
  if c.signer_person_id is not null then
    select * into s from public.rev_people where id = c.signer_person_id;
    v_contact := s.contact_id;
    if v_contact is null and s.email is not null then select id into v_contact from public.contacts where lower(email) = lower(s.email) limit 1; end if;
    if v_contact is null then
      insert into public.contacts (display_name, first_name, last_name, email, phone, title, organization, linkedin_url, ghl_contact_id)
      values (s.display_name, s.first_name, s.last_name, s.email, s.phone, s.title, v_name, s.linkedin_url, s.ghl_contact_id)
      returning id into v_contact;
    end if;
    update public.rev_people set contact_id = v_contact where id = s.id and contact_id is null;
    insert into public.contact_roles (contact_id, role, is_primary) values (v_contact, 'client', true) on conflict do nothing;
    -- client_contacts is keyed on airtable_contract_id; for native contracts we record the link in rev_contracts.meta and the rev_people.contact_id pointer
  end if;

  update public.rev_deals set status = 'won', won_at = coalesce(won_at, now()), client_id = v_client where id = d.id;
  if c.id is not null then
    update public.rev_contracts set client_id = v_client, contract_row_id = v_contract, converted_at = coalesce(converted_at, now()),
           meta = meta || jsonb_build_object('signer_contact_id', v_contact, 'client_created', v_created)
     where id = c.id;
  end if;
  insert into public.rev_activities (deal_id, person_id, brand_id, kind, direction, actor_id, actor_kind, subject, is_touch, meta)
  values (d.id, c.signer_person_id, d.brand_id, 'system', 'internal', auth.uid(), 'system',
          'Converted to client' || case when v_created then ' (new clients_v2 row)' else ' (linked existing client)' end, false,
          jsonb_build_object('client_id', v_client, 'contract_id', v_contract, 'signer_contact_id', v_contact));
  return jsonb_build_object('client_id', v_client, 'contract_id', v_contract, 'signer_contact_id', v_contact, 'client_created', v_created);
end
$$;


--
-- Name: rev_daily_metrics(date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_daily_metrics(p_from date, p_to date, p_user uuid DEFAULT NULL::uuid) RETURNS TABLE(day date, user_id uuid, metric text, value numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with acts as (
    select (a.occurred_at at time zone 'America/Chicago')::date as day, a.actor_id as user_id, a.kind, a.channel, a.direction, a.is_positive, a.is_touch,
           coalesce(d.counts_as, '{}') as counts_as
      from public.rev_activities a
      left join public.rev_dispositions d on d.id = a.disposition_id
     where a.actor_id is not null
       and a.occurred_at >= (p_from::timestamp at time zone 'America/Chicago')
       and a.occurred_at <  ((p_to + 1)::timestamp at time zone 'America/Chicago')
       and (p_user is null or a.actor_id = p_user)
  ),
  act_metrics as (
    select day, user_id, 'dials'::text as metric, count(*)::numeric as value from acts where kind = 'call' and direction = 'outbound' group by 1,2
    union all select day, user_id, 'answers',            count(*) from acts where 'answer' = any(counts_as) group by 1,2
    union all select day, user_id, 'conversations',      count(*) from acts where 'conversation' = any(counts_as) group by 1,2
    union all select day, user_id, 'sets',               count(*) from acts where 'set' = any(counts_as) group by 1,2
    union all select day, user_id, 'shows',              count(*) from acts where 'show' = any(counts_as) group by 1,2
    union all select day, user_id, 'no_shows',           count(*) from acts where 'no_show' = any(counts_as) group by 1,2
    union all select day, user_id, 'offers',             count(*) from acts where 'offer' = any(counts_as) group by 1,2
    union all select day, user_id, 'closes',             count(*) from acts where 'close' = any(counts_as) group by 1,2
    union all select day, user_id, 'dms',                count(*) from acts where kind = 'dm' and direction = 'outbound' group by 1,2
    union all select day, user_id, 'sends',              count(*) from acts where kind in ('email', 'dm', 'sms') and direction = 'outbound' group by 1,2
    union all select day, user_id, 'emails_sent',        count(*) from acts where kind = 'email' and direction = 'outbound' group by 1,2
    union all select day, user_id, 'replies',            count(*) from acts where kind in ('email', 'dm', 'sms') and direction = 'inbound' group by 1,2
    union all select day, user_id, 'positive_replies',   count(*) from acts where coalesce(is_positive, false) group by 1,2
    union all select day, user_id, 'follow_ups',         count(*) from acts where is_touch and direction = 'outbound' group by 1,2
    union all select day, user_id, 'meetings',           count(*) from acts where kind = 'meeting' group by 1,2
  ),
  moves as (
    select (h.created_at at time zone 'America/Chicago')::date as day, h.changed_by as user_id, s.slug as to_slug, p.slug as pipeline_slug, h.deal_id
      from public.rev_deal_stage_history h
      join public.rev_stages s on s.id = h.to_stage_id
      join public.rev_pipelines p on p.id = h.to_pipeline_id
     where h.created_at >= (p_from::timestamp at time zone 'America/Chicago')
       and h.created_at <  ((p_to + 1)::timestamp at time zone 'America/Chicago')
       and h.changed_by is not null
       and (p_user is null or h.changed_by = p_user)
  ),
  move_metrics as (
    select day, user_id, 'discovery_booked'::text as metric, count(distinct deal_id)::numeric from moves where to_slug in ('booked', 'discovery-booked', 'demo', 'discovery') group by 1,2
    union all select day, user_id, 'discovery_taken',  count(distinct deal_id) from moves where to_slug in ('discovery-taken') group by 1,2
    union all select day, user_id, 'sales_booked',     count(distinct deal_id) from moves where to_slug in ('sales-booked', 'trial') group by 1,2
    union all select day, user_id, 'offers_sent',      count(distinct deal_id) from moves where to_slug in ('offer', 'proposal') group by 1,2
    union all select day, user_id, 'contracts_sent',   count(distinct deal_id) from moves where to_slug in ('contract-sent', 'contract') group by 1,2
    union all select day, user_id, 'agreements_signed',count(distinct deal_id) from moves where to_slug in ('won', 'subscribed') group by 1,2
    union all select day, user_id, 'handoffs',         count(distinct deal_id) from moves where to_slug in ('positive', 'handoff') group by 1,2
  ),
  won as (
    select (d.won_at at time zone 'America/Chicago')::date as day, coalesce(d.owner_closer_id, d.owner_setter_id, d.owner_lg_id) as user_id, d.est_mrr_cents, d.est_one_time_cents
      from public.rev_deals d
     where d.status = 'won' and d.won_at is not null
       and d.won_at >= (p_from::timestamp at time zone 'America/Chicago')
       and d.won_at <  ((p_to + 1)::timestamp at time zone 'America/Chicago')
       and (p_user is null or coalesce(d.owner_closer_id, d.owner_setter_id, d.owner_lg_id) = p_user)
  ),
  won_metrics as (
    select day, user_id, 'won'::text as metric, count(*)::numeric from won where user_id is not null group by 1,2
    union all select day, user_id, 'mrr_sold_cents',     coalesce(sum(est_mrr_cents), 0) from won where user_id is not null group by 1,2
    union all select day, user_id, 'fe_cash_cents',      coalesce(sum(est_one_time_cents), 0) from won where user_id is not null group by 1,2
  ),
  new_leads as (
    select (d.created_at at time zone 'America/Chicago')::date as day, coalesce(d.owner_lg_id, d.created_by) as user_id, count(*)::numeric as value
      from public.rev_deals d
     where d.created_at >= (p_from::timestamp at time zone 'America/Chicago')
       and d.created_at <  ((p_to + 1)::timestamp at time zone 'America/Chicago')
       and (p_user is null or coalesce(d.owner_lg_id, d.created_by) = p_user)
     group by 1,2
  )
  select * from act_metrics
  union all select * from move_metrics
  union all select * from won_metrics
  union all select day, user_id, 'new_leads', value from new_leads where user_id is not null
$$;


--
-- Name: rev_deal_responsible(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_deal_responsible(p_deal_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case p.lane
           when 'marketing' then d.owner_lg_id
           when 'lead_gen'  then d.owner_lg_id
           when 'setter'    then d.owner_setter_id
           else d.owner_closer_id
         end
    from public.rev_deals d
    join public.rev_pipelines p on p.id = d.pipeline_id
   where d.id = p_deal_id
     and ((select auth.uid()) is null or public.can_view_revenue())
$$;


--
-- Name: rev_deal_stage_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_deal_stage_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_stage  public.rev_stages%rowtype;
  v_land   public.rev_stages%rowtype;
  v_field  text;
  v_val    text;
begin
  perform set_config('rev.handoff_from', '', true);
  if tg_op = 'UPDATE' and new.stage_id = old.stage_id and new.pipeline_id = old.pipeline_id then
    return new;
  end if;

  select * into v_stage from public.rev_stages where id = new.stage_id;
  if v_stage.id is null then
    raise exception 'rev_deals: unknown stage' using errcode = '23503';
  end if;
  if v_stage.pipeline_id <> new.pipeline_id then
    -- Allow the caller to pass only the stage: adopt its pipeline.
    new.pipeline_id := v_stage.pipeline_id;
  end if;

  foreach v_field in array v_stage.required_fields loop
    execute format('select ($1).%I::text', v_field) into v_val using new;
    if v_val is null or v_val = '' then
      raise exception 'rev_deals: stage "%" requires % to be set', v_stage.name, v_field using errcode = '23514';
    end if;
  end loop;

  new.stage_entered_at := now();
  new.status := case v_stage.outcome when 'won' then 'won' when 'lost' then 'lost' else 'open' end;
  new.won_at  := case when v_stage.outcome = 'won'  then coalesce(new.won_at, now())  else null end;
  new.lost_at := case when v_stage.outcome = 'lost' then coalesce(new.lost_at, now()) else null end;

  -- Lane handoff: land in the next pipeline's entry stage. The picked stage
  -- is stashed in a transaction-local GUC so the AFTER trigger writes both
  -- history rows (what the human picked, where it landed).
  if v_stage.handoff_pipeline_id is not null then
    select * into v_land from public.rev_stages
     where pipeline_id = v_stage.handoff_pipeline_id
       and slug = coalesce(v_stage.handoff_stage_slug, slug)
     order by position limit 1;
    if v_land.id is not null and v_land.id <> new.stage_id then
      perform set_config('rev.handoff_from', v_stage.id::text, true);
      new.pipeline_id := v_land.pipeline_id;
      new.stage_id := v_land.id;
      new.status := case v_land.outcome when 'won' then 'won' when 'lost' then 'lost' else 'open' end;
    end if;
  end if;
  return new;
end
$_$;


--
-- Name: rev_deal_stage_history_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_deal_stage_history_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_reason text := coalesce(nullif(current_setting('rev.stage_reason', true), ''), case when tg_op = 'INSERT' then 'created' else 'manual' end);
  v_picked uuid := nullif(current_setting('rev.handoff_from', true), '')::uuid;
  v_picked_row public.rev_stages%rowtype;
  v_land_row   public.rev_stages%rowtype;
begin
  if tg_op = 'UPDATE' and new.stage_id = old.stage_id and new.pipeline_id = old.pipeline_id then
    return null;
  end if;
  if v_picked is not null then
    perform set_config('rev.handoff_from', '', true);
    select * into v_picked_row from public.rev_stages where id = v_picked;
    select * into v_land_row from public.rev_stages where id = new.stage_id;
    insert into public.rev_deal_stage_history (deal_id, from_pipeline_id, from_stage_id, to_pipeline_id, to_stage_id, changed_by, reason)
    values (new.id, case when tg_op = 'UPDATE' then old.pipeline_id end, case when tg_op = 'UPDATE' then old.stage_id end,
            v_picked_row.pipeline_id, v_picked_row.id, auth.uid(), v_reason);
    insert into public.rev_deal_stage_history (deal_id, from_pipeline_id, from_stage_id, to_pipeline_id, to_stage_id, changed_by, reason, note)
    values (new.id, v_picked_row.pipeline_id, v_picked_row.id, new.pipeline_id, new.stage_id, auth.uid(), 'handoff', v_picked_row.name || ' -> ' || v_land_row.name);
  else
    insert into public.rev_deal_stage_history (deal_id, from_pipeline_id, from_stage_id, to_pipeline_id, to_stage_id, changed_by, reason)
    values (new.id, case when tg_op = 'UPDATE' then old.pipeline_id end, case when tg_op = 'UPDATE' then old.stage_id end,
            new.pipeline_id, new.stage_id, auth.uid(), v_reason);
  end if;
  return null;
end
$$;


--
-- Name: rev_deals_bell_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_deals_bell_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_owner uuid;
begin
  if pg_trigger_depth() > 2 then return null; end if;
  if tg_op = 'UPDATE' and new.routing is distinct from old.routing and new.routing = 'book_call' then
    v_owner := coalesce(new.owner_setter_id, new.owner_lg_id, new.owner_closer_id);
    perform public.rev_bell(v_owner, 'revenue', 'Hot lead: ' || new.title, 'Tier ' || coalesce(new.mql_tier::text, '?') || ' — ' || coalesce(new.quality_score::text, '?') || '-' || coalesce(new.heat_score::text, '?'), '/prospects/deals/' || new.id, 'rev:hot:' || new.id);
  end if;
  return null;
end
$$;


--
-- Name: rev_deals_ghl_eligible_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_deals_ghl_eligible_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_slug text; v_list jsonb;
begin
  if pg_trigger_depth() > 2 then return null; end if;
  if tg_op = 'UPDATE' and new.stage_id is not distinct from old.stage_id then
    -- a re-push is needed when a pushed deal changes stage / scores / owner
    if new.ghl_push_status = 'pushed' and (new.quality_score is distinct from old.quality_score or new.heat_score is distinct from old.heat_score
         or new.owner_setter_id is distinct from old.owner_setter_id or new.owner_closer_id is distinct from old.owner_closer_id
         or new.est_mrr_cents is distinct from old.est_mrr_cents or new.status is distinct from old.status) then
      update public.rev_deals set ghl_push_status = 'eligible' where id = new.id and ghl_push_status = 'pushed';
    end if;
    return null;
  end if;
  select s.slug into v_slug from public.rev_stages s where s.id = new.stage_id;
  select value into v_list from public.ghl_settings where key = 'push_min_stage_slugs';
  if v_list is not null and v_list ? v_slug then
    perform public.rev_ghl_mark_eligible(new.id, 'stage ' || v_slug);
  elsif tg_op = 'UPDATE' and new.ghl_push_status = 'pushed' then
    update public.rev_deals set ghl_push_status = 'eligible' where id = new.id;
  end if;
  return null;
end
$$;


--
-- Name: rev_deals_rescore_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_deals_rescore_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if pg_trigger_depth() > 1 then return null; end if;
  if tg_op = 'INSERT'
     or new.fit_signals is distinct from old.fit_signals
     or new.budget_band is distinct from old.budget_band
     or new.timing is distinct from old.timing
     or new.stage_id is distinct from old.stage_id
     or new.no_show_count is distinct from old.no_show_count
     or new.status is distinct from old.status then
    perform public.rev_rescore(new.id);
  end if;
  return null;
end
$$;


--
-- Name: rev_form_submission_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_form_submission_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  l public.rev_form_links%rowtype;
  v_slug text;
  v_payload jsonb; r jsonb;
begin
  select * into l from public.rev_form_links where form_id = new.form_id and enabled;
  if l.form_id is null then return null; end if;
  select slug into v_slug from public.forms where id = new.form_id;
  v_payload := public.rev_map_payload(l.field_map, new.data,
    jsonb_build_object('pipeline', l.default_pipeline, 'source', l.default_source, 'channel', l.default_channel, 'motion', l.default_motion,
                       'created_via', 'webhook',
                       'activity', jsonb_build_object('kind', 'form', 'channel', 'web', 'direction', 'inbound', 'subject', 'Form: ' || coalesce(v_slug, 'form'),
                                                      'external_source', 'form:' || coalesce(v_slug, ''), 'external_id', new.id::text, 'is_touch', true)));
  begin
    r := public.rev_intake_scored(v_payload);
    insert into public.rev_intake_events (source_key, external_id, status, payload, mapped, deal_id, person_id, processed_at)
    values ('website_form', 'form:' || new.id::text, 'processed', new.data, v_payload, (r->>'deal_id')::uuid, (r->>'person_id')::uuid, now())
    on conflict do nothing;
  exception when others then
    insert into public.rev_intake_events (source_key, external_id, status, payload, mapped, error, processed_at)
    values ('website_form', 'form:' || new.id::text, 'rejected', new.data, v_payload, sqlerrm, now())
    on conflict do nothing;
  end;
  return null;
end
$$;


--
-- Name: rev_ghl_import_rows(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_ghl_import_rows(p_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  r jsonb; m public.ghl_stage_map%rowtype; d public.rev_deals%rowtype;
  v_opp text; v_pipe text; v_stage text; v_status text; v_existing uuid; v_res jsonb;
  v_deal uuid; v_person uuid; v_fresh boolean; v_advanced boolean; v_target uuid; v_new_rank int; v_cur_rank int;
  v_out jsonb := '[]'::jsonb;
begin
  if auth.uid() is not null and not public.can_manage_revenue() then
    raise exception 'revenue: GHL import needs manage_revenue' using errcode = '42501';
  end if;
  if jsonb_typeof(p_rows) is distinct from 'array' or jsonb_array_length(p_rows) > 200 then
    raise exception 'revenue: p_rows must be an array of at most 200 rows' using errcode = '22023';
  end if;

  for r in select value from jsonb_array_elements(p_rows) loop
    v_opp := nullif(r->>'ghl_opportunity_id', '');
    begin
      if v_opp is null then
        v_out := v_out || jsonb_build_object('opp', null, 'status', 'skipped', 'reason', 'no opportunity id');
        continue;
      end if;
      -- serialise this opportunity across concurrent callers (cron + Admin)
      perform pg_advisory_xact_lock(hashtext('rev_ghl_opp:' || v_opp));
      select id into v_existing from public.rev_deals
       where ghl_opportunity_id = v_opp or meta->'ghl_opportunity_ids' ? v_opp
       limit 1;
      if v_existing is not null then
        v_out := v_out || jsonb_build_object('opp', v_opp, 'status', 'exists', 'deal_id', v_existing);
        continue;
      end if;
      select * into m from public.ghl_stage_map where ghl_stage_id = r->>'ghl_stage_id';
      if m.ghl_stage_id is null then
        v_out := v_out || jsonb_build_object('opp', v_opp, 'status', 'skipped', 'reason', 'unmapped stage ' || coalesce(r->>'ghl_stage_id', '?'));
        continue;
      end if;

      v_pipe := m.pipeline_slug;
      v_stage := m.stage_slug;
      v_status := coalesce(nullif(r->>'ghl_status', ''), 'open');
      if v_status = 'won' then
        v_pipe := case when m.pipeline_slug = 'beacon' then 'beacon' else 'closer' end;
        select s.slug into v_stage from public.rev_stages s join public.rev_pipelines p on p.id = s.pipeline_id
         where p.slug = v_pipe and s.outcome = 'won' order by s.position limit 1;
      elsif v_status in ('lost', 'abandoned') then
        select s.slug into v_stage from public.rev_stages s join public.rev_pipelines p on p.id = s.pipeline_id
         where p.slug = v_pipe and s.outcome = 'lost' order by s.position limit 1;
      end if;

      v_res := public.rev_intake(coalesce(r->'person', '{}'::jsonb) || jsonb_build_object(
        'pipeline', v_pipe, 'stage', v_stage,
        'brand_name', nullif(r->'person'->>'company_name', ''),
        'motion', case when v_pipe = 'beacon' then 'beacon' else 'pr' end,
        'source', 'ghl', 'channel', 'ghl', 'campaign', nullif(r->>'ghl_source', ''),
        'created_via', 'import', 'owner_email', nullif(r->>'owner_email', ''),
        'est_mrr_cents', r->'value_cents',
        'activity', jsonb_build_object(
          'kind', 'system', 'channel', 'ghl', 'is_touch', false,
          'subject', 'Imported from GHL: ' || m.ghl_pipeline_name || ' / ' || m.ghl_stage_name,
          'external_source', 'ghl', 'external_id', 'opp:' || v_opp,
          'occurred_at', coalesce(nullif(r->>'created_at', ''), now()::text),
          'meta', jsonb_build_object('ghl_status', v_status))));
      v_deal := (v_res->>'deal_id')::uuid;
      v_person := (v_res->>'person_id')::uuid;
      v_fresh := v_res->'created' ? 'deal';
      select * into d from public.rev_deals where id = v_deal;

      -- a reused deal advances only when GHL has it further down the funnel
      select p.id into v_target from public.rev_stages p join public.rev_pipelines pp on pp.id = p.pipeline_id
       where pp.slug = v_pipe and p.slug = v_stage;
      select (case pp.lane when 'marketing' then 1 when 'lead_gen' then 2 when 'setter' then 3 else 4 end) * 1000 + s.position
        into v_new_rank from public.rev_stages s join public.rev_pipelines pp on pp.id = s.pipeline_id where s.id = v_target;
      select (case pp.lane when 'marketing' then 1 when 'lead_gen' then 2 when 'setter' then 3 else 4 end) * 1000 + s.position
        into v_cur_rank from public.rev_stages s join public.rev_pipelines pp on pp.id = s.pipeline_id where s.id = d.stage_id;
      v_advanced := not v_fresh and d.status = 'open' and v_target is not null and v_new_rank > v_cur_rank;
      if v_advanced then
        -- 'sync' is an allowed rev_deal_stage_history.reason (0121); clear it after
        perform set_config('rev.stage_reason', 'sync', true);
        update public.rev_deals set stage_id = v_target where id = v_deal;
        perform set_config('rev.stage_reason', '', true);
      end if;

      update public.rev_deals set
        ghl_opportunity_id = coalesce(ghl_opportunity_id, v_opp),
        ghl_location_id    = coalesce(ghl_location_id, nullif(r->>'ghl_location_id', '')),
        ghl_contact_id     = coalesce(ghl_contact_id, nullif(r->>'ghl_contact_id', '')),
        ghl_pipeline_id    = nullif(r->>'ghl_pipeline_id', ''),
        ghl_stage_id       = nullif(r->>'ghl_stage_id', ''),
        ghl_push_status    = 'pushed',
        ghl_push_error     = null,
        ghl_eligible_at    = null,
        created_at         = case when v_fresh then coalesce(nullif(r->>'created_at', '')::timestamptz, created_at) else created_at end,
        stage_entered_at   = case when v_fresh or v_advanced then coalesce(nullif(r->>'last_stage_change_at', '')::timestamptz, stage_entered_at) else stage_entered_at end,
        won_at  = case when status = 'won'  then coalesce(nullif(r->>'last_status_change_at', '')::timestamptz, won_at)  else won_at end,
        lost_at = case when status = 'lost' then coalesce(nullif(r->>'last_status_change_at', '')::timestamptz, lost_at) else lost_at end,
        meta = meta
          || jsonb_build_object('ghl_opportunity_ids', coalesce(meta->'ghl_opportunity_ids', '[]'::jsonb) || to_jsonb(v_opp))
          || case when v_fresh or (v_advanced and not meta ? 'imported_at') then jsonb_build_object('imported_at', now()) else '{}'::jsonb end
          || case when m.icp_band is not null then jsonb_build_object('ghl_icp_band', m.icp_band) else '{}'::jsonb end
      where id = v_deal;

      update public.rev_people set ghl_contact_id = nullif(r->>'ghl_contact_id', ''), ghl_location_id = nullif(r->>'ghl_location_id', '')
       where id = v_person and ghl_contact_id is null and nullif(r->>'ghl_contact_id', '') is not null;

      v_out := v_out || jsonb_build_object('opp', v_opp, 'status', case when v_fresh then 'imported' else 'merged' end, 'deal_id', v_deal);
    exception when others then
      v_out := v_out || jsonb_build_object('opp', v_opp, 'status', 'error', 'error', sqlerrm);
    end;
  end loop;
  return v_out;
end
$$;


--
-- Name: rev_ghl_mark_eligible(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_ghl_mark_eligible(p_deal uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  update public.rev_deals d
     set ghl_push_status = case when d.ghl_push_status = 'pushed' then 'eligible' else coalesce(nullif(d.ghl_push_status, 'skipped'), 'eligible') end,
         ghl_eligible_at = coalesce(d.ghl_eligible_at, now()),
         ghl_push_error = null
   where d.id = p_deal and d.status = 'open'
     and (d.ghl_push_status is distinct from 'eligible');
  if found then
    insert into public.ghl_sync_log (direction, kind, status, deal_id, summary)
    values ('outbound', 'eligible', 'skipped', p_deal, 'Eligible for GHL push: ' || p_reason);
  end if;
end
$$;


--
-- Name: rev_intake(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_intake(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_email text := nullif(lower(btrim(p->>'email')), '');
  v_phone text := public.rev_norm_phone(p->>'phone');
  v_li    text := public.rev_norm_linkedin(p->>'linkedin_url');
  v_first text := nullif(btrim(p->>'first_name'), '');
  v_last  text := nullif(btrim(p->>'last_name'), '');
  v_name  text := nullif(btrim(coalesce(p->>'display_name', concat_ws(' ', nullif(btrim(p->>'first_name'), ''), nullif(btrim(p->>'last_name'), '')))), '');
  v_brand_name text := nullif(btrim(p->>'brand_name'), '');
  v_company_name text := nullif(btrim(coalesce(p->>'company_name', p->>'brand_name')), '');
  v_domain text := coalesce(public.rev_norm_domain(p->>'brand_website'), public.rev_norm_domain(p->>'company_website'), public.rev_norm_domain(p->>'website'),
                            case when v_email is not null and split_part(v_email, '@', 2) not in ('gmail.com','yahoo.com','hotmail.com','outlook.com','icloud.com','aol.com','me.com','live.com','proton.me','protonmail.com') then split_part(v_email, '@', 2) end);
  v_person uuid; v_brand uuid; v_company uuid; v_deal uuid; v_pipeline public.rev_pipelines%rowtype; v_stage uuid;
  v_matched text := null; v_created jsonb := '{}'::jsonb; v_owner uuid; v_dup uuid; v_role text;
  v_products uuid[] := '{}';
  v_via text := coalesce(nullif(p->>'created_via', ''), 'ui');
begin
  if v_uid is not null and not public.can_view_revenue() then
    raise exception 'revenue: internal staff only' using errcode = '42501';
  end if;
  if v_name is null and v_email is null and v_phone is null and v_li is null and v_brand_name is null then
    raise exception 'revenue: intake needs a name, email, phone, LinkedIn URL or brand' using errcode = '22023';
  end if;

  -- 1. Person: exact identity match in the spec order.
  if v_li is not null then
    select id into v_person from public.rev_people where linkedin_key = v_li limit 1;
    if v_person is not null then v_matched := 'linkedin'; end if;
  end if;
  if v_person is null and v_phone is not null then
    select id into v_person from public.rev_people where phone = v_phone or v_phone = any(phones) limit 1;
    if v_person is not null then v_matched := 'phone'; end if;
  end if;
  if v_person is null and v_email is not null then
    select id into v_person from public.rev_people where email_key = v_email or v_email = any(emails) limit 1;
    if v_person is not null then v_matched := 'email'; end if;
  end if;
  if v_person is null and v_name is not null and v_domain is not null then
    -- domain + name: a person already linked to a brand/company on that domain with the same name
    select pp.id into v_person
      from public.rev_people pp
      join public.rev_person_links l on l.person_id = pp.id
      left join public.rev_brands b on b.id = l.brand_id
      left join public.rev_companies c on c.id = l.company_id
     where lower(pp.display_name) = lower(v_name) and (b.domain = v_domain or c.domain = v_domain)
     limit 1;
    if v_person is not null then v_matched := 'domain+name'; end if;
  end if;

  if v_person is null then
    if v_name is null then v_name := coalesce(v_email, v_phone, v_li, v_brand_name); end if;
    insert into public.rev_people (first_name, last_name, display_name, title, email, phone, linkedin_url, instagram, website, location, notes_md, created_by)
    values (v_first, v_last, v_name, nullif(p->>'title', ''), v_email, v_phone, nullif(p->>'linkedin_url', ''), nullif(p->>'instagram', ''), nullif(p->>'website', ''), nullif(p->>'location', ''), nullif(p->>'notes', ''), v_uid)
    returning id into v_person;
    v_created := v_created || jsonb_build_object('person', v_person);
    -- Fuzzy: same display name elsewhere -> review queue, never auto-merge.
    for v_dup in select id from public.rev_people where id <> v_person and lower(display_name) = lower(v_name) limit 3 loop
      insert into public.rev_duplicate_candidates (entity, keep_id, drop_id, match_on, confidence)
      values ('person', v_dup, v_person, 'name', 0.4) on conflict do nothing;
    end loop;
  else
    -- Fill blanks on the existing record; never overwrite a value with another.
    update public.rev_people set
      first_name = coalesce(first_name, v_first), last_name = coalesce(last_name, v_last),
      title = coalesce(title, nullif(p->>'title', '')),
      email = coalesce(email, v_email),
      emails = case when v_email is not null and email is not null and lower(email) <> v_email and not (v_email = any(emails)) then emails || v_email else emails end,
      phone = coalesce(phone, v_phone),
      phones = case when v_phone is not null and phone is not null and phone <> v_phone and not (v_phone = any(phones)) then phones || v_phone else phones end,
      linkedin_url = coalesce(linkedin_url, nullif(p->>'linkedin_url', '')),
      instagram = coalesce(instagram, nullif(p->>'instagram', '')),
      website = coalesce(website, nullif(p->>'website', '')),
      location = coalesce(location, nullif(p->>'location', ''))
    where id = v_person;
  end if;

  -- 2. Company (by domain, then name key) and brand (by domain, then name key).
  if v_company_name is not null or v_domain is not null then
    if v_domain is not null then select id into v_company from public.rev_companies where domain = v_domain limit 1; end if;
    if v_company is null and v_company_name is not null then select id into v_company from public.rev_companies where name_key = lower(v_company_name) limit 1; end if;
    if v_company is null and v_company_name is not null then
      insert into public.rev_companies (name, domain, website, industry, vertical, created_by)
      values (v_company_name, v_domain, nullif(coalesce(p->>'company_website', p->>'brand_website', p->>'website'), ''), nullif(p->>'industry', ''), nullif(p->>'vertical', ''), v_uid)
      returning id into v_company;
      v_created := v_created || jsonb_build_object('company', v_company);
    elsif v_company is not null then
      update public.rev_companies set domain = coalesce(domain, v_domain), industry = coalesce(industry, nullif(p->>'industry', '')), vertical = coalesce(vertical, nullif(p->>'vertical', '')) where id = v_company;
    end if;
  end if;
  if v_brand_name is not null then
    select id into v_brand from public.rev_brands where name_key = lower(v_brand_name) limit 1;
    if v_brand is null and v_domain is not null and v_company_name is not null and lower(v_company_name) = lower(v_brand_name) then
      select id into v_brand from public.rev_brands where domain = v_domain limit 1;
    end if;
    if v_brand is null then
      insert into public.rev_brands (name, domain, website, industry, vertical, created_by)
      values (v_brand_name, v_domain, nullif(coalesce(p->>'brand_website', p->>'website'), ''), nullif(p->>'industry', ''), nullif(p->>'vertical', ''), v_uid)
      returning id into v_brand;
      v_created := v_created || jsonb_build_object('brand', v_brand);
    end if;
    if v_company is not null then
      insert into public.rev_brand_companies (brand_id, company_id) values (v_brand, v_company) on conflict do nothing;
    end if;
  end if;

  -- 3. Link the person to the brand / company with a role.
  v_role := coalesce(nullif(p->>'person_role', ''), 'decision_maker');
  if v_brand is not null then
    insert into public.rev_person_links (person_id, brand_id, role, is_primary)
    values (v_person, v_brand, v_role, not exists (select 1 from public.rev_person_links where brand_id = v_brand and is_primary))
    on conflict do nothing;
  elsif v_company is not null then
    insert into public.rev_person_links (person_id, company_id, role, is_primary)
    values (v_person, v_company, v_role, not exists (select 1 from public.rev_person_links where company_id = v_company and is_primary))
    on conflict do nothing;
  end if;

  -- 4. Deal (unless dedupe_only). One open deal per brand per motion: reuse it.
  if coalesce((p->>'dedupe_only')::boolean, false) is false and p->>'pipeline' is not null then
    select * into v_pipeline from public.rev_pipelines where slug = p->>'pipeline' and is_active;
    if v_pipeline.id is null then raise exception 'revenue: unknown pipeline %', p->>'pipeline' using errcode = '23503'; end if;
    select id into v_stage from public.rev_stages where pipeline_id = v_pipeline.id and slug = coalesce(nullif(p->>'stage', ''), slug) order by position limit 1;
    if v_stage is null then raise exception 'revenue: unknown stage % in %', p->>'stage', p->>'pipeline' using errcode = '23503'; end if;
    if p->'product_slugs' is not null then
      select coalesce(array_agg(pr.id), '{}') into v_products from public.rev_products pr where pr.slug in (select jsonb_array_elements_text(p->'product_slugs'));
    end if;
    if p->>'owner_email' is not null then
      select id into v_owner from public.profiles where lower(email) = lower(p->>'owner_email') and is_active;
    end if;

    select id into v_deal from public.rev_deals
     where status = 'open' and motion = coalesce(nullif(p->>'motion', ''), 'pr')
       and ((v_brand is not null and brand_id = v_brand) or (v_brand is null and primary_person_id = v_person))
     order by created_at desc limit 1;

    if v_deal is null then
      insert into public.rev_deals (brand_id, company_id, primary_person_id, title, motion, pipeline_id, stage_id, product_ids, est_mrr_cents, est_one_time_cents,
                                    owner_lg_id, owner_setter_id, owner_closer_id, source, campaign, channel, created_by, created_via, intake_created, meta)
      values (v_brand, v_company, v_person,
              coalesce(v_brand_name, v_company_name, v_name) || case when coalesce(nullif(p->>'motion', ''), 'pr') <> 'pr' then ' · ' || initcap(replace(coalesce(p->>'motion', 'pr'), '_', ' ')) else '' end,
              coalesce(nullif(p->>'motion', ''), 'pr'), v_pipeline.id, v_stage, v_products,
              (p->>'est_mrr_cents')::bigint, (p->>'est_one_time_cents')::bigint,
              case when v_pipeline.lane in ('lead_gen', 'marketing') then v_owner end,
              case when v_pipeline.lane = 'setter' then v_owner end,
              case when v_pipeline.lane in ('closer', 'full_cycle') then v_owner end,
              nullif(p->>'source', ''), nullif(p->>'campaign', ''), nullif(p->>'channel', ''), v_uid, v_via, v_created,
              coalesce(p->'meta', '{}'::jsonb))
      returning id into v_deal;
      v_created := v_created || jsonb_build_object('deal', v_deal);
    else
      update public.rev_deals set
        primary_person_id = coalesce(primary_person_id, v_person),
        company_id = coalesce(company_id, v_company),
        source = coalesce(source, nullif(p->>'source', '')), campaign = coalesce(campaign, nullif(p->>'campaign', '')), channel = coalesce(channel, nullif(p->>'channel', '')),
        product_ids = case when cardinality(v_products) > 0 then (select array_agg(distinct x) from unnest(product_ids || v_products) x) else product_ids end
      where id = v_deal;
    end if;

    -- 5. The intake itself is a touch.
    insert into public.rev_activities (deal_id, person_id, brand_id, kind, channel, direction, actor_id, actor_kind, subject, body_md, is_touch, is_positive, occurred_at, external_source, external_id, meta)
    values (v_deal, v_person, v_brand,
            coalesce(nullif(p->'activity'->>'kind', ''), case when v_via = 'import' then 'system' when v_via = 'webhook' then 'form' else 'note' end),
            coalesce(nullif(p->'activity'->>'channel', ''), nullif(p->>'channel', '')),
            coalesce(nullif(p->'activity'->>'direction', ''), 'inbound'),
            v_uid, case when v_uid is null then 'system' else 'human' end,
            coalesce(nullif(p->'activity'->>'subject', ''), case when v_matched is null then 'Added' else 'Matched existing person on ' || v_matched end || ' via ' || v_via),
            nullif(p->'activity'->>'body_md', ''),
            coalesce((p->'activity'->>'is_touch')::boolean, v_via <> 'import'),
            (p->'activity'->>'is_positive')::boolean,
            coalesce((p->'activity'->>'occurred_at')::timestamptz, now()),
            nullif(p->'activity'->>'external_source', ''), nullif(p->'activity'->>'external_id', ''),
            coalesce(p->'activity'->'meta', '{}'::jsonb))
    on conflict do nothing;
  end if;

  return jsonb_build_object('deal_id', v_deal, 'person_id', v_person, 'brand_id', v_brand, 'company_id', v_company, 'matched_on', v_matched, 'created', v_created);
end
$$;


--
-- Name: rev_intake_revert(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_intake_revert(p_deal uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_c jsonb; v_person uuid; v_brand uuid; v_company uuid; v_removed text[] := '{deal}';
begin
  -- A signed-in caller needs the capability; the service role (no uid) is the
  -- Data Imports engine itself and passes.
  if auth.uid() is not null and not (public.can_manage_revenue() or public.can_import_data()) then
    raise exception 'revenue: manage_revenue or import_data is required to revert an intake' using errcode = '42501';
  end if;
  select intake_created into v_c from public.rev_deals where id = p_deal;
  if v_c is null then return jsonb_build_object('removed', '{}'::text[]); end if;
  v_person := (v_c->>'person')::uuid; v_brand := (v_c->>'brand')::uuid; v_company := (v_c->>'company')::uuid;
  delete from public.rev_deals where id = p_deal;
  if v_person is not null and not exists (select 1 from public.rev_deals where primary_person_id = v_person)
     and not exists (select 1 from public.rev_activities where person_id = v_person)
     and not exists (select 1 from public.rev_tasks where person_id = v_person) then
    delete from public.rev_people where id = v_person; v_removed := v_removed || array['person'];
  end if;
  if v_brand is not null and not exists (select 1 from public.rev_deals where brand_id = v_brand) then
    delete from public.rev_brands where id = v_brand; v_removed := v_removed || array['brand'];
  end if;
  if v_company is not null and not exists (select 1 from public.rev_deals where company_id = v_company)
     and not exists (select 1 from public.rev_brand_companies where company_id = v_company) then
    delete from public.rev_companies where id = v_company; v_removed := v_removed || array['company'];
  end if;
  return jsonb_build_object('removed', v_removed);
end
$$;


--
-- Name: rev_intake_scored(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_intake_scored(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  r jsonb; v_deal uuid; f jsonb := coalesce(p->'fit_signals', '{}'::jsonb);
begin
  if public.is_portal_user() then raise exception 'revenue: not allowed from the client portal' using errcode = '42501'; end if;
  r := public.rev_intake(p - 'fit_signals');
  v_deal := (r->>'deal_id')::uuid;
  if v_deal is not null then
    update public.rev_deals d set
      fit_signals = d.fit_signals || f,
      budget_band = coalesce(d.budget_band, case when f->>'budget_band' in ('none', '500_3k', '3k_7_5k', '7_5k_20k', '20k_plus') then f->>'budget_band' end),
      timing = coalesce(d.timing, case when f->>'timing' in ('immediately', 'within_30', 'after_30', 'unknown') then f->>'timing' end)
    where d.id = v_deal;
    -- the brand's industry from the form if the brand has none
    if f ? 'industry' and (r->>'brand_id') is not null then
      update public.rev_brands set industry = coalesce(industry, f->>'industry') where id = (r->>'brand_id')::uuid;
    end if;
    -- a form answer with a website URL fills the brand website
    if (p->>'brand_website') is not null and (r->>'brand_id') is not null then
      update public.rev_brands set website = coalesce(website, p->>'brand_website'), domain = coalesce(domain, public.rev_norm_domain(p->>'brand_website')) where id = (r->>'brand_id')::uuid;
    end if;
    r := r || jsonb_build_object('score', (select jsonb_build_object('quality', quality_score, 'heat', heat_score, 'tier', mql_tier, 'routing', routing) from public.rev_deals where id = v_deal));
  end if;
  return r;
end
$$;


--
-- Name: rev_intake_scraped(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_intake_scraped(p_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  rec record; v_res jsonb; v_sent int := 0; v_failed int := 0; v_errors jsonb := '[]'::jsonb; v_owner text;
begin
  if auth.uid() is not null and not (public.can_run_scrapers() and public.can_view_revenue()) then
    raise exception 'revenue: sending scraper leads needs the scraper capability' using errcode = '42501';
  end if;
  if p_ids is null or cardinality(p_ids) = 0 then
    return jsonb_build_object('sent', 0, 'skipped', 0, 'failed', 0, 'errors', '[]'::jsonb);
  end if;
  if cardinality(p_ids) > 500 then
    raise exception 'revenue: at most 500 scraper rows per call' using errcode = '22023';
  end if;
  if not coalesce((select enabled from public.rev_intake_sources where key = 'apify_scraper'), false) then
    return jsonb_build_object('sent', 0, 'skipped', cardinality(p_ids), 'failed', 0, 'errors', '[]'::jsonb, 'disabled', true);
  end if;

  for rec in
    select r.id, r.job_id, r.full_name, r.email, r.phone, r.linkedin_url, r.job_title, r.seniority, r.company_name, r.company_domain,
           r.company_industry, r.company_size, r.location, r.raw, j.preset, j.params, j.requested_by
      from public.scraped_records r
      join public.scrape_jobs j on j.id = r.job_id
     where r.id = any(p_ids) and r.status = 'approved' and j.kind = 'lead' and r.sent_to_prospects_at is null
       for update of r skip locked
  loop
    begin
      select email into v_owner from public.profiles where id = rec.requested_by;
      v_res := public.rev_intake(jsonb_build_object(
        'display_name', coalesce(nullif(btrim(rec.full_name), ''), rec.email, rec.linkedin_url, rec.company_name),
        'first_name', coalesce(rec.raw->>'firstName', rec.raw->>'first_name'),
        'last_name', coalesce(rec.raw->>'lastName', rec.raw->>'last_name'),
        'email', rec.email, 'phone', rec.phone, 'linkedin_url', rec.linkedin_url, 'title', rec.job_title,
        'company_name', rec.company_name, 'brand_name', rec.company_name, 'brand_website', rec.company_domain,
        'company_website', rec.company_domain, 'industry', rec.company_industry, 'location', rec.location,
        'pipeline', 'lead-gen', 'stage', 'sourced', 'motion', 'pr', 'source', 'scrape', 'channel', 'web',
        'campaign', rec.preset, 'created_via', 'import', 'owner_email', v_owner,
        'activity', jsonb_build_object(
          'kind', 'scrape_hit', 'channel', 'web', 'is_touch', false,
          'subject', 'Lead Scraper · ' || rec.preset,
          'external_source', 'scraper', 'external_id', rec.id::text,
          'meta', jsonb_build_object('job_id', rec.job_id, 'preset', rec.preset, 'params', rec.params))));
      update public.rev_people
         set enrichment = enrichment || jsonb_build_object('scrape', jsonb_strip_nulls(jsonb_build_object('seniority', rec.seniority, 'headline', rec.raw->>'headline', 'job_title', rec.job_title)))
       where id = (v_res->>'person_id')::uuid;
      update public.rev_brands
         set industry = coalesce(industry, rec.company_industry),
             enrichment = enrichment || jsonb_build_object('scrape', jsonb_strip_nulls(jsonb_build_object('industry', rec.company_industry, 'size', rec.company_size)))
       where id = (v_res->>'brand_id')::uuid;
      update public.scraped_records
         set rev_person_id = (v_res->>'person_id')::uuid, rev_deal_id = (v_res->>'deal_id')::uuid, sent_to_prospects_at = now()
       where id = rec.id;
      v_sent := v_sent + 1;
    exception when others then
      v_failed := v_failed + 1;
      v_errors := v_errors || jsonb_build_object('id', rec.id, 'error', sqlerrm);
    end;
  end loop;
  return jsonb_build_object('sent', v_sent, 'skipped', cardinality(p_ids) - v_sent - v_failed, 'failed', v_failed, 'errors', v_errors);
end
$$;


--
-- Name: rev_intake_scraped_backlog(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_intake_scraped_backlog(p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_ids uuid[]; v_res jsonb;
begin
  if auth.uid() is not null and not public.can_manage_revenue() then
    raise exception 'revenue: the scraper backlog needs manage_revenue' using errcode = '42501';
  end if;
  select coalesce(array_agg(id), '{}') into v_ids from (
    select r.id from public.scraped_records r join public.scrape_jobs j on j.id = r.job_id
     where r.status = 'approved' and j.kind = 'lead' and r.sent_to_prospects_at is null
     order by r.created_at, r.id
     limit least(greatest(p_limit, 1), 500)) q;
  v_res := public.rev_intake_scraped(v_ids);
  return v_res || jsonb_build_object('remaining', (
    select count(*) from public.scraped_records r join public.scrape_jobs j on j.id = r.job_id
     where r.status = 'approved' and j.kind = 'lead' and r.sent_to_prospects_at is null));
end
$$;


--
-- Name: rev_map_payload(jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_map_payload(p_map jsonb, p_data jsonb, p_defaults jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
declare
  k text; path text; v jsonb; sval text;
  out jsonb := '{}'::jsonb;
  fit jsonb := '{}'::jsonb;
  act jsonb := '{}'::jsonb;
  meta jsonb := '{}'::jsonb;
  parts text[];
begin
  for k, path in select key, value #>> '{}' from jsonb_each(p_map) loop
    parts := string_to_array(path, '.');
    v := p_data #> parts;
    if v is null or v = 'null'::jsonb then continue; end if;
    sval := case when jsonb_typeof(v) = 'string' then v #>> '{}' else v::text end;
    if sval is null or btrim(sval) = '' then continue; end if;
    if k like 'fit.%' then
      k := substr(k, 5);
      if k in ('interest_pr', 'interest_ads', 'interest_smm', 'agency_before', 'work_email') then
        fit := fit || jsonb_build_object(k, lower(sval) in ('yes', 'true', '1', 'y'));
      elsif k = 'budget_band' then
        fit := fit || jsonb_build_object(k, case
          when sval in ('none', '500_3k', '3k_7_5k', '7_5k_20k', '20k_plus') then sval
          when sval ilike 'no budget%' or sval ilike '%no budget%' then 'none'
          when sval like '$500%' or sval ilike '%500%3,000%' or sval ilike '%500-3k%' then '500_3k'
          when sval like '$3,000%' or sval ilike '%3k%7.5k%' or sval ilike '%3,000%7,500%' then '3k_7_5k'
          when sval like '$7,500%' or sval ilike '%7.5k%20k%' or sval ilike '%7,500%20,000%' then '7_5k_20k'
          when sval like '$20,000%' or sval ilike '%20k+%' or sval ilike '%20,000+%' then '20k_plus'
          else null end);
      elsif k = 'timing' then
        fit := fit || jsonb_build_object(k, case
          when sval in ('immediately', 'within_30', 'after_30', 'unknown') then sval
          when sval ilike 'immediate%' then 'immediately'
          when sval ilike 'within%' then 'within_30'
          when sval ilike 'after%' then 'after_30'
          else 'unknown' end);
      elsif k = 'website' then
        fit := fit || jsonb_build_object(k, case when sval ~ '^[0-3]$' then sval::int else null end);
      else
        fit := fit || jsonb_build_object(k, sval);
      end if;
    elsif k like 'activity.%' then
      k := substr(k, 10);
      if k = 'is_positive' then act := act || jsonb_build_object(k, lower(sval) in ('yes', 'true', '1', 'y', 'interested', 'positive'));
      else act := act || jsonb_build_object(k, sval); end if;
    elsif k like 'meta.%' then
      meta := meta || jsonb_build_object(substr(k, 6), sval);
    else
      out := out || jsonb_build_object(k, sval);
    end if;
  end loop;
  -- the website answer often carries the URL: keep it as brand_website too
  if (fit ? 'website') is false and out ? 'brand_website' then null; end if;
  out := p_defaults || out;
  if fit <> '{}'::jsonb then out := out || jsonb_build_object('fit_signals', fit); end if;
  if act <> '{}'::jsonb then out := out || jsonb_build_object('activity', coalesce(out->'activity', '{}'::jsonb) || act); end if;
  if meta <> '{}'::jsonb then out := out || jsonb_build_object('meta', coalesce(out->'meta', '{}'::jsonb) || meta); end if;
  return out;
end
$_$;


--
-- Name: rev_merge_people(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_merge_people(p_keep uuid, p_drop uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_keep public.rev_people%rowtype; v_drop public.rev_people%rowtype; v_n int;
begin
  if not public.can_manage_revenue() then
    raise exception 'revenue: the manage_revenue capability is required to merge' using errcode = '42501';
  end if;
  if p_keep = p_drop then raise exception 'revenue: cannot merge a person into itself' using errcode = '22023'; end if;
  select * into v_keep from public.rev_people where id = p_keep for update;
  select * into v_drop from public.rev_people where id = p_drop for update;
  if v_keep.id is null or v_drop.id is null then raise exception 'revenue: unknown person' using errcode = '23503'; end if;

  update public.rev_people set
    first_name   = coalesce(first_name, v_drop.first_name),
    last_name    = coalesce(last_name, v_drop.last_name),
    title        = coalesce(title, v_drop.title),
    email        = coalesce(email, v_drop.email),
    emails       = coalesce((select array_agg(distinct e) from unnest(emails || v_drop.emails || array[v_drop.email]) e where e is not null and lower(e) <> lower(coalesce(v_keep.email, v_drop.email, ''))), '{}'),
    phone        = coalesce(phone, v_drop.phone),
    phones       = coalesce((select array_agg(distinct e) from unnest(phones || v_drop.phones || array[v_drop.phone]) e where e is not null and e <> coalesce(v_keep.phone, v_drop.phone, '')), '{}'),
    linkedin_url = coalesce(linkedin_url, v_drop.linkedin_url),
    instagram    = coalesce(instagram, v_drop.instagram),
    facebook     = coalesce(facebook, v_drop.facebook),
    tiktok       = coalesce(tiktok, v_drop.tiktok),
    x_handle     = coalesce(x_handle, v_drop.x_handle),
    website      = coalesce(website, v_drop.website),
    location     = coalesce(location, v_drop.location),
    notes_md     = case when v_drop.notes_md is null then notes_md else coalesce(notes_md, '') || E'\n\n' || v_drop.notes_md end,
    enrichment   = v_drop.enrichment || enrichment,
    ghl_contact_id = coalesce(ghl_contact_id, v_drop.ghl_contact_id),
    ghl_location_id = coalesce(ghl_location_id, v_drop.ghl_location_id)
  where id = p_keep;

  update public.rev_deals set primary_person_id = p_keep where primary_person_id = p_drop;
  update public.rev_activities set person_id = p_keep where person_id = p_drop;
  update public.rev_tasks set person_id = p_keep where person_id = p_drop;
  -- links: move the ones the keeper does not already hold, drop the rest
  delete from public.rev_person_links l where l.person_id = p_drop and exists (
    select 1 from public.rev_person_links k where k.person_id = p_keep
      and coalesce(k.brand_id, '00000000-0000-0000-0000-000000000000') = coalesce(l.brand_id, '00000000-0000-0000-0000-000000000000')
      and coalesce(k.company_id, '00000000-0000-0000-0000-000000000000') = coalesce(l.company_id, '00000000-0000-0000-0000-000000000000')
      and k.role = l.role);
  update public.rev_person_links set person_id = p_keep where person_id = p_drop;
  get diagnostics v_n = row_count;

  update public.rev_duplicate_candidates set status = 'merged', decided_by = auth.uid(), decided_at = now()
   where entity = 'person' and status = 'open' and ((keep_id = p_keep and drop_id = p_drop) or (keep_id = p_drop and drop_id = p_keep));
  -- Other open candidates pointing at the dropped id now point at the keeper.
  update public.rev_duplicate_candidates set keep_id = p_keep where entity = 'person' and status = 'open' and keep_id = p_drop and drop_id <> p_keep;
  update public.rev_duplicate_candidates set drop_id = p_keep where entity = 'person' and status = 'open' and drop_id = p_drop and keep_id <> p_keep;

  insert into public.rev_activities (person_id, kind, actor_id, actor_kind, subject, is_touch, meta)
  values (p_keep, 'system', auth.uid(), 'human', 'Merged duplicate person', false, jsonb_build_object('dropped', p_drop, 'dropped_name', v_drop.display_name));

  delete from public.rev_people where id = p_drop;
  return jsonb_build_object('keep', p_keep, 'dropped', p_drop, 'links_moved', v_n);
end
$$;


--
-- Name: rev_my_day(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_my_day(p_user uuid DEFAULT auth.uid(), p_limit integer DEFAULT 50) RETURNS TABLE(deal_id uuid, title text, stage_name text, pipeline_slug text, lane text, person_name text, brand_name text, heat_score smallint, quality_score smallint, routing text, next_action text, next_action_at timestamp with time zone, created_at timestamp with time zone, stage_entered_at timestamp with time zone, sla_hours integer, delay_until timestamp with time zone, value_cents bigint, phone text, email text, score numeric, reason text)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with r as (
    select key, value from public.rev_queue_rules
  ),
  cfg as (
    select
      (select value from r where key = 'new_lead_minutes') as new_min,
      (select value from r where key = 'w_new') as w_new,
      (select value from r where key = 'w_overdue') as w_overdue,
      (select value from r where key = 'w_due_today') as w_due_today,
      (select value from r where key = 'w_heat') as w_heat,
      (select value from r where key = 'w_quality') as w_quality,
      (select value from r where key = 'w_value_per_1k') as w_value,
      (select value from r where key = 'w_sla_breach') as w_sla,
      (select value from r where key = 'w_delay') as w_delay
  ),
  mine as (
    select d.*, s.name as stage_name, s.sla_hours, p.slug as pipeline_slug, p.lane,
           (d.created_at > now() - make_interval(mins => (select new_min from cfg)::int)) as is_new,
           (d.next_action_at is not null and d.next_action_at < now()) as overdue,
           (d.next_action_at is not null and d.next_action_at >= now() and d.next_action_at < (date_trunc('day', now() at time zone 'America/Chicago') + interval '1 day') at time zone 'America/Chicago') as due_today,
           (s.sla_hours is not null and d.stage_entered_at < now() - make_interval(hours => s.sla_hours)) as sla_breach,
           (d.delay_until is not null and d.delay_until > now()) as delayed,
           exists (select 1 from public.rev_tasks t where t.deal_id = d.id and t.owner_id = p_user and t.done_at is null and t.due_at < now()) as task_overdue
      from public.rev_deals d
      join public.rev_stages s on s.id = d.stage_id
      join public.rev_pipelines p on p.id = d.pipeline_id
     where d.status = 'open'
       and (p_user = any(array[d.owner_lg_id, d.owner_setter_id, d.owner_closer_id]))
  )
  select m.id, m.title, m.stage_name, m.pipeline_slug, m.lane,
         pe.display_name, b.name,
         m.heat_score, m.quality_score, m.routing, m.next_action, m.next_action_at,
         m.created_at, m.stage_entered_at, m.sla_hours, m.delay_until,
         coalesce(m.est_mrr_cents, 0) + coalesce(m.est_one_time_cents, 0),
         pe.phone, pe.email,
         (case when m.is_new then c.w_new else 0 end
          + case when m.overdue or m.task_overdue then c.w_overdue else 0 end
          + case when m.due_today then c.w_due_today else 0 end
          + coalesce(m.heat_score, 0) * c.w_heat
          + coalesce(m.quality_score, 0) * c.w_quality
          + (coalesce(m.est_mrr_cents, 0) + coalesce(m.est_one_time_cents, 0)) / 100000.0 * c.w_value
          + case when m.sla_breach then c.w_sla else 0 end
          + case when m.delayed then c.w_delay else 0 end)::numeric(12,2),
         case when m.delayed then 'on delay'
              when m.is_new then 'new lead'
              when m.overdue or m.task_overdue then 'follow-up overdue'
              when m.due_today then 'due today'
              when m.sla_breach then 'SLA breached'
              when coalesce(m.heat_score, 0) >= 10 then 'hot'
              else 'next up' end
    from mine m
    cross join cfg c
    left join public.rev_people pe on pe.id = m.primary_person_id
    left join public.rev_brands b on b.id = m.brand_id
   order by 20 desc, m.created_at desc
   limit p_limit
$$;


--
-- Name: rev_norm_domain(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_norm_domain(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $_$
  select nullif(regexp_replace(regexp_replace(lower(btrim(coalesce(p, ''))), '^https?://', ''), '^www\.|/.*$|:.*$', '', 'g'), '')
$_$;


--
-- Name: rev_norm_linkedin(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_norm_linkedin(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $_$
  select nullif(regexp_replace(lower(btrim(coalesce(p, ''))), '^(https?://)?(www\.)?linkedin\.com/in/|/+$|\?.*$', '', 'g'), '')
$_$;


--
-- Name: rev_norm_phone(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_norm_phone(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case
    when p is null or btrim(p) = '' then null
    when regexp_replace(p, '[^0-9+]', '', 'g') ~ '^\+' then regexp_replace(p, '[^0-9+]', '', 'g')
    when length(regexp_replace(p, '[^0-9]', '', 'g')) = 10 then '+1' || regexp_replace(p, '[^0-9]', '', 'g')
    when length(regexp_replace(p, '[^0-9]', '', 'g')) = 11 and left(regexp_replace(p, '[^0-9]', '', 'g'), 1) = '1' then '+' || regexp_replace(p, '[^0-9]', '', 'g')
    when length(regexp_replace(p, '[^0-9]', '', 'g')) >= 8 then '+' || regexp_replace(p, '[^0-9]', '', 'g')
    else null end
$$;


--
-- Name: rev_deals; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.rev_deals (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid DEFAULT spine.default_tenant_id() NOT NULL,
    brand_id uuid,
    company_id uuid,
    primary_person_id uuid,
    title text NOT NULL,
    motion text DEFAULT 'pr'::text NOT NULL,
    pipeline_id uuid NOT NULL,
    stage_id uuid NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    product_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    est_mrr_cents bigint,
    est_one_time_cents bigint,
    owner_lg_id uuid,
    owner_setter_id uuid,
    owner_closer_id uuid,
    source text,
    campaign text,
    channel text,
    quality_score smallint,
    heat_score smallint,
    qualification text,
    budget_band text,
    timing text,
    next_action text,
    next_action_at timestamp with time zone,
    lost_reason text,
    first_touch_at timestamp with time zone,
    last_touch_at timestamp with time zone,
    touches_30d integer DEFAULT 0 NOT NULL,
    no_show_count smallint DEFAULT 0 NOT NULL,
    stage_entered_at timestamp with time zone DEFAULT now() NOT NULL,
    won_at timestamp with time zone,
    lost_at timestamp with time zone,
    client_id uuid,
    ghl_opportunity_id text,
    ghl_location_id text,
    ghl_pushed_at timestamp with time zone,
    intake_created jsonb DEFAULT '{}'::jsonb NOT NULL,
    meta jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_by uuid,
    created_via text DEFAULT 'ui'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    fit_signals jsonb DEFAULT '{}'::jsonb NOT NULL,
    quality_breakdown jsonb,
    heat_breakdown jsonb,
    scored_at timestamp with time zone,
    mql_tier smallint,
    routing text,
    routed_at timestamp with time zone,
    delay_until timestamp with time zone,
    ai_fit_summary text,
    ghl_push_status text,
    ghl_push_error text,
    ghl_eligible_at timestamp with time zone,
    ghl_pipeline_id text,
    ghl_stage_id text,
    ghl_contact_id text,
    CONSTRAINT rev_deals_budget_band_check CHECK (((budget_band IS NULL) OR (budget_band = ANY (ARRAY['none'::text, '500_3k'::text, '3k_7_5k'::text, '7_5k_20k'::text, '20k_plus'::text])))),
    CONSTRAINT rev_deals_created_via_check CHECK ((created_via = ANY (ARRAY['ui'::text, 'import'::text, 'webhook'::text, 'mcp'::text, 'ghl'::text, 'scraper'::text, 'system'::text]))),
    CONSTRAINT rev_deals_est_mrr_cents_check CHECK (((est_mrr_cents IS NULL) OR (est_mrr_cents >= 0))),
    CONSTRAINT rev_deals_est_one_time_cents_check CHECK (((est_one_time_cents IS NULL) OR (est_one_time_cents >= 0))),
    CONSTRAINT rev_deals_ghl_push_status_check CHECK (((ghl_push_status IS NULL) OR (ghl_push_status = ANY (ARRAY['eligible'::text, 'pushed'::text, 'failed'::text, 'skipped'::text])))),
    CONSTRAINT rev_deals_motion_check CHECK ((motion = ANY (ARRAY['pr'::text, 'social'::text, 'both'::text, 'beacon'::text, 'premium'::text, 'low_ticket'::text, 'high_ticket'::text, 'other'::text]))),
    CONSTRAINT rev_deals_mql_tier_check CHECK (((mql_tier IS NULL) OR ((mql_tier >= 1) AND (mql_tier <= 5)))),
    CONSTRAINT rev_deals_qualification_check CHECK (((qualification IS NULL) OR (qualification = ANY (ARRAY['unqualified'::text, 'low_budget'::text, 'qualified'::text, 'high_value'::text, 'premium'::text])))),
    CONSTRAINT rev_deals_quality_score_check CHECK (((quality_score IS NULL) OR ((quality_score >= 0) AND (quality_score <= 25)))),
    CONSTRAINT rev_deals_routing_check CHECK (((routing IS NULL) OR (routing = ANY (ARRAY['book_call'::text, 'setter_outreach'::text, 'nurture'::text, 'beacon_offer'::text, 'manual'::text])))),
    CONSTRAINT rev_deals_status_check CHECK ((status = ANY (ARRAY['open'::text, 'won'::text, 'lost'::text]))),
    CONSTRAINT rev_deals_timing_check CHECK (((timing IS NULL) OR (timing = ANY (ARRAY['immediately'::text, 'within_30'::text, 'after_30'::text, 'unknown'::text])))),
    CONSTRAINT rev_deals_title_check CHECK (((char_length(title) >= 1) AND (char_length(title) <= 240)))
);


--
-- Name: rev_pipeline_deals(uuid[], text, uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_pipeline_deals(p_pipeline_ids uuid[] DEFAULT NULL::uuid[], p_status text DEFAULT 'open'::text, p_owner uuid DEFAULT NULL::uuid, p_source text DEFAULT NULL::text, p_stage uuid DEFAULT NULL::uuid, p_q text DEFAULT NULL::text) RETURNS SETOF public.rev_deals
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select d.*
    from public.rev_deals d
   where (p_pipeline_ids is null or d.pipeline_id = any(p_pipeline_ids))
     and (p_status = 'all' or d.status = p_status)
     and (p_owner is null or p_owner in (d.owner_lg_id, d.owner_setter_id, d.owner_closer_id))
     and (p_source is null or d.source = p_source)
     and (p_stage is null or d.stage_id = p_stage)
     and (p_q is null
          or d.title ilike '%' || p_q || '%'
          or exists (select 1 from public.rev_people p
                      where p.id = d.primary_person_id
                        and (p.display_name ilike '%' || p_q || '%' or p.email_key like '%' || lower(p_q) || '%'))
          or exists (select 1 from public.rev_brands b
                      where b.id = d.brand_id and b.name ilike '%' || p_q || '%'))
$$;




--
-- Name: rev_pipeline_summary(uuid[], text, uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_pipeline_summary(p_pipeline_ids uuid[] DEFAULT NULL::uuid[], p_status text DEFAULT 'open'::text, p_owner uuid DEFAULT NULL::uuid, p_source text DEFAULT NULL::text, p_stage uuid DEFAULT NULL::uuid, p_q text DEFAULT NULL::text) RETURNS TABLE(stage_id uuid, deals bigint, value_cents bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select d.stage_id,
         count(*)::bigint,
         coalesce(sum(coalesce(d.est_mrr_cents, 0) + coalesce(d.est_one_time_cents, 0)), 0)::bigint
    from public.rev_pipeline_deals(p_pipeline_ids, p_status, p_owner, p_source, p_stage, p_q) d
   group by d.stage_id
$$;




--
-- Name: rev_referrals_milestone_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_referrals_milestone_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare ref public.rev_referrals%rowtype; v_slug text; rule jsonb; c public.rev_contracts%rowtype; m int; v_pct numeric;
begin
  if pg_trigger_depth() > 3 then return null; end if;
  for ref in select * from public.rev_referrals r where r.deal_id = new.id and r.status in ('referred', 'call_reached') loop
    rule := public.rev_commission_rule(ref.referrer_kind);
    select s.slug into v_slug from public.rev_stages s where s.id = new.stage_id;
    if ref.status = 'referred' and (v_slug in ('booked', 'discovery-booked', 'discovery-taken', 'sales-booked', 'demo', 'discovery', 'offer', 'contract-sent') or new.status = 'won') then
      update public.rev_referrals set status = 'call_reached', reached_call_at = now() where id = ref.id;
      if (rule->>'intro_cents')::bigint > 0 then
        insert into public.rev_commission_payouts (referral_id, kind, amount_cents, note) values (ref.id, 'intro_bonus', (rule->>'intro_cents')::bigint, 'Intro reached a call')
        on conflict do nothing;
      end if;
      ref.status := 'call_reached';
    end if;
    if new.status = 'won' and ref.status <> 'closed' then
      select * into c from public.rev_contracts where deal_id = new.id and status = 'signed' order by signed_at desc limit 1;
      v_pct := (rule->>'pct')::numeric;
      update public.rev_referrals set status = 'closed', closed_at = now(), commission = rule || jsonb_build_object('mrr_cents', coalesce(c.mrr_cents, new.est_mrr_cents, 0), 'contract_id', c.id) where id = ref.id;
      if v_pct > 0 and coalesce(c.mrr_cents, new.est_mrr_cents, 0) > 0 then
        for m in 0..((rule->>'months')::int - 1) loop
          insert into public.rev_commission_payouts (referral_id, kind, period_month, amount_cents, basis_cents, pct, note)
          values (ref.id, 'monthly_pct', (date_trunc('month', coalesce(c.starts_on, current_date)) + make_interval(months => m))::date,
                  round(coalesce(c.mrr_cents, new.est_mrr_cents, 0) * v_pct / 100), coalesce(c.mrr_cents, new.est_mrr_cents, 0), v_pct, 'Month ' || (m + 1) || ' of ' || (rule->>'months'))
          on conflict do nothing;
        end loop;
      end if;
    end if;
    if new.status = 'lost' then update public.rev_referrals set status = 'lost' where id = ref.id; end if;
  end loop;
  return null;
end
$$;


--
-- Name: rev_rescore(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_rescore(p_deal uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  d public.rev_deals%rowtype;
  q jsonb; h jsonb;
  v_tier smallint;
  v_qual text;
  v_routing text;
  v_lane text;
  v_delay timestamptz;
begin
  if public.is_portal_user() then raise exception 'revenue: not allowed from the client portal' using errcode = '42501'; end if;
  select * into d from public.rev_deals where id = p_deal;
  if d.id is null then return null; end if;
  q := public.rev_compute_quality(p_deal);
  h := public.rev_compute_heat(p_deal);
  v_tier := public.rev_budget_tier(coalesce(d.budget_band, d.fit_signals->>'budget_band'));
  v_qual := case v_tier when 1 then 'unqualified' when 2 then 'low_budget' when 3 then 'qualified' when 4 then 'high_value' when 5 then 'premium' else d.qualification end;
  select p.lane into v_lane from public.rev_pipelines p where p.id = d.pipeline_id;
  v_routing := d.routing;
  if d.status = 'open' and d.routing is distinct from 'manual' and v_tier is not null and v_lane in ('marketing', 'lead_gen', 'setter') then
    v_routing := case
      when v_tier >= public.rev_cfg_num('r_book_min_tier', 3) then 'book_call'
      when v_tier = public.rev_cfg_num('r_setter_tier', 2) then 'setter_outreach'
      else 'nurture' end;
  end if;
  v_delay := d.delay_until;
  if d.no_show_count >= public.rev_cfg_num('h_no_show_delay_count', 3) and (v_delay is null or v_delay < now()) then
    v_delay := now() + make_interval(days => public.rev_cfg_num('h_no_show_delay_days', 90)::int);
  end if;

  update public.rev_deals set
    -- stored on the /25 scale the doc uses (0121 CHECK): raw total and max live in the breakdown
    quality_score = least(greatest(round((q->>'total')::numeric / greatest((q->>'max')::numeric, 1) * 25), 0), 25)::smallint,
    heat_score = (h->>'total')::numeric::smallint,
    quality_breakdown = q,
    heat_breakdown = h,
    qualification = v_qual,
    mql_tier = v_tier,
    budget_band = coalesce(budget_band, nullif(fit_signals->>'budget_band', '')),
    timing = coalesce(timing, case when fit_signals->>'timing' in ('immediately', 'within_30', 'after_30', 'unknown') then fit_signals->>'timing' end),
    routing = v_routing,
    routed_at = case when v_routing is distinct from routing then now() else routed_at end,
    delay_until = v_delay,
    scored_at = now()
  where id = p_deal;

  if v_routing is distinct from d.routing and v_routing is not null then
    perform public.rev_route_notify(p_deal, v_routing);
    insert into public.rev_activities (deal_id, person_id, brand_id, kind, actor_kind, subject, is_touch, meta)
    values (p_deal, d.primary_person_id, d.brand_id, 'system', 'system', 'Routed: ' || replace(v_routing, '_', ' ') || ' (tier ' || coalesce(v_tier::text, '?') || ', ' || (q->>'total') || '-' || (h->>'total') || ')', false,
            jsonb_build_object('routing', v_routing, 'tier', v_tier, 'quality', q->>'total', 'heat', h->>'total'));
  end if;
  return jsonb_build_object('quality', q->>'total', 'heat', h->>'total', 'tier', v_tier, 'routing', v_routing, 'delay_until', v_delay);
end
$$;


--
-- Name: rev_route_notify(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_route_notify(p_deal uuid, p_routing text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  d public.rev_deals%rowtype;
  v_owner uuid;
  v_sla int := public.rev_cfg_num('r_setter_sla_minutes', 60)::int;
  v_title text;
  v_body text;
begin
  select * into d from public.rev_deals where id = p_deal;
  if d.id is null then return; end if;
  v_owner := coalesce(d.owner_setter_id, d.owner_lg_id, d.owner_closer_id);
  v_title := case p_routing
    when 'book_call'       then 'Hot lead: ' || d.title
    when 'setter_outreach' then 'Reach out now: ' || d.title
    when 'beacon_offer'    then 'Beacon fit: ' || d.title
    when 'nurture'         then 'Nurture: ' || d.title
    else 'Routed: ' || d.title end;
  v_body := case p_routing
    when 'book_call'       then 'Budget tier ' || coalesce(d.mql_tier::text, '?') || ' — booking link offered. Confirm the call lands on the calendar.'
    when 'setter_outreach' then 'Budget tier 2 — call within ' || v_sla || ' minutes, email at 1 hour. Beacon is the likely fit.'
    when 'beacon_offer'    then 'Low budget — route to the Beacon offer.'
    when 'nurture'         then 'No budget — thank-you email + nurture; book if they insist.'
    else null end;
  if v_owner is not null then
    insert into public.notifications (user_id, kind, title, body, href, dedupe_key)
    values (v_owner, 'revenue', v_title, v_body, '/prospects/deals/' || d.id, 'rev:route:' || d.id || ':' || p_routing)
    on conflict (user_id, dedupe_key) where dedupe_key is not null do nothing;
  end if;
  if p_routing = 'setter_outreach' then
    insert into public.rev_tasks (deal_id, person_id, owner_id, title, body_md, due_at, created_by_kind)
    select d.id, d.primary_person_id, v_owner, 'Reach out within ' || v_sla || ' minutes', 'Tier-2 lead (' || coalesce(d.source, 'unknown source') || '). Call first, email at 1 hour if no answer.', now() + make_interval(mins => v_sla), 'automation'
    where not exists (select 1 from public.rev_tasks t where t.deal_id = d.id and t.created_by_kind = 'automation' and t.done_at is null and t.title like 'Reach out within%');
  end if;
end
$$;


--
-- Name: rev_scrape_exported(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_scrape_exported(p_job uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare n int;
begin
  if auth.uid() is not null and not public.can_run_scrapers() then
    raise exception 'revenue: export needs the scraper capability' using errcode = '42501';
  end if;
  insert into public.rev_activities (deal_id, person_id, kind, channel, direction, actor_id, actor_kind, subject, is_touch, external_source, external_id, meta)
  -- one note per deal per job: several scraper rows can land on the same deal
  -- (dedupe by LinkedIn / email / brand), and the deal should read it once
  select distinct on (r.rev_deal_id)
         r.rev_deal_id, r.rev_person_id, 'system', 'web', 'internal', auth.uid(), case when auth.uid() is null then 'system' else 'human' end,
         'Exported to CSV for a sequence', false, 'scraper_export', p_job::text || ':' || r.rev_deal_id::text, jsonb_build_object('job_id', p_job)
    from public.scraped_records r
   where r.job_id = p_job and r.rev_deal_id is not null
   order by r.rev_deal_id, r.created_at, r.id
  on conflict do nothing;
  get diagnostics n = row_count;
  return n;
end
$$;


--
-- Name: rev_sla_sweep(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_sla_sweep() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare n int := 0; r record;
begin
  for r in
    select d.id, d.title, d.stage_entered_at, s.name, s.sla_hours, coalesce(d.owner_setter_id, d.owner_closer_id, d.owner_lg_id) as owner_id
      from public.rev_deals d join public.rev_stages s on s.id = d.stage_id
     where d.status = 'open' and s.sla_hours is not null and d.stage_entered_at < now() - make_interval(hours => s.sla_hours)
       and (d.delay_until is null or d.delay_until < now())
       -- 0155: a stage entry that predates the GHL import is history, not a breach
       and not (d.meta ? 'imported_at' and d.stage_entered_at <= (d.meta->>'imported_at')::timestamptz)
  loop
    if r.owner_id is not null then
      perform public.rev_bell(r.owner_id, 'revenue', 'SLA breached: ' || r.title, r.name || ' allows ' || r.sla_hours || 'h.', '/prospects/deals/' || r.id, 'rev:sla:' || r.id || ':' || to_char(r.stage_entered_at, 'YYYYMMDDHH24MI'));
      n := n + 1;
    end if;
  end loop;
  return n;
end
$$;


--
-- Name: rev_task_default_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_task_default_owner() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.owner_id is null and new.deal_id is not null then
    new.owner_id := public.rev_deal_responsible(new.deal_id);
  end if;
  return new;
end;
$$;


--
-- Name: rev_task_to_work(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_task_to_work() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if current_setting('app.rev_task_sync', true) = 'on' then
    return null;
  end if;
  begin
    perform set_config('app.rev_task_sync', 'on', true);
    if tg_op = 'DELETE' then
      delete from public.projects where source_kind = 'rev_task' and source_id = old.id::text;
    elsif tg_op = 'INSERT' then
      perform public.rev_task_work_upsert(new, true);
    else
      perform public.rev_task_work_upsert(new,
        (old.owner_id is null and new.owner_id is not null)
        or (old.done_at is not null and new.done_at is null));
    end if;
    perform set_config('app.rev_task_sync', 'off', true);
  exception when others then
    raise warning 'rev_task_to_work(%): %', coalesce(new.id, old.id), sqlerrm;
  end;
  return null;
end;
$$;


--
-- Name: rev_tasks; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.rev_tasks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid DEFAULT spine.default_tenant_id() NOT NULL,
    deal_id uuid,
    person_id uuid,
    owner_id uuid,
    title text NOT NULL,
    body_md text,
    due_at timestamp with time zone,
    done_at timestamp with time zone,
    created_by uuid,
    created_by_kind text DEFAULT 'human'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT rev_tasks_anchor CHECK (((deal_id IS NOT NULL) OR (person_id IS NOT NULL))),
    CONSTRAINT rev_tasks_created_by_kind_check CHECK ((created_by_kind = ANY (ARRAY['human'::text, 'ai'::text, 'automation'::text]))),
    CONSTRAINT rev_tasks_title_check CHECK (((char_length(title) >= 1) AND (char_length(title) <= 300)))
);


--
-- Name: rev_task_work_upsert(public.rev_tasks, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rev_task_work_upsert(t public.rev_tasks, p_may_create boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_id uuid; v_status text; v_done boolean; v_deal text; v_url text; v_name text; v_body text; v_new_status text; v_ends date;
begin
  select id, status into v_id, v_status from public.projects where source_kind = 'rev_task' and source_id = t.id::text;
  if v_id is null and (not p_may_create or t.owner_id is null or t.done_at is not null) then
    return;
  end if;

  select d.title into v_deal from public.rev_deals d where d.id = t.deal_id;
  v_url := case when t.deal_id is not null then '/prospects/deals/' || t.deal_id else '/prospects/people/' || t.person_id end;
  v_name := left(t.title || coalesce(' · ' || v_deal, ''), 300);
  v_body := '_From Prospects: [' || coalesce(v_deal, 'open the prospect') || '](' || v_url || ')_';
  v_ends := (t.due_at at time zone 'UTC')::date;

  if v_id is null then
    insert into public.projects (name, kind, status, owner_id, created_by, ends_at, description_md, source_kind, source_id, source_url, priority)
    values (v_name, 'task', 'to_do', t.owner_id, coalesce(t.created_by, t.owner_id), v_ends, v_body, 'rev_task', t.id::text, v_url, 'medium')
    on conflict (source_kind, source_id) do nothing;
    return;
  end if;

  select coalesce(bool_or(s.is_completion or s.is_terminal), false) into v_done from public.work_item_statuses s where s.slug = v_status;
  v_new_status := case
    when t.done_at is not null and not v_done then 'done'
    when t.done_at is null and v_done then 'to_do'
    else v_status
  end;

  update public.projects
     set name = v_name, description_md = v_body, owner_id = t.owner_id, ends_at = v_ends, status = v_new_status, source_url = v_url
   where id = v_id
     and (name, description_md, owner_id, ends_at, status, source_url)
         is distinct from (v_name, v_body, t.owner_id, v_ends, v_new_status, v_url);
end;
$$;


--
-- Name: scrape_job_estimated_usd(text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scrape_job_estimated_usd(p_preset text, p_status text, p_max_results integer, p_found integer) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select round(
    (case
       when p_status in ('running', 'importing') then greatest(p_max_results, p_found)
       when p_status = 'queued' then 0
       else p_found
     end)::numeric
    * coalesce((select (s.cost_per_1000 ->> p_preset)::numeric from public.scraper_settings s where s.id = 1), 0)
    / 1000.0,
    2);
$$;


--
-- Name: scrape_jobs_budget_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scrape_jobs_budget_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_cap numeric;
  v_spent numeric;
  v_commit numeric;
begin
  if old.status = 'queued' and new.status = 'running' then
    select s.monthly_budget_usd into v_cap from public.scraper_settings s where s.id = 1;
    if v_cap is not null then
      v_spent := public.scraper_month_spend_usd(new.id);
      v_commit := public.scrape_job_estimated_usd(new.preset, 'running', new.max_results, new.found);
      if v_spent + v_commit > v_cap then
        raise exception 'SCRAPER_BUDGET_CAP: monthly scraper budget cap reached ($% of $% used this month; this run would add $%). Raise the cap on Admin -> Lead Scraper or wait for next month.',
          to_char(v_spent, 'FM999999990.00'), to_char(v_cap, 'FM999999990.00'), to_char(v_commit, 'FM999999990.00')
          using errcode = 'check_violation';
      end if;
    end if;
    -- A held job carries the refusal in `error`; clear it when it finally goes.
    new.error := null;
  end if;
  return new;
end;
$_$;


--
-- Name: scraper_budget_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scraper_budget_status() RETURNS TABLE(monthly_budget_usd numeric, spent_usd numeric, remaining_usd numeric, over_cap boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select
    s.monthly_budget_usd,
    public.scraper_month_spend_usd() as spent_usd,
    case when s.monthly_budget_usd is null then null
         else greatest(s.monthly_budget_usd - public.scraper_month_spend_usd(), 0) end as remaining_usd,
    (s.monthly_budget_usd is not null and public.scraper_month_spend_usd() >= s.monthly_budget_usd) as over_cap
  from public.scraper_settings s
  where s.id = 1;
$$;


--
-- Name: scraper_month_spend_usd(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scraper_month_spend_usd(p_exclude_job uuid DEFAULT NULL::uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(sum(public.scrape_job_estimated_usd(j.preset, j.status, j.max_results, j.found)), 0)
  from public.scrape_jobs j
  where j.created_at >= date_trunc('month', now() at time zone 'utc') at time zone 'utc'
    and (p_exclude_job is null or j.id <> p_exclude_job);
$$;


