--
-- Name: staff_request_design_to_work_item(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_request_design_to_work_item() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_id uuid;
begin
  if new.kind <> 'design_project' or new.status <> 'approved' or old.status = 'approved' then
    return new;
  end if;
  begin
    insert into public.projects (name, kind, status, owner_id, created_by, description_md, source_kind, source_id, priority)
    values (
      new.title, 'task', 'to_do', new.requester_id, coalesce(new.decided_by, new.requester_id),
      coalesce(new.body_md, '') || E'\n\n_Created from an approved design request (' || new.id::text || ')._',
      'staff_request', new.id::text, 'medium')
    on conflict (source_kind, source_id) do nothing;
    select id into v_id from public.projects where source_kind = 'staff_request' and source_id = new.id::text;
    if v_id is not null then
      new.subject_table := 'projects';
      new.subject_id := v_id::text;
    end if;
  exception when others then
    raise warning 'staff_request_design_to_work_item(%): %', new.id, sqlerrm;
  end;
  return new;
end;
$$;




--
-- Name: staff_request_position_effect(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_request_position_effect() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_pos uuid; v_slug text; v_dept uuid; v_comp_level text; v_mult numeric;
begin
  if new.kind <> 'position_request' or new.status = old.status then return new; end if;
  v_pos := nullif(new.payload->>'position_id', '')::uuid;
  if new.status = 'approved' then
    if v_pos is null then
      v_slug := regexp_replace(lower(btrim(new.payload->>'role_title')), '[^a-z0-9]+', '-', 'g');
      v_slug := btrim(v_slug, '-');
      if v_slug = '' or v_slug !~ '^[a-z0-9]' then v_slug := 'role'; end if;
      v_slug := left(v_slug, 60) || '-' || to_char(now(), 'yymmdd') || '-' || left(replace(gen_random_uuid()::text, '-', ''), 4);
      select t.id into v_dept from public.tags t where t.category = 'department' and lower(t.label) = lower(coalesce(new.payload->>'department', '')) limit 1;
      insert into public.hire_positions (brand, title, slug, status, department_tag_id, department_label, employment_type, headcount, hiring_manager_id, requested_by, request_id, approved_by, approved_at, target_start_on, pay_level, created_by, updated_by, notes_md)
      values (coalesce(nullif(new.payload->>'brand', ''), 'main'),
              left(btrim(new.payload->>'role_title'), 160), v_slug, 'approved', v_dept, nullif(new.payload->>'department', ''),
              coalesce(new.payload->>'employment_type', 'full_time'),
              greatest(1, least(50, coalesce((new.payload->>'headcount')::int, 1))),
              coalesce(nullif(new.payload->>'hiring_manager_id', '')::uuid, new.requester_id),
              new.requester_id, new.id, new.decided_by, now(),
              nullif(new.payload->>'target_start_on', '')::date,
              (select slug from public.hire_pay_levels where slug = new.payload->>'pay_level'),
              new.requester_id, new.decided_by, new.body_md)
      returning id into v_pos;
    else
      update public.hire_positions
         set status = 'approved', approved_by = new.decided_by, approved_at = now(), request_id = new.id, updated_by = new.decided_by
       where id = v_pos and status in ('draft', 'pending_approval');
    end if;
    v_comp_level := new.payload->>'pay_level';
    v_mult := nullif(new.payload->>'pay_multiplier', '')::numeric;
    if v_pos is not null and v_comp_level is not null and v_mult is not null
       and exists (select 1 from public.hire_pay_levels where slug = v_comp_level) then
      insert into public.hire_position_comp (position_id, pay_multiplier, pay_level, step, updated_by)
      values (v_pos, v_mult, v_comp_level, 1, new.decided_by)
      on conflict (position_id) do update set pay_multiplier = excluded.pay_multiplier, pay_level = excluded.pay_level, updated_by = excluded.updated_by;
    end if;
    if nullif(new.payload->>'posting_budget_usd', '') is not null and v_pos is not null then
      update public.hire_positions set posting_budget_cents = ((new.payload->>'posting_budget_usd')::numeric * 100)::bigint where id = v_pos;
    end if;
    new.subject_table := 'hire_positions';
    new.subject_id := v_pos::text;
  elsif new.status in ('denied', 'withdrawn') and v_pos is not null then
    update public.hire_positions set status = 'draft', updated_by = coalesce(new.decided_by, new.requester_id)
     where id = v_pos and status = 'pending_approval';
  end if;
  return new;
end;
$$;


--
-- Name: stamp_project_completion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stamp_project_completion() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
	was_done boolean;
	is_done  boolean;
begin
	if new.status is not distinct from old.status then
		return new;
	end if;

	-- A slug can exist in several kind configs; if ANY of them calls it a
	-- completion, it is one.
	select coalesce(bool_or(is_completion), false) into was_done
		from public.work_item_statuses where slug = old.status;
	select coalesce(bool_or(is_completion), false) into is_done
		from public.work_item_statuses where slug = new.status;

	if is_done and not was_done then
		-- Only stamp if unset, so reopening and re-closing keeps the FIRST
		-- completion rather than silently moving the item between months.
		new.completed_at := coalesce(new.completed_at, now());
	elsif was_done and not is_done then
		new.completed_at := null;
	end if;

	return new;
end;
$$;


--
-- Name: stripe_confirm_match(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stripe_confirm_match(p_customer_id uuid, p_client_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if not (select public.is_admin() or exists (select 1 from public.profiles where id = auth.uid() and role in ('exec', 'manager'))) then
    raise exception 'stripe_confirm_match: admin/exec/manager only' using errcode = '42501';
  end if;
  update public.stripe_customers
     set client_id = p_client_id,
         match_status = 'matched',
         match_reason = 'manual',
         matched_by = auth.uid(),
         matched_at = now()
   where id = p_customer_id;
end
$$;


