-- Name: stripe_email_domain(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stripe_email_domain(p_email text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select public.stripe_normalize_domain(split_part(p_email, '@', 2)) -- email domain, not the whole address
$$;


--
-- Name: stripe_ignore_match(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stripe_ignore_match(p_customer_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if not (select public.is_admin() or exists (select 1 from public.profiles where id = auth.uid() and role in ('exec', 'manager'))) then
    raise exception 'stripe_ignore_match: admin/exec/manager only' using errcode = '42501';
  end if;
  update public.stripe_customers set match_status = 'ignored', match_reason = 'manual: not a client' where id = p_customer_id;
end
$$;


--
-- Name: stripe_match_customers(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stripe_match_customers(p_account_label text DEFAULT 'beacon'::text) RETURNS TABLE(matched_count integer, review_count integer, unmatched_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_matched int := 0;
  v_review int := 0;
  v_unmatched int := 0;
  r record;
  v_candidates jsonb;
  v_single uuid;
  v_domain text;
begin
  for r in
    select sc.id, sc.email
    from public.stripe_customers sc
    where sc.account_label = p_account_label
      and sc.match_status in ('unmatched', 'review')
      and sc.deleted = false
  loop
    v_candidates := '[]'::jsonb;

    -- 1. email exact match through contacts linked to a contract's client.
    select jsonb_agg(distinct jsonb_build_object('client_id', c.id, 'display_name', c.display_name, 'reason', 'email exact'))
      into v_candidates
    from public.contacts ct
    join public.client_contacts cc on cc.contact_id = ct.id
    join public.contracts co on co.airtable_contract_id = cc.airtable_contract_id
    join public.clients_v2 c on c.id = co.client_id
    where r.email is not null and lower(ct.email) = lower(r.email);

    -- 2. fall back to a domain match against the client's website, only when
    --    the email match found nothing (a weaker signal; still never used to
    --    override an email hit).
    if v_candidates is null or jsonb_array_length(v_candidates) = 0 then
      v_domain := public.stripe_email_domain(r.email);
      if v_domain is not null then
        select jsonb_agg(distinct jsonb_build_object('client_id', c.id, 'display_name', c.display_name, 'reason', 'domain match'))
          into v_candidates
        from public.client_meta cm
        join public.contracts co on co.airtable_contract_id = cm.airtable_contract_id
        join public.clients_v2 c on c.id = co.client_id
        where public.stripe_normalize_domain(cm.website_url) = v_domain;
      end if;
    end if;
    v_candidates := coalesce(v_candidates, '[]'::jsonb);

    if jsonb_array_length(v_candidates) = 1 then
      v_single := (v_candidates->0->>'client_id')::uuid;
      update public.stripe_customers
         set client_id = v_single,
             match_status = 'matched',
             match_reason = v_candidates->0->>'reason',
             match_candidates = v_candidates,
             matched_at = now(),
             matched_by = null
       where id = r.id;
      v_matched := v_matched + 1;
    elsif jsonb_array_length(v_candidates) > 1 then
      update public.stripe_customers
         set match_status = 'review',
             match_reason = 'multiple candidates',
             match_candidates = v_candidates
       where id = r.id;
      v_review := v_review + 1;
    else
      update public.stripe_customers
         set match_status = 'unmatched',
             match_reason = null,
             match_candidates = '[]'::jsonb
       where id = r.id;
      v_unmatched := v_unmatched + 1;
    end if;
  end loop;

  return query select v_matched, v_review, v_unmatched;
end
$$;


--
-- Name: stripe_normalize_domain(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stripe_normalize_domain(p_text text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case
    when p_text is null or trim(p_text) = '' then null
    else lower(regexp_replace(regexp_replace(trim(p_text), '^[a-z]+://', '', 'i'), '^www\.', '', 'i'))
  end
$$;


--
-- Name: sync_scrape_review_to_work_runs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_scrape_review_to_work_runs() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_job uuid;
begin
  if tg_op = 'DELETE' then
    for v_job in select distinct job_id from old_rows loop
      perform public.work_engine_sync('scrape_jobs', v_job);
    end loop;
  else
    for v_job in select distinct job_id from new_rows loop
      perform public.work_engine_sync('scrape_jobs', v_job);
    end loop;
  end if;
  return null;
end;
$$;


--
-- Name: sync_to_work_runs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_to_work_runs() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'DELETE' then
    perform public.work_engine_sync(tg_table_name, old.id);
    return old;
  end if;
  perform public.work_engine_sync(tg_table_name, new.id);
  return new;
end;
$$;


--
-- Name: sync_work_item_primary_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_work_item_primary_owner() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
	if tg_op = 'UPDATE' and new.owner_id is not distinct from old.owner_id then
		return null;
	end if;
	delete from public.work_item_owners
	where work_item_id = new.id and is_primary
	  and (new.owner_id is null or user_id <> new.owner_id);
	if new.owner_id is not null then
		insert into public.work_item_owners (work_item_id, user_id, is_primary)
		values (new.id, new.owner_id, true)
		on conflict (work_item_id, user_id) do update set is_primary = true;
	end if;
	return null;
end;
$$;


--
-- Name: user_capabilities_r6_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_capabilities_r6_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_capability text := coalesce(new.capability, old.capability);
begin
  if v_capability = 'acquisitions'
     and auth.uid() is not null
     and auth.uid() <> 'a0c633df-d69c-45b6-800a-73679692c645'::uuid then
    raise exception 'R6: the acquisitions capability can only be granted or revoked by Alex.'
      using errcode = 'insufficient_privilege';
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


--
-- Name: work_engine_sync(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.work_engine_sync(p_table text, p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  r record;
  v_domain text; v_kind text; v_title text; v_status text;
  v_payload jsonb := '{}'::jsonb; v_result jsonb; v_error text;
  v_requested_by uuid; v_via text := 'ui'; v_group text;
  v_approved_by uuid; v_approved_at timestamptz;
  v_client uuid; v_work_item uuid; v_parent uuid; v_cost numeric(10,4);
  v_created timestamptz; v_started timestamptz; v_finished timestamptz;
  v_pending int;
begin
  if p_table = 'scrape_jobs' then
    select * into r from public.scrape_jobs where id = p_id;
    if not found then
      delete from public.work_runs where source_table = p_table and source_id = p_id::text;
      return;
    end if;
    select count(*) into v_pending from public.scraped_records where job_id = r.id and status = 'pending';
    v_domain := 'scrape'; v_kind := r.preset;
    v_title := r.kind || ' scrape: ' || r.preset || ' (' || r.found || ' found, ' || v_pending || ' to review)';
    v_status := case r.status
      when 'queued' then 'queued'
      when 'running' then 'running'
      when 'importing' then 'running'
      when 'done' then case when v_pending > 0 then 'waiting_approval' else 'done' end
      when 'failed' then 'failed'
      when 'cancelled' then 'cancelled'
      else 'queued' end;
    v_payload := jsonb_build_object('kind', r.kind, 'preset', r.preset, 'max_results', r.max_results, 'params', r.params);
    v_result := jsonb_build_object('found', r.found, 'imported', r.imported, 'duplicates', r.duplicates, 'pending_review', v_pending);
    v_error := r.error; v_requested_by := r.requested_by; v_via := 'ui';
    v_created := r.created_at; v_started := r.started_at; v_finished := r.finished_at;

  elsif p_table = 'staff_requests' then
    select s.*, g.key as group_key into r
      from public.staff_requests s
      left join public.reviewer_groups g on g.id = s.reviewer_group_id
     where s.id = p_id;
    if not found then
      delete from public.work_runs where source_table = p_table and source_id = p_id::text;
      return;
    end if;
    v_domain := 'staff_request'; v_kind := r.kind; v_title := r.title;
    v_status := case r.status
      when 'pending' then 'waiting_approval'
      when 'in_review' then 'waiting_approval'
      when 'approved' then 'approved'
      when 'denied' then 'rejected'
      when 'completed' then 'done'
      when 'withdrawn' then 'cancelled'
      else 'waiting_approval' end;
    v_payload := jsonb_build_object('legacy_status', r.status, 'subject_table', r.subject_table, 'subject_id', r.subject_id);
    v_result := case when r.decision_note_md is null then null else jsonb_build_object('decision_note', r.decision_note_md) end;
    v_requested_by := r.requester_id; v_group := r.group_key;
    v_approved_by := r.decided_by; v_approved_at := r.decided_at;
    v_created := r.created_at;
    v_finished := case when r.status in ('denied', 'completed', 'withdrawn') then coalesce(r.decided_at, r.updated_at) end;

  elsif p_table = 'content_jobs' then
    select * into r from public.content_jobs where id = p_id;
    if not found then
      delete from public.work_runs where source_table = p_table and source_id = p_id::text;
      return;
    end if;
    v_domain := 'content'; v_kind := r.capability;
    v_title := replace(r.capability, '_', ' ') || ' via ' || r.provider;
    v_status := case r.status
      when 'queued' then 'queued'
      when 'submitted' then 'running'
      when 'running' then 'running'
      when 'done' then 'done'
      when 'failed' then 'failed'
      when 'cancelled' then 'cancelled'
      else 'queued' end;
    v_payload := jsonb_build_object('provider', r.provider, 'capability', r.capability, 'consumer_slug', r.consumer_slug, 'provider_ref', r.provider_ref);
    v_error := r.error; v_requested_by := r.requested_by;
    v_via := case when r.requested_via in ('ui', 'mcp', 'skill') then r.requested_via else 'system' end;
    v_cost := r.cost_usd;
    -- content_jobs.client_id / work_item_id are bare uuids (no FK); only
    -- carry them when they resolve, or the work_runs FK would refuse the row.
    select id into v_client from public.clients_v2 where id = r.client_id;
    select id into v_work_item from public.tasks where id = r.work_item_id;
    select w.id into v_parent from public.work_runs w where w.source_table = 'content_jobs' and w.source_id = r.parent_job_id::text;
    v_created := r.created_at; v_started := r.submitted_at; v_finished := r.finished_at;

  elsif p_table = 'import_batches' then
    select * into r from public.import_batches where id = p_id;
    if not found then
      delete from public.work_runs where source_table = p_table and source_id = p_id::text;
      return;
    end if;
    v_domain := 'import'; v_kind := r.target;
    v_title := 'Import ' || coalesce(r.file_name, '(no file)') || ' into ' || r.target || coalesce(' / ' || r.target_ref, '');
    v_status := case r.status
      when 'draft' then 'queued'
      when 'uploaded' then 'queued'
      when 'targeted' then 'queued'
      when 'mapped' then 'queued'
      when 'dry_run' then 'running'
      when 'committing' then 'running'
      when 'committed' then 'done'
      when 'rolled_back' then 'cancelled'
      when 'failed' then 'failed'
      else 'queued' end;
    v_payload := jsonb_build_object('legacy_status', r.status, 'target', r.target, 'target_ref', r.target_ref, 'file_name', r.file_name, 'row_count', r.row_count);
    v_result := jsonb_build_object('inserted', r.insert_count, 'updated', r.update_count, 'rejected', r.reject_count, 'progress', r.progress);
    v_error := r.error; v_requested_by := r.requested_by;
    v_created := r.created_at; v_finished := coalesce(r.committed_at, r.rolled_back_at);

  elsif p_table = 'automation_runs' then
    -- 0101 creates the table; this branch is only reached once it exists.
    select a.*, ru.name as rule_name, ru.slug as rule_slug, ru.approver_group as rule_group, ru.client_id as rule_client
      into r
      from public.automation_runs a
      join public.automation_rules ru on ru.id = a.rule_id
     where a.id = p_id;
    if not found then
      delete from public.work_runs where source_table = p_table and source_id = p_id::text;
      return;
    end if;
    v_domain := 'automation'; v_kind := r.rule_slug; v_title := r.rule_name;
    v_status := r.status;
    v_payload := jsonb_build_object('rule_id', r.rule_id, 'trigger', r.trigger_payload);
    v_result := r.step_results; v_error := r.error;
    v_requested_by := r.requested_by; v_via := r.requested_via; v_group := r.rule_group;
    v_approved_by := r.approved_by; v_approved_at := r.approved_at;
    v_client := r.rule_client;
    v_created := r.created_at; v_started := r.started_at; v_finished := r.finished_at;

  else
    raise exception 'work_engine_sync: unknown table %', p_table;
  end if;

  perform set_config('work_engine.sync', 'on', true);
  insert into public.work_runs as w (
    domain, kind, title, status, payload, result, error,
    requested_by, requested_via, approver_group, approved_by, approved_at,
    client_id, work_item_id, parent_run_id, cost_usd,
    source_table, source_id, created_at, started_at, finished_at
  ) values (
    v_domain, v_kind, left(v_title, 300), v_status, v_payload, v_result, v_error,
    v_requested_by, v_via, v_group, v_approved_by, v_approved_at,
    v_client, v_work_item, v_parent, v_cost,
    p_table, p_id::text, coalesce(v_created, now()), v_started, v_finished
  )
  on conflict (source_table, source_id) where source_table is not null do update set
    kind = excluded.kind, title = excluded.title, status = excluded.status,
    payload = excluded.payload, result = excluded.result, error = excluded.error,
    requested_by = excluded.requested_by, requested_via = excluded.requested_via,
    approver_group = excluded.approver_group, approved_by = excluded.approved_by, approved_at = excluded.approved_at,
    client_id = excluded.client_id, work_item_id = excluded.work_item_id, parent_run_id = excluded.parent_run_id,
    cost_usd = excluded.cost_usd, started_at = excluded.started_at, finished_at = excluded.finished_at;
  perform set_config('work_engine.sync', 'off', true);
exception when others then
  perform set_config('work_engine.sync', 'off', true);
  raise warning 'work_engine_sync(%, %) skipped: %', p_table, p_id, sqlerrm;
end;
$$;


--
-- Name: work_item_add_follower(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.work_item_add_follower(p_item uuid, p_user uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
	if auth.uid() is null then
		raise exception 'Not signed in' using errcode = '42501';
	end if;
	if not public.has_module_access('the_work') then
		raise exception 'No access to The Work' using errcode = '42501';
	end if;
	if not exists (select 1 from public.projects where id = p_item) then
		raise exception 'Work item not found' using errcode = 'P0002';
	end if;
	if not exists (select 1 from public.profiles where id = p_user and is_active) then
		raise exception 'That person is not an active member' using errcode = 'P0002';
	end if;
	insert into public.work_item_followers (work_item_id, user_id)
	values (p_item, p_user)
	on conflict do nothing;
end;
$$;


--
-- Name: work_item_owner_autofollow(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.work_item_owner_autofollow() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
	if new.owner_id is not null and (tg_op = 'INSERT' or new.owner_id is distinct from old.owner_id) then
		insert into public.work_item_followers (work_item_id, user_id)
		values (new.id, new.owner_id)
		on conflict do nothing;
	end if;
	return null;
end;
$$;


--
-- Name: work_runs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.work_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid DEFAULT spine.default_tenant_id() NOT NULL,
    domain text NOT NULL,
    kind text NOT NULL,
    title text,
    status text DEFAULT 'queued'::text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    result jsonb,
    error text,
    requested_by uuid,
    requested_via text DEFAULT 'ui'::text NOT NULL,
    approver_group text,
    approved_by uuid,
    approved_at timestamp with time zone,
    client_id uuid,
    work_item_id uuid,
    parent_run_id uuid,
    cost_usd numeric(10,4),
    source_table text,
    source_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    started_at timestamp with time zone,
    finished_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT work_runs_cost_usd_check CHECK (((cost_usd IS NULL) OR (cost_usd >= (0)::numeric))),
    CONSTRAINT work_runs_domain_check CHECK ((domain = ANY (ARRAY['scrape'::text, 'content'::text, 'import'::text, 'staff_request'::text, 'automation'::text, 'cron'::text, 'ticket'::text]))),
    CONSTRAINT work_runs_kind_check CHECK (((char_length(kind) >= 1) AND (char_length(kind) <= 120))),
    CONSTRAINT work_runs_payload_size CHECK ((pg_column_size(payload) <= 65536)),
    CONSTRAINT work_runs_requested_via_check CHECK ((requested_via = ANY (ARRAY['ui'::text, 'mcp'::text, 'skill'::text, 'cron'::text, 'system'::text]))),
    CONSTRAINT work_runs_source_pair CHECK (((source_table IS NULL) = (source_id IS NULL))),
    CONSTRAINT work_runs_source_table_check CHECK (((source_table IS NULL) OR (source_table ~ '^[a-z][a-z0-9_]*$'::text))),
    CONSTRAINT work_runs_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'running'::text, 'waiting_approval'::text, 'approved'::text, 'rejected'::text, 'done'::text, 'failed'::text, 'cancelled'::text]))),
    CONSTRAINT work_runs_title_check CHECK (((title IS NULL) OR (char_length(title) <= 300)))
);


--
-- Name: work_run_cancel(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.work_run_cancel(p_id uuid) RETURNS public.work_runs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_row public.work_runs;
begin
  select * into v_row from public.work_runs where id = p_id for update;
  if not found then raise exception 'work_runs: not found' using errcode = 'P0002'; end if;
  if v_row.source_table is not null then
    raise exception 'WORK_ENGINE_LEGACY: act on this run through its % record', v_row.source_table;
  end if;
  if not (public.can_manage_work_engine() or v_row.requested_by = auth.uid()) then
    raise exception 'work_runs: only the requester or a manager cancels' using errcode = '42501';
  end if;
  update public.work_runs set status = 'cancelled' where id = p_id returning * into v_row;
  return v_row;
end;
$$;


--
-- Name: work_run_decide(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.work_run_decide(p_id uuid, p_decision text, p_note text DEFAULT NULL::text) RETURNS public.work_runs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_row public.work_runs;
begin
  if p_decision not in ('approved', 'rejected') then
    raise exception 'work_runs: decision must be approved or rejected' using errcode = '22023';
  end if;
  select * into v_row from public.work_runs where id = p_id for update;
  if not found then raise exception 'work_runs: not found' using errcode = 'P0002'; end if;
  if v_row.source_table is not null then
    raise exception 'WORK_ENGINE_LEGACY: act on this run through its % record', v_row.source_table;
  end if;
  if not (public.can_manage_work_engine() or public.is_reviewer_by_key(v_row.approver_group)) then
    raise exception 'work_runs: not an approver for this run' using errcode = '42501';
  end if;
  update public.work_runs
     set status = p_decision,
         result = case when p_note is null then result
                       else coalesce(result, '{}'::jsonb) || jsonb_build_object('decision_note', p_note) end
   where id = p_id
   returning * into v_row;
  return v_row;
end;
$$;


--
-- Name: work_run_retry(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.work_run_retry(p_id uuid) RETURNS public.work_runs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_row public.work_runs;
begin
  select * into v_row from public.work_runs where id = p_id for update;
  if not found then raise exception 'work_runs: not found' using errcode = 'P0002'; end if;
  if v_row.source_table is not null then
    raise exception 'WORK_ENGINE_LEGACY: act on this run through its % record', v_row.source_table;
  end if;
  if not (public.can_manage_work_engine() or v_row.requested_by = auth.uid()) then
    raise exception 'work_runs: only the requester or a manager retries' using errcode = '42501';
  end if;
  update public.work_runs set status = 'queued' where id = p_id returning * into v_row;
  return v_row;
end;
$$;


--
-- Name: work_run_transition_allowed(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.work_run_transition_allowed(p_from text, p_to text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select p_from = p_to or (p_from, p_to) in (
    ('queued', 'running'), ('queued', 'waiting_approval'), ('queued', 'failed'), ('queued', 'cancelled'),
    ('running', 'waiting_approval'), ('running', 'done'), ('running', 'failed'), ('running', 'cancelled'),
    ('waiting_approval', 'approved'), ('waiting_approval', 'rejected'),
    ('waiting_approval', 'done'), ('waiting_approval', 'cancelled'),
    ('approved', 'running'), ('approved', 'done'), ('approved', 'failed'), ('approved', 'cancelled'),
    ('failed', 'queued')
  )
$$;


--
-- Name: work_to_rev_task(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.work_to_rev_task() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_closed boolean; v_task_id uuid;
begin
  if current_setting('app.rev_task_sync', true) = 'on' then
    return null;
  end if;
  -- projects_guard_rev_task already refuses this; belt and braces for the definer write below.
  if (select auth.uid()) is not null and not public.can_view_revenue() then
    return null;
  end if;
  begin
    perform set_config('app.rev_task_sync', 'on', true);
    v_task_id := new.source_id::uuid;
    select coalesce(bool_or(s.is_completion or s.is_terminal), false) into v_closed from public.work_item_statuses s where s.slug = new.status;

    update public.rev_tasks t
       set done_at = case when v_closed then coalesce(t.done_at, now()) else null end,
           owner_id = new.owner_id,
           due_at = case
             when new.ends_at is not distinct from old.ends_at then t.due_at
             when new.ends_at is null then null
             -- keep the time of day the task had (17:00 UTC when it had none)
             else (new.ends_at + coalesce((t.due_at at time zone 'UTC')::time, time '17:00')) at time zone 'UTC'
           end
     where t.id = v_task_id
       and ((t.done_at is not null) is distinct from v_closed
            or t.owner_id is distinct from new.owner_id
            or new.ends_at is distinct from old.ends_at);
    perform set_config('app.rev_task_sync', 'off', true);
  exception when others then
    raise warning 'work_to_rev_task(%): %', new.id, sqlerrm;
  end;
  return null;
end;
$$;


--
-- Name: agent_client_pulse__read_client_pulse(jsonb); Type: FUNCTION; Schema: spine; Owner: -
--

CREATE FUNCTION spine.agent_client_pulse__read_client_pulse(p_arg jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_q        text := nullif(btrim(coalesce(p_arg->>'client_query', '')), '');
  v_key      text;
  v_client   record;
  v_cands    jsonb;
  v_contracts text[];
  v_projects jsonb;
  v_tasks    jsonb;
  v_task_count int;
  v_calls    jsonb;
  v_links    jsonb;
  v_health   jsonb;
  v_meta     jsonb;
begin
  if v_q is null then
    return jsonb_build_object('resolved', false, 'reason', 'no client named', 'row_count', 0);
  end if;
  v_key := regexp_replace(lower(v_q), '[^a-z0-9]+', '', 'g');

  -- Candidates: exact key, then alias raw_name, then substring; take the best.
  select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'display_name', x.display_name, 'status', x.status, 'rank', x.rank) order by x.rank, x.display_name), '[]'::jsonb)
    into v_cands
    from (
      select distinct on (c.id) c.id, c.display_name, c.status,
             case when c.display_name_key = v_key then 0
                  when exists (select 1 from public.client_aliases a where a.client_id = c.id and regexp_replace(lower(a.raw_name), '[^a-z0-9]+', '', 'g') = v_key) then 1
                  when c.display_name_key like v_key || '%' then 2
                  when c.display_name_key like '%' || v_key || '%' then 3
                  when lower(c.display_name) like '%' || lower(v_q) || '%' then 4
                  else null end as rank
        from public.clients_v2 c
       where c.display_name_key = v_key
          or c.display_name_key like '%' || v_key || '%'
          or lower(c.display_name) like '%' || lower(v_q) || '%'
          or exists (select 1 from public.client_aliases a where a.client_id = c.id and regexp_replace(lower(a.raw_name), '[^a-z0-9]+', '', 'g') = v_key)
       order by c.id
    ) x
   where x.rank is not null
   limit 8;

  if jsonb_array_length(v_cands) = 0 then
    return jsonb_build_object('resolved', false, 'reason', 'no client matched', 'query', v_q, 'row_count', 0);
  end if;

  select (v_cands->0->>'id')::uuid as id, v_cands->0->>'display_name' as display_name, v_cands->0->>'status' as status into v_client;

  select coalesce(array_agg(a.external_id), '{}') into v_contracts
    from public.client_aliases a where a.client_id = v_client.id and a.source like 'airtable%';

  select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'name', p.name, 'kind', p.kind, 'status', p.status, 'priority', p.priority,
                                               'owner', nullif(btrim(concat_ws(' ', o.first_name, o.last_name)), ''),
                                               'ends_at', p.ends_at, 'updated_at', p.updated_at) order by p.updated_at desc), '[]'::jsonb)
    into v_projects
    from (select * from public.projects p where p.client_id = v_client.id and not coalesce(p.archived, false) and p.completed_at is null
           order by p.updated_at desc limit 12) p
    left join public.profiles o on o.id = p.owner_id;

  select count(*) into v_task_count
    from public.tasks t join public.projects p on p.id = t.project_id
   where p.client_id = v_client.id and t.completed_at is null and not coalesce(p.archived, false);

  select coalesce(jsonb_agg(jsonb_build_object('id', t.id, 'title', t.title, 'status', t.status, 'priority', t.priority, 'due_at', t.due_at,
                                               'assignee', nullif(btrim(concat_ws(' ', a.first_name, a.last_name)), ''), 'project', p.name)
                            order by t.due_at nulls last, t.updated_at desc), '[]'::jsonb)
    into v_tasks
    from (select t.* from public.tasks t join public.projects p on p.id = t.project_id
           where p.client_id = v_client.id and t.completed_at is null and not coalesce(p.archived, false)
           order by t.due_at nulls last, t.updated_at desc limit 10) t
    join public.projects p on p.id = t.project_id
    left join public.profiles a on a.id = t.assignee_id;

  select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'occurred_at', c.occurred_at, 'call_type', c.call_type, 'duration_minutes', c.duration_minutes,
                                               'score', ca.overall_score, 'summary', left(ca.summary_md, 700), 'attention_points', ca.attention_points)
                            order by c.occurred_at desc), '[]'::jsonb)
    into v_calls
    from (select * from public.calls c where c.client_id = v_client.id order by c.occurred_at desc limit 5) c
    left join lateral (select * from public.call_analyses x where x.call_id = c.id order by x.created_at desc limit 1) ca on true;

  select coalesce(jsonb_agg(jsonb_build_object('outlet', l.outlet, 'headline', l.headline, 'url', l.url, 'live_date', l.live_date,
                                               'tier', l.tier, 'is_national', l.is_national) order by l.live_date desc nulls last), '[]'::jsonb)
    into v_links
    from (select * from public.live_links l where l.airtable_contract_id = any (v_contracts) order by l.live_date desc nulls last limit 6) l;

  select jsonb_build_object('period_month', h.period_month, 'total_score', h.total_score, 'factors', h.factor_breakdown, 'computed_at', h.computed_at)
    into v_health
    from public.health_scores h where h.airtable_contract_id = any (v_contracts) order by h.period_month desc limit 1;

  select jsonb_build_object('notice_period_days', m.notice_period_days, 'pr_goals', left(m.pr_goals_md, 500),
                            'deliverables', left(m.contracted_deliverables_md, 500), 'first_live_link_at', m.first_live_link_at)
    into v_meta
    from public.client_meta m where m.airtable_contract_id = any (v_contracts) limit 1;

  return jsonb_build_object(
    'resolved', true,
    'query', v_q,
    'client', jsonb_build_object('id', v_client.id, 'display_name', v_client.display_name, 'status', v_client.status),
    'candidates', v_cands,
    'open_work', jsonb_build_object('projects', v_projects, 'open_task_count', v_task_count, 'tasks', v_tasks),
    'recent_calls', v_calls,
    'live_links', v_links,
    'health', v_health,
    'meta', v_meta,
    'read_as', current_user,
    'row_count', jsonb_array_length(v_projects) + jsonb_array_length(v_tasks) + jsonb_array_length(v_calls) + jsonb_array_length(v_links) + 1
  );
end
$$;


--
-- Name: agent_read_allowed(name); Type: FUNCTION; Schema: spine; Owner: -
--

CREATE FUNCTION spine.agent_read_allowed(p_role name) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'spine', 'pg_temp'
    AS $$
  select exists (
    select 1 from spine.agent_identities
    where pg_role = p_role::text and enabled = true
  )
$$;


--
-- Name: agent_transcript_reader__read_transcript(uuid); Type: FUNCTION; Schema: spine; Owner: -
--

CREATE FUNCTION spine.agent_transcript_reader__read_transcript(p_call_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object(
           'call_id', t.call_id, 'content', t.content, 'word_count', t.word_count,
           'language', t.language, 'source', t.source,
           'occurred_at', c.occurred_at, 'client_id', c.client_id, 'call_type', c.call_type,
           'read_as', current_user)
    from public.call_transcripts t
    join public.calls c on c.id = t.call_id
   where t.call_id = p_call_id
$$;


--
-- Name: apply_chat_reply(uuid); Type: FUNCTION; Schema: spine; Owner: -
--

CREATE FUNCTION spine.apply_chat_reply(p_action_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'spine', 'comms', 'public', 'pg_temp'
    AS $$
declare
  v_a        record;
  v_conv     record;
  v_pid      uuid;
  v_sub      uuid;
  v_event_id uuid;
  v_msg      uuid;
  v_auto     text;
  v_audit_id bigint;
  v_body     text;
begin
  select * into v_a from spine.proposed_actions where id = p_action_id for update;
  if v_a.id is null then raise exception 'spine: unknown proposed action' using errcode = '23503'; end if;
  if v_a.action_type <> 'chat.reply' then raise exception 'spine: not a chat.reply' using errcode = '22023'; end if;
  if v_a.status <> 'pending' then
    return jsonb_build_object('status', v_a.status, 'action_id', v_a.id, 'message_id', v_a.payload->>'message_id');
  end if;

  select * into v_conv from comms.conversations where id = (v_a.payload->>'conversation_id')::uuid;
  if v_conv.id is null then raise exception 'spine: chat.reply has no conversation' using errcode = '22023'; end if;
  select autonomy_level into v_auto from spine.action_types where action_type = 'chat.reply';

  -- The gate. Client and external audiences never auto-apply (brief: permanent).
  if v_conv.audience <> 'internal' or v_auto <> 'auto' then
    return jsonb_build_object('status', 'pending', 'action_id', v_a.id, 'reason', 'audience ' || v_conv.audience || ' requires a human click');
  end if;

  select cp.id into v_pid from comms.conversation_participants cp
   where cp.conversation_id = v_conv.id and cp.agent_identity_slug = v_a.identity_slug and cp.left_at is null;
  if v_pid is null then
    update spine.proposed_actions set status = 'rejected', decided_at = now() where id = v_a.id;
    return jsonb_build_object('status', 'rejected', 'action_id', v_a.id, 'reason', 'identity is no longer a participant');
  end if;

  select r.requested_by, r.triggered_by_event_id into v_sub, v_event_id from public.skill_runs r where r.id = v_a.skill_run_id;
  if v_sub is null then
    select owner_user_id into v_sub from spine.agent_identities where slug = v_a.identity_slug;
  end if;
  if v_conv.work_item_id is null and v_event_id is null then
    return jsonb_build_object('status', 'pending', 'action_id', v_a.id, 'reason', 'no audit anchor (no work item, no event)');
  end if;

  v_body := coalesce(v_a.payload->>'body', '');
  if length(btrim(v_body)) = 0 then
    update spine.proposed_actions set status = 'rejected', decided_at = now() where id = v_a.id;
    return jsonb_build_object('status', 'rejected', 'action_id', v_a.id, 'reason', 'empty body');
  end if;

  insert into comms.messages (conversation_id, sender_participant_id, body, body_format, direction, visibility, provider,
                              in_reply_to_message_id, payload)
  values (v_conv.id, v_pid, v_body, 'markdown', 'internal', 'all', 'openronin',
          nullif(v_a.payload->>'in_reply_to_message_id', '')::uuid,
          jsonb_build_object('agent', v_a.identity_slug, 'proposed_action_id', v_a.id, 'skill_run_id', v_a.skill_run_id,
                             'why', coalesce(v_a.payload->'why', '{}'::jsonb)))
  returning id into v_msg;

  v_audit_id := spine.record_agent_audit(v_sub, v_a.identity_slug, v_conv.work_item_id, 'write', 'comms.messages', 1, null, 'ok', null, v_event_id);
  update spine.proposed_actions
     set status = 'applied', decided_at = now(),
         payload = payload || jsonb_build_object('message_id', v_msg, 'audit_id', v_audit_id)
   where id = v_a.id;
  update comms.messages set payload = payload || jsonb_build_object('audit_id', v_audit_id) where id = v_msg;
  return jsonb_build_object('status', 'applied', 'action_id', v_a.id, 'message_id', v_msg, 'audit_id', v_audit_id, 'sub', v_sub, 'act', v_a.identity_slug);
end
$$;


--
-- Name: can_read_agent_audit(uuid); Type: FUNCTION; Schema: spine; Owner: -
--

CREATE FUNCTION spine.can_read_agent_audit(p_sub uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select public.is_admin()
      or auth.uid() = p_sub
      or exists (select 1 from public.profiles p where p.id = p_sub and p.manager_id = auth.uid())
$$;


--
-- Name: disable_identity(text); Type: FUNCTION; Schema: spine; Owner: -
--

CREATE FUNCTION spine.disable_identity(p_slug text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'spine', 'public', 'pg_temp'
    AS $$
declare
  v_role text;
  v_t    record;
begin
  if auth.uid() is not null and not public.is_admin() then
    raise exception 'Only an admin or exec can disable an identity' using errcode = '42501';
  end if;
  select pg_role into v_role from spine.agent_identities where slug = p_slug and enabled = true;
  if v_role is null then return false; end if;
  update spine.agent_identities set enabled = false, disabled_at = now() where slug = p_slug;
  for v_t in
    select distinct table_schema, table_name from information_schema.role_table_grants where grantee = v_role
  loop
    execute format('revoke all on %I.%I from %I', v_t.table_schema, v_t.table_name, v_role);
  end loop;
  -- Drop it from every conversation (brief: "spine.disable_identity(slug) also drops it from every conversation").
  update comms.conversation_participants set left_at = now() where agent_identity_slug = p_slug and left_at is null;
  return true;
end
$$;


--
-- Name: dispatch_events(integer); Type: FUNCTION; Schema: spine; Owner: -
--

CREATE FUNCTION spine.dispatch_events(p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'spine', 'public', 'pg_temp'
    AS $$
declare
  v_ev        record;
  v_route     record;
  v_owner     uuid;
  v_sub       uuid;
  v_enabled   boolean;
  v_run_id    uuid;
  v_dispatched integer := 0;
  v_skipped    integer := 0;
begin
  for v_ev in
    select * from spine.events
     where processed_at is null
     order by occurred_at
     limit greatest(1, least(p_limit, 500))
     for update skip locked
  loop
    begin
      select * into v_route from spine.event_routes where kind = v_ev.kind and enabled = true;
      if not found then
        update spine.events set processed_at = now(), outcome = 'no_route' where id = v_ev.id;
        v_skipped := v_skipped + 1;
        continue;
      end if;
      select owner_user_id, enabled into v_owner, v_enabled from spine.agent_identities where slug = v_route.identity_slug;
      if not coalesce(v_enabled, false) or v_owner is null then
        update spine.events set processed_at = now(), outcome = 'identity_disabled',
               error = case when v_owner is null then 'identity has no owner (sub)' else 'identity disabled' end
         where id = v_ev.id;
        v_skipped := v_skipped + 1;
        continue;
      end if;
      v_sub := v_owner;
      if (v_ev.payload ? 'sub') and exists (select 1 from public.profiles where id = (v_ev.payload->>'sub')::uuid) then
        v_sub := (v_ev.payload->>'sub')::uuid;
      end if;
      insert into public.skill_runs (skill, context, requested_by, identity_slug, triggered_by_event_id)
      values (v_route.skill,
              v_ev.payload || jsonb_build_object('event_id', v_ev.id, 'event_kind', v_ev.kind),
              v_sub, v_route.identity_slug, v_ev.id)
      returning id into v_run_id;
      update spine.events set processed_at = now(), outcome = 'dispatched', skill_run_id = v_run_id where id = v_ev.id;
      perform spine.record_agent_audit(v_sub, v_route.identity_slug, null, 'dispatch', 'public.skill_runs', 1, null, 'ok', null, v_ev.id);
      v_dispatched := v_dispatched + 1;
    exception when others then
      update spine.events set processed_at = now(), outcome = 'error', error = left(sqlerrm, 1000) where id = v_ev.id;
      v_skipped := v_skipped + 1;
    end;
  end loop;
  return jsonb_build_object('dispatched', v_dispatched, 'skipped', v_skipped);
end
$$;


--
-- Name: emit_call_transcript_event(); Type: FUNCTION; Schema: spine; Owner: -
--

CREATE FUNCTION spine.emit_call_transcript_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'spine', 'public', 'pg_temp'
    AS $$
begin
  insert into spine.events (kind, source, payload)
  values ('call_transcripts.inserted', 'public.call_transcripts',
          jsonb_build_object('call_id', new.call_id, 'source', new.source, 'word_count', new.word_count));
  return new;
end
$$;


--
-- Name: gateway_read(text, uuid, text, jsonb, uuid, uuid); Type: FUNCTION; Schema: spine; Owner: -
--

CREATE FUNCTION spine.gateway_read(p_identity_slug text, p_sub uuid, p_reader text, p_arg jsonb, p_work_item_id uuid DEFAULT NULL::uuid, p_event_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'spine', 'public', 'pg_temp'
    AS $_$
declare
  v_role     text;
  v_enabled  boolean;
  v_fn       text;
  v_t0       timestamptz := clock_timestamp();
  v_row      jsonb;
  v_ms       integer;
  v_audit_id bigint;
  v_err      text;
begin
  if p_work_item_id is null and p_event_id is null then
    raise exception 'spine gateway: a work_item_id or event_id anchor is required' using errcode = '22023';
  end if;
  if p_work_item_id is not null and not exists (select 1 from public.projects where id = p_work_item_id) then
    raise exception 'spine gateway: unknown work item %', p_work_item_id using errcode = '23503';
  end if;
  if p_sub is null or not exists (select 1 from public.profiles where id = p_sub) then
    raise exception 'spine gateway: sub must be a real profile' using errcode = '23503';
  end if;
  if p_event_id is not null and not exists (select 1 from spine.events where id = p_event_id) then
    raise exception 'spine gateway: unknown event %', p_event_id using errcode = '23503';
  end if;
  if p_reader !~ '^[a-z][a-z0-9_]{0,40}$' then
    raise exception 'spine gateway: bad reader name' using errcode = '22023';
  end if;
  select pg_role, enabled into v_role, v_enabled from spine.agent_identities where slug = p_identity_slug;
  if v_role is null then
    raise exception 'spine gateway: unknown identity %', p_identity_slug using errcode = '23503';
  end if;
  v_fn := v_role || '__read_' || p_reader;
  if not v_enabled then
    v_audit_id := spine.record_agent_audit(p_sub, p_identity_slug, p_work_item_id, 'read', 'reader:' || p_reader, 0, 0, 'denied', 'identity disabled', p_event_id);
    return jsonb_build_object('status', 'denied', 'error', 'identity disabled', 'audit_id', v_audit_id, 'act', p_identity_slug);
  end if;
  if not exists (
    select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
     where n.nspname = 'spine' and p.proname = v_fn
       and p.proowner = (select oid from pg_roles where rolname = v_role)
       and p.prosecdef
  ) then
    raise exception 'spine gateway: reader % for % is missing or not owned by its identity role', p_reader, p_identity_slug using errcode = '42501';
  end if;
  begin
    execute format('select spine.%I($1)', v_fn) into v_row using coalesce(p_arg, '{}'::jsonb);
  exception when others then
    v_err := sqlerrm;
  end;
  v_ms := (extract(epoch from clock_timestamp() - v_t0) * 1000)::integer;
  if v_err is not null then
    v_audit_id := spine.record_agent_audit(p_sub, p_identity_slug, p_work_item_id, 'read', 'reader:' || p_reader, 0, v_ms, 'error', v_err, p_event_id);
    return jsonb_build_object('status', 'error', 'error', v_err, 'audit_id', v_audit_id, 'act', p_identity_slug);
  end if;
  v_audit_id := spine.record_agent_audit(p_sub, p_identity_slug, p_work_item_id, 'read', 'reader:' || p_reader,
                                         coalesce((v_row->>'row_count')::integer, case when v_row is null then 0 else 1 end), v_ms, 'ok', null, p_event_id);
  return jsonb_build_object('status', 'ok', 'audit_id', v_audit_id, 'act', p_identity_slug, 'sub', p_sub,
                            'work_item_id', p_work_item_id, 'event_id', p_event_id, 'row', v_row);
end
$_$;


--
-- Name: gateway_read_transcript(text, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: spine; Owner: -
--

CREATE FUNCTION spine.gateway_read_transcript(p_identity_slug text, p_sub uuid, p_work_item_id uuid, p_call_id uuid, p_event_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'spine', 'public', 'pg_temp'
    AS $_$
declare
  v_role     text;
  v_enabled  boolean;
  v_t0       timestamptz := clock_timestamp();
  v_row      jsonb;
  v_n        integer := 0;
  v_ms       integer;
  v_audit_id bigint;
  v_err      text;
begin
  if p_work_item_id is null and p_event_id is null then
    raise exception 'spine gateway: a work_item_id or event_id anchor is required' using errcode = '22023';
  end if;
  if p_work_item_id is not null and not exists (select 1 from public.projects where id = p_work_item_id) then
    raise exception 'spine gateway: unknown work item %', p_work_item_id using errcode = '23503';
  end if;
  if p_sub is null or not exists (select 1 from public.profiles where id = p_sub) then
    raise exception 'spine gateway: sub must be a real profile' using errcode = '23503';
  end if;
  if p_event_id is not null and not exists (select 1 from spine.events where id = p_event_id) then
    raise exception 'spine gateway: unknown event %', p_event_id using errcode = '23503';
  end if;

  select pg_role, enabled into v_role, v_enabled from spine.agent_identities where slug = p_identity_slug;
  if v_role is null then
    raise exception 'spine gateway: unknown identity %', p_identity_slug using errcode = '23503';
  end if;
  if not v_enabled then
    v_audit_id := spine.record_agent_audit(p_sub, p_identity_slug, p_work_item_id, 'read', 'public.call_transcripts+calls',
                                           0, 0, 'denied', 'identity disabled', p_event_id);
    return jsonb_build_object('status', 'denied', 'error', 'identity disabled', 'audit_id', v_audit_id, 'act', p_identity_slug);
  end if;

  -- The read runs inside the identity-owned reader: its GRANTs and RLS apply.
  -- Assert the ownership rather than trusting the naming convention.
  if not exists (
    select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
     where n.nspname = 'spine' and p.proname = v_role || '__read_transcript'
       and p.proowner = (select oid from pg_roles where rolname = v_role)
       and p.prosecdef
  ) then
    raise exception 'spine gateway: reader for % is missing or not owned by its identity role', p_identity_slug using errcode = '42501';
  end if;
  begin
    execute format('select spine.%I($1)', v_role || '__read_transcript') into v_row using p_call_id;
    v_n := case when v_row is null then 0 else 1 end;
  exception when others then
    v_err := sqlerrm;
  end;

  v_ms := (extract(epoch from clock_timestamp() - v_t0) * 1000)::integer;
  if v_err is not null then
    v_audit_id := spine.record_agent_audit(p_sub, p_identity_slug, p_work_item_id, 'read', 'public.call_transcripts+calls',
                                           0, v_ms, 'error', v_err, p_event_id);
    return jsonb_build_object('status', 'error', 'error', v_err, 'audit_id', v_audit_id, 'act', p_identity_slug);
  end if;
  v_audit_id := spine.record_agent_audit(p_sub, p_identity_slug, p_work_item_id, 'read', 'public.call_transcripts+calls',
                                         v_n, v_ms, 'ok', null, p_event_id);
  return jsonb_build_object('status', 'ok', 'rows', v_n, 'audit_id', v_audit_id, 'act', p_identity_slug,
                            'sub', p_sub, 'work_item_id', p_work_item_id, 'row', v_row);
end
$_$;


--
-- Name: guard_consumer_scope_ceiling(); Type: FUNCTION; Schema: spine; Owner: -
--

CREATE FUNCTION spine.guard_consumer_scope_ceiling() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'spine', 'public', 'pg_temp'
    AS $$
declare
  v_ceiling text[];
  v_over    text[];
begin
  if new.identity_slug is null or new.revoked_at is not null then
    return new;
  end if;
  select allowed_scopes into v_ceiling from spine.agent_identities where slug = new.identity_slug;
  if v_ceiling is null then
    raise exception 'SPINE_SCOPE_CEILING: unknown identity %', new.identity_slug using errcode = '23503';
  end if;
  select coalesce(array_agg(s), '{}') into v_over
    from unnest(new.scopes) s where not (s = any (v_ceiling));
  if coalesce(array_length(v_over, 1), 0) > 0 then
    raise exception 'SPINE_SCOPE_CEILING: consumer % asks for % but identity % allows only %',
      new.slug, v_over, new.identity_slug, v_ceiling using errcode = '42501';
  end if;
  return new;
end
$$;


--
-- Name: post_chat_failure(uuid, text); Type: FUNCTION; Schema: spine; Owner: -
--

CREATE FUNCTION spine.post_chat_failure(p_skill_run_id uuid, p_error text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'spine', 'comms', 'public', 'pg_temp'
    AS $$
declare v_r record; v_pid uuid; v_msg uuid; v_conv uuid;
begin
  select r.identity_slug, r.context into v_r from public.skill_runs r where r.id = p_skill_run_id;
  v_conv := nullif(v_r.context->>'conversation_id', '')::uuid;
  if v_conv is null or v_r.identity_slug is null then return null; end if;
  select id into v_pid from comms.conversation_participants where conversation_id = v_conv and agent_identity_slug = v_r.identity_slug and left_at is null;
  if v_pid is null then return null; end if;
  insert into comms.messages (conversation_id, sender_participant_id, body, body_format, direction, visibility, provider, payload)
  values (v_conv, v_pid, 'I could not answer that: ' || left(coalesce(p_error, 'unknown error'), 500), 'system', 'internal', 'staff_only', 'openronin',
          jsonb_build_object('agent', v_r.identity_slug, 'skill_run_id', p_skill_run_id, 'failure', true))
  returning id into v_msg;
  insert into comms.conversation_events (conversation_id, kind, actor_participant_id, payload)
  values (v_conv, 'agent_run_failed', v_pid, jsonb_build_object('skill_run_id', p_skill_run_id));
  return v_msg;
end
$$;


--
-- Name: propose_action(text, text, uuid, uuid, text, jsonb); Type: FUNCTION; Schema: spine; Owner: -
--

CREATE FUNCTION spine.propose_action(p_action_type text, p_identity_slug text, p_skill_run_id uuid, p_work_item_id uuid, p_reasoning text, p_payload jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'spine', 'public', 'pg_temp'
    AS $$
declare v_id uuid;
begin
  if not exists (select 1 from spine.agent_identities where slug = p_identity_slug and enabled) then
    raise exception 'spine: identity % is not enabled', p_identity_slug using errcode = '42501';
  end if;
  insert into spine.proposed_actions (action_type, identity_slug, skill_run_id, work_item_id, reasoning, payload)
  values (p_action_type, p_identity_slug, p_skill_run_id, p_work_item_id, p_reasoning, coalesce(p_payload, '{}'::jsonb))
  returning id into v_id;
  return v_id;
end
$$;


--
-- Name: provision_identity(text, text, text, text, text, text[], jsonb); Type: FUNCTION; Schema: spine; Owner: -
--

CREATE FUNCTION spine.provision_identity(p_slug text, p_tier text, p_owner_email text, p_workflow text, p_justification text, p_allowed_scopes text[], p_chat_profile jsonb DEFAULT '{}'::jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'spine', 'public', 'pg_temp'
    AS $_$
declare
  v_role  text := 'agent_' || p_slug;
  v_owner uuid;
begin
  if auth.uid() is not null and not public.is_admin() then
    raise exception 'Only an admin or exec can provision a spine identity' using errcode = '42501';
  end if;
  if p_slug !~ '^[a-z][a-z0-9_]{1,39}$' then
    raise exception 'spine: identity slug % is not ^[a-z][a-z0-9_]{1,39}$', p_slug using errcode = '22023';
  end if;
  if length(coalesce(p_justification, '')) < 20 then
    raise exception 'spine: a one-line justification (>= 20 chars) is required (decision 19)' using errcode = '22023';
  end if;
  select id into v_owner from public.profiles where lower(email) = lower(p_owner_email) and is_active limit 1;
  if v_owner is null then
    raise exception 'spine: owner % is not an active profile', p_owner_email using errcode = '23503';
  end if;
  if not public.mcp_scopes_ok(p_allowed_scopes) then
    raise exception 'spine: allowed_scopes contains an unknown scope' using errcode = '22023';
  end if;

  if not exists (select 1 from pg_roles where rolname = v_role) then
    execute format('create role %I nologin noinherit', v_role);
  end if;
  -- postgres is a member so it can hand ownership over during migrations
  -- (0059 section 4). Idempotent: GRANT on an existing membership is a no-op.
  execute format('grant %I to postgres', v_role);
  execute format('grant usage on schema public to %I', v_role);
  execute format('grant usage on schema spine  to %I', v_role);

  insert into spine.agent_identities
    (slug, tier, pg_role, owner_user_id, workflow, justification, allowed_scopes, chat_profile, enabled, disabled_at)
  values
    (p_slug, p_tier, v_role, v_owner, p_workflow, p_justification, p_allowed_scopes, coalesce(p_chat_profile, '{}'::jsonb), true, null)
  on conflict (slug) do update
    set tier           = excluded.tier,
        owner_user_id  = excluded.owner_user_id,
        workflow       = excluded.workflow,
        justification  = excluded.justification,
        allowed_scopes = excluded.allowed_scopes,
        chat_profile   = case when excluded.chat_profile = '{}'::jsonb then spine.agent_identities.chat_profile else excluded.chat_profile end,
        enabled        = true,
        disabled_at    = null;

  insert into public.audit_log (actor_id, entity_kind, entity_ref, action, diff, status)
  values (auth.uid(), 'mcp', 'spine.agent_identities/' || p_slug, 'spine.identity.provisioned',
          jsonb_build_object('tier', p_tier, 'owner', p_owner_email, 'workflow', p_workflow, 'allowed_scopes', p_allowed_scopes), 'ok');
  return p_slug;
end
$_$;


--
-- Name: record_agent_audit(uuid, text, uuid, text, text, integer, integer, text, text, uuid); Type: FUNCTION; Schema: spine; Owner: -
--

CREATE FUNCTION spine.record_agent_audit(p_sub uuid, p_act text, p_work_item_id uuid, p_operation text, p_target text, p_row_count integer DEFAULT NULL::integer, p_latency_ms integer DEFAULT NULL::integer, p_status text DEFAULT 'ok'::text, p_error text DEFAULT NULL::text, p_event_id uuid DEFAULT NULL::uuid) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'spine', 'public', 'pg_temp'
    AS $$
declare
  v_id bigint;
begin
  if not exists (select 1 from spine.agent_identities where slug = p_act) then
    raise exception 'spine: unknown identity "%"', p_act using errcode = '23503';
  end if;
  insert into spine.agent_audit (sub, act, work_item_id, event_id, operation, target, row_count, latency_ms, status, error)
  values (p_sub, p_act, p_work_item_id, p_event_id, p_operation, p_target, p_row_count, p_latency_ms, p_status, p_error)
  returning id into v_id;
  return v_id;
end
$$;


--
-- Name: retire_identity(text, text); Type: FUNCTION; Schema: spine; Owner: -
--

CREATE FUNCTION spine.retire_identity(p_slug text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'spine', 'public', 'pg_temp'
    AS $$
declare
  v_role     text;
  v_revoked  int := 0;
  v_grants   int := 0;
  r          record;
begin
  if auth.uid() is not null and not public.is_admin() then
    raise exception 'Only an admin or exec can retire a spine identity' using errcode = '42501';
  end if;
  select pg_role into v_role from spine.agent_identities where slug = p_slug;
  if v_role is null then
    raise exception 'spine: unknown identity %', p_slug using errcode = '23503';
  end if;

  update public.mcp_consumers set revoked_at = now()
   where identity_slug = p_slug and revoked_at is null;
  get diagnostics v_revoked = row_count;

  -- disable_identity (0059) flips enabled and strips the transcript grants;
  -- it returns false when already disabled, which is fine here.
  perform spine.disable_identity(p_slug);
  update spine.agent_identities set enabled = false, disabled_at = coalesce(disabled_at, now()) where slug = p_slug;

  -- Strip every remaining table grant the role holds, whatever schema.
  for r in
    select distinct table_schema, table_name
      from information_schema.role_table_grants
     where grantee = v_role
  loop
    execute format('revoke all on %I.%I from %I', r.table_schema, r.table_name, v_role);
    v_grants := v_grants + 1;
  end loop;

  insert into public.audit_log (actor_id, entity_kind, entity_ref, action, diff, status)
  values (auth.uid(), 'mcp', 'spine.agent_identities/' || p_slug, 'spine.identity.retired',
          jsonb_build_object('consumers_revoked', v_revoked, 'grants_stripped', v_grants, 'reason', p_reason), 'ok');
  return jsonb_build_object('slug', p_slug, 'consumers_revoked', v_revoked, 'grants_stripped', v_grants);
end
$$;


