    CONSTRAINT acquisition_targets_status_check CHECK ((status = ANY (ARRAY['identified'::text, 'screened'::text, 'contacted'::text, 'conversation'::text, 'nda'::text, 'loi'::text, 'diligence'::text, 'acquired'::text, 'integrating'::text, 'passed'::text, 'dead'::text])))
