    tenant_id uuid DEFAULT spine.default_tenant_id() NOT NULL,
    client_id uuid NOT NULL,
    contact_id uuid,
    org_tag_id uuid,
    kind text NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    priority text,
    assignee_id uuid,
    linked_task_id uuid,
    linked_conversation_id uuid,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT client_tickets_contact_or_internal CHECK (true),
    CONSTRAINT client_tickets_kind_check CHECK ((kind = ANY (ARRAY['bug'::text, 'question'::text, 'request'::text, 'billing'::text, 'other'::text]))),
    CONSTRAINT client_tickets_priority_check CHECK ((priority = ANY (ARRAY['urgent'::text, 'high'::text, 'medium'::text, 'low'::text]))),
    CONSTRAINT client_tickets_status_check CHECK ((status = ANY (ARRAY['open'::text, 'in_progress'::text, 'waiting_on_client'::text, 'resolved'::text, 'closed'::text])))
);


