--
-- Name: client_tickets_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.client_tickets_view WITH (security_invoker='true') AS
 SELECT t.id,
    t.tenant_id,
    t.client_id,
    t.contact_id,
    t.org_tag_id,
    t.kind,
    t.status,
    t.priority,
    t.assignee_id,
    t.linked_task_id,
    t.linked_conversation_id,
    t.created_by,
    t.created_at,
    t.updated_at,
    c.display_name AS client_display_name,
    ct.display_name AS contact_display_name,
    p.assignee_display_name,
    (t.assignee_id = auth.uid()) AS is_assigned_to_me,
    ( SELECT tags.slug
           FROM public.tags
          WHERE (tags.id = t.org_tag_id)) AS org_slug
   FROM (((public.client_tickets t
     LEFT JOIN public.clients_v2 c ON ((c.id = t.client_id)))
     LEFT JOIN public.contacts ct ON ((ct.id = t.contact_id)))
     LEFT JOIN LATERAL ( SELECT NULLIF(btrim(concat_ws(' '::text, pr.first_name, pr.last_name)), ''::text) AS assignee_display_name
           FROM public.profiles pr
          WHERE (pr.id = t.assignee_id)) p ON (true));


