--
-- Name: comms_agents; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.comms_agents WITH (security_invoker='true') AS
 SELECT slug,
    (chat_profile ->> 'display_name'::text) AS display_name,
    (chat_profile ->> 'blurb'::text) AS blurb,
    (chat_profile ->> 'avatar'::text) AS avatar_url,
    COALESCE((chat_profile -> 'conversation_kinds'::text), '[]'::jsonb) AS conversation_kinds,
    tier,
    enabled
   FROM spine.agent_identities ai
  WHERE (chat_profile ? 'display_name'::text);


