--
-- Name: comms_conversations; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.comms_conversations WITH (security_invoker='true') AS
 SELECT id,
    tenant_id,
    kind,
    audience,
    slug,
    title,
    topic,
    client_id,
    contact_id,
    work_item_id,
    is_private,
    created_by,
    created_at,
    updated_at,
    last_message_at,
    archived_at,
    comms.is_active_participant(id, auth.uid()) AS is_member,
    ( SELECT count(*) AS count
           FROM comms.conversation_participants cp
          WHERE ((cp.conversation_id = c.id) AND (cp.left_at IS NULL))) AS participant_count,
    ( SELECT (count(*))::integer AS count
           FROM comms.messages m
          WHERE ((m.conversation_id = c.id) AND (m.deleted_at IS NULL) AND (m.sent_at > COALESCE(( SELECT cp.last_read_at
                   FROM comms.conversation_participants cp
                  WHERE ((cp.conversation_id = c.id) AND (cp.profile_id = auth.uid()) AND (cp.left_at IS NULL))), '1970-01-01 00:00:00+00'::timestamp with time zone)) AND (NOT (EXISTS ( SELECT 1
                   FROM comms.conversation_participants sp
                  WHERE ((sp.id = m.sender_participant_id) AND (sp.profile_id = auth.uid()))))))) AS unread_count,
    ( SELECT "left"(m.body, 140) AS "left"
           FROM comms.messages m
          WHERE ((m.conversation_id = c.id) AND (m.deleted_at IS NULL))
          ORDER BY m.sent_at DESC
         LIMIT 1) AS last_message_preview
   FROM comms.conversations c;


--
-- Name: comms_messages; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.comms_messages WITH (security_invoker='true') AS
 SELECT m.id,
    m.conversation_id,
    m.sender_participant_id,
    m.connection_id,
    m.body,
    m.body_format,
    m.payload,
    m.direction,
    m.visibility,
    m.provider,
    m.provider_message_id,
    m.provider_thread_id,
    m.in_reply_to_message_id,
    m.attachments,
    m.sent_at,
    m.delivered_at,
    m.read_at,
    m.edited_at,
    m.deleted_at,
    cp.participant_type AS sender_type,
    cp.profile_id AS sender_profile_id,
    cp.agent_identity_slug AS sender_agent_slug,
        CASE cp.participant_type
            WHEN 'user'::text THEN COALESCE(NULLIF(btrim(concat_ws(' '::text, p.first_name, p.last_name)), ''::text), p.email)
            WHEN 'agent'::text THEN COALESCE((ai.chat_profile ->> 'display_name'::text), ai.slug)
            WHEN 'external_app'::text THEN cp.external_app
            ELSE COALESCE(ct.display_name, 'Contact'::text)
        END AS sender_name,
        CASE cp.participant_type
            WHEN 'user'::text THEN COALESCE(p.photo_url, p.avatar_url)
            WHEN 'agent'::text THEN (ai.chat_profile ->> 'avatar'::text)
            ELSE NULL::text
        END AS sender_avatar_url,
    (cp.profile_id = auth.uid()) AS is_mine
   FROM ((((comms.messages m
     LEFT JOIN comms.conversation_participants cp ON ((cp.id = m.sender_participant_id)))
     LEFT JOIN public.profiles p ON ((p.id = cp.profile_id)))
     LEFT JOIN spine.agent_identities ai ON ((ai.slug = cp.agent_identity_slug)))
     LEFT JOIN public.contacts ct ON ((ct.id = cp.contact_id)));


--
-- Name: comms_participants; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.comms_participants WITH (security_invoker='true') AS
 SELECT cp.id,
    cp.conversation_id,
    cp.participant_type,
    cp.profile_id,
    cp.contact_id,
    cp.agent_identity_slug,
    cp.external_app,
    cp.role,
    cp.notify_level,
    cp.joined_at,
    cp.left_at,
    cp.last_read_at,
        CASE cp.participant_type
            WHEN 'user'::text THEN COALESCE(NULLIF(btrim(concat_ws(' '::text, p.first_name, p.last_name)), ''::text), p.email)
            WHEN 'agent'::text THEN COALESCE((ai.chat_profile ->> 'display_name'::text), ai.slug)
            WHEN 'external_app'::text THEN cp.external_app
            ELSE COALESCE(ct.display_name, 'Contact'::text)
        END AS display_name,
        CASE cp.participant_type
            WHEN 'user'::text THEN COALESCE(p.photo_url, p.avatar_url)
            WHEN 'agent'::text THEN (ai.chat_profile ->> 'avatar'::text)
            ELSE NULL::text
        END AS avatar_url,
        CASE cp.participant_type
            WHEN 'agent'::text THEN (ai.chat_profile ->> 'blurb'::text)
            WHEN 'user'::text THEN p.title
            ELSE NULL::text
        END AS subtitle
   FROM (((comms.conversation_participants cp
     LEFT JOIN public.profiles p ON ((p.id = cp.profile_id)))
     LEFT JOIN spine.agent_identities ai ON ((ai.slug = cp.agent_identity_slug)))
     LEFT JOIN public.contacts ct ON ((ct.id = cp.contact_id)));


