);


--
-- Name: cron_health; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.cron_health WITH (security_invoker='true') AS
 WITH last_run AS (
         SELECT DISTINCT ON (cron_runs.route) cron_runs.route,
            cron_runs.id,
            cron_runs.started_at,
            cron_runs.finished_at,
            cron_runs.status,
            cron_runs.http_status,
            cron_runs.duration_ms,
            cron_runs.error
           FROM public.cron_runs
          ORDER BY cron_runs.route, cron_runs.started_at DESC
        ), last_ok AS (
         SELECT DISTINCT ON (cron_runs.route) cron_runs.route,
            cron_runs.started_at AS last_ok_at
           FROM public.cron_runs
          WHERE (cron_runs.status = 'ok'::text)
          ORDER BY cron_runs.route, cron_runs.started_at DESC
        )
 SELECT r.route,
    r.id AS last_run_id,
    r.started_at AS last_started_at,
    r.finished_at AS last_finished_at,
    r.status AS last_status,
    r.http_status AS last_http_status,
    r.duration_ms AS last_duration_ms,
    r.error AS last_error,
    o.last_ok_at
   FROM (last_run r
     LEFT JOIN last_ok o USING (route));


