    CONSTRAINT external_jobs_last_status_check CHECK (((last_status IS NULL) OR (last_status = ANY (ARRAY['ok'::text, 'error'::text, 'running'::text])))),
    CONSTRAINT external_jobs_name_check CHECK (((char_length(name) >= 1) AND (char_length(name) <= 200))),
    CONSTRAINT external_jobs_source_check CHECK ((source = ANY (ARRAY['hermes'::text, 'n8n'::text, 'github'::text, 'other'::text])))
);




