--
-- Name: import_batches; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.import_batches (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid DEFAULT spine.default_tenant_id() NOT NULL,
    target text,
    target_ref text,
    file_path text,
    file_name text,
    file_size integer,
    headers jsonb DEFAULT '[]'::jsonb NOT NULL,
    sample jsonb DEFAULT '[]'::jsonb NOT NULL,
    mapping jsonb DEFAULT '{}'::jsonb NOT NULL,
    options jsonb DEFAULT '{}'::jsonb NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    row_count integer DEFAULT 0 NOT NULL,
    insert_count integer DEFAULT 0 NOT NULL,
    update_count integer DEFAULT 0 NOT NULL,
    reject_count integer DEFAULT 0 NOT NULL,
    progress integer DEFAULT 0 NOT NULL,
    error text,
    requested_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    committed_at timestamp with time zone,
    rolled_back_at timestamp with time zone,
    rolled_back_by uuid,
    CONSTRAINT import_batches_airtable_ref CHECK (((target <> 'airtable'::text) OR (target_ref IS NOT NULL))),
    CONSTRAINT import_batches_counts_nonneg CHECK (((row_count >= 0) AND (insert_count >= 0) AND (update_count >= 0) AND (reject_count >= 0) AND (progress >= 0))),
    CONSTRAINT import_batches_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'uploaded'::text, 'targeted'::text, 'mapped'::text, 'dry_run'::text, 'committing'::text, 'committed'::text, 'rolled_back'::text, 'failed'::text]))),
    CONSTRAINT import_batches_target_check CHECK ((target = ANY (ARRAY['contacts'::text, 'prospects'::text, 'media_outlets'::text, 'client_aliases'::text, 'metrics'::text, 'media_opportunities'::text, 'rev_prospects'::text, 'airtable'::text]))),
    CONSTRAINT import_batches_target_when_targeted CHECK (((target IS NOT NULL) OR (status = ANY (ARRAY['draft'::text, 'uploaded'::text]))))
);


