--
-- Name: v_client_analytics_contracts; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_client_analytics_contracts WITH (security_invoker='true') AS
 WITH goal_rows AS (
         SELECT DISTINCT ON (g.airtable_contract_id, g.month) g.airtable_contract_id,
            g.month,
            g.media_opps_goal
           FROM public.client_goals g
          WHERE (g.media_opps_goal IS NOT NULL)
          ORDER BY g.airtable_contract_id, g.month, g.updated_at DESC
        ), last_secured AS (
         SELECT m.airtable_contract_id,
            max(m.month) FILTER (WHERE (m.secured_count > 0)) AS last_secured_month,
            max(m.month) FILTER (WHERE (m.live_count > 0)) AS last_live_month,
            max(m.synced_at) AS synced_at
           FROM public.client_opp_months m
          GROUP BY m.airtable_contract_id
        )
 SELECT spine.default_tenant_id() AS tenant_id,
    c.id AS contract_id,
    c.client_id,
    v.display_name,
    c.airtable_contract_id,
    c.status,
    c.package,
    public.package_family(c.package) AS package_family,
    public.package_opps_goal(c.package) AS package_quota,
    COALESCE(gm.media_opps_goal, public.package_opps_goal(c.package)) AS current_month_goal,
        CASE
            WHEN (gm.media_opps_goal IS NOT NULL) THEN 'goal row'::text
            WHEN (public.package_opps_goal(c.package) IS NOT NULL) THEN 'tier default'::text
            ELSE NULL::text
        END AS current_month_goal_source,
    c.per_month_cents,
    c.starts_on,
    c.ends_on,
        CASE
            WHEN ((c.starts_on IS NOT NULL) AND (c.ends_on IS NOT NULL)) THEN (((EXTRACT(year FROM age((c.ends_on)::timestamp with time zone, (c.starts_on)::timestamp with time zone)) * (12)::numeric) + EXTRACT(month FROM age((c.ends_on)::timestamp with time zone, (c.starts_on)::timestamp with time zone))))::integer
            ELSE NULL::integer
        END AS term_months,
        CASE
            WHEN (c.ends_on IS NOT NULL) THEN c.ends_on
            WHEN (c.starts_on IS NOT NULL) THEN ((c.starts_on + ('1 year'::interval * (((EXTRACT(year FROM age((CURRENT_DATE)::timestamp with time zone, (c.starts_on)::timestamp with time zone)))::integer + 1))::double precision)))::date
            ELSE NULL::date
        END AS renewal_on,
    ls.last_secured_month,
    ls.last_live_month,
        CASE
            WHEN (ls.last_secured_month IS NULL) THEN NULL::integer
            WHEN (ls.last_secured_month >= (date_trunc('month'::text, (CURRENT_DATE)::timestamp with time zone))::date) THEN 0
            ELSE (CURRENT_DATE - ((ls.last_secured_month + '1 mon -1 days'::interval))::date)
        END AS days_since_last_secured,
    ls.synced_at AS opps_synced_at
   FROM (((public.contracts c
     JOIN public.clients_v2 v ON ((v.id = c.client_id)))
     LEFT JOIN goal_rows gm ON (((gm.airtable_contract_id = c.airtable_contract_id) AND (gm.month = (date_trunc('month'::text, (CURRENT_DATE)::timestamp with time zone))::date))))
     LEFT JOIN last_secured ls ON ((ls.airtable_contract_id = c.airtable_contract_id)))
  WHERE ((c.status = ANY (ARRAY['active'::text, 'hold'::text, '60-day'::text])) AND (c.airtable_contract_id IS NOT NULL));


--
-- Name: v_client_opp_trend; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_client_opp_trend WITH (security_invoker='true') AS
 WITH goal_rows AS (
         SELECT DISTINCT ON (g.airtable_contract_id, g.month) g.airtable_contract_id,
            g.month,
            g.media_opps_goal
           FROM public.client_goals g
          WHERE (g.media_opps_goal IS NOT NULL)
          ORDER BY g.airtable_contract_id, g.month, g.updated_at DESC
        )
 SELECT spine.default_tenant_id() AS tenant_id,
    c.client_id,
    v.display_name,
    m.airtable_contract_id,
    c.status AS contract_status,
    public.package_family(c.package) AS package_family,
    m.month,
    m.secured_count,
    m.live_count,
    COALESCE(gr.media_opps_goal, public.package_opps_goal(c.package)) AS goal,
        CASE
            WHEN (gr.media_opps_goal IS NOT NULL) THEN 'goal row'::text
            WHEN (public.package_opps_goal(c.package) IS NOT NULL) THEN 'tier default'::text
            ELSE NULL::text
        END AS goal_source,
        CASE
            WHEN (COALESCE(gr.media_opps_goal, public.package_opps_goal(c.package)) > 0) THEN round((((m.secured_count)::numeric / (COALESCE(gr.media_opps_goal, public.package_opps_goal(c.package)))::numeric) * (100)::numeric), 1)
            ELSE NULL::numeric
        END AS secured_pct_of_goal,
    m.synced_at
   FROM (((public.client_opp_months m
     LEFT JOIN public.contracts c ON ((c.airtable_contract_id = m.airtable_contract_id)))
     LEFT JOIN public.clients_v2 v ON ((v.id = c.client_id)))
     LEFT JOIN goal_rows gr ON (((gr.airtable_contract_id = m.airtable_contract_id) AND (gr.month = m.month))));


--
-- Name: v_client_payment_timeliness; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_client_payment_timeliness WITH (security_invoker='true') AS
 WITH w AS (
         SELECT p.airtable_contract_id,
            p.due_on,
            p.paid_on,
            p.status,
            ((p.paid_on IS NOT NULL) AND (p.paid_on <= (p.due_on + 10))) AS on_time,
            (((p.paid_on IS NOT NULL) AND (p.paid_on > (p.due_on + 10))) OR ((p.paid_on IS NULL) AND (CURRENT_DATE > (p.due_on + 10)))) AS late
           FROM public.payments p
          WHERE ((p.due_on <= CURRENT_DATE) AND (p.due_on > (CURRENT_DATE - '6 mons'::interval)) AND (COALESCE(p.status, ''::text) <> 'Hold'::text))
        ), agg AS (
         SELECT w.airtable_contract_id,
            (count(*) FILTER (WHERE w.on_time))::integer AS on_time_count,
            (count(*) FILTER (WHERE w.late))::integer AS late_count,
            (count(*) FILTER (WHERE ((w.paid_on IS NULL) AND w.late)))::integer AS unpaid_late_count
           FROM w
          GROUP BY w.airtable_contract_id
        ), allp AS (
         SELECT p.airtable_contract_id,
            max(p.paid_on) AS last_paid_on,
            min(p.due_on) FILTER (WHERE ((p.paid_on IS NULL) AND (p.due_on >= CURRENT_DATE) AND (COALESCE(p.status, ''::text) <> ALL (ARRAY['Hold'::text, 'Lost Revenue'::text])))) AS next_due_on,
            (count(*))::integer AS payments_on_file
           FROM public.payments p
          GROUP BY p.airtable_contract_id
        )
 SELECT spine.default_tenant_id() AS tenant_id,
    c.client_id,
    c.display_name,
    c.airtable_contract_id,
    COALESCE(a.on_time_count, 0) AS on_time_count,
    COALESCE(a.late_count, 0) AS late_count,
    COALESCE(a.unpaid_late_count, 0) AS unpaid_late_count,
        CASE
            WHEN ((COALESCE(a.on_time_count, 0) + COALESCE(a.late_count, 0)) >= 2) THEN round((((a.on_time_count)::numeric / ((a.on_time_count + a.late_count))::numeric) * (100)::numeric), 1)
            ELSE NULL::numeric
        END AS on_time_pct,
    ((COALESCE(a.on_time_count, 0) + COALESCE(a.late_count, 0)) >= 2) AS measured,
    ap.last_paid_on,
    ap.next_due_on,
    COALESCE(ap.payments_on_file, 0) AS payments_on_file
   FROM ((public.v_client_analytics_contracts c
     LEFT JOIN agg a ON ((a.airtable_contract_id = c.airtable_contract_id)))
     LEFT JOIN allp ap ON ((ap.airtable_contract_id = c.airtable_contract_id)));


--
-- Name: v_client_top_outlets; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_client_top_outlets WITH (security_invoker='true') AS
 SELECT spine.default_tenant_id() AS tenant_id,
    c.client_id,
    l.airtable_contract_id,
    l.outlet,
    (count(*))::integer AS live_links,
    max(l.live_date) AS last_live_on,
    (sum(l.reach))::bigint AS reach
   FROM (public.live_links l
     LEFT JOIN public.contracts c ON ((c.airtable_contract_id = l.airtable_contract_id)))
  WHERE (l.outlet IS NOT NULL)
  GROUP BY c.client_id, l.airtable_contract_id, l.outlet;


--
-- Name: v_current_quarter; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_current_quarter WITH (security_invoker='true') AS
 SELECT id,
    name,
    year,
    quarter,
    starts_on,
    ends_on,
    is_current,
    created_at
   FROM public.quarters
  WHERE ((CURRENT_DATE >= starts_on) AND (CURRENT_DATE <= ends_on));


--
-- Name: v_live_links_weekly; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_live_links_weekly WITH (security_invoker='true') AS
 WITH weeks AS (
         SELECT ((date_trunc('week'::text, (CURRENT_DATE)::timestamp with time zone) - ((n.n)::double precision * '7 days'::interval)))::date AS week_start
           FROM generate_series(0, 11) n(n)
        )
 SELECT spine.default_tenant_id() AS tenant_id,
    w.week_start,
    (w.week_start + 6) AS week_end,
    (count(l.id))::integer AS live_links,
    (count(l.id) FILTER (WHERE ((l.tier ~~* '%1%'::text) OR (l.tier ~~* 'tier one'::text))))::integer AS tier_one_links,
    (count(DISTINCT l.airtable_contract_id))::integer AS contracts_with_links,
    (sum(l.reach))::bigint AS reach,
    (sum(l.est_value_cents))::bigint AS est_value_cents
   FROM (weeks w
     LEFT JOIN public.live_links l ON (((l.live_date >= w.week_start) AND (l.live_date < (w.week_start + 7)))))
  GROUP BY w.week_start;


--
-- Name: v_portfolio_opp_trend; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_portfolio_opp_trend WITH (security_invoker='true') AS
 SELECT spine.default_tenant_id() AS tenant_id,
    month,
    (count(*))::integer AS contracts_synced,
    (count(*) FILTER (WHERE (contract_status = ANY (ARRAY['active'::text, 'hold'::text, '60-day'::text]))))::integer AS contracts_in_scope,
    (sum(secured_count))::integer AS secured_count,
    (sum(live_count))::integer AS live_count,
    (sum(goal) FILTER (WHERE (goal IS NOT NULL)))::integer AS goal_total,
    (count(*) FILTER (WHERE (goal IS NOT NULL)))::integer AS contracts_with_goal,
    (sum(secured_count) FILTER (WHERE (goal IS NOT NULL)))::integer AS secured_toward_goal,
        CASE
            WHEN (sum(goal) FILTER (WHERE (goal IS NOT NULL)) > 0) THEN round((((sum(secured_count) FILTER (WHERE (goal IS NOT NULL)))::numeric / (sum(goal) FILTER (WHERE (goal IS NOT NULL)))::numeric) * (100)::numeric), 1)
            ELSE NULL::numeric
        END AS secured_pct_of_goal,
    max(synced_at) AS synced_at
   FROM public.v_client_opp_trend t
  GROUP BY month;


--
-- Name: v_portfolio_package_mix; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_portfolio_package_mix WITH (security_invoker='true') AS
 SELECT spine.default_tenant_id() AS tenant_id,
    package_family,
    (count(*))::integer AS contracts,
    (count(DISTINCT client_id))::integer AS clients,
    max(package_quota) AS monthly_quota_each,
    (sum(package_quota))::integer AS monthly_quota_total,
    (sum(per_month_cents))::bigint AS per_month_cents_total
   FROM public.v_client_analytics_contracts c
  GROUP BY package_family;


--
-- Name: v_portfolio_payment_timeliness; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_portfolio_payment_timeliness WITH (security_invoker='true') AS
 SELECT spine.default_tenant_id() AS tenant_id,
    (sum(on_time_count))::integer AS on_time_count,
    (sum(late_count))::integer AS late_count,
    (sum(unpaid_late_count))::integer AS unpaid_late_count,
    (count(*) FILTER (WHERE measured))::integer AS contracts_measured,
    (count(*))::integer AS contracts_in_scope,
        CASE
            WHEN ((sum(on_time_count) + sum(late_count)) > 0) THEN round((((sum(on_time_count))::numeric / ((sum(on_time_count) + sum(late_count)))::numeric) * (100)::numeric), 1)
            ELSE NULL::numeric
        END AS on_time_pct
   FROM public.v_client_payment_timeliness t;


--
-- Name: v_portfolio_tier_share; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_portfolio_tier_share WITH (security_invoker='true') AS
 SELECT spine.default_tenant_id() AS tenant_id,
    (date_trunc('month'::text, (live_date)::timestamp with time zone))::date AS month,
    (count(*))::integer AS live_links,
    (count(*) FILTER (WHERE ((tier ~~* '%1%'::text) OR (tier ~~* 'tier one'::text))))::integer AS tier_one_links,
    round((((count(*) FILTER (WHERE ((tier ~~* '%1%'::text) OR (tier ~~* 'tier one'::text))))::numeric / (NULLIF(count(*), 0))::numeric) * (100)::numeric), 1) AS tier_one_pct
   FROM public.live_links l
  WHERE (live_date IS NOT NULL)
  GROUP BY (date_trunc('month'::text, (live_date)::timestamp with time zone));


--
-- Name: v_scrape_job_costs; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_scrape_job_costs WITH (security_invoker='true') AS
 SELECT id,
    kind,
    preset,
    status,
    max_results,
    found,
    imported,
    requested_by,
    created_at,
    finished_at,
    public.scrape_job_estimated_usd(preset, status, max_results, found) AS estimated_usd
   FROM public.scrape_jobs j;


--
-- Name: v_time_study_dept_totals; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_time_study_dept_totals WITH (security_invoker='true') AS
 SELECT e.study_id,
    COALESCE(t.label, 'Unassigned'::text) AS department,
    e.category,
    (count(*) * 10) AS minutes,
    count(DISTINCT e.user_id) AS people
   FROM ((public.time_study_entries e
     JOIN public.profiles p ON ((p.id = e.user_id)))
     LEFT JOIN public.tags t ON (((t.id = p.department_tag_id) AND (t.category = 'department'::text))))
  GROUP BY e.study_id, COALESCE(t.label, 'Unassigned'::text), e.category;


--
-- Name: v_time_study_person_totals; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_time_study_person_totals WITH (security_invoker='true') AS
 SELECT study_id,
    user_id,
    category,
    (count(*) * 10) AS minutes,
    (count(*) FILTER (WHERE (source = 'calendar'::text)) * 10) AS calendar_minutes
   FROM public.time_study_entries e
  GROUP BY study_id, user_id, category;


--
-- Name: v_vantage_point; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_vantage_point WITH (security_invoker='true') AS
 SELECT c.id AS cycle_id,
    q.id AS quarter_id,
    q.name AS quarter_name,
    q.year,
    q.quarter,
    s.subject_id,
    s.performance,
    s.potential,
    ((((s.potential - 1) * 3) + s.performance))::smallint AS box,
    s.submitted_at AS reconciled_at,
    s.scorer_id AS reconciled_by
   FROM ((public.calibration_scores s
     JOIN public.calibration_cycles c ON ((c.id = s.cycle_id)))
     JOIN public.quarters q ON ((q.id = c.quarter_id)))
  WHERE ((s.round = 'exec'::text) AND (s.submitted_at IS NOT NULL));


