    CONSTRAINT weekly_checkins_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'submitted'::text]))),
    CONSTRAINT weekly_checkins_submitted_is_complete CHECK (((status = 'draft'::text) OR ((weekly_high IS NOT NULL) AND (weekly_low IS NOT NULL) AND (submitted_at IS NOT NULL)))),
    CONSTRAINT weekly_checkins_week_is_friday CHECK ((((week_end - '2026-01-02'::date) % 7) = 0))
);


