CREATE POLICY gn_write_update ON public.graph_nodes FOR UPDATE USING ((EXISTS ( SELECT 1
   FROM public.profiles
  WHERE ((profiles.id = ( SELECT auth.uid() AS uid)) AND (profiles.role = ANY (ARRAY['exec'::text, 'admin'::text, 'manager'::text]))))));


