set search_path = public, extensions;
-- auth.users triggers: domain gate + profile row on signup
drop trigger if exists "enforce_email_domain_trigger" on auth."users";
CREATE TRIGGER enforce_email_domain_trigger BEFORE INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.enforce_email_domain();
drop trigger if exists "on_auth_user_created" on auth."users";
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();

