-- storage.objects policies
drop policy if exists "avatars_storage_delete" on storage."objects";
create policy "avatars_storage_delete" on storage."objects" as permissive for delete to public using (((bucket_id = 'avatars'::text) AND (((auth.uid())::text = split_part(name, '/'::text, 1)) OR is_people_manager(auth.uid()) OR is_admin())));
drop policy if exists "avatars_storage_insert" on storage."objects";
create policy "avatars_storage_insert" on storage."objects" as permissive for insert to public with check (((bucket_id = 'avatars'::text) AND (((auth.uid())::text = split_part(name, '/'::text, 1)) OR is_people_manager(auth.uid()) OR is_admin())));
drop policy if exists "avatars_storage_select" on storage."objects";
create policy "avatars_storage_select" on storage."objects" as permissive for select to public using ((bucket_id = 'avatars'::text));
drop policy if exists "avatars_storage_update" on storage."objects";
create policy "avatars_storage_update" on storage."objects" as permissive for update to public using (((bucket_id = 'avatars'::text) AND (((auth.uid())::text = split_part(name, '/'::text, 1)) OR is_people_manager(auth.uid()) OR is_admin()))) with check (((bucket_id = 'avatars'::text) AND (((auth.uid())::text = split_part(name, '/'::text, 1)) OR is_people_manager(auth.uid()) OR is_admin())));
drop policy if exists "content_storage_delete" on storage."objects";
create policy "content_storage_delete" on storage."objects" as permissive for delete to "authenticated" using (((bucket_id = 'content'::text) AND is_admin()));
drop policy if exists "content_storage_insert" on storage."objects";
create policy "content_storage_insert" on storage."objects" as permissive for insert to "authenticated" with check (((bucket_id = 'content'::text) AND can_run_content()));
drop policy if exists "content_storage_select" on storage."objects";
create policy "content_storage_select" on storage."objects" as permissive for select to "authenticated" using (((bucket_id = 'content'::text) AND can_run_content()));
drop policy if exists "flywheel_uploads_delete" on storage."objects";
create policy "flywheel_uploads_delete" on storage."objects" as permissive for delete to "authenticated" using (((bucket_id = 'flywheel-uploads'::text) AND ( SELECT can_manage_flywheel() AS can_manage_flywheel)));
drop policy if exists "flywheel_uploads_insert" on storage."objects";
create policy "flywheel_uploads_insert" on storage."objects" as permissive for insert to "authenticated" with check (((bucket_id = 'flywheel-uploads'::text) AND ( SELECT can_view_flywheel() AS can_view_flywheel)));
drop policy if exists "flywheel_uploads_read" on storage."objects";
create policy "flywheel_uploads_read" on storage."objects" as permissive for select to "authenticated" using (((bucket_id = 'flywheel-uploads'::text) AND ( SELECT can_view_flywheel() AS can_view_flywheel)));
drop policy if exists "form_uploads_delete" on storage."objects";
create policy "form_uploads_delete" on storage."objects" as permissive for delete to "authenticated" using (((bucket_id = 'form-uploads'::text) AND ( SELECT is_admin() AS is_admin)));
drop policy if exists "form_uploads_read" on storage."objects";
create policy "form_uploads_read" on storage."objects" as permissive for select to "authenticated" using (((bucket_id = 'form-uploads'::text) AND (split_part(name, '/'::text, 1) ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text) AND ( SELECT can_view_form_submissions((split_part(objects.name, '/'::text, 1))::uuid) AS can_view_form_submissions)));
drop policy if exists "hiring_uploads_delete" on storage."objects";
create policy "hiring_uploads_delete" on storage."objects" as permissive for delete to "authenticated" using (((bucket_id = 'hiring-uploads'::text) AND ( SELECT can_manage_hiring() AS can_manage_hiring)));
drop policy if exists "hiring_uploads_read" on storage."objects";
create policy "hiring_uploads_read" on storage."objects" as permissive for select to "authenticated" using (((bucket_id = 'hiring-uploads'::text) AND ( SELECT can_view_hiring() AS can_view_hiring)));
drop policy if exists "imports_storage_delete" on storage."objects";
create policy "imports_storage_delete" on storage."objects" as permissive for delete to "authenticated" using (((bucket_id = 'imports'::text) AND can_import_data() AND (((auth.uid())::text = split_part(name, '/'::text, 1)) OR is_admin())));
drop policy if exists "imports_storage_insert" on storage."objects";
create policy "imports_storage_insert" on storage."objects" as permissive for insert to "authenticated" with check (((bucket_id = 'imports'::text) AND can_import_data() AND ((auth.uid())::text = split_part(name, '/'::text, 1))));
drop policy if exists "imports_storage_select" on storage."objects";
create policy "imports_storage_select" on storage."objects" as permissive for select to "authenticated" using (((bucket_id = 'imports'::text) AND can_import_data() AND (((auth.uid())::text = split_part(name, '/'::text, 1)) OR is_admin())));
drop policy if exists "portal_block" on storage."objects";
create policy "portal_block" on storage."objects" as restrictive for all to "authenticated" using ((NOT is_portal_user())) with check ((NOT is_portal_user()));
drop policy if exists "proof_assets_storage_delete" on storage."objects";
create policy "proof_assets_storage_delete" on storage."objects" as permissive for delete to "authenticated" using (((bucket_id = 'proof-assets'::text) AND ( SELECT can_manage_revenue() AS can_manage_revenue)));
drop policy if exists "proof_assets_storage_insert" on storage."objects";
create policy "proof_assets_storage_insert" on storage."objects" as permissive for insert to "authenticated" with check (((bucket_id = 'proof-assets'::text) AND ( SELECT can_manage_revenue() AS can_manage_revenue)));
drop policy if exists "proof_assets_storage_select" on storage."objects";
create policy "proof_assets_storage_select" on storage."objects" as permissive for select to public using ((bucket_id = 'proof-assets'::text));
drop policy if exists "proof_assets_storage_update" on storage."objects";
create policy "proof_assets_storage_update" on storage."objects" as permissive for update to "authenticated" using (((bucket_id = 'proof-assets'::text) AND ( SELECT can_manage_revenue() AS can_manage_revenue)));
drop policy if exists "revenue_documents_delete" on storage."objects";
create policy "revenue_documents_delete" on storage."objects" as permissive for delete to "authenticated" using (((bucket_id = 'revenue-documents'::text) AND ( SELECT can_manage_revenue() AS can_manage_revenue)));
drop policy if exists "revenue_documents_insert" on storage."objects";
create policy "revenue_documents_insert" on storage."objects" as permissive for insert to "authenticated" with check (((bucket_id = 'revenue-documents'::text) AND ( SELECT can_view_revenue() AS can_view_revenue)));
drop policy if exists "revenue_documents_read" on storage."objects";
create policy "revenue_documents_read" on storage."objects" as permissive for select to "authenticated" using (((bucket_id = 'revenue-documents'::text) AND ( SELECT can_view_revenue() AS can_view_revenue)));
drop policy if exists "work_item_attachments_storage_delete" on storage."objects";
create policy "work_item_attachments_storage_delete" on storage."objects" as permissive for delete to public using (((bucket_id = 'work-item-attachments'::text) AND (auth.role() = 'authenticated'::text)));
drop policy if exists "work_item_attachments_storage_insert" on storage."objects";
create policy "work_item_attachments_storage_insert" on storage."objects" as permissive for insert to public with check (((bucket_id = 'work-item-attachments'::text) AND (auth.role() = 'authenticated'::text)));
drop policy if exists "work_item_attachments_storage_read" on storage."objects";
create policy "work_item_attachments_storage_read" on storage."objects" as permissive for select to public using (((bucket_id = 'work-item-attachments'::text) AND (auth.role() = 'authenticated'::text)));

